window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-2/physio-patho","titre":"Physiopathologie I","sources":[{"t":"Lésion Médullaire","q":"qcm/neuro/lesion-medullaire.html","f":"fiches/neuro/lesion-medullaire.html"},{"t":"Lésions Périphériques","q":"qcm/neuro/lesions-peripheriques.html","f":"fiches/neuro/lesions-peripheriques.html"},{"t":"Lésions SNC + Encéphale","q":"qcm/neuro/lesions-snc-encephale.html","f":"fiches/neuro/lesions-snc-encephale.html"},{"t":"Système Nerveux","q":"qcm/neuro/systeme-nerveux.html","f":"fiches/neuro/systeme-nerveux.html"},{"t":"Support Neurophysio 1","q":"qcm/neuroanat/suporte-1.html","f":"fiches/neuroanat/suporte-1.html"},{"t":"Support Neurophysio 2a","q":"qcm/neuroanat/suporte-2a.html","f":"fiches/neuroanat/suporte-2a.html"},{"t":"Support Neurophysio 2b","q":"qcm/neuroanat/suporte-2b.html","f":"fiches/neuroanat/suporte-2b.html"},{"t":"TP 1 — Introduction Physiopathologie","q":"qcm/tp/tp-01.html","f":"fiches/tp/tp-01.html"},{"t":"TP 2 — Lésions Cellulaires","q":"qcm/tp/tp-02.html","f":"fiches/tp/tp-02.html"},{"t":"TP 3 — Maladies Infectieuses","q":"qcm/tp/tp-03.html","f":"fiches/tp/tp-03.html"},{"t":"TP 4 — Inflammation & Réparation","q":"qcm/tp/tp-04.html","f":"fiches/tp/tp-04.html"},{"t":"TP 5 — Squelette & Tissu Osseux","q":"qcm/tp/tp-05.html","f":"fiches/tp/tp-05.html"},{"t":"TP 6-7 — Troubles musculo-squelettiques","q":"qcm/tp/tp-06-07.html","f":"fiches/tp/tp-06-07.html"},{"t":"TP 6 — Ostéoporose & Fractures","q":"qcm/tp/tp-06.html","f":"fiches/tp/tp-06.html"},{"t":"TP 7 — Posture & Scoliose","q":"qcm/tp/tp-07.html","f":"fiches/tp/tp-07.html"},{"t":"TP 8 — Arthrose","q":"qcm/tp/tp-08.html","f":"fiches/tp/tp-08.html"},{"t":"TP 9 — Réparation Tissulaire","q":"qcm/tp/tp-09.html","f":"fiches/tp/tp-09.html"},{"t":"TP 10 — Sepsie & Choc Septique","q":"qcm/tp/tp-10.html","f":"fiches/tp/tp-10.html"},{"t":"TP 11 — Voies Respiratoires Supérieures","q":"qcm/tp/tp-11.html","f":"fiches/tp/tp-11.html"},{"t":"TP 12 — Voies Respiratoires Inférieures","q":"qcm/tp/tp-12.html","f":"fiches/tp/tp-12.html"},{"t":"TP 13 — Maladies Obstructives","q":"qcm/tp/tp-13.html","f":"fiches/tp/tp-13.html"},{"t":"TP 14 — Maladies Restrictives & Plèvre","q":"qcm/tp/tp-14.html","f":"fiches/tp/tp-14.html"},{"t":"TP 15 — Néoplasies (Cancer)","q":"qcm/tp/tp-15.html","f":"fiches/tp/tp-15.html"}],"questions":[{"q":"Jusqu'à quel niveau vertébral s'étend la moelle épinière chez l'adulte ?","o":["L4-L5","L1-L2","T12-L1","S1"],"r":1,"e":"Chez l'adulte, la moelle épinière s'étend de l'orifice occipital jusqu'à L1-L2. En dessous se trouve la queue de cheval.","s":0},{"q":"Comment s'appelle l'ensemble des racines nerveuses libres situées en dessous du cône médullaire ?","o":["Filum terminale","Queue de cheval","Plexus sacré","Cône terminal"],"r":1,"e":"La queue de cheval = ensemble des racines L2-S5 qui parcourent le canal rachidien sous le cône médullaire (fin de la moelle).","s":0},{"q":"Concernant la substance grise de la moelle, quelles affirmations sont vraies ?","o":["Les cornes antérieures sont motrices","Les cornes postérieures sont sensitives","Les cornes latérales contiennent des neurones du SNA","Les cornes antérieures sont sensitives","La substance grise contient surtout des axones myélinisés"],"r":[0,1,2],"e":"Antérieur = moteur, postérieur = sensitif, latéral = SNA. La substance grise contient les corps cellulaires (les axones myélinisés sont dans la substance blanche).","s":0},{"q":"La règle mnémotechnique pour la moelle est :","o":["Antérieur = sensitif, postérieur = moteur","Antérieur = moteur, postérieur = sensitif","Latéral = moteur, médian = sensitif","Toutes les directions ont des fonctions mixtes"],"r":1,"e":"Antérieur = moteur, postérieur = sensitif (valable pour les cornes ET les cordons).","s":0},{"q":"Quelles voies sensitives passent par la colonne POSTÉRIEURE de la moelle ?","o":["La proprioception consciente","La sensibilité vibratoire","Le toucher fin, épicritique","La sensibilité douloureuse","La sensibilité thermique"],"r":[0,1,2],"e":"Colonne postérieure (gracile + cunéiforme) = proprioception, vibration, toucher fin. Douleur et température passent par la voie spinothalamique latérale.","s":0},{"q":"La voie spinothalamique latérale véhicule :","o":["Le toucher fin et la proprioception","La douleur et la température","La motricité volontaire","Les réflexes ostéo-tendineux"],"r":1,"e":"La voie spinothalamique latérale = douleur + température (voie protopathique). Elle CROISE rapidement (1-2 segments au-dessus de l'entrée).","s":0},{"q":"Une lésion AU-DESSUS de D1 (T1) entraîne :","o":["Une paraplégie","Une tétraplégie","Une hémiplégie","Aucun déficit"],"r":1,"e":"Au-dessus de T1 = atteinte des 4 membres = tétraplégie/tétraparésie. En dessous de T1 = paraplégie.","s":0},{"q":"Concernant le syndrome de BROWN-SÉQUARD (hémisection médullaire), quelles affirmations sont vraies ?","o":["Une perte motrice ipsilatérale","Une perte de la proprioception ipsilatérale","Une perte thermoalgique controlatérale","Une perte motrice controlatérale","Une absence de tout déficit moteur"],"r":[0,1,2],"e":"Brown-Séquard : motricité + proprioception ipsilatérales (corticospinale et colonne postérieure homolatérales) ; douleur/T° controlatérales (spinothalamique croisée).","s":0},{"q":"Le syndrome ANTÉRIEUR de la moelle (atteinte de l'artère spinale antérieure) se caractérise par :","o":["Une perte motrice et thermoalgique, proprioception préservée","Une perte de la proprioception uniquement, motricité intacte","Une hémisection avec un déficit croisé, de type Brown-Séquard","Une atteinte sphinctérienne isolée, sans autre déficit"],"r":0,"e":"Le syndrome antérieur (artère spinale antérieure) atteint les 2/3 antérieurs de la moelle : déficit moteur + perte douleur/T° BILATÉRALES, mais la colonne POSTÉRIEURE est intacte (proprioception et toucher fin préservés).","s":0},{"q":"Concernant le syndrome CENTROMÉDULLAIRE, quelles propositions sont vraies ?","o":["Les membres supérieurs plus touchés que les inférieurs","Un mécanisme typique d'hyperextension cervicale","Une atteinte du canal central et des fibres médianes","Les membres inférieurs toujours plus touchés que les supérieurs","Une absence de toute atteinte sphinctérienne"],"r":[0,1,2],"e":"Syndrome centromédullaire : MS > MI (les fibres des MS sont plus centrales dans le tractus corticospinal latéral). Mécanisme classique : hyperextension cervicale. Rétention urinaire fréquente.","s":0},{"q":"Quel niveau médullaire contient le centre de la miction ?","o":["L1-L2","S2-S4","T10-T12","C5-C6"],"r":1,"e":"Le centre médullaire de la miction se situe en S2-S4 (parasympathique sacré). Une lésion à ce niveau entraîne une vessie flasque/autonome.","s":0},{"q":"Concernant le CHOC MÉDULLAIRE (phase initiale), quelles affirmations sont correctes ?","o":["Paralysie flasque","Aréflexie","Anesthésie","Hyperréflexie immédiate","Spasticité immédiate"],"r":[0,1,2],"e":"Phase de choc spinal : paralysie FLASQUE, aréflexie, anesthésie, atonie vésicale et intestinale. La spasticité et l'hyperréflexie n'apparaissent qu'APRÈS le retour de l'activité réflexe.","s":0},{"q":"Après la phase de choc médullaire, une lésion du 1er neurone (motoneurone supérieur) se traduit par :","o":["Paralysie flasque + aréflexie + atrophie","Paralysie spastique + hyperréflexie","Aucun déficit","Atrophie isolée sans paralysie"],"r":1,"e":"Lésion 1er neurone (SNC) après le choc : paralysie spastique, hyperréflexie, signe de Babinski, spasmes. La paralysie flasque + aréflexie + atrophie = lésion du 2e neurone (SNP).","s":0},{"q":"Dans la classification ASIA, le grade A correspond à :","o":["Lésion incomplète motrice","Lésion complète","Fonctions normales","Lésion incomplète sensitive"],"r":1,"e":"ASIA A = lésion complète : aucune fonction motrice ni sensorielle préservée dans les segments S4-S5. ASIA E = normal.","s":0},{"q":"Concernant la classification ASIA, quelles correspondances sont correctes ?","o":["A, une lésion complète","B, une lésion incomplète sensitive","C, motrice incomplète, muscles surtout sous 3/5","D, motrice incomplète, muscles surtout à 3/5 ou plus","E, une atteinte sphinctérienne isolée"],"r":[0,1,2,3],"e":"ASIA : A complète, B incomplète sensitive (motricité absente sous le niveau), C incomplète motrice <3/5, D incomplète motrice ≥3/5, E normale. Les sphincters ne sont pas un grade ASIA.","s":0},{"q":"Combien de dermatomes sont testés dans l'examen ASIA ?","o":["10","15","23","31"],"r":2,"e":"L'examen ASIA teste 23 dermatomes (sensibilité tactile et douloureuse) et 10 myotomes clés (5 par côté pour le bilan moteur).","s":0},{"q":"Le myotome C5 correspond principalement à :","o":["L'extension du coude, par le triceps","L'abduction du bras et la flexion du coude","La flexion plantaire de la cheville","L'extension du poignet, par les radiaux"],"r":1,"e":"C5 = abduction de l'épaule et flexion du coude (deltoïde, biceps). C6 = extension du poignet, C7 = extension du coude/triceps.","s":0},{"q":"Le myotome S1 correspond à :","o":["La flexion de hanche","L'extension du genou","La dorsiflexion","La flexion plantaire"],"r":3,"e":"S1 = flexion plantaire (triceps sural). L4 = dorsiflexion ; L3 = extension genou ; L2 = flexion de hanche.","s":0},{"q":"Quels niveaux médullaires assurent l'innervation diaphragmatique (centre phrénique) ?","o":["C2","C3","C4","C5","T1"],"r":[1,2,3],"e":"Le diaphragme est innervé par le nerf phrénique issu de C3-C4-C5. Une lésion AU-DESSUS de C3 menace la respiration et nécessite une ventilation.","s":0},{"q":"Parmi les complications classiques d'un blessé médullaire, on retrouve :","o":["Escarres / ulcères de pression","Thrombose veineuse profonde","Hypotension orthostatique","Ostéoporose","Hyperhidrose excessive sans risque"],"r":[0,1,2,3],"e":"Complications classiques : escarres (téguments), TVP (vasculaire), hypotension orthostatique, ostéoporose, vessie neurogène, calcifications hétérotopiques. L'hyperhidrose peut survenir lors d'une hyperréflexie autonome (urgence).","s":0},{"q":"L'anesthésie en SELLE (périnée + face interne des cuisses) évoque :","o":["Un syndrome de Brown-Séquard","Un syndrome centromédullaire","Un syndrome du cône ou de la queue de cheval","Une section médullaire totale, haute et cervicale"],"r":2,"e":"L'anesthésie en selle (S3-S5) est typique du syndrome du cône médullaire / queue de cheval, avec troubles sphinctériens et sexuels.","s":0},{"q":"Une lésion COMPLÈTE selon ASIA correspond à :","o":["Aucun mouvement volontaire, la sensibilité restant préservée","Aucune fonction motrice ni sensitive préservée en S4-S5","Une force musculaire inférieure ou égale à 3/5, sous le niveau","Un réflexe sphinctérien isolé, en S4-S5"],"r":1,"e":"Une lésion ASIA A (complète) = aucune fonction motrice NI sensorielle dans les segments sacrés S4-S5 (test du toucher anal et de la contraction volontaire).","s":0},{"q":"Concernant la PHASE 2 (lésion secondaire) de la lésion médullaire, quelles affirmations sont correctes ?","o":["Une ischémie étendue, par baisse du flux","Un œdème de la moelle","Une excitotoxicité par le glutamate","Une démyélinisation axonale graduelle","Une rupture physique immédiate des axones"],"r":[0,1,2,3],"e":"Phase secondaire : ischémie, œdème, inflammation, excitotoxicité (glutamate, K+), apoptose, démyélinisation graduelle. La rupture physique des axones est généralement progressive (sauf blessures par balle), pas immédiate.","s":0},{"q":"Une lésion intra-durale extra-médullaire correspond à :","o":["Une lésion dans la moelle, comme une syringomyélie","Une lésion sous la dure-mère, hors de la moelle","Une lésion hors de la dure-mère, comme une hernie discale","Une lésion vasculaire pure, par infarctus"],"r":1,"e":"Intra-durale extra-médullaire : sous la dure-mère MAIS en dehors de la moelle. Exemples : méningiome, schwannome. Intra-médullaire = dans la moelle ; extra-durale = hernie discale, métastase. Le méningiome en est un exemple.","s":0},{"q":"Concernant la cotation motrice ASIA (0-5), quelles correspondances sont vraies ?","o":["0 = paralysie totale","2 = mouvement actif sans la pesanteur","3 = mouvement actif contre la pesanteur","4 = contre résistance partielle","5 = mouvement seulement visible"],"r":[0,1,2,3],"e":"Cotation : 0 paralysie / 1 contraction visible/palpable / 2 sans pesanteur / 3 contre pesanteur / 4 contre résistance partielle / 5 force normale.","s":0},{"q":"Selon les statistiques épidémiologiques, quelle est la cause la plus fréquente de lésion médullaire ?","o":["Les chutes, surtout chez les personnes âgées","La violence, par arme à feu","Les accidents de la route","Le sport, en plongeon"],"r":2,"e":"Les accidents de la route représentent ~48% des lésions médullaires, devant les chutes (~23%), la violence (~14%) et le sport (~9%). 80% des victimes sont des hommes, âge moyen ~37 ans.","s":0},{"q":"Une dyssynergie vésico-sphinctérienne correspond à :","o":["Une vessie flasque, sans aucune contraction","Une vessie qui se contracte contre un sphincter fermé","Une infection urinaire, par stase prolongée et répétée","Une fistule entre la vessie et le rectum"],"r":1,"e":"La dyssynergie vésico-sphinctérienne = contraction simultanée du détrusor (vessie) et du sphincter externe → mauvaise vidange, hyperpression, risque d'hydronéphrose. Complication classique des lésions du 1er neurone. Le sphincter ne se relâche pas pendant la contraction.","s":0},{"q":"Quels sites anatomiques sont à risque d'escarre chez le blessé médullaire ?","o":["La région sacrée","Les talons, en décubitus","Les ischions, en position assise","L'occiput, chez l'alité","La face palmaire des mains"],"r":[0,1,2,3],"e":"Les zones à risque d'escarre = points d'appui : sacrum, ischions, talons, occiput, omoplates, malléoles, coudes. La face palmaire des mains n'est pas une zone classique d'escarre.","s":0},{"q":"Une lésion médullaire haute (cervicale C1-C4) entraîne typiquement :","o":["Une tétraplégie et une atteinte du diaphragme","Une paraplégie isolée, sans atteinte respiratoire","Aucune atteinte motrice, seulement des troubles sensitifs","Un déficit sensitif facial, par atteinte du trijumeau"],"r":0,"e":"Lésion C1-C4 : tétraplégie + paralysie diaphragmatique (nerf phrénique C3-C5) → ventilation mécanique nécessaire.","s":0},{"q":"Une lésion thoracique provoque :","o":["Une tétraplégie complète","Une paraplégie avec perte sensitive sous la lésion","Une hémiplégie, d'un seul côté","Aucun déficit, la moelle thoracique étant bien protégée"],"r":1,"e":"Lésion thoracique → paraplégie (membres inférieurs) + perte sensitive sous le niveau lésionnel.","s":0},{"q":"Le choc spinal correspond à :","o":["Une récupération immédiate de toute la motricité","Une aréflexie initiale et temporaire sous la lésion","Une spasticité immédiate, dès le traumatisme","Une hyperréflexie, avec clonus"],"r":1,"e":"Choc spinal = phase initiale de l'atteinte médullaire : aréflexie, hypotonie, perte transitoire des fonctions, dure heures à semaines. Elle dure de quelques heures à quelques semaines.","s":0},{"q":"Après le choc spinal, on observe typiquement :","o":["Une flaccidité permanente des membres","L'apparition d'une spasticité, avec hyperréflexie","Un retour à la normale, en quelques semaines de rééducation","Une atrophie totale, par dénervation"],"r":1,"e":"Après le choc spinal : spasticité, hyperréflexie, signe de Babinski (atteinte du 1er motoneurone). C'est une lésion du 1er motoneurone.","s":0},{"q":"Le syndrome de Brown-Séquard correspond à :","o":["Une atteinte symétrique, des deux côtés","Une hémisection, au déficit moteur ipsilatéral","Une compression complète, avec perte totale sous la lésion","Une lésion antérieure, par l'artère spinale"],"r":1,"e":"Brown-Séquard (hémisection) : moteur + tact épicritique ipsi (cordon dorsal et latéral) ; thermoalgique controlatéral (faisceau spinothalamique croisé). La sensibilité thermoalgique est perdue du côté opposé.","s":0},{"q":"La dysréflexie autonome est :","o":["Une réaction bénigne, sans gravité","Une urgence, avec poussée tensionnelle massive","Un trouble sans rapport avec la lésion, d'origine psychique","Toujours hypotensive, par vasodilatation"],"r":1,"e":"Dysréflexie autonome (lésion ≥T6) : poussée hypertensive sévère + bradycardie + sueurs sus-lésionnelles. Stimulus = vessie pleine, fécalome. Urgence. Elle survient chez le tétraplégique, déclenchée par un stimulus sous-lésionnel.","s":0},{"q":"L'échelle ASIA évalue :","o":["L'âge physiologique du patient","Le niveau et la complétude de la lésion","La douleur, sur une échelle de 0 à 10","La vigilance, par l'échelle de Glasgow modifiée"],"r":1,"e":"ASIA Impairment Scale : grade A (complète) à E (normal). Définit niveau moteur, sensitif et complétude de la lésion. La lésion est médullaire.","s":0},{"q":"Les complications fréquentes du blessé médullaire incluent :","o":["Escarres","Infection urinaire","Thrombose veineuse profonde","Spasticité","Ostéoporose","Hyperthyroïdie"],"r":[0,1,2,3,4],"e":"Complications : escarres, IU, TVP/EP, spasticité, ostéoporose, douleurs neuropathiques, dysréflexie autonome.","s":0},{"q":"Le réflexe rotulien (L3-L4) est :","o":["Aboli en lésion centrale, dès la phase chronique","Vif, en lésion centrale chronique","Toujours absent, quel que soit le niveau","Ipsilatéral à toute lésion, quelle qu'elle soit"],"r":1,"e":"Lésion centrale chronique → ROT vifs (hyperréflexie, spasticité). Lésion périphérique L3-L4 → ROT abolis. La vivacité traduit la spasticité.","s":0},{"q":"La rééducation du blessé médullaire vise à :","o":["Récupérer la marche dans tous les cas","Maximiser l'autonomie et prévenir les complications","Aucun objectif, la lésion étant fixée","Soulager uniquement la douleur, par antalgiques et repos"],"r":1,"e":"Rééducation : autonomie selon niveau (transferts, fauteuil, AVC, marche si paraplégie incomplète), prévention complications. L'autonomie visée dépend du niveau lésionnel.","s":0},{"q":"Quels espaces et membranes traverse-t-on de l'extérieur vers la moelle ?","o":["Espace épidural, dure-mère, arachnoïde puis pie-mère","Dure-mère, pie-mère, arachnoïde puis LCR","Pie-mère, arachnoïde, dure-mère puis espace épidural","Arachnoïde, dure-mère, pie-mère puis espace épidural profond"],"r":0,"e":"La fiche décrit cette succession ; le LCR occupe l'espace sous-arachnoïdien, juste au-dessus de la pie-mère. Les espaces sous-dural et sous-arachnoïdien s'intercalent entre ces membranes.","s":0},{"q":"Que contient l'espace épidural ?","o":["De la graisse et des veines","Du LCR, en circulation","Des racines nerveuses libres uniquement","De la substance blanche"],"r":0,"e":"L'espace épidural est graisseux et veineux ; le LCR est sous-arachnoïdien.","s":0},{"q":"Quel type de neurones les interneurones propriospinaux relient-ils ?","o":["Ils relient les segments de la moelle entre eux","Ils relient directement le cortex au muscle","Ils relient le cervelet au thalamus, par le pédoncule","Ils innervent les glandes, par le sympathique"],"r":0,"e":"Le système propriospinal, ascendant et descendant, connecte les segments médullaires entre eux. Les connexions sont intra- et intersegmentaires.","s":0},{"q":"Que véhicule le faisceau spinothalamique antérieur ?","o":["Le toucher et la pression","La douleur et la température","La proprioception consciente","La sensibilité profonde inconsciente"],"r":0,"e":"Le spinothalamique latéral porte douleur et température, l'antérieur le toucher et la pression.","s":0},{"q":"Que véhiculent les voies spinocérébelleuses ?","o":["La sensibilité profonde inconsciente","La douleur et la température","Le toucher fin épicritique","Les commandes motrices volontaires"],"r":0,"e":"Ces voies portent la proprioception inconsciente vers le cervelet.","s":0},{"q":"À quel âge le contrôle de la miction devient-il supra-médullaire ?","o":["Vers 2 ans","Vers 6 mois","Vers 5 ans","Vers 10 ans"],"r":0,"e":"Le centre S2-S4 fonctionne sur un mode réflexe jusqu'à environ 2 ans, puis le contrôle devient supra-médullaire.","s":0},{"q":"Que désignent les CPG (générateurs centraux de schémas) médullaires ?","o":["Des réseaux de la locomotion automatique","Le centre de la miction, en sacré","Les voies pyramidales, issues du cortex","Les ganglions spinaux sensitifs"],"r":0,"e":"Les CPG médullaires produisent les schémas rythmiques de la locomotion sans commande corticale permanente.","s":0},{"q":"À quel myotome correspond l'extension du gros orteil ?","o":["L5","L4","S1","L3"],"r":0,"e":"L4 = dorsiflexion, L5 = extension de l'hallux, S1 = flexion plantaire.","s":0},{"q":"À quel myotome correspond l'extension du genou ?","o":["L3","L2","L4","L5"],"r":0,"e":"L2 fléchit la hanche, L3 étend le genou, L4 assure la dorsiflexion.","s":0},{"q":"Quelle durée minimale la définition d'une lésion médullaire retient-elle ?","o":["Plus de 24 heures à 4 semaines","Moins de 24 heures","Plus de 6 mois","Plus de 72 heures seulement"],"r":0,"e":"La fiche définit la lésion médullaire par une atteinte durable, au-delà de 24 heures à 4 semaines.","s":0},{"q":"Quel exemple de lésion intramédullaire la fiche donne-t-elle ?","o":["Les tumeurs gliales et la syringomyélie","Le méningiome et le schwannome, sous la dure-mère","La hernie discale, en extradural","La métastase vertébrale, osseuse"],"r":0,"e":"Gliomes et syringomyélie sont intramédullaires ; méningiome et schwannome sont intra-duraux extramédullaires.","s":0},{"q":"Quel exemple de lésion extradurale la fiche donne-t-elle ?","o":["La hernie discale et la métastase","Le schwannome intradural","La syringomyélie, intramédullaire","Le méningiome, sous la dure-mère, hors de la moelle"],"r":0,"e":"Les lésions extradurales siègent hors de la dure-mère : hernie discale, métastase.","s":0},{"q":"Quelles cellules assurent la myélinisation des nerfs dans le SNP ?","o":["Oligodendrocytes","Cellules de Schwann","Astrocytes","Cellules microgliales"],"r":1,"e":"Dans le SNP, ce sont les cellules de Schwann qui myélinisent les axones. Les oligodendrocytes assurent cette fonction dans le SNC.","s":1},{"q":"Comment s'appelle la gaine conjonctive qui entoure CHAQUE fibre nerveuse ?","o":["Endonèvre","Périnèvre","Épinèvre","Mésonèvre"],"r":0,"e":"Endonèvre = chaque fibre. Périnèvre = un faisceau. Épinèvre = le nerf entier.","s":1},{"q":"Quelles affirmations concernant la conduction nerveuse sont VRAIES ?","o":["Avec myéline intacte, la conduction est saltatoire","La vitesse normale est d'environ 400 km/h","La perte de myéline réduit la vitesse à environ 4 km/h","Les nœuds de Ranvier ralentissent la conduction","La conduction est toujours uniforme le long de l'axone"],"r":[0,1,2],"e":"La myéline permet la conduction saltatoire (~400 km/h, de nœud de Ranvier en nœud). Sans myéline, la conduction est ~4 km/h. Les nœuds ne ralentissent pas, ils accélèrent.","s":1},{"q":"Le neurotransmetteur de la jonction neuromusculaire (système somatique) est :","o":["Noradrénaline","Acétylcholine","Dopamine","GABA"],"r":1,"e":"Le système somatique utilise l'acétylcholine (ACh) à la jonction neuromusculaire pour activer le muscle squelettique.","s":1},{"q":"Une compression neurale aiguë avec récupération en environ 10 minutes correspond à :","o":["Une neurotmèse complète","Une axonotmèse partielle","Une neuropraxie, de quelques jours","Une ischémie transitoire"],"r":3,"e":"L'ischémie transitoire (stade 0) = anoxie endonévrale aiguë avec paresthésies/déficits réversibles en ~10 min. La neuropraxie est plus longue (jours-semaines).","s":1},{"q":"Concernant la NEUROPRAXIE (Seddon I), quelles affirmations sont correctes ?","o":["Tous les éléments anatomiques sont préservés","Il y a une perte transitoire de conductivité","La sensibilité est généralement plus atteinte que la motricité","La récupération prend des jours à des semaines","Une dégénérescence wallérienne se produit"],"r":[0,1,3],"e":"Neuropraxie : préservation anatomique complète, perte transitoire de conduction, motricité plus touchée que sensibilité, récupération en jours/semaines, PAS de dégénérescence wallérienne.","s":1},{"q":"Quelle est la vitesse moyenne de régénération axonale après une axonotmèse ?","o":["0,1 mm/jour","1–2 mm/jour","1 cm/jour","10 cm/jour"],"r":1,"e":"L'axone régénère à environ 1–2 mm/jour, vitesse qui ralentit avec la distance au corps cellulaire.","s":1},{"q":"La dégénérescence de Waller correspond à :","o":["La régénération de l'axone après une lésion","La dégénérescence distale d'un axone sectionné","La démyélinisation auto-immune des nerfs","La formation d'un névrome, au bout du nerf"],"r":1,"e":"La dégénérescence de Waller est la dégénérescence de la portion distale d'un axone après section ou interruption. Elle prépare la repousse mais plus elle dure, plus la récupération est difficile.","s":1},{"q":"Concernant la NEUROTMÈSE (Seddon III / Sunderland V), quelles propositions sont vraies ?","o":["Une division complète du nerf","Des tubes neuraux détruits","Une récupération généralement totale","Un névrome possible lors de la repousse","Une chirurgie souvent nécessaire"],"r":[0,1,3,4],"e":"Neurotmèse = section complète, tubes neuraux détruits, formation possible d'un névrome, fonction parfois adéquate mais JAMAIS normale, chirurgie souvent indispensable.","s":1},{"q":"Une mononeuropathie correspond à :","o":["Atteinte symétrique distale et bilatérale","Atteinte d'un seul nerf isolé","Atteinte d'un plexus complet","Atteinte des racines spinales uniquement"],"r":1,"e":"Mononeuropathie = atteinte d'un nerf isolé (ex : canal carpien, paralysie faciale). La polyneuropathie = atteinte symétrique distale bilatérale.","s":1},{"q":"Parmi les pathologies suivantes, lesquelles sont des MONONEUROPATHIES ?","o":["Syndrome du canal carpien","Paralysie faciale (Bell)","Syndrome de Guillain-Barré","Polyneuropathie diabétique","Névralgie du trijumeau"],"r":[0,1,4],"e":"Mononeuropathies = canal carpien, paralysie faciale, névralgie du trijumeau. Guillain-Barré et la polyneuropathie diabétique sont des polyneuropathies.","s":1},{"q":"Une paralysie faciale PÉRIPHÉRIQUE atteint :","o":["Uniquement la moitié inférieure du visage, front épargné","La totalité d'un hémiface, front compris","Les deux hémifaces, de façon symétrique","Aucune zone du visage, seulement le goût"],"r":1,"e":"La paralysie périphérique (lésion du VII) touche TOUT l'hémiface du même côté (front + bouche). La paralysie centrale épargne le front (innervation bilatérale du frontal).","s":1},{"q":"Une lagophtalmie est :","o":["Une perte du goût","Une incapacité à fermer l'œil","Une larmoiement excessif","Une vision floue"],"r":1,"e":"La lagophtalmie = incapacité à fermer la paupière, signe classique de paralysie faciale périphérique. Elle expose la cornée et nécessite une protection oculaire.","s":1},{"q":"Concernant la paralysie faciale CENTRALE, quelles affirmations sont vraies ?","o":["Une lésion au-dessus du noyau du VII","Une atteinte surtout du bas du visage","Un front épargné, des deux côtés","Une association fréquente à un AVC","Une perte du goût sur l'avant de la langue"],"r":[0,1,2,3],"e":"Paralysie centrale : lésion supranucléaire (faisceau pyramidal), atteinte du visage inférieur, front épargné (innervation bilatérale), fréquente après AVC. La perte du goût est un signe périphérique.","s":1},{"q":"Le nerf facial (VII) assure la sensibilité gustative de :","o":["La totalité de la langue","Les 2/3 antérieurs de la langue","Le 1/3 postérieur de la langue","La pointe de la langue uniquement"],"r":1,"e":"Le VII (via la corde du tympan) innerve les 2/3 antérieurs de la langue pour le goût. Le 1/3 postérieur est innervé par le IX (glossopharyngien).","s":1},{"q":"Quelles sont des fonctions du nerf facial (VII) ?","o":["Motricité des muscles de la mimique","Innervation parasympathique des glandes lacrymales","Innervation parasympathique des glandes sublinguales","Innervation des muscles masticateurs","Innervation du muscle stapédien"],"r":[0,1,2,4],"e":"VII = mimique faciale + stapédien (motrice), goût (2/3 ant. langue) et parasympathique pour glandes lacrymales/salivaires sous-maxillaires/sublinguales. Les muscles masticateurs sont innervés par le V.","s":1},{"q":"Le syndrome de Guillain-Barré est une maladie :","o":["Vasculaire","Auto-immune","Tumorale","Génétique"],"r":1,"e":"Guillain-Barré = polyneuropathie auto-immune avec attaque des cellules de Schwann (démyélinisation), souvent post-infectieuse.","s":1},{"q":"Concernant le syndrome de Guillain-Barré, quelles affirmations sont vraies ?","o":["Une atteinte ascendante, depuis les jambes","Une évolution rapide, en jours","Un risque pour les muscles respiratoires","Une hyperréflexie typique, avec Babinski","Un traitement par immunoglobulines IV"],"r":[0,1,2,4],"e":"GBS : faiblesse musculaire ascendante rapide, paresthésies, AREFLEXIE (pas hyperréflexie), risque d'insuffisance respiratoire, traitement = Ig IV, plasmaphérèse, corticoïdes, soins intensifs.","s":1},{"q":"La polyneuropathie diabétique est typiquement :","o":["Asymétrique et proximale","Sensitivo-motrice symétrique distale","Purement motrice","Affectant uniquement les nerfs crâniens"],"r":1,"e":"La polyneuropathie diabétique est sensitivo-motrice, symétrique et distale (mains/pieds en gants/chaussettes). Le pied diabétique en est la complication la plus grave.","s":1},{"q":"Quels sont les mécanismes physiopathologiques de la polyneuropathie diabétique ?","o":["Microangiopathie distale","Ischémie","Glycation des protéines nerveuses","Excès de radicaux libres","Démyélinisation auto-immune"],"r":[0,1,2,3],"e":"PND : microangiopathie → ischémie → glycation des protéines + stress oxydatif (radicaux libres) → dégénérescence axonale et démyélinisation secondaire. L'auto-immunité concerne le GBS, pas le diabète.","s":1},{"q":"De quelles racines naît le plexus brachial ?","o":["C1 à C4","C5 à T1","T2 à T6","L1 à L4"],"r":1,"e":"Le plexus brachial naît des branches antérieures de C5, C6, C7, C8 et T1.","s":1},{"q":"La paralysie d'Erb-Duchenne correspond à une atteinte du :","o":["Tronc supérieur (C5-C6)","Tronc moyen (C7)","Tronc inférieur (C8-T1)","Plexus entier"],"r":0,"e":"Erb-Duchenne = atteinte du tronc supérieur C5-C6, déficit en abduction d'épaule, flexion du coude et rotation externe (paralysie obstétricale classique).","s":1},{"q":"La paralysie de Klumpke correspond à une atteinte du :","o":["Tronc supérieur (C5-C6)","Tronc moyen (C7)","Tronc inférieur (C8-T1)","Nerf radial isolé"],"r":2,"e":"Klumpke = atteinte du tronc inférieur C8-T1, déficit des muscles intrinsèques de la main et flexion des doigts (main en griffe).","s":1},{"q":"Quelles sont des étapes de la régénération axonale ?","o":["Réponse du corps cellulaire (germination)","Allongement guidé par les cellules de Schwann","Cessation et synaptogenèse","Remyélinisation progressive","Apoptose massive obligatoire"],"r":[0,1,2,3],"e":"Régénération axonale en 3 étapes : germination, allongement (guidé par Schwann + facteurs chimiques), cessation/synaptogenèse + remyélinisation. L'apoptose massive n'est pas une étape de la régénération.","s":1},{"q":"Une synkinésie correspond à :","o":["Une paralysie totale d'un muscle, après lésion","Un mouvement involontaire lié à un geste volontaire","Une douleur provoquée par le mouvement","Une atrophie progressive, par dénervation"],"r":1,"e":"Synkinésie = mouvement involontaire qui accompagne un mouvement volontaire (ex : fermer la paupière en souriant). Elle signe une régénération anormale et un mauvais pronostic.","s":1},{"q":"Concernant le tableau récapitulatif des lésions, l'AXONOTMÈSE (Sunderland II) se caractérise par :","o":["Axone interrompu","Endonèvre intact","Périnèvre détruit","Dégénérescence wallérienne","Pronostic excellent en quelques minutes"],"r":[0,1,3],"e":"Axonotmèse Sunderland II : axone interrompu, endonèvre/périnèvre/épinèvre intacts, dégénérescence wallérienne présente, récupération en mois (pas minutes).","s":1},{"q":"Concernant la régénération nerveuse, quelle affirmation est vraie ?","o":["Le SNC régénère mieux que le SNP","Le SNP peut régénérer, contrairement au SNC","Aucun nerf ne peut régénérer, ni central ni périphérique","Seul le SNC peut régénérer, grâce à la glie"],"r":1,"e":"Le SNP peut régénérer (cellules de Schwann, tubes neuraux préservés guidant la repousse). Le SNC ne régénère pratiquement pas (cicatrice gliale, pas de tubes guides).","s":1},{"q":"Parmi les étiologies de la paralysie faciale, on retrouve :","o":["Idiopathique (Bell)","Virale (zona, herpès)","Bactérienne (Lyme)","Traumatique","Cardiovasculaire ischémique"],"r":[0,1,2,3],"e":"Étiologies de la paralysie faciale : idiopathique (Bell, la plus fréquente), virale, bactérienne (Lyme), traumatique, congénitale, métabolique. La cause cardiovasculaire concerne plutôt la paralysie centrale (AVC).","s":1},{"q":"Une lésion du nerf médian au poignet provoque :","o":["Une main en griffe cubitale, sur les 4e et 5e doigts","Une atrophie thénar et une hypoesthésie des 3 premiers doigts","Une main de prédicateur, avec les doigts 2 et 3 restés en extension","Aucune atteinte, le nerf étant protégé"],"r":1,"e":"Lésion médian au poignet (canal carpien évolué) : atrophie thénarienne, déficit sensitif des 3 premiers doigts + moitié 4. La moitié du 4e doigt est aussi touchée.","s":1},{"q":"Une lésion du nerf cubital (ulnaire) provoque :","o":["Une main en griffe, sur les 4e et 5e doigts","Une main de prédicateur, sur les 2e et 3e doigts","Un pied tombant, avec un steppage à la marche rapide","Aucune atteinte motrice de la main"],"r":0,"e":"Lésion ulnaire : main en griffe cubitale (4e et 5e doigts), atrophie hypothénar et interosseux, déficit sensitif 5e doigt + moitié 4.","s":1},{"q":"Une paralysie du nerf radial provoque :","o":["Une main tombante, sans extension du poignet","Une main en griffe cubitale","Un pied tombant, avec steppage","Une hémiplégie, par lésion du cortex moteur controlatéral"],"r":0,"e":"Paralysie radiale : « main tombante » par paralysie des extenseurs du poignet et des doigts.","s":1},{"q":"Une paralysie du nerf SPE (sciatique poplité externe) provoque :","o":["Une main tombante, au poignet","Un pied tombant, avec steppage","Une atrophie de la main, côté thénar","Aucune atteinte de la marche"],"r":1,"e":"Paralysie du SPE (péronier commun) : pied tombant → steppage à la marche, déficit éversion + dorsiflexion.","s":1},{"q":"Le syndrome de Guillain-Barré est :","o":["Une lésion centrale, de la moelle épinière","Une polyradiculonévrite aiguë et auto-immune","Une myopathie, d'origine génétique","Une fracture, par traumatisme"],"r":1,"e":"GBS = polyradiculonévrite aiguë démyélinisante, post-infectieuse, paralysie ascendante symétrique, aréflexie. Elle est inflammatoire et démyélinisante.","s":1},{"q":"L'évolution typique du Guillain-Barré est :","o":["Une atteinte permanente → aucune évolution","Une extension → un plateau → une récupération","Une forme aiguë mortelle d'emblée → décès en jours","Aucune récupération → séquelles totales"],"r":1,"e":"GBS : 3 phases : extension (≤4 sem) → plateau → récupération (mois). Surveillance respi en USI (atteinte phrénique). L'extension dure 3 à 4 semaines et la récupération des mois.","s":1},{"q":"La paralysie faciale périphérique se distingue de la centrale par :","o":["Une asymétrie du bas du visage, front épargné","Une atteinte de tout l'hémiface, front compris","L'absence d'atteinte du front","L'absence de toute asymétrie"],"r":1,"e":"Périphérique : atteinte hémiface complète (front + bouche). Centrale : front respecté car innervation bilatérale.","s":1},{"q":"Le syndrome du canal carpien correspond à :","o":["Une compression du nerf médian au poignet","Une atteinte centrale, cervicale","Une lésion du nerf radial, dans la gouttière humérale","Une atteinte du nerf sciatique"],"r":0,"e":"Canal carpien : compression du nerf médian au poignet → paresthésies/hypoesthésie nocturnes pouce-index-majeur, ± atrophie thénar tardive.","s":1},{"q":"L'EMG (électromyographie) permet de :","o":["Mesurer la tension artérielle, au bras","Évaluer la conduction nerveuse et l'activité musculaire","Mesurer la glycémie, au doigt","Imager le cerveau, en coupes, avec un champ magnétique puissant"],"r":1,"e":"EMG/ENMG : étude conduction nerveuse + tracé musculaire → atteinte neurogène (axonale, démyélinisante) vs myogène. Il distingue une atteinte neurogène d'une atteinte myogène.","s":1},{"q":"La régénération nerveuse périphérique se fait à :","o":["Environ 10 mm par jour","Environ 1 à 3 mm par jour","Environ 100 mm par jour","Aucune vitesse, sans régénération"],"r":1,"e":"Régénération axonale ~1-3 mm/jour après dégénérescence wallérienne distale. Centrale = pas de régénération.","s":1},{"q":"À quelle vitesse l'influx circule-t-il sur une fibre à myéline intacte ?","o":["Environ 400 km/h","Environ 4 km/h","Environ 40 km/h","Environ 4 000 km/h"],"r":0,"e":"La fiche oppose 400 km/h avec myéline intacte à 4 km/h après destruction de la myéline.","s":1},{"q":"Quelle caractéristique a l'axone préganglionnaire sympathique ?","o":["Il est peu myélinisé, la noradrénaline venant ensuite","Il est très myélinisé et cholinergique","Il n'est pas myélinisé du tout, comme les fibres C de la douleur","Il est seul, sans neurone postganglionnaire"],"r":0,"e":"Le sympathique comporte deux neurones, avec un axone préganglionnaire peu myélinisé et de la noradrénaline en aval.","s":1},{"q":"Quels mécanismes lésionnels du nerf périphérique la fiche énumère-t-elle ?","o":["Ischémie, traction, compression, lacération, brûlure","Infection, inflammation, tumeur, toxique, génétique","Étirement, luxation, fracture, œdème, hématome","Dénutrition, déshydratation, hypoxie, acidose, fièvre"],"r":0,"e":"Ces cinq mécanismes sont ceux listés dans la fiche pour les neuropathies traumatiques.","s":1},{"q":"Quelle est l'atteinte anatomique dans l'ischémie transitoire (stade 0) ?","o":["Aucune structure n'est lésée, l'anoxie étant aiguë","L'axone est interrompu, sous la lésion","L'endonèvre est détruit, avec les tubes neuraux du nerf","Le nerf est complètement sectionné"],"r":0,"e":"Au stade 0, toutes les structures restent intactes, sans dégénérescence wallérienne, avec récupération en 10 minutes. L'anoxie est endonévrale.","s":1},{"q":"Quel type de compression est à l'origine de la neuropraxie ?","o":["Une compression neurale chronique","Une compression aiguë de quelques minutes","Une section franche","Une brûlure profonde"],"r":0,"e":"La neuropraxie résulte d'une compression chronique, alors que le stade 0 correspond à une compression aiguë brève.","s":1},{"q":"Quel est l'état de la sensibilité dans une neuropraxie ?","o":["Préservée, avec parfois des dysesthésies","Toujours abolie, sur tout le territoire","Abolie en gant ou en chaussette","Remplacée par une hyperesthésie"],"r":0,"e":"La neuropraxie donne surtout une perte motrice temporaire ; la sensibilité est habituellement conservée.","s":1},{"q":"À quels stades de Sunderland l'axonotmèse correspond-elle ?","o":["Sunderland II à IV","Sunderland I","Sunderland V","Sunderland I et II"],"r":0,"e":"Seddon II = Sunderland II-IV ; Sunderland I est la neuropraxie et V la neurotmèse.","s":1},{"q":"Quelles structures sont détruites dans une axonotmèse de stade IV ?","o":["L'endonèvre et le périnèvre, sans l'épinèvre","L'endonèvre seul, les autres restant intacts","Toutes les enveloppes, épinèvre compris, avec section","Aucune enveloppe, seul l'axone étant touché"],"r":0,"e":"Le stade IV détruit endonèvre et périnèvre mais respecte l'épinèvre, d'où un mauvais pronostic sans section complète.","s":1},{"q":"Quelle différence sépare l'axonotmèse de stade II de celle de stade III ?","o":["Au stade III l'endonèvre est détruit, pas au stade II","Au stade III l'axone est intact, alors qu'il est rompu au stade II","Au stade II il n'y a pas de dégénérescence wallérienne","Au stade III l'épinèvre est détruit"],"r":0,"e":"La destruction de l'endonèvre au stade III compromet le guidage de la repousse, d'où une récupération partielle.","s":1},{"q":"De quoi est constitué un névrome après neurotmèse ?","o":["De fibres, de cellules de Schwann et de fibroblastes","Uniquement de tissu cicatriciel, avasculaire et sans fibres","De cellules gliales du SNC, en amas","De dépôts amyloïdes, extracellulaires"],"r":0,"e":"La repousse désorganisée dans un nerf sectionné forme ce bourgeon fibro-nerveux. Les fibres sont régénératives.","s":1},{"q":"Qu'est-ce qui guide le cône de croissance lors de la régénération axonale ?","o":["Les cellules de Schwann et des facteurs chimiques","Les oligodendrocytes, comme dans le SNC","Les fibroblastes de l'épinèvre","La myéline résiduelle du segment distal, intacte et compacte"],"r":0,"e":"Les cellules de Schwann prolifèrent et balisent le trajet, aidées par des facteurs chimiotactiques. Ces facteurs sont des angioneurines.","s":1},{"q":"Quelle est la troisième étape de la régénération axonale ?","o":["L'arrêt de l'allongement et la synaptogenèse","La germination à partir du corps cellulaire","L'allongement guidé par le cône","La dégénérescence wallérienne distale"],"r":0,"e":"Après la réponse du corps cellulaire et l'allongement, la repousse s'arrête et de nouvelles synapses se forment. Elle s'accompagne d'une remyélinisation.","s":1},{"q":"Le thalamus joue principalement le rôle de :","o":["Le centre moteur principal, qui commande les muscles","Le grand relais sensoriel, sauf pour l'olfaction","Le centre du langage, à gauche","Le régulateur hormonal, comme l'hypophyse"],"r":1,"e":"Le thalamus est le grand relais sensoriel : TOUTES les afférences sensorielles (sauf olfactives) y font relais avant d'atteindre le cortex.","s":2},{"q":"Quelles structures composent les ganglions de la base ?","o":["Noyau caudé","Putamen","Globus pallidus","Noyau subthalamique","Thalamus"],"r":[0,1,2,3],"e":"Ganglions de la base : noyau caudé + putamen (= striatum), globus pallidus, noyau subthalamique. Le thalamus est une structure distincte mais très liée fonctionnellement.","s":2},{"q":"L'aire de Broca, située dans le lobe frontal, est responsable de :","o":["La compréhension du langage oral","La production motrice du langage parlé","La vision, dans le cortex visuel","L'audition, dans le cortex auditif"],"r":1,"e":"L'aire de Broca (frontal gauche) = production motrice du langage. L'aire de Wernicke (temporal) = compréhension du langage.","s":2},{"q":"Concernant les lobes cérébraux, quelles correspondances sont correctes ?","o":["Lobe frontal, motricité et Broca","Lobe pariétal, somesthésie et schéma corporel","Lobe temporal, audition, Wernicke et mémoire","Lobe occipital, vision","Lobe occipital, langage et mémoire"],"r":[0,1,2,3],"e":"Frontal = motricité + Broca + jugement ; Pariétal = somatosensoriel + schéma corporel ; Temporal = audition + Wernicke + mémoire ; Occipital = vision.","s":2},{"q":"Le système carotidien irrigue principalement :","o":["Les deux tiers antérieurs du cerveau","Le tronc cérébral et le cervelet, en arrière","Les lobes occipitaux, en arrière","La moelle épinière cervicale"],"r":0,"e":"Système carotidien (circulation antérieure) = 2/3 antérieurs du cerveau. Le système vertébro-basilaire (postérieur) irrigue tronc, cervelet, lobes occipitaux.","s":2},{"q":"Quelles artères naissent directement de l'artère carotide interne ?","o":["Artère cérébrale antérieure (ACA)","Artère cérébrale moyenne (ACM)","Artère ophtalmique","Artère cérébrale postérieure (ACP)","Artère choroïdienne antérieure"],"r":[0,1,2,4],"e":"De l'ACI naissent : ACA, ACM (sa branche principale), ophtalmique, choroïdienne antérieure et communicante postérieure. L'ACP naît du tronc basilaire (vertébro-basilaire).","s":2},{"q":"Le polygone de Willis est :","o":["Un faisceau de fibres motrices, du cortex à la moelle","Un réseau anastomotique entre les deux circulations","Une zone du cortex visuel, en occipital","Une voie sensitive descendante, inhibitrice"],"r":1,"e":"Le polygone de Willis est un réseau anastomotique à la base du cerveau qui relie les circulations carotidienne et vertébro-basilaire. Il permet la redistribution du flux en cas d'occlusion. Il relie les circulations antérieure et postérieure.","s":2},{"q":"Un AVC ischémique représente environ quelle proportion de tous les AVC ?","o":["50%","65%","85%","98%"],"r":2,"e":"L'AVC ischémique représente ~85% des AVC. L'AVC hémorragique représente les 15% restants mais a une mortalité plus élevée.","s":2},{"q":"Concernant l'AIT (Accident Ischémique Transitoire), quelles affirmations sont vraies ?","o":["Déficit neurologique focal","Durée < 24h","Lésion visible à l'imagerie","Signe d'alerte d'AVC à venir","Pas besoin de prise en charge"],"r":[0,1,3],"e":"AIT : déficit focal de < 24h SANS lésion à l'imagerie. C'est un signe d'alerte majeur pour un AVC futur — prise en charge urgente nécessaire.","s":2},{"q":"Le traitement de référence d'un AVC ischémique en phase aiguë est :","o":["Les anti-hypertenseurs, pour baisser la pression","La thrombolyse et la thrombectomie","Les anti-épileptiques, en prévention","Les corticoïdes, contre l'œdème"],"r":1,"e":"Le traitement aigu de l'AVC ischémique = rTPA (thrombolyse intraveineuse) si <4,5h, et/ou thrombectomie mécanique. Le délai est crucial : 'time is brain'. La thrombolyse utilise le rTPA.","s":2},{"q":"Concernant l'évolution clinique après AVC, dans quel ordre apparaissent les phases ?","o":["1. Hypotonie/aréflexie initiale","2. Hypertonie et co-contraction (spasticité)","3. Modèles synergiques de mouvement","4. Spasticité immédiate dès le début","5. Hypotonie permanente sans récupération"],"r":[0,1,2],"e":"Évolution AVC : phase 1 = hypotonie/aréflexie (choc) → phase 2 = hypertonie/spasticité → phase 3 = mouvements synergiques puis sélectifs. Pas de spasticité immédiate.","s":2},{"q":"Un hématome épidural se développe typiquement en :","o":["Quelques minutes","Quelques heures","Plusieurs jours","Plusieurs mois"],"r":1,"e":"Hématome épidural : développement en quelques HEURES (souvent par rupture de l'artère méningée moyenne). Sous-dural subaigu = jours, sous-dural chronique = mois.","s":2},{"q":"Concernant la maladie de Parkinson, quelles affirmations sont vraies ?","o":["Dégénérescence de la substance noire","Perte des récepteurs dopaminergiques","Hyperréflexie typique","Tremblement au REPOS","Bradykinésie"],"r":[0,1,3,4],"e":"Parkinson : dégénérescence dopaminergique de la substance noire → bradykinésie, tremblement de REPOS, rigidité, instabilité posturale. Les réflexes ne sont PAS hyperactifs.","s":2},{"q":"La rigidité 'en roue dentée' est typique de quelle maladie ?","o":["Sclérose en plaques","Maladie de Parkinson","Syndrome de Guillain-Barré","Maladie d'Alzheimer"],"r":1,"e":"La rigidité en roue dentée (résistance saccadée à la mobilisation passive) est un signe cardinal de la maladie de Parkinson, avec la bradykinésie et le tremblement de repos.","s":2},{"q":"Parmi les signes moteurs de Parkinson, on retrouve :","o":["La bradykinésie, ou lenteur","La micrographie, en écrivant","L'amimie, ou visage figé","Une marche à grands pas, avec ballant","Le freezing, ou enrayage"],"r":[0,1,2,4],"e":"Signes moteurs Parkinson : bradykinésie, micrographie, amimie, hypophonie, marche à PETITS pas (festination, perte du ballant), freezing, tremblement de repos.","s":2},{"q":"Le traitement médicamenteux principal de la maladie de Parkinson est :","o":["Lévodopa","Corticoïdes","Antiépileptiques","Interférons"],"r":0,"e":"La lévodopa (souvent associée à la carbidopa) est le traitement de référence : précurseur de la dopamine qui passe la barrière hémato-encéphalique.","s":2},{"q":"Les '5 A' de la démence comprennent :","o":["Amnésie","Anomie","Apraxie","Agnosie","Aphasie","Ataxie"],"r":[0,1,2,3,4],"e":"Les 5 A de la démence : Amnésie (mémoire), Anomie (oubli des mots), Apraxie (gestes), Agnosie (reconnaissance), Aphasie (langage). L'ataxie est un trouble de la coordination d'origine cérébelleuse ou proprioceptive, hors du champ des « 5 A » cognitifs.","s":2},{"q":"Concernant la physiopathologie de la maladie d'Alzheimer, quelles affirmations sont correctes ?","o":["Des plaques amyloïdes extracellulaires","Des tresses neurofibrillaires de protéine tau","Une démyélinisation auto-immune des axones","Une dégénérescence des neurones dopaminergiques","Une réponse des astrocytes et de la microglie"],"r":[0,1,4],"e":"Alzheimer : plaques amyloïdes (Aβ) extracellulaires + tresses neurofibrillaires (tau) intracellulaires + neuroinflammation. La démyélinisation = SEP, la dégénérescence dopaminergique = Parkinson.","s":2},{"q":"La sclérose en plaques (SEP) est :","o":["Une maladie auto-immune attaquant les oligodendrocytes","Une maladie vasculaire, par infarctus dans la substance blanche","Une maladie tumorale d'origine gliale","Une maladie génétique, à transmission dominante"],"r":0,"e":"SEP = maladie auto-immune attaquant les oligodendrocytes (cellules myélinisantes du SNC) → démyélinisation de la substance blanche par plaques disséminées dans le temps et l'espace.","s":2},{"q":"Quels facteurs peuvent aggraver ou déclencher une poussée de SEP ?","o":["Chaleur","Stress","Effort physique","Infections","Repos prolongé"],"r":[0,1,2,3],"e":"Facteurs aggravants/déclenchants de SEP : chaleur (signe d'Uhthoff), stress, effort physique, infections. Le repos n'est pas un déclencheur.","s":2},{"q":"La SLA (sclérose latérale amyotrophique) atteint :","o":["Le seul 2e motoneurone, dans la corne antérieure","Les 1er et 2e motoneurones","La sensibilité uniquement, par les cordons","La cognition uniquement, par le cortex"],"r":1,"e":"La SLA atteint à la fois le motoneurone supérieur (1er, central) ET le motoneurone inférieur (2e, périphérique). La sensibilité et la cognition restent INTACTES — paralysie progressive sans déficit sensitif.","s":2},{"q":"La myasthénie grave est due à :","o":["Une auto-immunité contre les récepteurs à l'ACh","Une perte de neurones de la substance noire","Une démyélinisation du SNC, en plaques","Une atteinte vasculaire du tronc cérébral"],"r":0,"e":"La myasthénie grave est une maladie auto-immune ciblant les récepteurs nicotiniques à l'acétylcholine de la jonction neuromusculaire. D'où la fatigabilité musculaire fluctuante.","s":2},{"q":"Quels sont les signes du SYNDROME CÉRÉBELLEUX ?","o":["Une ataxie de la marche","Une hypotonie musculaire","Une dysmétrie du geste","Une dysarthrie, ou parole scandée","Une hypertonie spastique"],"r":[0,1,2,3],"e":"Syndrome cérébelleux : ataxie, dysmétrie, dysdiadococinésie, dysarthrie, tremblement intentionnel, hypotonie. L'hypertonie spastique signe une atteinte pyramidale, PAS cérébelleuse.","s":2},{"q":"Quel examen offre la meilleure résolution SPATIALE pour visualiser les structures molles du cerveau ?","o":["EEG","EMG","TDM (scanner)","IRM"],"r":3,"e":"L'IRM offre la meilleure résolution spatiale pour les tissus mous (matière blanche/grise, lésions). L'EEG a la meilleure résolution TEMPORELLE.","s":2},{"q":"En urgence pour un AVC suspecté, quel examen est réalisé en premier ?","o":["Un EEG, pour les crises","Un EMG des quatre membres","Une TDM cérébrale, ou scanner","Une IRM fonctionnelle cérébrale"],"r":2,"e":"En urgence AVC : TDM cérébrale d'abord (rapide, accessible, élimine l'hémorragie). L'IRM peut être réalisée ensuite pour mieux visualiser l'ischémie aiguë.","s":2},{"q":"Parmi les principes de la NEUROPLASTICITÉ, on retrouve :","o":["Use it or lose it, utiliser ou perdre","Specificity, la spécificité de l'entraînement","Repetition, des milliers de répétitions","Salience, l'émotion et la motivation","Le repos absolu, qui favorise la récupération"],"r":[0,1,2,3],"e":"Neuroplasticité (10 principes) : use it or lose it, use it & improve it, specificity, repetition, intensity, time, salience, age, transference, interference. Le repos absolu n'en fait PAS partie.","s":2},{"q":"Une crise d'épilepsie 'petit mal' (absence) se caractérise par :","o":["Des convulsions tonico-cloniques généralisées","Un regard perdu de 10 à 30 secondes, sans chute","Une paralysie d'un hémicorps, de 24 heures","Une perte définitive de conscience"],"r":1,"e":"L'absence (petit mal) = brève suspension de conscience (10-30 sec) avec regard fixe, sans convulsions ni chute. Surtout chez l'enfant.","s":2},{"q":"Quelles affirmations sur la VASCULARISATION cérébrale sont vraies ?","o":["L'ACM est la branche principale de l'ACI","Le système vertébro-basilaire irrigue le tronc et le cervelet","La PICA est la plus grande branche de l'artère vertébrale","L'ACP naît directement de la carotide interne","Le polygone de Willis relie les deux systèmes"],"r":[0,1,2,4],"e":"ACM = branche principale de l'ACI ; système vertébro-basilaire = tronc/cervelet/occipital ; PICA = grande branche de l'artère vertébrale ; polygone de Willis relie carotidien et vertébro-basilaire. L'ACP naît du tronc basilaire, PAS de l'ACI.","s":2},{"q":"L'AVC ischémique représente :","o":["10% des AVC","30% des AVC","~80% des AVC","100%"],"r":2,"e":"AVC : 80% ischémiques (occlusion artérielle), 20% hémorragiques (rupture vasculaire).","s":2},{"q":"La fenêtre thérapeutique pour la thrombolyse IV (rt-PA) dans l'AVC ischémique est de :","o":["1 heure","4h30","12 heures","24 heures"],"r":1,"e":"Thrombolyse IV (rt-PA) : ≤ 4h30 après début des symptômes. Thrombectomie possible jusqu'à 6-24h selon imagerie.","s":2},{"q":"Une hémiplégie droite + aphasie de Broca évoque une lésion :","o":["Du cervelet droit, avec une ataxie homolatérale","De l'hémisphère gauche, pyramidal et Broca","Du tronc cérébral, au niveau du bulbe","Médullaire, au niveau cervical"],"r":1,"e":"Hémisphère gauche dominant : moteur droit (pyramidal croisé) + langage (Broca). AVC sylvien gauche.","s":2},{"q":"Le signe de Babinski (extension du gros orteil) traduit :","o":["Un réflexe normal chez l'adulte","Une atteinte du faisceau pyramidal","Une atteinte cérébelleuse, avec une ataxie associée","Une lésion sensitive, du cordon postérieur"],"r":1,"e":"Babinski + = atteinte du faisceau pyramidal (cortico-spinal), signe d'atteinte 1er motoneurone. C'est une atteinte du 1er motoneurone.","s":2},{"q":"L'hémorragie sous-arachnoïdienne (HSA) est typiquement due à :","o":["Une hypertension chronique","La rupture d'un anévrisme cérébral","Un AVC ischémique, par embolie","Une tumeur cérébrale, qui saigne brutalement"],"r":1,"e":"HSA : 80% par rupture d'anévrisme. Céphalée brutale en coup de tonnerre + raideur méningée.","s":2},{"q":"Un hématome extra-dural est typiquement causé par :","o":["La rupture d'un anévrisme cérébral","La rupture de l'artère méningée moyenne","Un AVC hémorragique, par hypertension","Une tumeur, avec un saignement interne"],"r":1,"e":"Hématome EDL : entre l'os et la dure-mère, rupture art. méningée moyenne, intervalle libre puis aggravation. Elle fait suite à un traumatisme crânien.","s":2},{"q":"L'intervalle libre est caractéristique :","o":["De l'AVC ischémique, au réveil","De l'hématome extra-dural traumatique","De la tumeur cérébrale, au stade avancé et évolutif","De la méningite bactérienne"],"r":1,"e":"Intervalle libre (lucidité initiale puis aggravation) = signe classique de l'hématome EDL après TC.","s":2},{"q":"L'œdème cérébral entraîne :","o":["↓ pression intracrânienne → céphalées","↑ pression intracrânienne → engagement","Aucun effet → résorption spontanée sans aucune séquelle","Hyperventilation → alcalose"],"r":1,"e":"Œdème → ↑ PIC → triade de Cushing (HTA, bradycardie, irrégularité respi), risque d'engagement et mort cérébrale.","s":2},{"q":"Les facteurs de risque modifiables d'AVC incluent :","o":["HTA","Diabète","Dyslipidémie","Tabac","FA / cardiopathie","Âge","Sexe masculin"],"r":[0,1,2,3,4],"e":"Modifiables : HTA (#1), diabète, dyslipidémie, tabac, FA, obésité, sédentarité. Non modifiables : âge, sexe, génétique.","s":2},{"q":"L'hémianopsie latérale homonyme correspond à :","o":["La perte de la vision d'un seul œil, côté lésé","La perte du même hémichamp aux deux yeux","Une vision floue, par trouble réfractif","Un strabisme, par paralysie oculomotrice"],"r":1,"e":"Hémianopsie latérale homonyme = perte du même hémichamp des deux yeux, lésion rétro-chiasmatique (radiations optiques, V1).","s":2},{"q":"Quelles structures composent le système limbique selon la fiche ?","o":["Amygdale, hippocampe, fornix et hypothalamus","Thalamus, épithalamus et subthalamus","Noyau caudé, putamen et globus pallidus","Mésencéphale, pont et bulbe"],"r":0,"e":"Le système limbique associe ces quatre structures et gère comportements, mémoire émotionnelle et motivation.","s":2},{"q":"Quelle particularité de latéralité caractérise le cervelet ?","o":["Ses fibres sont ipsilatérales","Ses fibres sont toutes croisées","Il n'a aucune connexion latéralisée","Il ne reçoit que des fibres controlatérales"],"r":0,"e":"Le cervelet agit sur l'hémicorps du même côté, contrairement au cortex moteur.","s":2},{"q":"Quel rôle la fiche attribue-t-elle aux ganglions de la base ?","o":["L'idéalisation et la préparation du mouvement","L'exécution directe du mouvement","Le relais des informations sensorielles","La production du LCR, dans les ventricules"],"r":0,"e":"Les noyaux gris centraux préparent et modulent le mouvement via les voies directe et indirecte ; le relais sensoriel est thalamique.","s":2},{"q":"Quel élément des ganglions de la base la fiche décrit-elle comme inhibiteur ?","o":["Le globus pallidus","Le noyau caudé","Le putamen","Le noyau subthalamique"],"r":0,"e":"Le globe pâle est le versant inhibiteur du dispositif ; caudé et putamen forment le striatum d'entrée.","s":2},{"q":"Quelles fonctions le lobe pariétal assure-t-il ?","o":["Somesthésie, schéma corporel et intelligence spatiale","Audition et compréhension du langage","Traitement visuel et reconnaissance d'objets, couleurs et formes","Pensée, jugement et production du langage"],"r":0,"e":"Le pariétal est somatosensoriel et spatial ; Wernicke est temporale et Broca frontale.","s":2},{"q":"Quelles fibres de substance blanche relient les deux hémisphères ?","o":["Les fibres commissurales","Les fibres d'association","Les fibres de projection","Les fibres perforantes"],"r":0,"e":"Les commissurales traversent la ligne médiane, les fibres d'association restent dans un hémisphère.","s":2},{"q":"Quelle proportion du cerveau le système carotidien irrigue-t-il ?","o":["Les deux tiers antérieurs","Le tiers postérieur","La totalité","Le cervelet et le tronc"],"r":0,"e":"La circulation antérieure carotidienne couvre les deux tiers antérieurs ; le système vertébro-basilaire irrigue tronc, cervelet et lobes occipitaux.","s":2},{"q":"Quelle est la branche principale de l'artère carotide interne ?","o":["L'artère cérébrale moyenne, dans la vallée sylvienne","L'artère cérébrale postérieure, vers l'occipital","L'artère basilaire, née de la réunion des deux vertébrales","La PICA, vers le cervelet"],"r":0,"e":"L'ACM est la branche terminale principale de l'ACI et chemine dans la vallée sylvienne.","s":2},{"q":"Quelle est la plus grande branche de l'artère vertébrale ?","o":["La PICA","L'AICA","L'ACS","L'artère spinale antérieure"],"r":0,"e":"La PICA (cérébelleuse postéro-inférieure) est la plus grande branche de la vertébrale.","s":2},{"q":"Quel est l'intérêt fonctionnel du polygone de Willis ?","o":["Redistribuer le flux sanguin en cas d'occlusion","Filtrer le LCR avant son retour dans le sang veineux","Réguler la pression intracrânienne","Assurer le drainage veineux du cerveau"],"r":0,"e":"Ce réseau anastomotique relie circulations antérieure et postérieure et supplée une occlusion.","s":2},{"q":"Quelles artères relie l'artère communicante postérieure ?","o":["La carotide interne et l'artère cérébrale postérieure","Les deux artères cérébrales antérieures, en avant du chiasma","Les deux artères vertébrales, sur le bulbe","L'artère basilaire et l'ACM"],"r":0,"e":"L'AComP referme le polygone en arrière ; l'AComA relie les deux cérébrales antérieures.","s":2},{"q":"Quelles altérations primaires la fiche décrit-elle après lésion cérébrale ?","o":["Une baisse du nombre d'unités motrices et de la force","Des rétractions et un désalignement des fibres","Des modifications de la coaptation articulaire","Des complications respiratoires, par encombrement et alitement"],"r":0,"e":"Les altérations citées en premier sont primaires ; rétractions, atteintes articulaires et complications respiratoires sont secondaires. La fréquence de décharge baisse et le timing d'activation est modifié.","s":2},{"q":"Quelles structures composent le Système Nerveux Central (SNC) ?","o":["Nerfs et ganglions","Encéphale et moelle épinière","Encéphale, moelle et nerfs crâniens","Cerveau seul"],"r":1,"e":"Le SNC = encéphale (cerveau, cervelet, tronc cérébral) + moelle épinière. Les nerfs et ganglions appartiennent au SNP.","s":3},{"q":"Combien de paires de nerfs crâniens et de nerfs rachidiens compte-t-on respectivement ?","o":["10 paires crâniennes et 30 paires rachidiennes","12 paires crâniennes et 31 paires rachidiennes","12 paires crâniennes et 33 paires rachidiennes","8 paires crâniennes et 31 paires rachidiennes"],"r":1,"e":"12 paires de nerfs crâniens (voie corticobulbaire) et 31 paires de nerfs rachidiens (voie cortico-spinale).","s":3},{"q":"Parmi les structures suivantes, lesquelles font partie de l'encéphale ?","o":["Cerveau","Cervelet","Tronc cérébral","Moelle épinière","Ganglions"],"r":[0,1,2],"e":"L'encéphale comprend cerveau + cervelet + tronc cérébral. La moelle épinière fait partie du SNC mais pas de l'encéphale. Les ganglions sont dans le SNP.","s":3},{"q":"Concernant le système nerveux autonome (viscéral), quelles affirmations sont vraies ?","o":["Il innerve les muscles squelettiques","Il innerve les muscles lisses, le cœur et les glandes","Il comprend le sympathique et le parasympathique","Il est sous contrôle volontaire, comme la motricité","Il a une composante afférente, viscérale"],"r":[1,2,4],"e":"Le SN autonome est involontaire. Il innerve muscles lisses/cœur/glandes. Il comprend sympathique (combat/fuite) et parasympathique (repos/digestion). Les muscles squelettiques relèvent du SN somatique.","s":3},{"q":"Quelle est la fonction principale du cervelet ?","o":["Fonctions cognitives supérieures","Coordination et équilibre","Fonctions vitales (respiration, rythme cardiaque)","Relais sensitif et moteur"],"r":1,"e":"Le cervelet est responsable de la coordination motrice et de l'équilibre. Les fonctions cognitives = cerveau ; les fonctions vitales = tronc cérébral.","s":3},{"q":"Le système sympathique est associé à :","o":["La digestion et le repos","Le combat ou la fuite","La sécrétion lacrymale","Le ralentissement cardiaque"],"r":1,"e":"Le sympathique correspond à la réaction « combat ou fuite » : dilatation pupillaire, accélération cardiaque, dilatation bronchique, sécrétion d'adrénaline.","s":3},{"q":"Parmi les nerfs crâniens suivants, lesquels sont purement SENSITIFS ?","o":["I — Olfactif","II — Optique","V — Trijumeau","VIII — Vestibulocochléaire","XII — Hypoglosse"],"r":[0,1,3],"e":"Les nerfs sensitifs purs sont I (olfactif), II (optique) et VIII (vestibulocochléaire). Le V (trijumeau) est mixte. Le XII (hypoglosse) est moteur.","s":3},{"q":"Quel nerf crânien innerve les muscles de la langue ?","o":["IX — Glossopharyngien","X — Vague","XI — Accessoire","XII — Hypoglosse"],"r":3,"e":"Le XII (hypoglosse) est moteur pour les muscles de la langue. Une déviation de la langue à la protraction = lésion du XII homolatéral.","s":3},{"q":"Quel nerf crânien évalue-t-on en demandant au patient de sourire, fermer les yeux fortement et froncer les sourcils ?","o":["V — Trijumeau","VII — Facial","IX — Glossopharyngien","XI — Spinal"],"r":1,"e":"Le VII (facial) innerve les muscles de la mimique. Tester : sourire, fermer paupières, froncer sourcils, gonfler les joues.","s":3},{"q":"Quelles sont les fonctions du nerf vague (X) ?","o":["L'innervation du cœur","L'innervation des bronches","L'innervation du tube digestif","Les mouvements des yeux","L'audition et l'équilibre"],"r":[0,1,2],"e":"Le X (vague/pneumogastrique) innerve cœur, bronches et tube digestif (parasympathique). Le mouvement des yeux relève des III, IV, VI ; l'audition du VIII.","s":3},{"q":"Sur l'échelle de Glasgow, quel est le score minimum possible ?","o":["0","1","3","5"],"r":2,"e":"Le score de Glasgow va de 3 (minimum) à 15 (maximum). Le minimum de 3 correspond à 1 (oculaire) + 1 (verbal) + 1 (moteur).","s":3},{"q":"Un score de Glasgow ≤ 8 correspond à :","o":["Un traumatisme léger","Un traumatisme modéré","Un traumatisme sévère / coma","Une conscience normale"],"r":2,"e":"Glasgow 13-15 = traumatisme léger ; 9-12 = modéré ; ≤ 8 = sévère, coma.","s":3},{"q":"Concernant la cotation 0-5 de la force musculaire, quelles propositions sont exactes ?","o":["0, aucune contraction visible","2, un mouvement contre la gravité","3, un mouvement contre la gravité seule","4, un mouvement contre une résistance","5, une absence totale de force"],"r":[0,2,3],"e":"0 = aucune contraction ; 1 = contraction visible ; 2 = mouvement SANS gravité ; 3 = mouvement CONTRE gravité ; 4 = contre résistance ; 5 = force normale.","s":3},{"q":"Une spasticité (hypertonie) signe une atteinte de :","o":["La corne antérieure de la moelle","La voie pyramidale","Le nerf périphérique","La jonction neuromusculaire"],"r":1,"e":"Spasticité = hypertonie élastique signant une atteinte de la voie pyramidale (motoneurone supérieur). La corne antérieure / SNP donnent une hypotonie.","s":3},{"q":"Une hypotonie + aréflexie + atrophie musculaire évoque :","o":["Une lésion du nerf périphérique","Une lésion de la voie pyramidale","Une lésion du cervelet, avec ataxie","Une lésion thalamique"],"r":0,"e":"Le syndrome neurogène périphérique = hypotonie + aréflexie + atrophie + fasciculations. Atteinte du motoneurone inférieur ou du nerf périphérique. Le SNP est en cause, ou le motoneurone inférieur.","s":3},{"q":"Parmi les éléments suivants, lesquels font partie de l'évaluation de la sensibilité de BASE ?","o":["La sensibilité douloureuse, à la piqûre","La sensibilité vibratoire, au diapason","La stéréognosie, par la reconnaissance d'objets","La proprioception, par le sens de position","La graphesthésie, par les chiffres tracés"],"r":[0,1,3],"e":"Sensibilité de base : douloureuse, vibratoire, proprioceptive, tactile. Stéréognosie et graphesthésie relèvent de la sensibilité DISCRIMINATIVE.","s":3},{"q":"Le réflexe rotulien explore principalement la racine :","o":["L2","L4","S1","C7"],"r":1,"e":"Réflexe rotulien = L4. Achilléen = S1. Bicipital = C5-C6. Tricipital = C7.","s":3},{"q":"Le test de Romberg permet d'évaluer :","o":["La force musculaire","La coordination cérébelleuse pure","L'équilibre proprioceptif","Les réflexes ostéo-tendineux"],"r":2,"e":"Le test de Romberg (debout pieds joints, yeux fermés) évalue l'équilibre proprioceptif. Une chute aux yeux fermés = ataxie sensitive (proprioceptive).","s":3},{"q":"Quels sont les tests cérébelleux classiques ?","o":["Épreuve doigt-nez","Épreuve talon-genou","Mouvements alternés rapides (diadococinésie)","Test de Romberg yeux fermés","Réflexe cutané plantaire"],"r":[0,1,2],"e":"Tests cérébelleux : doigt-nez, talon-genou, mouvements alternés rapides (dysdiadococinésie). Le Romberg explore la proprioception, pas le cervelet pur. Le réflexe cutané plantaire explore la voie pyramidale.","s":3},{"q":"Quels sont les signes d'irritation méningée ?","o":["Raideur de nuque","Signe de Brudzinski","Signe de Kernig","Signe de Babinski","Signe de Lasègue"],"r":[0,1,2],"e":"Signes méningés : raideur de nuque, Brudzinski (flexion des hanches lors de la flexion du cou), Kernig. Babinski = atteinte pyramidale ; Lasègue = sciatalgie.","s":3},{"q":"Une marche en circumduction du membre inférieur, avec bras fléchi en écharpe, évoque :","o":["Une marche parkinsonienne","Une marche hémiplégique","Une ataxie cérébelleuse","Un steppage"],"r":1,"e":"Cette description = marche hémiplégique (lésion vasculaire du SNC controlatéral). Parkinson = petits pas/festination ; cérébelleuse = ébrieuse ; steppage = relevé du pied.","s":3},{"q":"Le steppage (footdrop) est dû à :","o":["Une atteinte du cervelet","Une paralysie des releveurs du pied","Une lésion parkinsonienne, avec rigidité","Une lésion du nerf vague"],"r":1,"e":"Le steppage = paralysie des releveurs du pied (souvent atteinte du nerf fibulaire/sciatique poplité externe). Le patient soulève exagérément le genou pour ne pas accrocher l'orteil.","s":3},{"q":"Le topodiagnostic correspond à :","o":["Le diagnostic du mécanisme physiopathologique","Le diagnostic du siège anatomique de la lésion","Le diagnostic étiologique, qui recherche la cause précise","Le diagnostic de gravité, par une échelle"],"r":1,"e":"Topodiagnostic = diagnostic de la LOCALISATION anatomique d'une lésion à partir des signes/symptômes.","s":3},{"q":"Associez correctement type de lésion et exemple :","o":["Focale → AVC ischémique","Multifocale → SEP (sclérose en plaques)","Diffuse → Encéphalite","Systématisée → SLA","Focale → Méningite"],"r":[0,1,2,3],"e":"Focale = 1 zone (AVC) ; Multifocale = plusieurs zones distinctes (SEP) ; Diffuse = ensemble du cerveau (encéphalite) ; Systématisée = système fonctionnel (SLA = motoneurone). La méningite est diffuse, pas focale.","s":3},{"q":"Un déficit sensitif en « gant » ou « chaussette » est typique de :","o":["Une lésion médullaire, avec un niveau sensitif net","Une lésion cérébrale corticale","Une polyneuropathie des nerfs périphériques","Une atteinte cérébelleuse"],"r":2,"e":"La distribution en gant et chaussette est caractéristique des polyneuropathies (atteinte distale et symétrique des nerfs périphériques, ex : neuropathie diabétique).","s":3},{"q":"Une lésion cérébrale focale peut être d'origine :","o":["Vasculaire (AVC)","Tumorale","Traumatique","Inflammatoire (méningite)","Démyélinisante","Carence en vitamine B12"],"r":[0,1,2,3,4],"e":"Les pathologies cérébrales focales possibles sont : vasculaires, tumorales, traumatiques, inflammatoires, démyélinisantes, toxiques/métaboliques. Toutes ces propositions sont correctes. La carence en B12 provoque une atteinte diffuse (sclérose combinée de la moelle, neuropathie), pas une lésion focale.","s":3},{"q":"Le MMSE (Mini-Mental State Examination) est utilisé pour :","o":["Évaluer la force musculaire, coté de 0 à 5","Dépister les démences, avec un score sur 30","Mesurer la spasticité, de 0 à 4","Évaluer la coordination, au doigt-nez"],"r":1,"e":"Le MMSE est un outil de dépistage des troubles cognitifs / démences, scoré sur 30. Le MoCA est plus sensible aux atteintes cognitives légères.","s":3},{"q":"Combien de paires de nerfs crâniens existe-t-il ?","o":["8","10","12","14"],"r":2,"e":"12 paires crâniennes (numérotées I à XII).","s":3},{"q":"Combien de paires de nerfs rachidiens existe-t-il ?","o":["12","24","31","42"],"r":2,"e":"31 paires rachidiennes : 8 cervicales, 12 thoraciques, 5 lombaires, 5 sacrées, 1 coccygienne.","s":3},{"q":"Le tronc cérébral comprend :","o":["Mésencéphale","Pont (protubérance)","Bulbe (moelle allongée)","Cervelet","Hypothalamus"],"r":[0,1,2],"e":"Tronc cérébral = mésencéphale + pont + bulbe. Cervelet est postérieur, hypothalamus dans le diencéphale.","s":3},{"q":"Le système nerveux sympathique est responsable de :","o":["Le repos et la digestion","La réaction de combat ou de fuite","La régulation thyroïdienne, par la TSH hypophysaire","La sécrétion biliaire, par la vésicule"],"r":1,"e":"Sympathique = « combat ou fuite » : ↑ FC, dilatation pupille, dilatation bronches, ↑ sécrétion adrénaline. Il mobilise les ressources de l'organisme.","s":3},{"q":"Le nerf X (vague) innerve :","o":["Les muscles oculaires, et la paupière","Le cœur, les bronches et le tube digestif","Les muscles faciaux uniquement","Les muscles de la langue"],"r":1,"e":"X (vague) : innervation parasympathique cœur, bronches, tube digestif. Atteinte → dysphonie, dysphagie.","s":3},{"q":"Le nerf trijumeau (V) est :","o":["Sensitif pur, pour la face","Moteur pur, pour les muscles de la mastication","Mixte, sensitif facial et masticateur","Olfactif, avec le nerf I"],"r":2,"e":"V trijumeau = mixte : sensibilité de la face + muscles de la mastication.","s":3},{"q":"L'aphasie de Broca affecte :","o":["La compréhension du langage","L'expression du langage, non fluent","La motricité du membre supérieur","La vision, par atteinte du cortex occipital"],"r":1,"e":"Broca (aire frontale gauche) = aphasie d'expression : discours laborieux, télégraphique. Compréhension préservée.","s":3},{"q":"L'aphasie de Wernicke affecte :","o":["La compréhension, avec un discours fluent","L'expression motrice, avec un discours haché et lent","La motricité du membre inférieur","La marche, par une ataxie du tronc"],"r":0,"e":"Wernicke (aire temporale gauche) = aphasie de compréhension : parole fluente mais paragraphies, anosognosie. Le discours reste fluent mais incohérent.","s":3},{"q":"L'échelle de Glasgow va de :","o":["0 à 10","3 à 15","1 à 20","0 à 100"],"r":1,"e":"Glasgow : 3 (coma profond) à 15 (conscience normale) : oculaire (1-4) + verbale (1-5) + motrice (1-6).","s":3},{"q":"Un score de Glasgow ≤ 8 définit :","o":["Une conscience normale","Un état de coma","Une confusion légère, réversible","Une mort cérébrale"],"r":1,"e":"GCS ≤ 8 = coma (intubation à envisager pour protection des voies aériennes).","s":3},{"q":"Quelle voie est associée aux 12 paires crâniennes ?","o":["La voie corticobulbaire","La voie cortico-spinale","La voie spino-thalamique","La voie lemniscale"],"r":0,"e":"La fiche associe les paires crâniennes à la voie corticobulbaire et les 31 paires rachidiennes à la voie cortico-spinale.","s":3},{"q":"Quels récepteurs sont concernés par la branche afférente du SN somatique ?","o":["Les extérocepteurs, de la peau et des sens","Les viscérocepteurs, des organes internes","Les barorécepteurs artériels, du sinus carotidien","Les chémorécepteurs centraux"],"r":0,"e":"Le somatique afférent part des extérocepteurs ; le viscéral afférent part des viscérocepteurs.","s":3},{"q":"Quel effet le parasympathique exerce-t-il sur le flux salivaire et lacrymal ?","o":["Il le stimule","Il l'inhibe","Il n'a aucun effet","Il le stimule puis l'inhibe"],"r":0,"e":"Le parasympathique stimule les sécrétions salivaire et lacrymale ; le sympathique inhibe le flux salivaire.","s":3},{"q":"Comment teste-t-on cliniquement le nerf olfactif (I) ?","o":["En faisant reconnaître des odeurs, yeux fermés","Par le fond d'œil, à l'ophtalmoscope","Par le réflexe pupillaire, à la lumière d'une lampe","Par le réflexe nauséeux, à l'abaisse-langue"],"r":0,"e":"Le test du I repose sur l'identification d'odeurs ; le fond d'œil explore le II et le réflexe nauséeux le IX.","s":3},{"q":"Quel mouvement oculaire le nerf trochléaire (IV) commande-t-il ?","o":["Le mouvement vers le bas et vers l'intérieur","L'abduction du globe, vers le côté externe","L'élévation de la paupière supérieure","La convergence pure des deux yeux"],"r":0,"e":"Le IV dirige l'œil en bas et en dedans ; l'abduction relève du VI.","s":3},{"q":"Quels tests explorent le nerf vestibulocochléaire (VIII) ?","o":["Weber, Rinne et Romberg","Doigt-nez, talon-genou","Kernig et Brudzinski","Le réflexe nauséeux"],"r":0,"e":"Weber et Rinne testent l'audition, Romberg l'équilibre proprioceptif et vestibulaire.","s":3},{"q":"Quel signe clinique traduit une lésion du nerf hypoglosse (XII) ?","o":["Une déviation de la langue à la protraction","Une dysphonie, voix rauque","Une lagophtalmie, œil ouvert","Une chute de l'épaule, par atteinte du trapèze"],"r":0,"e":"La langue dévie du côté lésé ; la dysphonie évoque le X et la chute d'épaule le XI.","s":3},{"q":"Comment la fiche définit-elle la léthargie ?","o":["Une somnolence marquée","Une confusion avec agitation motrice","Un réveil bref aux stimuli","Une impossibilité de réveiller le patient"],"r":0,"e":"La léthargie est une somnolence marquée ; la stupeur permet un réveil bref et le coma aucun.","s":3},{"q":"Quel niveau de conscience associe confusion et agitation motrice ?","o":["Le délire","La léthargie","La stupeur","Le coma"],"r":0,"e":"Le délire combine confusion et agitation ; la confusion simple se limite à des réponses inappropriées.","s":3},{"q":"Que teste la gnosie ?","o":["La reconnaissance d'objets","La capacité motrice","La mémoire de travail","L'orientation temporelle"],"r":0,"e":"La gnosie est la reconnaissance ; la praxie désigne la capacité motrice.","s":3},{"q":"Sur quel total le MMSE est-il coté ?","o":["30","15","20","100"],"r":0,"e":"Le Mini-Mental State Examination est coté sur 30 points ; l'échelle de Glasgow va de 3 à 15.","s":3},{"q":"À quel score de Glasgow correspond la réponse motrice « localise la douleur » ?","o":["5","6","4","3"],"r":0,"e":"Obéir aux ordres vaut 6, localiser la douleur 5, le retrait 4 et la décortication 3.","s":3},{"q":"Que vaut en réponse motrice une extension (décérébration) sur l'échelle de Glasgow ?","o":["2","3","1","4"],"r":0,"e":"L'extension en décérébration vaut 2, la flexion en décortication 3, l'absence de réponse 1.","s":3},{"q":"Concernant l'unité fonctionnelle du SN (le neurone), quelle proposition est exacte ?","o":["Il a plusieurs axones et une seule dendrite","Il a une seule dendrite et un seul axone","Il a plusieurs dendrites et un seul axone","Il n'a ni dendrite ni axone"],"r":2,"e":"Un neurone possède PLUSIEURS dendrites (qui amènent l'influx au corps cellulaire) mais UN SEUL axone (qui conduit l'influx loin du corps cellulaire).","s":4},{"q":"Combien de paires de nerfs spinaux compose le SNP ?","o":["12","24","31","33"],"r":2,"e":"31 paires : 8 cervicales (C1-C8), 12 thoraciques (T1-T12), 5 lombaires (L1-L5), 5 sacrées (S1-S5), 1 coccygienne.","s":4},{"q":"Concernant les MÉNINGES, quelles affirmations sont vraies ?","o":["La dure-mère est la couche externe","L'arachnoïde est avasculaire","La pie-mère est vasculaire et adhère au tissu cérébral","La pie-mère est la couche externe","Le LCR circule dans l'espace épidural"],"r":[0,1,2],"e":"Dure-mère = externe (résistante). Arachnoïde = moyenne, AVASCULAIRE. Pie-mère = interne, VASCULAIRE, accolée au tissu. Le LCR circule dans l'espace SOUS-ARACHNOÏDIEN, pas épidural.","s":4},{"q":"Le LCR (liquide céphalo-rachidien) circule dans :","o":["L'espace épidural, autour de la dure-mère","L'espace sous-dural, sous la dure-mère","L'espace sous-arachnoïdien et les ventricules","La pie-mère uniquement"],"r":2,"e":"Le LCR circule dans l'espace SOUS-ARACHNOÏDIEN (entre arachnoïde et pie-mère) et dans les 4 ventricules cérébraux. Il protège des chocs.","s":4},{"q":"L'aire de Broca est située dans :","o":["Le lobe occipital","Le lobe temporal","Le lobe frontal","Le lobe pariétal"],"r":2,"e":"L'aire de Broca (langage moteur, production) est dans le lobe FRONTAL. L'aire de Wernicke (compréhension du langage) est dans le lobe temporal.","s":4},{"q":"Quelle correspondance LOBE → fonction est correcte ?","o":["Frontal, motricité volontaire et jugement","Temporal, audition et Wernicke","Pariétal, interprétation sensorielle","Occipital, vision","Frontal, vision et lecture"],"r":[0,1,2,3],"e":"Frontal = moteur + Broca + jugement. Temporal = audition + Wernicke + mémoire. Pariétal = sensoriel. Occipital = visuel. La vision n'est PAS frontale.","s":4},{"q":"Le THALAMUS a pour rôle principal :","o":["Le centre de la respiration","Le relais des influx vers et depuis le cortex","La régulation de la température du corps","La sécrétion d'hormones hypophysaires"],"r":1,"e":"Le thalamus = grand relais : transmet les influx vers et depuis les régions cérébrales appropriées. Il distingue aussi les stimuli plaisants/déplaisants.","s":4},{"q":"L'HYPOTHALAMUS régule :","o":["La température corporelle","L'appétit et la satiété","La pression artérielle","Le rythme respiratoire","La motricité fine volontaire"],"r":[0,1,2,3],"e":"Hypothalamus = centre autonome : T°, appétit, PA, respiration, sommeil, contrôle partiel hypophyse, réaction au stress. La motricité fine volontaire = cortex moteur.","s":4},{"q":"Quelle structure coordonne les mouvements musculaires, contrôle la posture et l'équilibre ?","o":["Le cervelet","Le bulbe rachidien","L'hippocampe","La moelle épinière"],"r":0,"e":"Le CERVELET, situé sous le cerveau à la base, coordonne les mouvements, contrôle la posture et maintient l'équilibre.","s":4},{"q":"Concernant les 3 parties du tronc cérébral :","o":["Le mésencéphale, avec les réflexes des nerfs III et IV","Le pont, avec la respiration et les nerfs V à VIII","Le bulbe, avec les fonctions cardiaques et vasomotrices","Le bulbe, avec les nerfs IX, X et XII","Le cervelet, comme partie du tronc cérébral"],"r":[0,1,2,3],"e":"Tronc = mésencéphale (oculomoteurs III/IV) + pont (V à VIII, respiration) + bulbe (IX/X/XII, fonctions vitales). Le cervelet n'est PAS dans le tronc.","s":4},{"q":"Jusqu'à quel niveau vertébral s'étend la moelle épinière chez l'adulte ?","o":["L1-L2","L4-L5","S1","T12"],"r":0,"e":"La moelle épinière descend jusqu'à L1-L2 chez l'adulte. En dessous, on trouve la queue de cheval (racines libres).","s":4},{"q":"Concernant les CORNES de la substance grise médullaire :","o":["Les cornes postérieures sont sensitives","Les cornes antérieures sont motrices","Les cornes antérieures sont sensitives","Les cornes postérieures sont motrices","Les cornes contiennent surtout des corps cellulaires"],"r":[0,1,4],"e":"Antérieur (ventral) = MOTEUR ; Postérieur (dorsal) = SENSITIF. Les cornes contiennent les corps cellulaires des neurones.","s":4},{"q":"Le système PYRAMIDAL (corticospinal) est responsable :","o":["Des mouvements grossiers et posturaux","Des mouvements fins et qualifiés","Du contrôle viscéral, par le sympathique","Des réflexes uniquement, sans commande volontaire"],"r":1,"e":"Pyramidal/corticospinal = mouvements FINS et qualifiés. Extra-pyramidal = mouvements grossiers, posture, tonus.","s":4},{"q":"Concernant la JONCTION racine antérieure / racine postérieure des nerfs spinaux :","o":["La racine antérieure, ventrale, est motrice","La racine postérieure, dorsale, est sensitive","Le ganglion postérieur contient les neurones sensitifs","La racine antérieure, ventrale, est sensitive","La racine postérieure, dorsale, est motrice"],"r":[0,1,2],"e":"Mnémo : antérieur=ventral=moteur ; postérieur=dorsal=sensitif. Le ganglion postérieur contient les corps cellulaires des neurones sensitifs.","s":4},{"q":"Le neurotransmetteur du système SYMPATHIQUE est :","o":["Acétylcholine","Noradrénaline","GABA","Dopamine"],"r":1,"e":"Sympathique = noradrénaline (adrénergique, combat/fuite). Parasympathique = acétylcholine (cholinergique, repos/digestion).","s":4},{"q":"La maladie d'Alzheimer touche principalement :","o":["Le cervelet, avec une ataxie progressive et précoce","Le cortex cérébral, surtout frontal","La moelle épinière, cervicale","Les nerfs périphériques"],"r":1,"e":"Alzheimer = trouble dégénératif progressif du CORTEX CÉRÉBRAL, atrophie maximale aux lobes frontaux mais touche tout le cortex.","s":4},{"q":"Lésions tissulaires caractéristiques de la maladie d'Alzheimer :","o":["Des enchevêtrements neurofibrillaires","Des plaques β-amyloïdes","Une dégénérescence granulovasculaire","Une atrophie corticale, ventricules dilatés","Une démyélinisation des nerfs périphériques"],"r":[0,1,2,3],"e":"Alzheimer : neurofibrillaires (tau), plaques amyloïdes (Aβ), dégénérescence granulovasculaire, atrophie + ventricules dilatés. Pas d'atteinte SNP.","s":4},{"q":"Le traitement de référence d'Alzheimer cible le neurotransmetteur :","o":["Le GABA, par les benzodiazépines","La sérotonine, par les inhibiteurs de sa recapture","L'acétylcholine, par les anticholinestérasiques","La dopamine, par la L-dopa"],"r":2,"e":"Cerveaux Alzheimer = jusqu'à 10 % du taux normal d'ACh. Tx : inhibiteurs de la cholinestérase (donépézil, rivastigmine, galantamine) + mémantine (NMDA).","s":4},{"q":"Concernant la SLA (sclérose latérale amyotrophique) :","o":["Atteinte des motoneurones supérieurs ET inférieurs","Faiblesse + fasciculations + atrophie","La sensibilité et la cognition sont préservées","Tx : Riluzole (neuroprotecteur)","Atteinte exclusive des nerfs sensitifs"],"r":[0,1,2,3],"e":"SLA = atteinte des 2 types de motoneurones, signe cardinal = faiblesse (60 %), fasciculations, atrophie, dysarthrie/dysphagie. Sensibilité et COGNITION PRÉSERVÉES. Tx Riluzole.","s":4},{"q":"Une crise tonico-clonique généralisée se caractérise par :","o":["Une absence simple de quelques secondes, regard fixe","Une chute, puis des phases tonique et clonique","Des secousses unilatérales sans perte de conscience","Une simple sensation de fourmillement"],"r":1,"e":"Tonico-clonique généralisée (grand mal) : cri → chute → tonique → clonique 2-5 min, morsure de langue, apnée, incontinence, confusion post-critique. Elle dure 2 à 5 minutes, avec parfois morsure de langue ou incontinence.","s":4},{"q":"Concernant l'épilepsie :","o":["Environ 50 % des cas sont idiopathiques","L'EEG est l'examen clé","Le valproate traite l'absence","La phénytoïne traite les crises tonico-cloniques","L'épilepsie diminue toujours l'intelligence"],"r":[0,1,2,3],"e":"50 % idiopathiques, EEG = clé, valproate/clonazépam/ethosuximide pour absence, phénytoïne/carbamazépine pour TC. L'épilepsie n'affecte PAS l'intelligence chez la plupart des patients.","s":4},{"q":"Le syndrome de Guillain-Barré est :","o":["Une maladie tumorale, des gaines nerveuses","Un syndrome auto-immun aigu, avec démyélinisation","Une infection bactérienne du SNC, aiguë","Une maladie génétique, transmise et héréditaire"],"r":1,"e":"GBS = polyneuropathie aiguë AUTO-IMMUNE post-infectieuse avec démyélinisation segmentaire. Évolution ascendante, risque respiratoire. La démyélinisation est segmentaire et touche les nerfs périphériques.","s":4},{"q":"Caractéristiques du Guillain-Barré :","o":["Une évolution ascendante, des jambes à la face","Une aréflexie ostéotendineuse","Une dissociation albumino-cytologique du LCR","Un traitement par immunoglobulines IV","Une hyperréflexie typique, avec Babinski"],"r":[0,1,2,3],"e":"GBS : ascendant, AREFLEXIE (pas hyperréflexie), dissociation albumino-cytologique LCR (pic 4-6 sem), Tx Ig IV ou plasmaphérèse, kinésithérapie.","s":4},{"q":"Concernant la MÉNINGITE bactérienne, quelles affirmations sont vraies ?","o":["Des germes comme le méningocoque et le pneumocoque","Un LCR trouble, riche en protéines et pauvre en glucose","Des signes de Brudzinski et de Kernig positifs","Une mortalité de 70 à 100 % sans traitement","Un traitement de première intention par aspirine seule"],"r":[0,1,2,3],"e":"Méningite bactérienne : Méningocoque, Haemophilus, Pneumocoque, E. coli. LCR trouble (↑ prot, ↓ glucose, Gram+culture). Brudzinski/Kernig positifs. Tx : ATB IV ≥ 2 sem (pénicilline G, ampicilline).","s":4},{"q":"Le signe de KERNIG correspond à :","o":["Une flexion de nuque → flexion réflexe de hanche","Une extension du genou, hanche fléchie → douleur","Un signe de Babinski positif","Une mydriase, par hypertension"],"r":1,"e":"Kernig : patient en décubitus, flexion de la hanche puis tentative d'extension du genou → douleur/résistance. Brudzinski : flexion du cou → flexion involontaire des hanches/genoux. La résistance à l'extension est aussi un signe.","s":4},{"q":"La sclérose en plaques (SEP) est due à :","o":["Une démyélinisation des nerfs du SNP, en segments","Une démyélinisation de la substance blanche du SNC","Une atteinte des motoneurones de la corne antérieure","Une carence en vitamine B12, par malabsorption"],"r":1,"e":"SEP = démyélinisation progressive de la SUBSTANCE BLANCHE du SNC (cerveau + moelle), formant des plaques scléreuses. NE TOUCHE PAS le SNP (= GBS, lui).","s":4},{"q":"Concernant la SEP :","o":["Elle touche surtout les femmes de 18 à 40 ans","Elle débute souvent par une névrite optique","L'IRM est l'examen le plus sensible","Elle évolue par poussées et rémissions","Elle atteint souvent le SNP, comme le Guillain-Barré"],"r":[0,1,2,3],"e":"SEP : ♀ jeunes 18-40, premiers signes = vision (névrite optique) + paresthésies, IRM lésions chez >90 %, poussées/rémissions. PAS de SNP (vs GBS). Des paresthésies accompagnent les premiers signes.","s":4},{"q":"Le test de TENSILON (édrophonium) sert à :","o":["Diagnostiquer une SEP, par les bandes du LCR","Diagnostiquer la myasthénie, et typer les crises","Diagnostiquer un Parkinson, par la L-dopa","Diagnostiquer une SLA, par l'EMG de repos"],"r":1,"e":"Tensilon = test diagnostique de la myasthénie grave. Différencie crise myasthénique (amélioration) vs crise cholinergique (aggravation, ↑ salivation, ↓ déglutition). Il différencie la crise myasthénique de la crise cholinergique.","s":4},{"q":"Concernant la maladie de Parkinson :","o":["Atteinte du système EXTRA-pyramidal","Carence en dopamine dans la substance noire","Triade : rigidité + akinésie + tremblement de repos","Tx 1ère ligne : lévodopa + carbidopa","Atteinte primitive de la jonction neuromusculaire"],"r":[0,1,2,3],"e":"Parkinson : extra-pyramidal, ↓ dopamine substance noire, triade rigidité (roue dentée)/akinésie/tremblement de repos pill-rolling. Tx lévodopa+carbidopa, DBS. Pas de jonction neuromusculaire (= myasthénie).","s":4},{"q":"Concernant l'AVC :","o":["Thrombose = cause la plus fréquente (sujets âgés)","AIT = déficit < 24 h sans lésion à l'imagerie","Tx ischémique : rTPA dans les 3 premières heures","La cocaïne ↑ le risque d'AVC hémorragique","L'hémorragie est la 1ère cause d'AVC"],"r":[0,1,2,3],"e":"AVC : thrombose 1ère cause (>50 %), embolie 2ème, hémorragie 3ème (mais cocaïne ↑ risque hémorragique par HTA sévère). AIT < 24h sans lésion. Tx ischémique = rTPA dans les 3h.","s":4},{"q":"La maladie d'Alzheimer est caractérisée histologiquement par :","o":["Des plaques amyloïdes et des dégénérescences tau","Une inflammation aiguë, avec un infiltrat dense","Une démyélinisation, en plaques","Une tumeur gliale, infiltrante"],"r":0,"e":"Alzheimer : plaques amyloïdes (Aβ) extracellulaires + neurofibrilles de protéine Tau hyperphosphorylée.","s":4},{"q":"Le premier symptôme habituel d'Alzheimer est :","o":["Un trouble de la marche","Un trouble de la mémoire récente","Une aphasie globale, d'emblée","Un coma, après une crise convulsive"],"r":1,"e":"Alzheimer débute par troubles mnésiques récents (oubli des évènements récents), puis désorientation, aphasie. C'est la mémoire épisodique.","s":4},{"q":"La SLA (Sclérose Latérale Amyotrophique) atteint :","o":["La seule sensibilité, par les cordons","Les motoneurones supérieurs et inférieurs","La cognition uniquement, par le cortex","Le cervelet, avec une ataxie"],"r":1,"e":"SLA = atteinte des motoneurones (1er + 2e) → faiblesse, atrophie, fasciculations + spasticité, ROT vifs. Sensibilité préservée.","s":4},{"q":"L'épilepsie tonico-clonique généralisée comprend :","o":["Une phase tonique → une phase clonique → un coma","Une phase clonique pure → réveil immédiat","Une absence pure → reprise du contact","Des hallucinations seules → aucun mouvement"],"r":0,"e":"Crise tonico-clonique : phase tonique 10-20s → phase clonique 1-2 min → résolution + confusion post-critique. La raideur tonique précède les secousses cloniques, puis vient le coma post-critique.","s":4},{"q":"L'épilepsie absence (petit mal) :","o":["Provoque des chutes, avec blessures","Une brève rupture de contact, sans convulsions","Provoque un coma prolongé, avec une confusion post-critique","Toujours convulsive, avec des secousses"],"r":1,"e":"Absence : rupture brève de contact, pointe-onde 3 Hz à l'EEG, fréquente entre 5-12 ans. Elle dure 5 à 15 s et est fréquente chez l'enfant.","s":4},{"q":"La méningite bactérienne se manifeste par :","o":["Une fièvre, des céphalées et une raideur de nuque","Une hémorragie cérébrale, avec déficit focal","Une atrophie cérébrale, progressive","Aucun signe, jusqu'au coma brutal"],"r":0,"e":"Méningite : triade classique + photophobie ± purpura. PL avec LCR trouble (↑ PNN, ↑ protéines, ↓ glucose) → urgence.","s":4},{"q":"La sclérose en plaques (SEP) est :","o":["Une maladie bactérienne, du LCR","Une maladie auto-immune et démyélinisante","Une maladie tumorale, du tissu glial du cerveau","Une maladie génétique pure"],"r":1,"e":"SEP : maladie auto-immune chronique avec démyélinisation multifocale du SNC, poussées + remissions, jeune adulte. Elle touche le SNC.","s":4},{"q":"La maladie de Parkinson est due à :","o":["Une atteinte du cervelet","Une perte de neurones dopaminergiques","Une démyélinisation, en plaques du SNC","Un AVC des noyaux gris centraux"],"r":1,"e":"Parkinson : perte des neurones dopaminergiques de la substance noire (pars compacta), corps de Lewy. Ces neurones sont ceux de la substance noire.","s":4},{"q":"La triade parkinsonienne classique inclut :","o":["Un tremblement de repos","Une rigidité en roue dentée","Une bradykinésie ou une akinésie","Une instabilité posturale, tardive","Une démence dès le début"],"r":[0,1,2,3],"e":"Triade : tremblement, rigidité, akinésie/bradykinésie + instabilité posturale tardive. Démence est tardive. Le tremblement est de 4 à 6 Hz.","s":4},{"q":"La myasthénie auto-immune est due à :","o":["Une démyélinisation centrale","Des anticorps contre les récepteurs à l'acétylcholine","Une atteinte centrale, du cortex moteur","Un trouble vasculaire, par micro-infarctus de la plaque motrice"],"r":1,"e":"Myasthénie : Ac anti-RACh post-synaptiques → fatigabilité musculaire à l'effort, ptosis, diplopie, déglutition difficile. Les récepteurs sont post-synaptiques.","s":4},{"q":"Quels sont les deux feuillets de la dure-mère ?","o":["Endostéal et méningé","Externe et vasculaire","Pariétal et viscéral","Fibreux et séreux"],"r":0,"e":"La dure-mère crânienne comporte un feuillet endostéal et un feuillet méningé ; l'arachnoïde est avasculaire et la pie-mère vascularisée.","s":4},{"q":"Quelle méninge est avasculaire ?","o":["L'arachnoïde","La pie-mère","La dure-mère","Aucune des trois"],"r":0,"e":"L'arachnoïde, membrane fine intermédiaire, est avasculaire ; la pie-mère est vascularisée.","s":4},{"q":"Quel espace méningé est virtuel ?","o":["L'espace sous-dural","L'espace épidural","L'espace sous-arachnoïdien","Aucun"],"r":0,"e":"L'espace sous-dural est virtuel ; l'épidural contient graisse et veines, le sous-arachnoïdien du LCR.","s":4},{"q":"Quelle scissure sépare le lobe frontal du lobe pariétal ?","o":["La scissure de Rolando, ou centrale","La scissure de Sylvius, ou latérale","La scissure pariéto-occipitale","La scissure calcarine"],"r":0,"e":"Rolando sépare frontal et pariétal ; Sylvius isole le temporal.","s":4},{"q":"Quelle scissure sépare le lobe temporal des lobes frontal et pariétal ?","o":["La scissure de Sylvius, ou latérale","La scissure de Rolando, ou centrale","La scissure pariéto-occipitale","La scissure interhémisphérique"],"r":0,"e":"La scissure latérale de Sylvius délimite le lobe temporal.","s":4},{"q":"Quelles émotions primitives la fiche attribue-t-elle au thalamus ?","o":["La peur et le tri entre plaisant et déplaisant","La motivation et la mémoire autobiographique","L'agressivité et la faim, avec la soif","Aucune, le thalamus étant purement sensoriel et moteur"],"r":0,"e":"Outre son rôle de relais, la fiche lui attribue ces fonctions émotionnelles primitives.","s":4},{"q":"Quelles fonctions le mésencéphale assure-t-il selon cette fiche ?","o":["Les réflexes des nerfs III et IV, pupillaires et oculaires","La régulation de la respiration, avec le pont","Les fonctions cardiaque et vasomotrice, du bulbe","Les centres du vomissement et de la toux, aux nerfs IX et X"],"r":0,"e":"Le pont régule la respiration et porte les réflexes V à VIII ; le bulbe abrite les fonctions vitales et les centres du vomissement.","s":4},{"q":"Quels nerfs crâniens émergent du bulbe rachidien selon la fiche ?","o":["IX, X et XII","III et IV","V, VI, VII et VIII","I et II"],"r":0,"e":"Le bulbe porte les nerfs IX, X et XII ; le mésencéphale III et IV, le pont V à VIII.","s":4},{"q":"Quelles structures forment la formation réticulée selon la fiche ?","o":["Le tronc cérébral, le thalamus et l'hypothalamus","Le cervelet, le pont et le bulbe, avec les olives","Les noyaux gris centraux et le thalamus","Le cortex et la substance blanche"],"r":0,"e":"Cette association constitue le réseau d'éveil et de vigilance.","s":4},{"q":"Pourquoi chaque nerf spinal se divise-t-il en rameaux avec recouvrement ?","o":["Il limite la perte de fonction si une racine est lésée","Il accélère la conduction de l'influx","Il permet la régénération axonale","Il protège contre les infections, par une barrière de myéline"],"r":0,"e":"Le chevauchement des territoires limite les conséquences d'une atteinte d'une seule racine.","s":4},{"q":"Le potentiel de membrane au repos d'un neurone est d'environ :","o":["+30 mV","-70 mV","0 mV","-100 mV"],"r":1,"e":"Le potentiel de repos est de -70 mV. Maintenu par la pompe Na⁺/K⁺ ATPase. K⁺ intra > extra ; Na⁺ extra > intra.","s":5},{"q":"Concernant les phases du potentiel d'action :","o":["La dépolarisation, par entrée de Na⁺","La repolarisation, par sortie de K⁺","Une hyperpolarisation possible, par le K⁺","Une dépolarisation, par sortie de Cl⁻","Une réponse en tout-ou-rien"],"r":[0,1,2,4],"e":"PA = tout-ou-rien. Dépolarisation : entrée Na⁺ → +30 mV. Repolarisation : sortie K⁺ → retour vers -70 mV. Hyperpolarisation parfois (refractaire). Le Cl⁻ n'intervient pas dans les phases standards.","s":5},{"q":"Quelle cellule gliale myélinise les axones du SNC ?","o":["Cellule de Schwann","Astrocyte","Oligodendrocyte","Microglie"],"r":2,"e":"SNC = oligodendrocyte (1 cellule peut myéliniser plusieurs axones). SNP = cellule de Schwann (1 cellule = 1 segment d'1 seul axone).","s":5},{"q":"Concernant la transmission synaptique :","o":["L'arrivée du PA déclenche l'entrée de Ca²⁺ au bouton terminal","Le Ca²⁺ déclenche la libération de neurotransmetteur","Liaison post-synaptique → EPSP (excitateur) ou IPSP (inhibiteur)","Tous les neurotransmetteurs sont excitateurs","Le glutamate est le principal excitateur du SNC"],"r":[0,1,2,4],"e":"PA → Ca²⁺ → libération NT → liaison récepteurs → EPSP/IPSP. Glutamate = principal excitateur SNC. GABA = principal inhibiteur SNC. Tous les NT ne sont pas excitateurs.","s":5},{"q":"Le principal neurotransmetteur INHIBITEUR du SNC est :","o":["Le glutamate","L'acétylcholine","Le GABA","La dopamine, ou DA"],"r":2,"e":"GABA = principal NT inhibiteur du SNC (récepteurs GABA-A et B). Glutamate = principal excitateur. Cible des benzodiazépines (potentialisent GABA).","s":5},{"q":"La barrière hémato-encéphalique (BHE) :","o":["Sépare le sang du tissu cérébral","Composée de jonctions serrées + astrocytes","Laisse passer O₂, CO₂, glucose","Bloque la majorité des médicaments","Permet librement le passage des bactéries"],"r":[0,1,2,3],"e":"BHE = jonctions serrées endothéliales + astrocytes. Imperméable à la plupart des molécules → protège. Laisse passer petites molécules liposolubles (O₂, CO₂) et substrats énergétiques (glucose via transporteurs). Bloque les pathogènes (sauf en méningite).","s":5},{"q":"Le LCR est produit par :","o":["Les méninges, surtout l'arachnoïde et ses villosités","Les plexus choroïdes, dans les ventricules","La pie-mère, à la surface du cerveau","Le bulbe rachidien, par ses noyaux"],"r":1,"e":"LCR = produit par les plexus choroïdes des ventricules cérébraux. Volume ~150 mL, production ~500 mL/j. Réabsorbé par les granulations arachnoïdiennes (de Pacchioni).","s":5},{"q":"Concernant le système nerveux SYMPATHIQUE :","o":["Origine thoraco-lombaire (T1-L2)","Fibres post-ganglionnaires longues à noradrénaline","Mydriase, ↑ FC, bronchodilatation","Récepteurs muscariniques principalement","Effet \"combat ou fuite\""],"r":[0,1,2,4],"e":"Sympathique : T1-L2, ganglions paravertébraux, post-ganglionnaire LONGUE à NA, récepteurs α/β. Effet combat/fuite. Les muscariniques sont des récepteurs PARASYMPATHIQUES.","s":5},{"q":"Le réflexe rotulien est un exemple de :","o":["Un réflexe polysynaptique","Un réflexe d'étirement monosynaptique","Un réflexe nociceptif, de retrait du membre","Un réflexe cutané, plantaire"],"r":1,"e":"Réflexe rotulien (myotatique) = monosynaptique : un neurone afférent (Ia) → un neurone efférent moteur. Sa réponse explore L4.","s":5},{"q":"Concernant la voie cordonale postérieure :","o":["Le tact fin discriminatif","La sensibilité vibratoire","La proprioception consciente","Un croisement au bulbe, dans le lemnisque","Un croisement immédiat, dans la moelle"],"r":[0,1,2,3],"e":"Cordon postérieur (gracile + cunéiforme) : tact fin, vibration, proprioception. Croisement au BULBE (lemnisque médian). La voie spinothalamique croise dans la moelle (1-2 segments au-dessus).","s":5},{"q":"La voie SPINOTHALAMIQUE LATÉRALE véhicule :","o":["Tact fin et proprioception","Douleur et température","Motricité volontaire","Réflexes ostéo-tendineux"],"r":1,"e":"Spinothalamique latérale = douleur + T°. Croisement dans la moelle 1-2 segments au-dessus. Spinothalamique antérieure = tact grossier, pression.","s":5},{"q":"Concernant les types de douleur :","o":["La nociceptive, par stimulation de récepteurs","La neuropathique, par lésion du système nerveux","La référée, ressentie à distance de la lésion","Celle du membre fantôme, après amputation","La viscérale, bien localisée sur l'organe"],"r":[0,1,2,3],"e":"Nociceptive = récepteurs stimulés. Neuropathique = lésion nerveuse (brûlures, décharges). Référée = à distance (épaule G dans IDM). Membre fantôme = post-amputation. La douleur viscérale est MAL localisée (vs cutanée bien localisée).","s":5},{"q":"Les fibres conduisant la douleur RAPIDE (piqûre, bien localisée) sont :","o":["Fibres C non myélinisées","Fibres Aδ myélinisées","Fibres Aα","Fibres B"],"r":1,"e":"Fibres Aδ (myélinisées, rapides) = douleur aiguë, bien localisée, rapide. Fibres C (non myélinisées, lentes) = douleur sourde, mal localisée, brûlante.","s":5},{"q":"Concernant la migraine :","o":["Unilatérale, pulsatile","Durée 4-72 h","± aura visuelle ou sensitive","Photo/phonophobie + nausées","Tx aigu : O₂ 100 %"],"r":[0,1,2,3],"e":"Migraine : unilatérale, pulsatile, 4-72 h, photo/phonophobie, nausées, ± aura. Tx aigu : triptans, AINS. L'O₂ 100 % est utilisé pour les ALGIES VASCULAIRES (cluster), pas la migraine.","s":5},{"q":"L'algie vasculaire de la face (cluster headache) est :","o":["Bilatérale et légère, en casque","Unilatérale, orbitaire, par salves intenses","Souvent provoquée par l'effort physique","Disparaît spontanément après 30 secondes"],"r":1,"e":"Cluster : crises courtes (15-180 min) très intenses, unilatérales orbitaires, par salves, avec signes dysautonomiques (larmoiement, congestion, ptosis). Tx : O₂ 100 %, sumatriptan SC. Elle s'accompagne de larmoiement et de congestion nasale.","s":5},{"q":"Le système PYRAMIDAL (corticospinal) :","o":["Il croise au niveau du thalamus","Il naît du cortex moteur et croise au bulbe","Il contrôle les mouvements grossiers","Il fait partie du cervelet, avec les voies spinocérébelleuses"],"r":1,"e":"Pyramidal/corticospinal : origine M1 (aire 4), décussation au BULBE (75 % en latéral), contrôle des mouvements FINS et qualifiés. Lésion → spasticité, hyperréflexie, Babinski +. Il naît de M1, l'aire 4.","s":5},{"q":"Différences UMN vs LMN :","o":["UMN = hypertonie spastique ; LMN = hypotonie","UMN = hyperréflexie ; LMN = hyporéflexie","UMN = atrophie précoce et marquée","LMN = fasciculations","UMN = Babinski positif"],"r":[0,1,3,4],"e":"UMN : spasticité, hyperréflexie, Babinski +, atrophie tardive et MODÉRÉE (de non-usage). LMN : flaccidité, hyporéflexie, atrophie PRÉCOCE et marquée, fasciculations.","s":5},{"q":"La SLA atteint :","o":["Uniquement les motoneurones supérieurs (UMN)","Uniquement les motoneurones inférieurs (LMN)","UMN ET LMN (mixte)","Uniquement les nerfs sensitifs"],"r":2,"e":"SLA = atteinte MIXTE des UMN et LMN. Mutation SOD1 dans 5-10 % des cas (chr 21). Faiblesse, atrophie, fasciculations + spasticité, Babinski. Sensibilité et cognition PRÉSERVÉES.","s":5},{"q":"Concernant la SEP :","o":["Une démyélinisation auto-immune du SNC","Des plaques disséminées dans le temps et l'espace","L'IRM comme examen de référence","Des bandes oligoclonales dans le LCR","Une atteinte fréquente des nerfs du SNP"],"r":[0,1,2,3],"e":"SEP : auto-immune, démyélinisation SNC (PAS du SNP, vs Guillain-Barré). Plaques disséminées temps/espace (critères de McDonald). IRM = examen clé. LCR : bandes oligoclonales chez 90 %.","s":5},{"q":"Le test diagnostique de la myasthénie grave est :","o":["Un EEG, à la recherche d'ondes lentes","Le test au Tensilon, ou édrophonium","Une ponction lombaire","Une TDM cérébrale"],"r":1,"e":"Tensilon (édrophonium) = anticholinestérasique d'action courte → amélioration transitoire de la force = test diagnostique. Aussi : dosage anti-RACh, EMG (décrément), recherche thymome au TDM thoracique.","s":5},{"q":"La dystrophie de Duchenne est :","o":["Liée à l'X et récessive, chez les garçons","Autosomique dominante, chez les deux sexes à égalité","Auto-immune, avec des anticorps","Acquise, par carence vitaminique"],"r":0,"e":"Duchenne = transmission X-RÉCESSIVE → garçons +++. Mutation du gène de la dystrophine. Début 3-5 ans, fauteuil ~12 ans. Signe de Gowers. ↑ CPK majeure.","s":5},{"q":"Signes du SYNDROME CÉRÉBELLEUX :","o":["Ataxie","Dysmétrie","Dysdiadococinésie","Tremblement intentionnel","Tremblement de repos"],"r":[0,1,2,3],"e":"Cérébelleux : ataxie, dysmétrie, dysdiadococinésie, tremblement INTENTIONNEL (pas de repos), hypotonie, dysarthrie scandée, nystagmus. Le tremblement de REPOS = Parkinson.","s":5},{"q":"La maladie de Huntington est :","o":["Autosomique dominante, par expansion CAG","Liée à l'X, chez les garçons","Auto-immune, par des anticorps","Une carence vitaminique, en B1 et B12"],"r":0,"e":"Huntington : autosomique DOMINANTE, mutation chr 4 (expansion CAG > 36). Atteinte du noyau caudé + putamen. Triade : chorée + démence + troubles psychiatriques. Début 30-50 ans. Le gène est sur le chromosome 4.","s":5},{"q":"L'hémiballisme (mouvements violents involontaires) est typiquement causé par une lésion du :","o":["Du cervelet, homolatéral","Du noyau subthalamique, ou de Luys","De la substance noire","Du cortex moteur primaire, en frontal"],"r":1,"e":"Hémiballisme = mouvements brusques, violents, en ballant des membres. Lésion contralatérale du noyau SUBTHALAMIQUE (Luys), souvent ischémique.","s":5},{"q":"Une lésion médullaire au niveau C4-C5 entraîne :","o":["Paraplégie sans atteinte respiratoire","Tétraplégie + respiration partielle","Hémiplégie","Aucune atteinte motrice"],"r":1,"e":"C4-C5 = tétraplégie + respiration partielle (atteinte du diaphragme, innervation C3-C5 par le nerf phrénique). C1-C3 = dépendance ventilatoire totale. T1+ = paraplégie.","s":5},{"q":"La DYSRÉFLEXIE AUTONOMIQUE est :","o":["Une urgence, pour une lésion à partir de T6","Une HTA sévère, déclenchée sous la lésion","Une bradycardie, des céphalées et des sueurs","Une réaction toujours bénigne, sans traitement","Un risque d'AVC en l'absence de traitement"],"r":[0,1,2,4],"e":"Dysréflexie autonomique : urgence chez blessé médullaire (lésion ≥ T6). Stimulus nociceptif sous-lésionnel (vessie pleine, escarre, fécalome) → décharge sympathique massive → HTA paroxystique sévère, bradycardie réflexe, céphalées, sueurs. Risque AVC, OAP.","s":5},{"q":"L'échelle de Glasgow (GCS) explore :","o":["Yeux + Verbal + Moteur (total /15)","Sensibilité + motricité + réflexes (total /20)","Glycémie + PA + FC","Force /5 dans 5 territoires"],"r":0,"e":"GCS : ouverture des yeux (1-4) + réponse verbale (1-5) + réponse motrice (1-6) = total /15. ≤ 8 = coma, indication d'intubation.","s":5},{"q":"Concernant l'HTIC (hypertension intracrânienne) :","o":["Monro-Kellie, avec trois compartiments","Une pression normale de 5 à 15 mmHg","Une HTIC au-delà de 20 mmHg","La triade de Cushing, HTA, bradycardie et respiration","Une absence constante de toute conséquence"],"r":[0,1,2,3],"e":"HTIC : Monro-Kellie (3 compartiments inextensibles). Normal 5-15 mmHg. > 20 mmHg = pathologique. Triade de Cushing = signe d'engagement imminent (HTA + bradycardie + irrégularités respi). Risque mortel.","s":5},{"q":"Concernant les types d'œdème cérébral :","o":["Le cytotoxique, par entrée d'eau dans les cellules","Le vasogénique, par rupture de la BHE","L'interstitiel, par passage du LCR","Un mécanisme identique pour tous les œdèmes","Un œdème toujours bénin, sans traitement"],"r":[0,1,2],"e":"3 types : cytotoxique (intracellulaire, AVC), vasogénique (extracellulaire, BHE rompue, tumeur/infection), interstitiel (LCR-parenchyme, hydrocéphalie). Mécanismes différents → traitements différents.","s":5},{"q":"Un hématome ÉPIDURAL :","o":["Une origine veineuse, par les veines en pont","Une origine artérielle, méningée moyenne","Une évolution lente, sur des semaines","Une image en croissant à la TDM"],"r":1,"e":"Hématome épidural : ARTÉRIEL (artère méningée moyenne), sur fracture temporale ++, INTERVALLE LIBRE classique, image en LENTILLE BICONVEXE. Vs sous-dural = veines en pont, image en CROISSANT. Il survient souvent sur fracture temporale, avec un intervalle libre.","s":5},{"q":"La forme la plus fréquente d'AVC est :","o":["AVC ischémique (~85 %)","AVC hémorragique (~85 %)","AVC ischémique (~50 %)","Hémorragie sous-arachnoïdienne (~70 %)"],"r":0,"e":"AVC ischémique = ~85 % des AVC. Hémorragique ~15 % mais plus mortel. Tx ischémique : tPA < 4,5 h, thrombectomie < 6-24 h selon profil.","s":5},{"q":"Concernant la prise en charge de l'AVC ischémique :","o":["tPA dans les 4,5 premières heures","Thrombectomie mécanique possible jusqu'à 6-24 h selon profil","TDM en urgence pour exclure hémorragie","FAST pour reconnaître (Face, Arms, Speech, Time)","Anticoagulation immédiate à dose curative"],"r":[0,1,2,3],"e":"AVC ischémique : TDM urgent (exclut hémorragie) → tPA si < 4,5 h, thrombectomie si possible. FAST = méthode de reconnaissance. L'anticoagulation curative immédiate n'est PAS systématique (risque de transformation hémorragique).","s":5},{"q":"Une céphalée brutale en \"coup de tonnerre\" évoque :","o":["Une migraine avec aura, précédée de signes visuels","Une céphalée de tension","Une hémorragie sous-arachnoïdienne","Une algie vasculaire de la face"],"r":2,"e":"Céphalée brutale en coup de tonnerre = drapeau rouge → HSA jusqu'à preuve du contraire (rupture d'anévrisme). Urgence neurochirurgicale. TDM en urgence ± PL si TDM négatif. Elle est souvent due à une rupture d'anévrisme.","s":5},{"q":"L'encéphalite herpétique (HSV) :","o":["Une atteinte temporale à l'IRM","Une confusion, des convulsions et des déficits","Un aciclovir IV en urgence","Une maladie bénigne, sans traitement","Une mortalité élevée sans traitement"],"r":[0,1,2,4],"e":"Encéphalite HSV : urgence ! IRM = atteinte temporale, EEG anormal, LCR avec lymphocytes + PCR HSV. Tx IMMÉDIAT par aciclovir IV (avant confirmation). Sans tx : mortalité ~70 %.","s":5},{"q":"État de mal épileptique :","o":["Une crise de plus de 5 min","Une urgence vitale","Une benzodiazépine IV en première ligne","Un risque d'œdème cérébral","Un trouble bénin et auto-résolutif"],"r":[0,1,2,3],"e":"État de mal = crise prolongée >5 min ou crises répétées sans reprise de conscience. URGENCE vitale → benzo IV en 1ère ligne (lorazépam, diazépam) puis phénytoïne, puis coma barbiturique si réfractaire. Risque œdème, hypoxie, décès. Plus de 2 crises sans récupération en sont aussi une définition.","s":5},{"q":"Le neurone est :","o":["La cellule de soutien du SN, qui nourrit et isole les neurones","La cellule fonctionnelle du SN, qui transmet l'influx","Une cellule sanguine, de la lignée blanche","Une cellule musculaire, à contraction lente"],"r":1,"e":"Neurone = unité fonctionnelle du SN (corps cellulaire + dendrites + axone). Glie = cellules de soutien.","s":5},{"q":"Le potentiel d'action (PA) repose sur :","o":["L'entrée de Na⁺ puis la sortie de K⁺","La sortie de Cl⁻ uniquement","L'entrée de Ca²⁺, puis la sortie de Mg²⁺ et de Cl⁻","Aucun mouvement ionique net"],"r":0,"e":"PA : ouverture canaux Na+ voltage-dépendants → entrée Na+ (dépol) → ouverture canaux K+ → sortie K+ (repol). L'entrée de Na⁺ dépolarise et la sortie de K⁺ repolarise.","s":5},{"q":"La synapse chimique transmet l'information via :","o":["Conduction électrique directe","Libération de neurotransmetteurs","Diffusion ionique","Voie sanguine"],"r":1,"e":"Synapse chimique : PA → entrée Ca2+ → libération vésicules de NT → liaison récepteurs post-synaptiques.","s":5},{"q":"La dopamine est principalement synthétisée par :","o":["L'hippocampe temporal","La substance noire du mésencéphale","Le cervelet, au vermis","Le bulbe olfactif, dans le lobe frontal"],"r":1,"e":"Dopamine : substance noire pars compacta (voie nigro-striée), aire tegmentale ventrale (voies mésocorticales/limbiques).","s":5},{"q":"L'aire motrice primaire est située :","o":["Dans le lobe occipital, au pôle","Dans le gyrus précentral du lobe frontal","Dans le lobe temporal, en arrière de l'aire auditive","Dans le cervelet, au vermis"],"r":1,"e":"Cortex moteur primaire (M1) = gyrus précentral du lobe frontal, contient l'homonculus moteur.","s":5},{"q":"L'aire somatosensorielle primaire est située :","o":["Dans le gyrus postcentral du lobe pariétal","Dans le lobe frontal, en avant de Rolando","Dans le lobe occipital, autour de la scissure calcarine","Dans le cervelet, au vermis"],"r":0,"e":"S1 = gyrus postcentral du lobe pariétal, traite les sensations tactiles et proprioceptives, homonculus sensoriel.","s":5},{"q":"Le cervelet contrôle :","o":["La mémoire à long terme, avec l'hippocampe","La coordination des mouvements et l'équilibre","L'humeur et les émotions primitives","La douleur et la température cutanées"],"r":1,"e":"Cervelet : coordination des mouvements fins, équilibre, ajustement du tonus. Atteinte → ataxie, dysmétrie.","s":5},{"q":"L'ataxie cérébelleuse se manifeste par :","o":["Une marche à petits pas, avec piétinement","Une marche ébrieuse et une dysmétrie du geste","Une akinésie, avec rigidité plastique","Une hémiplégie, avec spasticité"],"r":1,"e":"Atteinte cérébelleuse : ataxie (marche ébrieuse), dysmétrie, adiadococinésie, dysarthrie, nystagmus, tremblement intentionnel. La dysarthrie scandée et le tremblement intentionnel en font aussi partie.","s":5},{"q":"Le syndrome extrapyramidal (Parkinson) se distingue du pyramidal par :","o":["Une spasticité élastique, avec un déficit moteur net","Une rigidité plastique, sans déficit moteur clair","Un signe de Babinski positif","Des réflexes ostéotendineux vifs"],"r":1,"e":"Syndrome EP : rigidité plastique, tremblement de repos, akinésie. Syndrome pyramidal : spasticité élastique, déficit moteur, Babinski. La rigidité est en roue dentée, avec un tremblement de repos.","s":5},{"q":"L'hippocampe est essentiel pour :","o":["La motricité volontaire fine","La consolidation de la mémoire","La vision des couleurs","L'audition des aigus"],"r":1,"e":"Hippocampe : structure du système limbique, consolidation des souvenirs (passage mémoire court terme → long terme). Il fait passer les souvenirs vers la mémoire à long terme.","s":5},{"q":"Que contient le soma d'un neurone selon la fiche ?","o":["Le noyau, le nucléole et les corps de Nissl","Uniquement des mitochondries, en grand nombre","Les nœuds de Ranvier, entre les gaines","Les boutons terminaux, à la synapse"],"r":0,"e":"Les corps de Nissl (RER riche en ARN) sont caractéristiques du corps cellulaire neuronal. Le réticulum endoplasmique rugueux en fait aussi partie.","s":5},{"q":"Quelle différence oppose l'oligodendrocyte à la cellule de Schwann ?","o":["L'oligodendrocyte en myélinise plusieurs, Schwann un seul","L'oligodendrocyte en myélinise un seul, Schwann plusieurs","Les deux myélinisent plusieurs axones, dans le SNC","Aucune ne myélinise, ce rôle revenant aux astrocytes"],"r":0,"e":"Un oligodendrocyte du SNC envoie des prolongements vers plusieurs axones ; une cellule de Schwann n'entoure qu'un seul segment d'un seul axone.","s":5},{"q":"Quelles cellules gliales du SNP la fiche cite-t-elle, outre les cellules de Schwann ?","o":["Les cellules satellites","Les astrocytes","Les épendymocytes","La microglie"],"r":0,"e":"Astrocytes, épendymocytes et microglie sont des cellules du SNC ; les cellules satellites accompagnent les corps cellulaires des ganglions périphériques.","s":5},{"q":"Quel ion entre dans le bouton terminal pour déclencher la libération du neurotransmetteur ?","o":["Le calcium","Le sodium","Le potassium","Le chlore"],"r":0,"e":"L'arrivée du potentiel d'action ouvre les canaux calciques voltage-dépendants, ce qui déclenche l'exocytose des vésicules.","s":5},{"q":"Quel est le volume total de LCR et sa production quotidienne ?","o":["Environ 150 mL pour une production de 500 mL par jour","Environ 500 mL pour une production de 150 mL par jour","Environ 50 mL pour 100 mL par jour","Environ 1 L pour 1 L par jour"],"r":0,"e":"Le LCR est donc renouvelé environ trois fois par jour.","s":5},{"q":"L'oreille est divisée en 3 compartiments. Lesquels ?","o":["L'oreille externe, qui capte le son","L'oreille moyenne, qui transmet et amplifie","L'oreille interne, qui transforme le signal","L'oreille centrale, qui analyse le son","L'oreille périphérique, qui protège"],"r":[0,1,2],"e":"3 parties : externe (pavillon + CAE + tympan), moyenne (osselets, trompe d'Eustache) et interne (cochlée + vestibule).","s":6},{"q":"Quels sont les 3 osselets de l'oreille moyenne (de l'extérieur vers l'intérieur) ?","o":["Étrier → Enclume → Marteau","Marteau → Enclume → Étrier","Marteau → Étrier → Enclume","Enclume → Marteau → Étrier"],"r":1,"e":"Marteau (malleus) → Enclume (incus) → Étrier (stapes). L'étrier transmet les vibrations à la fenêtre ovale de l'oreille interne.","s":6},{"q":"La trompe d'Eustache relie :","o":["L'oreille moyenne au rhinopharynx","La cochlée au cervelet, par le nerf vestibulaire","Les deux oreilles moyennes entre elles","Le tympan au conduit auditif externe"],"r":0,"e":"Trompe d'Eustache = oreille moyenne ↔ rhinopharynx. Rôle : équilibrer la pression et drainer. Sa dysfonction → otite séreuse.","s":6},{"q":"Concernant l'oreille interne :","o":["Elle contient deux labyrinthes, osseux et membraneux","La cochlée y assure l'audition","Le vestibule et les canaux y assurent l'équilibre","Elle est innervée par le nerf VIII","Elle est innervée par le nerf V, le trijumeau"],"r":[0,1,2,3],"e":"Oreille interne : labyrinthe osseux (perilymphe) + membraneux (endolymphe). Cochlée audition, vestibule/canaux SC équilibre. NC VIII (vestibulo-cochléaire). Le V innerve le pavillon, pas l'oreille interne.","s":6},{"q":"Le tympan vu à l'otoscope est :","o":["Plat et opaque, sans reflet lumineux","Un cône concave, avec umbo et cône lumineux","Bombé et rouge, en condition normale","Toujours blanc nacré, de façon uniforme"],"r":1,"e":"Tympan normal : transparent gris-perlé, cône lumineux, manche du marteau visible, umbo (apex). Bombé rouge = OMA. Concave = dépression (dysfonction tubaire). Le manche du marteau est visible.","s":6},{"q":"Pourquoi peut-on déclencher un réflexe de toux/vomissement à l'otoscopie chez l'enfant ?","o":["Une stimulation du nerf V, sensitif","L'innervation vagale du conduit auditif","Une stimulation du nerf VIII, par la pression sur le tympan","Un réflexe oculo-cardiaque"],"r":1,"e":"Le CAE postérieur est innervé en partie par le nerf vague (X) → réflexe de toux ou vomissement, surtout chez l'enfant à l'otoscopie.","s":6},{"q":"L'otite externe (\"oreille du nageur\") est typiquement causée par :","o":["Streptococcus pneumoniae, comme l'otite moyenne","Pseudomonas aeruginosa et S. aureus","Mycobacterium tuberculosis","Le virus de l'herpès simplex"],"r":1,"e":"Otite externe : Pseudomonas aeruginosa ++, S. aureus. Douleur intense à la traction du pavillon. Tx : gouttes ATB ± corticoïdes.","s":6},{"q":"L'otosclérose est une atteinte de :","o":["L'enclume, au centre de la chaîne","Le marteau, attaché au tympan par son manche","L'étrier et la fenêtre ovale","La cochlée, dans l'oreille interne"],"r":2,"e":"Otosclérose = dystrophie osseuse autour de l'étrier et de la fenêtre ovale → blocage de l'étrier → surdité de transmission progressive. Hérédité, ♀ jeune ++, aggravée par grossesse. Tx : prothèse ou stapédectomie.","s":6},{"q":"Concernant l'OMA (otite moyenne aiguë) :","o":["La 1re cause de consultation pédiatrique","Des germes comme le pneumocoque","Une otalgie, une fièvre et un tympan bombé","L'amoxicilline en première intention","Une origine toujours virale, sans bactérie"],"r":[0,1,2,3],"e":"OMA : 1ère cause de consultation chez l'enfant, post-rhume, dysfonction tubaire. Pneumocoque, H. influenzae, Moraxella. Tympan rouge bombé. Tx : amoxicilline. Peut être virale OU bactérienne. H. influenzae et M. catarrhalis sont les autres germes.","s":6},{"q":"Le barotraumatisme (avion, plongée) survient en cas de :","o":["Un excès de cérumen, qui obstrue le conduit externe","Un écart de pression que la trompe n'équilibre pas","Une otite chronique, ancienne","Une surdité de perception"],"r":1,"e":"Barotrauma : changement rapide de pression atmosphérique non compensé par la trompe d'Eustache. Otalgie, hypoacousie, hémotympan possible. Prévention : déglutition, Valsalva.","s":6},{"q":"Mécanique auditive normale (transduction) :","o":["L'onde sonore fait vibrer le tympan","Le tympan met en jeu la chaîne des osselets","L'étrier transmet l'onde à la périlymphe","La membrane basilaire stimule les cellules ciliées","L'influx gagne le nerf VIII puis le cortex auditif","L'endolymphe se déplace dans les canaux semi-circulaires"],"r":[0,1,2,3,4],"e":"Toute la chaîne : son → tympan → osselets → étrier sur fenêtre ovale → perilymphe → membrane basilaire → cellules ciliées (organe de Corti) → NC VIII → noyaux cochléaires → colliculi inférieurs → corps géniculé médian (thalamus) → cortex auditif primaire (aire 41). Ce déplacement code les accélérations angulaires : il relève du vestibule, non de l'audition.","s":6},{"q":"La tonotopie cochléaire signifie que :","o":["Toutes les fréquences sont codées au même endroit","Les aigus sont à la base et les graves à l'apex","Les graves sont à la base et les aigus à l'apex","La cochlée ne détecte qu'une seule fréquence, la plus forte"],"r":1,"e":"Tonotopie : la membrane basilaire est 'accordée'. Les hautes fréquences (aigus) à la BASE, les basses fréquences (graves) à l'APEX. Audition humaine 20-20 000 Hz, sensibilité max 1000-3000 Hz.","s":6},{"q":"Les acouphènes (tinnitus) sont :","o":["Toujours associés à une lésion vasculaire","Une perception de son sans stimulus externe","Une cause systématique de surdité totale","Toujours d'origine psychogène"],"r":1,"e":"Acouphènes = perception d'un son sans stimulus externe (sifflement, bourdonnement). Touchent ~1/5 personnes. Subjectifs (la majorité) ou objectifs (rares, vasculaires). Causes : bouchon, trauma sonore, ototoxiques, presbyacousie, HTA.","s":6},{"q":"Médicaments OTOTOXIQUES classiques :","o":["L'aspirine à fortes doses","Les aminosides, comme la gentamicine","Le furosémide à fortes doses","Le cisplatine, en chimiothérapie","Le paracétamol à doses usuelles"],"r":[0,1,2,3],"e":"Ototoxiques : aspirine (réversible), aminosides (irréversible), diurétiques de l'anse (furosémide à hautes doses), cisplatine, vancomycine. Le paracétamol n'est pas ototoxique.","s":6},{"q":"Une surdité de TRANSMISSION (conductive) :","o":["Provient d'une atteinte de la cochlée ou du nerf VIII","Provient d'une atteinte de l'oreille externe ou moyenne","Provient d'une atteinte des voies auditives centrales du tronc","Est toujours bilatérale, et symétrique"],"r":1,"e":"Transmission : atteinte oreille externe (bouchon) ou moyenne (OMA, otosclérose, perforation tympanique). Le son n'est pas correctement transmis à l'oreille interne. Perception : atteinte interne (cochlée, VIII).","s":6},{"q":"Concernant les tests de Rinne et Weber :","o":["Rinne positif, CA > CO, normal ou perception","Rinne négatif, CO > CA, transmission","Weber vers l'oreille atteinte, transmission","Weber vers l'oreille saine, perception","Weber vers l'oreille saine, transmission"],"r":[0,1,2,3],"e":"Rinne + : conduction aérienne > osseuse (normal). Rinne − : CO > CA (transmission). Weber → oreille atteinte = transmission ; → oreille saine = perception.","s":6},{"q":"La presbyacousie est :","o":["Une surdité brutale, d'un seul côté","Une perte progressive et bilatérale, liée à l'âge","Une infection bactérienne de l'oreille","Une surdité de transmission, par blocage des osselets"],"r":1,"e":"Presbyacousie : perte auditive de PERCEPTION liée à l'âge, progressive et bilatérale, atteint les FRÉQUENCES AIGUËS en premier. Impact social et lien avec déclin cognitif/démence. Elle touche d'abord les fréquences aiguës.","s":6},{"q":"Causes de surdité de PERCEPTION :","o":["Presbyacousie","Traumatisme sonore","Ototoxiques","Maladie de Ménière","Bouchon de cérumen"],"r":[0,1,2,3],"e":"Surdité de perception : presbyacousie, trauma sonore, ototoxiques, génétique, infection (CMV, méningite), Ménière, neurinome de l'acoustique. Le bouchon de cérumen = surdité de TRANSMISSION.","s":6},{"q":"Concernant les CANAUX SEMI-CIRCULAIRES :","o":["Au nombre de 3 : latéral, antérieur, postérieur","Disposés dans les 3 plans de l'espace","Détectent l'accélération ANGULAIRE (rotations)","Détectent la position statique de la tête","Contiennent la cupule + cellules ciliées (crista ampullaris)"],"r":[0,1,2,4],"e":"3 canaux SC perpendiculaires (latéral, antérieur, postérieur) : détectent les ROTATIONS (accélération angulaire). Cupule + crista ampullaris dans l'ampoule. La position STATIQUE est détectée par les MACULES (saccule + utricule), pas les canaux SC.","s":6},{"q":"Le saccule et l'utricule détectent :","o":["L'accélération angulaire, lors des rotations","L'accélération linéaire et la position de la tête","L'audition des sons graves","La proprioception des articulations"],"r":1,"e":"Saccule et utricule contiennent les MACULES avec OTOLITHES (carbonate de calcium) → détectent la gravité et l'accélération LINÉAIRE. Utricule = plan horizontal, saccule = plan vertical. Les canaux SC = rotations. Ils sont sensibles à la gravité.","s":6},{"q":"Le réflexe vestibulo-oculaire (VOR) :","o":["Empêche tout mouvement des yeux","Stabilise le regard pendant les mouvements de la tête","Provoque un nystagmus pathologique","Active uniquement le nerf IV, pour l'abaissement"],"r":1,"e":"VOR : déplacement de la tête → mouvement oculaire compensatoire opposé pour stabiliser l'image sur la rétine. Implique les NC III, IV, VI. Crucial pour la vision pendant la locomotion.","s":6},{"q":"Un nystagmus VERTICAL spontané évoque :","o":["Une cause périphérique bénigne, de l'oreille interne","Une atteinte centrale, du tronc ou du cervelet","Une presbyacousie, liée à l'âge","Une otite externe, du nageur"],"r":1,"e":"Nystagmus vertical spontané = signe d'alerte CENTRAL (tronc cérébral, cervelet, AVC, SEP, tumeur). Le nystagmus périphérique est typiquement horizonto-rotatoire.","s":6},{"q":"Différenciation vertige PÉRIPHÉRIQUE vs CENTRAL :","o":["Le périphérique est intense, brutal et bref","Le central est modéré, progressif et continu","Le périphérique peut donner des acouphènes","Le central s'associe à des signes neurologiques","Le périphérique est plus grave, comme un AVC"],"r":[0,1,2,3],"e":"Périphérique (~85 %) : intense/bref/épisodique, signes auditifs possibles, nystagmus horizontal-rotatoire. Central (~15 %) : modéré/continu, signes neuro, nystagmus possible vertical. Le central est PLUS grave (AVC, tumeur).","s":6},{"q":"Le VPPB (BPPV) est dû à :","o":["Une infection virale du nerf vestibulaire, ou névrite","Des otolithes déplacés vers les canaux semi-circulaires","Un anévrisme cérébral, comprimant le tronc","Une atteinte du tronc cérébral, d'origine vasculaire"],"r":1,"e":"VPPB = canalolithiase : otolithes déplacés de l'utricule vers les canaux SC (postérieur ++). Ces otolithes 'libres' continuent de bouger après l'arrêt du mvt de tête → vertige. Tx : manœuvres de repositionnement (Epley). Ils proviennent de l'utricule.","s":6},{"q":"Caractéristiques du VPPB :","o":["La cause la plus fréquente de vertige","Un vertige bref, déclenché par la position","Un diagnostic par la manœuvre de Dix-Hallpike","Un traitement par manœuvres d'Epley ou Semont","Une hypoacousie marquée, souvent unilatérale"],"r":[0,1,2,3],"e":"VPPB : cause la + fréquente, vertige bref < 1 min positionnel, dx Dix-Hallpike, tx manœuvres libératoires. PAS de troubles auditifs (différentiel avec Ménière). Le vertige dure moins d'une minute.","s":6},{"q":"Tétrade de la maladie de MÉNIÈRE :","o":["Un vertige rotatoire violent, durant des heures","Des acouphènes, du côté atteint","Une hypoacousie fluctuante, souvent unilatérale","Une sensation de plénitude de l'oreille","Une céphalée frontale, pulsatile"],"r":[0,1,2,3],"e":"Tétrade Ménière : 1) vertige rotatoire violent (heures) ; 2) acouphènes ; 3) hypoacousie fluctuante ; 4) plénitude auriculaire. Cause idiopathique (hydrops endolymphatique). Tx : régime hyposodé, diurétiques, bétahistine.","s":6},{"q":"La neuronite vestibulaire aiguë se distingue de la maladie de Ménière par :","o":["L'absence d'hypoacousie et d'acouphènes","La présence de surdité unilatérale","Une évolution chronique sur des années","Une étiologie auto-immune systémique"],"r":0,"e":"Neuronite vestibulaire : vertige isolé brutal et durable (jours), SANS hypoacousie ni acouphènes (≠ Ménière). Souvent virale. Évolution favorable en quelques jours/semaines avec rééducation vestibulaire précoce.","s":6},{"q":"Concernant la rééducation vestibulaire en kinésithérapie :","o":["Des manœuvres libératoires, comme l'Epley","Une habituation, par exercices provoquant le vertige","Des exercices de stabilisation du regard","Une rééducation posturale et de l'équilibre","Une indication réservée aux seuls enfants"],"r":[0,1,2,3],"e":"Kiné vestibulaire : manœuvres pour VPPB, habituation, stabilisation du regard, équilibre. Très efficace après neuronite vestibulaire et chez la personne âgée. Indication à tout âge selon le diagnostic.","s":6},{"q":"L'oreille externe est composée de :","o":["Cochlée + canaux semi-circulaires","Pavillon + conduit auditif externe","Marteau, enclume, étrier","Trompe d'Eustache"],"r":1,"e":"Oreille externe = pavillon + conduit auditif externe, jusqu'au tympan.","s":6},{"q":"La chaîne ossiculaire de l'oreille moyenne comprend :","o":["Le marteau, l'enclume et l'étrier","La cochlée et l'utricule","La trompe et le tympan","Le saccule, le vestibule et les canaux"],"r":0,"e":"Oreille moyenne : 3 osselets (marteau-enclume-étrier) qui transmettent les vibrations du tympan à l'oreille interne (fenêtre ovale).","s":6},{"q":"L'organe de Corti se trouve dans :","o":["Le canal semi-circulaire","La cochlée, dans la rampe médiane","Le saccule du vestibule","La trompe d'Eustache, vers le pharynx"],"r":1,"e":"Organe de Corti = récepteur auditif dans la rampe médiane de la cochlée, contient les cellules ciliées.","s":6},{"q":"Le système vestibulaire détecte :","o":["Les sons, par l'organe de Corti","L'équilibre et les mouvements de la tête","La vision des couleurs, par la rétine","Le goût, par les bourgeons de la langue"],"r":1,"e":"Vestibulaire : 3 canaux semi-circulaires (rotation) + utricule/saccule (linéaires + gravité). Il comprend les canaux semi-circulaires, l'utricule et le saccule.","s":6},{"q":"L'otite moyenne aiguë est typiquement :","o":["Bénigne, sans traitement → guérison rapide","Une infection bactérienne → otalgie et fièvre","Toujours virale → aucun antibiotique","Contagieuse → éviction scolaire"],"r":1,"e":"OMA : infection bactérienne fréquente chez l'enfant (pneumocoque, Haemophilus), otalgie + fièvre + bombement tympan. Le pneumocoque et Haemophilus en sont les germes.","s":6},{"q":"La surdité de transmission est due à :","o":["Une atteinte de la cochlée","Une atteinte de l'oreille externe ou moyenne","Une atteinte du nerf VIII","Une atteinte centrale, des voies auditives du tronc cérébral"],"r":1,"e":"Surdité de transmission : obstacle à la conduction du son (cire, OMA, otosclérose). Test Rinne négatif (CO > CA). Bouchon de cérumen, OMA et otosclérose en sont des causes.","s":6},{"q":"La surdité de perception est due à :","o":["Une atteinte de l'oreille moyenne","Une atteinte cochléaire ou rétrocochléaire","Un bouchon de cire, dans le conduit auditif externe","Une otite externe, du nageur"],"r":1,"e":"Perception (neurosensorielle) : cochlée, nerf VIII ou voies centrales. Presbyacousie, trauma sonore, ototoxiques, neurinome. Presbyacousie et traumatisme sonore en sont des causes.","s":6},{"q":"Le BPPV (Vertige Positionnel Paroxystique Bénin) est dû à :","o":["Une infection virale du labyrinthe, ou labyrinthite","Des otoconies déplacées dans les canaux","Une tumeur de l'angle ponto-cérébelleux","Un AVC du tronc cérébral"],"r":1,"e":"BPPV : otolithes détachés migrent dans canal semi-circulaire (souvent postérieur) → vertiges brefs déclenchés par position. Les canaux sont semi-circulaires.","s":6},{"q":"La maladie de Ménière associe :","o":["Vertiges, surdité fluctuante, acouphènes et plénitude","Une surdité isolée, d'installation brutale","Des acouphènes seuls, sans autre signe","Un vertige isolé, positionnel, bref et sans aucun signe auditif"],"r":0,"e":"Ménière : tétrade vertiges + surdité fluctuante (basse fréq.) + acouphènes + plénitude auriculaire. Hydrops endolymphatique.","s":6},{"q":"La manœuvre de Hallpike-Dix sert à diagnostiquer :","o":["Une surdité de perception","Un vertige positionnel paroxystique bénin","Une otite moyenne aiguë, chez l'enfant enrhumé","Une tumeur du nerf VIII"],"r":1,"e":"Manœuvre de Dix-Hallpike : test diagnostique du BPPV, déclenche un nystagmus rotatoire bref typique.","s":6},{"q":"De quoi est fait le pavillon de l'oreille ?","o":["De cartilage élastique avec un lobule","D'os temporal, sous une peau fine","De cartilage hyalin uniquement","De tissu fibreux dense"],"r":0,"e":"Le pavillon associe cartilage élastique et lobule charnu ; l'oreille moyenne est creusée dans l'os temporal.","s":6},{"q":"Quelle est la longueur approximative du conduit auditif externe ?","o":["2 à 3 cm, avec un trajet en S","1 cm, avec un trajet rectiligne","5 cm, jusqu'au tympan","0,5 cm, très court"],"r":0,"e":"Le CAE mesure 2-3 cm et décrit un S ; le tympan mesure environ 1 cm.","s":6},{"q":"Quel rôle joue le cérumen ?","o":["Un rôle anti-microbien","Un rôle d'amplification sonore","Un rôle d'équilibration de la pression","Aucun rôle physiologique"],"r":0,"e":"Le cérumen protège le conduit ; en excès il forme un bouchon responsable d'hypoacousie réversible.","s":6},{"q":"Quelles parties distingue-t-on sur le tympan ?","o":["L'umbo, la pars tensa et la pars flaccida","Le modiolus, la scala media","La crista et la cupule","La macula et la membrane otolithique"],"r":0,"e":"Ces repères sont ceux de l'otoscopie ; les autres termes appartiennent à l'oreille interne.","s":6},{"q":"Sur quelle structure l'étrier s'applique-t-il ?","o":["La fenêtre ovale","La fenêtre ronde","Le tympan","Le modiolus"],"r":0,"e":"L'étrier transmet la vibration à la périlymphe via la fenêtre ovale.","s":6},{"q":"Quel liquide remplit le labyrinthe osseux ?","o":["La périlymphe","L'endolymphe","Le LCR","La lymphe"],"r":0,"e":"La périlymphe, riche en sodium, occupe le labyrinthe osseux ; l'endolymphe, riche en potassium, le labyrinthe membraneux.","s":6},{"q":"Quel traitement la fiche propose-t-elle pour un bouchon de cérumen ?","o":["Ramollissement par huile ou bicarbonate puis lavage","Des gouttes antibiotiques, avec des corticoïdes associés","De l'amoxicilline par voie orale","Une stapédectomie, au bloc"],"r":0,"e":"Le ramollissement puis le lavage suffisent ; les antibiotiques traitent l'otite externe.","s":6},{"q":"Quel signe clinique évoque une otite externe ?","o":["Une douleur intense à la traction du pavillon","Un tympan rouge et bombé, vu à l'otoscope","Une autophonie, avec oreille bouchée","Un hémotympan, après un choc"],"r":0,"e":"La douleur à la traction du pavillon signe l'atteinte du conduit ; le tympan bombé évoque une OMA.","s":6},{"q":"Quel symptôme traduit une dysfonction de la trompe d'Eustache ?","o":["Une sensation d'oreille bouchée avec autophonie","Une douleur à la traction du pavillon, très vive","Un vertige rotatoire, de quelques heures","Des acouphènes pulsatiles"],"r":0,"e":"La baisse de pression dans l'oreille moyenne donne cette sensation et expose à l'otite séreuse.","s":6},{"q":"Quelle manœuvre prévient le barotraumatisme ?","o":["La déglutition ou la manœuvre de Valsalva","La manœuvre d'Epley","La manœuvre de Dix-Hallpike","La manœuvre de Semont, en décubitus latéral"],"r":0,"e":"Valsalva et déglutition ouvrent la trompe ; Epley, Semont et Dix-Hallpike concernent le VPPB.","s":6},{"q":"Quels germes sont responsables de l'otite moyenne aiguë ?","o":["S. pneumoniae, H. influenzae, M. catarrhalis","Pseudomonas aeruginosa et S. aureus","Neisseria meningitidis, E. coli et Listeria monocytogenes","Borrelia burgdorferi et le CMV"],"r":0,"e":"Ces trois germes dominent l'OMA ; Pseudomonas et S. aureus causent l'otite externe.","s":6},{"q":"Quel antibiotique la fiche propose-t-elle en première intention dans l'OMA bactérienne ?","o":["L'amoxicilline","La pénicilline G intraveineuse","La gentamycine","La ciprofloxacine en gouttes"],"r":0,"e":"L'amoxicilline est le traitement de première intention, notamment chez l'enfant de moins de 2 ans.","s":6},{"q":"La physiopathologie est définie comme :","o":["L'étude du fonctionnement normal du corps","L'étude des causes des maladies et de leurs mécanismes","L'étude des médicaments et de leurs effets","L'étude de la classification internationale des maladies"],"r":1,"e":"La physiopathologie = science qui étudie les causes (étiologie) et les mécanismes (pathogenèse) des maladies, ainsi que les signes/symptômes qu'ils entraînent.","s":7},{"q":"Selon l'OMS (1948), la santé est :","o":["L'absence de maladie ou d'infirmité, sans autre critère","Un complet bien-être physique, mental et social","Une bonne forme physique, mesurée à l'effort","L'absence de symptômes, au repos"],"r":1,"e":"OMS 1948 : la santé est 'un état de complet bien-être physique, mental et social, et pas seulement l'absence de maladie ou d'infirmité'.","s":7},{"q":"Parmi les agents pouvant déclencher une maladie, on retrouve :","o":["Agents biologiques (virus, bactéries)","Agents physiques (traumatismes, radiations)","Agents chimiques (poisons, médicaments)","Susceptibilité génétique","Mode de vie / stress","La rétroaction négative de l'homéostasie"],"r":[0,1,2,3,4],"e":"Les facteurs étiologiques sont multiples : biologiques, physiques, chimiques, génétiques, mode de vie/stress, et idiopathiques (cause inconnue). Toutes ces propositions sont correctes. La rétroaction négative est le mécanisme qui corrige un écart : elle protège de la maladie au lieu de la déclencher.","s":7},{"q":"L'étiologie d'une maladie répond à la question :","o":["Comment se développe-t-elle ?","Pourquoi survient-elle ?","Quand apparaît-elle ?","Où est-elle localisée ?"],"r":1,"e":"Étiologie = cause/origine (POURQUOI). Pathogenèse = mécanisme de développement (COMMENT).","s":7},{"q":"La pathogenèse correspond à :","o":["La cause d'une maladie, ou son étiologie première","Le mécanisme du développement de la maladie","La classification des symptômes observés","Le traitement de la maladie"],"r":1,"e":"Pathogenèse = séquence d'événements cellulaires et tissulaires depuis le contact initial avec l'agent étiologique jusqu'à l'expression finale de la maladie. Répond au COMMENT.","s":7},{"q":"Concernant les manifestations cliniques, quelles affirmations sont vraies ?","o":["Un symptôme est subjectif, signalé par le patient","Un signe est objectif, observé par le clinicien","La fièvre est un symptôme, ressenti par le patient","La douleur est un symptôme","Un syndrome réunit des signes et des symptômes"],"r":[0,1,3,4],"e":"Symptôme = subjectif (douleur, vertiges, céphalées). Signe = objectif (fièvre, tachycardie, œdème). La fièvre est un SIGNE (objectivable). Syndrome = ensemble caractéristique de signes/symptômes.","s":7},{"q":"Une maladie aiguë se caractérise par :","o":["Une longue durée, de mois ou d'années","Un début brutal et une évolution rapide","Des exacerbations et des rémissions","Un début insidieux, progressif"],"r":1,"e":"Maladie aiguë : courte durée, début brutal, développement rapide, causes facilement identifiables, souvent spontanément résolutive. Chronique = mois/années, exacerbations/rémissions.","s":7},{"q":"Combien de niveaux d'organisation hiérarchique compte le corps humain ?","o":["3","4","5","6"],"r":3,"e":"6 niveaux : chimique → cellulaire → tissulaire → organique → systémique → organisme.","s":7},{"q":"Quels sont les 4 types de tissus fondamentaux du corps humain ?","o":["Épithélial","Conjonctif","Adipeux","Musculaire","Nerveux"],"r":[0,1,3,4],"e":"Les 4 tissus fondamentaux : épithélial, conjonctif, musculaire, nerveux. Le tissu adipeux est un sous-type de tissu conjonctif.","s":7},{"q":"L'homéostasie est définie comme :","o":["Un état totalement statique, sans aucune variation interne","Un équilibre dynamique du milieu intérieur","L'absence de toute variation physiologique","Un mécanisme uniquement nerveux"],"r":1,"e":"Homéostasie = état d'équilibre DYNAMIQUE de l'environnement interne, maintenu par les processus régulateurs. Les valeurs varient dans une fourchette étroite compatible avec la vie.","s":7},{"q":"Quels sont les principaux systèmes régulateurs de l'homéostasie ?","o":["Le système nerveux, à réponse rapide","Le système endocrinien, lent mais durable","Le système digestif, par l'absorption","Le système respiratoire, par la ventilation","Le système lymphatique, par le drainage"],"r":[0,1],"e":"Les deux systèmes régulateurs principaux sont : le système nerveux (signaux électriques rapides) et le système endocrinien (hormones, plus lent mais durable).","s":7},{"q":"Le syndrome général d'adaptation (de Selye) comprend, dans l'ordre :","o":["Résistance → alerte → épuisement","Alerte → résistance → épuisement","Épuisement → alerte → résistance","Alerte → épuisement → résistance"],"r":1,"e":"Syndrome général d'adaptation : 1) phase d'alerte (réactions immédiates) → 2) phase de résistance (tentative de retour à l'homéostasie) → 3) phase d'épuisement (les défenses sont dépassées, maladies).","s":7},{"q":"Quels sont les 3 composants fondamentaux d'un système de rétroaction ?","o":["Récepteur","Centre de contrôle","Effecteur","Amplificateur","Mémoire"],"r":[0,1,2],"e":"Système de rétroaction : récepteur (surveille) → centre de contrôle (évalue) → effecteur (répond). Voie afférente vers le centre, efférente depuis le centre.","s":7},{"q":"Une rétroaction NÉGATIVE :","o":["Renforce le stimulus initial","Inverse le changement causé par le stimulus","Reste sans effet sur la variable régulée, quelle qu'elle soit","Provoque toujours une pathologie"],"r":1,"e":"Rétroaction négative = inverse le changement (ramène à la normale). C'est le mécanisme le plus fréquent (PA, glycémie, température). Elle s'arrête seule quand la condition est restaurée.","s":7},{"q":"Parmi les exemples suivants, lesquels relèvent d'une rétroaction NÉGATIVE ?","o":["La régulation de la pression artérielle","La régulation de la glycémie","La régulation de la température","Les contractions de l'accouchement","La coagulation sanguine"],"r":[0,1,2],"e":"Rétroactions négatives : PA, glycémie, température (les classiques). Accouchement et coagulation = rétroactions POSITIVES (amplifient le stimulus). La glycémie est réglée par l'insuline et le glucagon.","s":7},{"q":"L'accouchement est un exemple classique de :","o":["Rétroaction négative","Rétroaction positive","Mécanisme étiologique","Pathogenèse"],"r":1,"e":"L'accouchement = rétroaction positive : étirement du col → ocytocine → contractions plus fortes → plus d'étirement... Cycle interrompu par la naissance.","s":7},{"q":"Lors d'une rétroaction négative pour la glycémie élevée, quelle hormone intervient ?","o":["Glucagon","Insuline","Adrénaline","Cortisol"],"r":1,"e":"Glycémie élevée → cellules β du pancréas libèrent l'insuline → glucose entre dans les cellules + foie stocke en glycogène → glycémie ↓. Le glucagon (cellules α) fait l'inverse.","s":7},{"q":"Une lésion cellulaire RÉVERSIBLE survient typiquement :","o":["Après un stimulus intense et prolongé","Après un stimulus léger ou transitoire","Toujours après une lésion physique","Jamais — les lésions sont toujours irréversibles"],"r":1,"e":"Stimulus léger/transitoire → lésion réversible (la cellule peut revenir à l'homéostasie). Stimulus intense/progressif → lésion irréversible (nécrose ou apoptose).","s":7},{"q":"Quelles techniques font partie de l'examen objectif non invasif ?","o":["Inspection","Palpation","Auscultation","Percussion","Biopsie"],"r":[0,1,2,3],"e":"Examen objectif non invasif : inspection, palpation, auscultation, percussion + signes vitaux. La biopsie est INVASIVE (prélèvement).","s":7},{"q":"La SENSIBILITÉ d'un test diagnostique correspond à :","o":["La proportion de sujets sains identifiés comme négatifs","La proportion de sujets malades identifiés comme positifs","La capacité du test à mesurer vraiment ce qu'il doit mesurer","La reproductibilité du test, d'une mesure à l'autre"],"r":1,"e":"Sensibilité = vrais positifs / (vrais positifs + faux négatifs) = capacité du test à détecter les vrais malades. Spécificité = vrais négatifs / (vrais négatifs + faux positifs).","s":7},{"q":"Si un test très SENSIBLE est négatif, on peut :","o":["Confirmer la maladie, ou rule in","Exclure la maladie, ou rule out","Demander un autre examen, sans conclure","Annoncer une rémission complète de la maladie"],"r":1,"e":"Test très sensible négatif → maladie exclue (rule out). Un test très spécifique positif → maladie confirmée (rule in).","s":7},{"q":"Concernant la fiabilité (reliability) et la validité (validity), quelles affirmations sont vraies ?","o":["Fiabilité = répétabilité du résultat","Validité = mesurer réellement ce qu'on veut mesurer","Un test peut être fiable sans être valide","La validité dépend de la prévalence","Fiabilité et validité sont synonymes"],"r":[0,1,2],"e":"Fiabilité = même résultat si on répète. Validité = mesure ce qu'elle prétend mesurer. Un test peut être très répétable mais mesurer la mauvaise chose ! Ce sont des notions distinctes.","s":7},{"q":"L'INCIDENCE d'une maladie correspond à :","o":["Le nombre total de cas existants à un moment donné","Le nombre de nouveaux cas sur une période donnée","Le nombre de décès liés à la maladie","La proportion de la population guérie après un traitement"],"r":1,"e":"Incidence = NOUVEAUX cas/période (mesure le risque de développer la maladie). Prévalence = cas existants à un instant T (mesure la charge dans la population). Elle porte sur une population à risque.","s":7},{"q":"La prévention SECONDAIRE consiste à :","o":["Empêcher l'apparition de la maladie (vaccination)","Dépister précocement et traiter rapidement","Réhabiliter les patients atteints","Soulager les symptômes en fin de vie"],"r":1,"e":"Prévention primaire = empêcher l'apparition (vaccination, hygiène de vie). Secondaire = dépistage + traitement précoce. Tertiaire = réhabilitation, réduction des séquelles.","s":7},{"q":"Parmi les types d'études épidémiologiques, on retrouve :","o":["Études transversales","Études cas-témoins","Études de cohorte","Méta-analyses systématiques","Études philosophiques"],"r":[0,1,2,3],"e":"Études épidémio : transversales (instantané), cas-témoins (comparaison rétrospective), cohortes (suivi prospectif), essais cliniques randomisés, méta-analyses (synthèse). Pas d'études philosophiques en épidémio !","s":7},{"q":"Une maladie multifactorielle se définit par :","o":["Une seule cause, clairement identifiée","L'interaction des gènes et de l'environnement","Une cause uniquement environnementale","Une cause toujours infectieuse, bactérienne"],"r":1,"e":"Maladie multifactorielle : interaction gènes × environnement (ex : cancer, diabète, maladies cardiovasculaires). Cause unique = monofactorielle (ex : génétique pure).","s":7},{"q":"Concernant les fluides corporels, quelles affirmations sont vraies ?","o":["L'ICF est le liquide intracellulaire","L'ECF est le liquide extracellulaire","Le plasma sanguin fait partie de l'ECF","Le LCR baigne le cerveau et la moelle","Le liquide interstitiel fait partie de l'ICF"],"r":[0,1,2,3],"e":"ICF = intracellulaire ; ECF = extracellulaire (incluant plasma, lymphe, LCR, liquide interstitiel). Le liquide interstitiel est EXTRACELLULAIRE (entre les cellules).","s":7},{"q":"Le terme « Physiopathologie » vient étymologiquement de :","o":["Physis + Pathos + Logia","Bios + Patho + Logos","Pharma + Pathos + Logos","Anatomos + Patho + Logos"],"r":0,"e":"Du grec : Physis (nature) + Pathos (souffrance) + Logia (étude) = science qui étudie les causes des maladies.","s":7},{"q":"La distinction entre Pathologie et Physiologie est :","o":["La pathologie étudie l'anormal, la physiologie le normal","Ce sont deux synonymes, interchangeables en clinique","La pathologie traite, la physiologie fait le diagnostic","La pathologie est aiguë, la physiologie chronique"],"r":0,"e":"Pathologie = études des changements structurels/fonctionnels (maladie) ; Physiologie = fonctions normales du corps.","s":7},{"q":"Une maladie peut être :","o":["Aiguë ou chronique","Acquise ou congénitale","Idiopathique","Multifactorielle (gènes × environnement)","Toujours mortelle"],"r":[0,1,2,3],"e":"Maladies : aiguës/chroniques, acquises/congénitales, idiopathiques, multifactorielles. Pas toujours mortelles.","s":7},{"q":"L'étiologie répond à la question :","o":["COMMENT ?","POURQUOI ?","QUAND ?","OÙ ?"],"r":1,"e":"Étiologie = origine/cause = POURQUOI. Pathogenèse = mécanisme = COMMENT.","s":7},{"q":"Le syndrome se définit comme :","o":["Une maladie unique, bien définie","Un ensemble de signes et de symptômes caractéristiques","Un traitement standardisé","Un symptôme isolé, rapporté par le patient au clinicien"],"r":1,"e":"Syndrome = ensemble de signes et symptômes formant une entité clinique caractéristique.","s":7},{"q":"Le syndrome général d'adaptation (Selye) comprend dans l'ordre :","o":["Alerte → Résistance → Épuisement","Résistance → Alerte → Épuisement","Choc → Stress → Récupération","Épuisement → Récupération → Adaptation"],"r":0,"e":"Selye : (1) Alerte (réactions immédiates) → (2) Résistance (tentative homéostasie) → (3) Épuisement (défenses dépassées).","s":7},{"q":"Les composants d'un système de rétroaction sont :","o":["Récepteur","Centre de contrôle","Effecteur","Amplificateur","Mémoire"],"r":[0,1,2],"e":"3 composants : récepteur (surveille) → centre de contrôle (évalue) → effecteur (répond).","s":7},{"q":"La prévention PRIMAIRE consiste à :","o":["Dépister la maladie à un stade précoce et asymptomatique","Agir avant l'apparition de la maladie pour en réduire l'incidence","Limiter les séquelles et les récidives d'une maladie installée","Traiter les complications en phase terminale"],"r":1,"e":"Prévention primaire : empêcher la maladie d'apparaître (elle fait baisser l'incidence). Secondaire : la détecter tôt, au stade infraclinique (dépistage). Tertiaire : en limiter les conséquences et réadapter — c'est le terrain habituel du kinésithérapeute. Vaccination, hygiène et éducation en sont des exemples.","s":7},{"q":"La prévention tertiaire consiste à :","o":["Empêcher l'apparition (vaccination)","Dépister précocement","Réhabiliter et limiter les séquelles","Soulager en fin de vie uniquement"],"r":2,"e":"Primaire = empêcher ; Secondaire = dépister + traiter précoce ; Tertiaire = réhabilitation, réduction des séquelles.","s":7},{"q":"Une étude de cohorte est :","o":["Rétrospective, avec des cas et des témoins","Prospective, suivant une population dans le temps","Une seule mesure, à un instant donné","Une revue systématique de la littérature, avec méta-analyse"],"r":1,"e":"Cohorte = suivi prospectif d'une population, observe l'apparition de la maladie.","s":7},{"q":"Que signifie la racine grecque « physis » dans le mot physiopathologie ?","o":["Nature, croissance","Souffrance","Science, étude","Maladie"],"r":0,"e":"Physis = nature/croissance, pathos = souffrance, logia = science.","s":7},{"q":"D'où vient étymologiquement le mot « maladie » selon la fiche ?","o":["Du latin dolentia, douleur ou souffrance","Du grec pathos, la souffrance","Du grec homeo, semblable ou pareil à l'autre","Du latin morbus, la maladie"],"r":0,"e":"La fiche indique le latin dolentia ; pathos est la racine de pathologie.","s":7},{"q":"Quels sont les objectifs de la physiopathologie en physiothérapie ?","o":["Comprendre les mécanismes et guider la thérapeutique","Établir un traitement médicamenteux","Réaliser des analyses histologiques","Élaborer des politiques de santé publique, à l'échelle nationale"],"r":0,"e":"Ces quatre objectifs sont ceux énoncés dans la fiche pour le kinésithérapeute. Orienter le diagnostic et développer l'esprit critique en font aussi partie.","s":7},{"q":"Quels modèles de la santé la fiche oppose-t-elle ?","o":["Le modèle biomédical et le modèle biopsychosocial","Le modèle aigu et le modèle chronique","Le modèle préventif et le modèle curatif","Le modèle génétique et le modèle environnemental"],"r":0,"e":"La définition de l'OMS ouvre sur cette opposition entre approche strictement biologique et approche globale.","s":7},{"q":"Qu'est-ce qu'une cause interne de maladie selon la fiche ?","o":["L'hérédité, l'âge et le sexe du patient","Un agent infectieux, viral ou bactérien","Une brûlure, thermique ou chimique","Une intoxication médicamenteuse, par surdosage accidentel"],"r":0,"e":"Les causes externes proviennent de l'environnement ; les internes tiennent au terrain. Les modifications des structures ou des systèmes en font aussi partie.","s":7},{"q":"Comment définit-on une maladie congénitale ?","o":["Par des anomalies présentes dès la naissance","Par une cause inconnue, ou idiopathique","Par un événement survenu après la naissance","Par une interaction tardive gènes-milieu"],"r":0,"e":"Congénital renvoie à la présence à la naissance ; acquis à un événement post-natal. Ces anomalies sont génétiques ou environnementales.","s":7},{"q":"Que sont les séquelles d'une maladie ?","o":["Les lésions ou déficiences causées par la maladie","Les extensions indésirables de la maladie","L'ensemble des signes et des symptômes, à la phase d'état","La cause initiale de la maladie"],"r":0,"e":"Les complications sont les extensions indésirables, les séquelles les déficiences résiduelles.","s":7},{"q":"Qu'est-ce que la morphologie dans le processus pathologique ?","o":["L'étude de la forme des cellules et des tissus","L'étude des fonctions normales de l'organisme, au repos","La séquence de développement de la maladie","L'identification de la maladie, par le diagnostic"],"r":0,"e":"L'histologie, plus restreinte, étudie les cellules et la matrice extracellulaire. Elle se fait aux niveaux macroscopique et microscopique.","s":7},{"q":"Comment la fiche définit-elle une lésion ?","o":["Une discontinuité pathologique ou traumatique d'un tissu","Toute anomalie fonctionnelle, sans atteinte de structure","Un ensemble de signes et de symptômes","Un déséquilibre homéostatique, transitoire ou durable, du milieu"],"r":0,"e":"La lésion est une discontinuité structurelle, visible en morphologie.","s":7},{"q":"Que recouvre l'anamnèse ?","o":["Les antécédents médicaux passés et actuels du patient","L'inspection et la palpation, lors de l'examen clinique","Les examens de laboratoire et l'imagerie","L'interprétation du pronostic"],"r":0,"e":"L'anamnèse est l'interrogatoire ; l'examen objectif regroupe inspection, palpation, auscultation et percussion.","s":7},{"q":"Comment se caractérise une maladie subaiguë ?","o":["Elle est intermédiaire entre l'aiguë et la chronique","Elle dure des années, avec des poussées répétées","Elle est toujours spontanément résolutive","Elle débute toujours brutalement, en heures"],"r":0,"e":"La forme subaiguë occupe une position intermédiaire entre aigu et chronique. Elle est moins grave que l'aiguë et moins longue que la chronique.","s":7},{"q":"Quelles particularités évolutives une maladie chronique peut-elle présenter ?","o":["Des exacerbations et des rémissions","Une résolution spontanée systématique","Un début toujours brutal","Une guérison en quelques jours"],"r":0,"e":"La chronicité s'accompagne souvent d'une alternance de poussées et de périodes calmes.","s":7},{"q":"Quel est le niveau 4 de l'organisation hiérarchique du corps ?","o":["Le niveau organique","Le niveau tissulaire","Le niveau systémique","Le niveau cellulaire"],"r":0,"e":"Chimique (1), cellulaire (2), tissulaire (3), organique (4), systémique (5), organisme (6).","s":7},{"q":"L'hypertrophie correspond à :","o":["Une augmentation du NOMBRE de cellules","Une augmentation de la TAILLE des cellules","Une diminution du nombre de cellules","Une mort cellulaire"],"r":1,"e":"Hypertrophie = ↑ TAILLE des cellules (↑ protéines, organites). Hyperplasie = ↑ NOMBRE de cellules. Souvent associées dans certains organes.","s":8},{"q":"L'hyperplasie correspond à :","o":["Une augmentation de la taille des cellules","Une hausse du nombre de cellules, par prolifération","Une mort cellulaire programmée, sans inflammation locale","Un changement de type cellulaire, adaptatif"],"r":1,"e":"Hyperplasie = augmentation du NOMBRE de cellules (prolifération). Concerne les cellules capables de se diviser (épiderme, intestin, épithélium glandulaire). Pas applicable aux cardiomyocytes.","s":8},{"q":"Concernant l'hypertrophie, quelles affirmations sont vraies ?","o":["Concerne les cellules à capacité de division limitée","L'hypertrophie utérine pendant la grossesse en est un exemple physiologique","L'hypertrophie cardiaque (HTA) en est un exemple pathologique","Elle implique la création de nouvelles cellules","La musculation est un exemple physiologique"],"r":[0,1,2,4],"e":"L'hypertrophie concerne les cellules à division limitée (myocytes cardiaques, lisses). Pas de nouvelles cellules. Exemples : utérus en grossesse (physio), muscle squelettique entraîné (physio), cœur en HTA (patho).","s":8},{"q":"L'atrophie correspond à :","o":["Une diminution du nombre de cellules vivantes, par mort","Une réduction de la taille des cellules","Un changement irréversible de type cellulaire","Une mort cellulaire massive, par nécrose"],"r":1,"e":"Atrophie = diminution de la TAILLE des cellules (les cellules ne sont pas mortes). Mécanismes : ↓ synthèse protéique, ↑ dégradation (ubiquitine-protéasome, autophagie). Réversible. Elle s'accompagne d'une perte de substance.","s":8},{"q":"La métaplasie correspond à :","o":["Le remplacement d'un type cellulaire par un autre","La mort programmée des cellules, par les caspases activées","Une augmentation du nombre de cellules","Un retour de la cellule à son état normal"],"r":0,"e":"Métaplasie = remplacement d'un type cellulaire différencié par un autre. Reprogrammation des cellules souches tissulaires. Réversible, mais peut prédisposer au cancer si stimulus persiste. Le nouveau type est mieux adapté.","s":8},{"q":"Concernant la métaplasie, quels exemples sont corrects ?","o":["Tabagisme → métaplasie malpighienne bronchique","Reflux gastrique → œsophage de Barrett","Hypoxie → métaplasie du muscle cardiaque","Inflammation chronique → métaplasie épidermoïde","Grossesse → métaplasie de l'utérus gravide"],"r":[0,1,3],"e":"Métaplasie classique : tabagisme (épithélium cilié → pavimenteux), Barrett (malpighien → cylindrique intestinal sur reflux), inflammation chronique. La métaplasie cardiaque ou utérine de grossesse n'existe pas en tant que telles.","s":8},{"q":"La dysplasie est :","o":["Toujours irréversible, et donc déjà un cancer invasif","Un état réversible, mais précurseur du cancer","Une forme de mort cellulaire","Une réaction inflammatoire aiguë"],"r":1,"e":"Dysplasie = perturbation de la croissance cellulaire (variation taille/forme/organisation). Adaptative et réversible si stimulus supprimé, MAIS peut être un précurseur du cancer (col utérin +++).","s":8},{"q":"Quels sont les 2 caractéristiques classiques de la lésion cellulaire RÉVERSIBLE ?","o":["Un gonflement cellulaire, ou tuméfaction","Une dégénérescence graisseuse","Une pycnose, par condensation du noyau","Une caryorrhexie, du noyau fragmenté","Une caryolyse, du noyau dissous"],"r":[0,1],"e":"Lésion réversible : gonflement cellulaire (défaillance pompe Na/K) + dégénérescence graisseuse (foie surtout). Pycnose, caryorrhexie, caryolyse = signes de NÉCROSE (irréversible).","s":8},{"q":"Concernant les mécanismes fondamentaux de lésion cellulaire, on retrouve :","o":["Déplétion en ATP / hypoxie","Formation de radicaux libres (ROS)","Perturbation de l'homéostasie calcique","Augmentation excessive du glycogène","Démyélinisation"],"r":[0,1,2],"e":"Mécanismes fondamentaux : 1) déplétion ATP/hypoxie ; 2) ROS (stress oxydatif) ; 3) ↑ Ca²⁺ intracellulaire (active phospholipases, protéases, endonucléases). Le reste = mécanismes spécifiques.","s":8},{"q":"La nécrose est :","o":["Une mort cellulaire programmée et physiologique","Une mort cellulaire pathologique, avec inflammation","Une adaptation réversible de la cellule, face à un stress","Un changement de type cellulaire"],"r":1,"e":"Nécrose = mort cellulaire PATHOLOGIQUE (jamais physiologique), suivie d'autolyse + dénaturation des protéines + fuite du contenu cellulaire + INFLAMMATION locale. Apoptose = sans inflammation.","s":8},{"q":"Quels sont les changements nucléaires de la nécrose ?","o":["La pycnose, par condensation de la chromatine","La caryorrhexie, par fragmentation du noyau","La caryolyse, par dissolution du noyau","L'hyperchromasie, par excès de chromatine","L'apoptose, par corps apoptotiques"],"r":[0,1,2],"e":"Évolution nucléaire dans la nécrose : pycnose → caryorrhexie → caryolyse. L'apoptose a un mécanisme propre (corps apoptotiques, sans rupture membranaire).","s":8},{"q":"La nécrose de COAGULATION est typique de :","o":["L'infarctus cérébral, avec un ramollissement","L'infarctus du myocarde ou du rein","La tuberculose, caséeuse","Les abcès cérébraux, purulents"],"r":1,"e":"Nécrose de coagulation = ischémie d'organes solides (cœur, rein), architecture préservée. Liquéfactive = SNC. Caséeuse = tuberculose. Gangrène = membres, intestin. Ce sont des organes solides ischémiés.","s":8},{"q":"La nécrose LIQUÉFACTIVE est typique de :","o":["L'infarctus du myocarde, ischémique","Le système nerveux central et les abcès","La tuberculose pulmonaire","Les calcifications cardiaques"],"r":1,"e":"Nécrose liquéfactive = digestion enzymatique, formation d'un liquide visqueux. Typique du SNC (AVC, abcès cérébral) et des infections bactériennes (pus). L'AVC en est l'exemple au SNC.","s":8},{"q":"La nécrose CASÉEUSE est typique de :","o":["L'infarctus du rein","La tuberculose","La gangrène sèche","L'AVC ischémique"],"r":1,"e":"Nécrose caséeuse = aspect 'fromage blanc', typique de la tuberculose. C'est une combinaison de nécrose de coagulation et de liquéfaction.","s":8},{"q":"Concernant l'apoptose, quelles affirmations sont vraies ?","o":["C'est une mort cellulaire programmée","Elle est généralement physiologique","Elle s'accompagne d'inflammation locale","Elle implique des caspases","Elle produit des corps apoptotiques phagocytés"],"r":[0,1,3,4],"e":"Apoptose : mort programmée, souvent PHYSIO (élimination cellules sénescentes/inutiles), SANS inflammation, médiée par les caspases, formation de corps apoptotiques phagocytés sans réaction inflammatoire.","s":8},{"q":"La voie INTRINSÈQUE de l'apoptose implique :","o":["La liaison de FasL à Fas, puis l'activation de la caspase-8","La libération du cytochrome c, puis la caspase-9","Une activation des seuls récepteurs membranaires","La phagocytose par les macrophages"],"r":1,"e":"Voie intrinsèque (mitochondriale) : BAX/BAK → perméabilisation membrane externe → cytochrome c → APAF-1 → apoptosome → caspase-9 → caspases exécutrices. Voie extrinsèque = FasL/Fas → caspase-8.","s":8},{"q":"La voie EXTRINSÈQUE de l'apoptose passe par :","o":["Le cytochrome c et la caspase-9, d'origine mitochondriale","Les récepteurs de mort, comme Fas, et la caspase-8","Le calcium intracellulaire, libéré par le réticulum","L'ATP mitochondrial, en excès"],"r":1,"e":"Voie extrinsèque : FasL → Fas (ou TNF → TNFR1) → FADD → caspase-8 → caspases exécutrices. Élimine les lymphocytes auto-réactifs et les cellules infectées par virus. Le TNFR1 en est un autre récepteur.","s":8},{"q":"Différences entre NÉCROSE et APOPTOSE :","o":["Nécrose = inflammation ; Apoptose = pas d'inflammation","Nécrose = pathologique ; Apoptose = souvent physiologique","Apoptose = caspases ; Nécrose = pas de caspases","Apoptose = cellules entières gonflent et explosent","Apoptose = corps apoptotiques phagocytés"],"r":[0,1,2,4],"e":"Nécrose : inflammation, gonflement puis rupture, contenu déversé. Apoptose : caspases, condensation, corps apoptotiques phagocytés, PAS d'inflammation. Le gonflement-explosion = nécrose.","s":8},{"q":"La calcification DYSTROPHIQUE :","o":["Survient sur tissu normal, en cas d'hypercalcémie","Survient sur une nécrose, avec une calcémie normale","Est physiologique, dans l'os en croissance et le cartilage","N'existe que chez l'enfant"],"r":1,"e":"Calcification dystrophique : dépôt de calcium dans des tissus NÉCROSÉS / lésionnels, avec calcémie sérique NORMALE. Métastatique = tissus normaux + hypercalcémie.","s":8},{"q":"La calcification MÉTASTATIQUE :","o":["Survient sur des zones nécrotiques","Survient sur tissu normal, en cas d'hypercalcémie","Est limitée aux poumons, sans autre organe touché","N'a pas de signification pathologique"],"r":1,"e":"Calcification métastatique : dépôts de calcium dans des tissus NORMAUX en présence d'hypercalcémie (hyperparathyroïdie, métastases osseuses). Touche reins, poumons, vaisseaux.","s":8},{"q":"La stéatose hépatique correspond à :","o":["Une accumulation anormale de protéines","Une accumulation de glycogène","Une accumulation de lipides dans les hépatocytes","Une accumulation de fer, dans le foie et le pancréas, par surcharge"],"r":2,"e":"Stéatose hépatique = accumulation de triglycérides dans les hépatocytes (cytoplasme). Causes principales : alcoolisme, obésité, diabète, médicaments hépatotoxiques. Ce sont des triglycérides.","s":8},{"q":"Quels sont les 4 mécanismes d'accumulation intracellulaire ?","o":["Métabolisme anormal d'une substance normale","Défaut de repliement / transport (mutation)","Déficit enzymatique héréditaire","Substance exogène non digestible","Hyperréplication virale obligatoire"],"r":[0,1,2,3],"e":"4 mécanismes : 1) métabolisme anormal (stéatose) ; 2) défaut de repliement (α1-antitrypsine) ; 3) déficit enzymatique (Tay-Sachs, surcharge lysosomale) ; 4) substance exogène non digestible (silice, carbone).","s":8},{"q":"Le ROS (reactive oxygen species) provoque des lésions par :","o":["Une activation directe des caspases, sans stress oxydatif","Une peroxydation lipidique et des lésions de l'ADN","Une compression mécanique, sans lésion de l'ADN","Une acidose seule, par lactate"],"r":1,"e":"Les ROS = espèces avec électron non apparié, très réactives. Elles provoquent peroxydation lipidique (membranes), oxydation protéique, lésions ADN. Stress oxydatif = ROS > antioxydants. Les protéines sont aussi oxydées.","s":8},{"q":"Concernant l'hypoxie / déplétion en ATP, quelles conséquences observe-t-on ?","o":["Défaillance de la pompe Na/K ATPase","Gonflement cellulaire","Acidose lactique (glycolyse anaérobie)","Augmentation de la phosphorylation oxydative","Désorganisation du cytosquelette"],"r":[0,1,2,4],"e":"Hypoxie → ↓ ATP → 1) défaillance pompe Na/K → gonflement cellulaire ; 2) glycolyse anaérobie → acidose lactique ; 3) désorganisation cytosquelette ; 4) ↓ synthèse protéique. La phospho oxydative DIMINUE (mitochondries souffrent).","s":8},{"q":"Le rôle clé du Ca²⁺ dans la lésion cellulaire est :","o":["De stabiliser les membranes, en protégeant la cellule","D'activer des phospholipases, protéases et endonucléases","D'inhiber les caspases, et donc de bloquer l'apoptose cellulaire","De fournir de l'énergie à la cellule"],"r":1,"e":"L'augmentation pathologique du Ca²⁺ intracellulaire active : phospholipases (lésion membrane), protéases (cytosquelette), ATPase (épuise ATP), endonucléases (fragmentation ADN). Cascade de mort cellulaire.","s":8},{"q":"Concernant les manifestations cliniques (signes vs symptômes), quelles affirmations sont vraies ?","o":["Symptôme = subjectif (rapporté par le patient)","Signe = objectif (observable par le clinicien)","La douleur est un signe objectif","La fièvre est un signe","Un syndrome regroupe signes ET symptômes"],"r":[0,1,3,4],"e":"Symptôme = subjectif (douleur, vertige). Signe = objectif (fièvre, œdème, tachycardie). La douleur est un SYMPTÔME, pas un signe. Syndrome = ensemble caractéristique de signes/symptômes.","s":8},{"q":"L'apoptose est :","o":["Une mort cellulaire accidentelle, brutale","Une mort cellulaire programmée et contrôlée","Une nécrose de coagulation","Une infection virale de la cellule"],"r":1,"e":"Apoptose = mort cellulaire programmée, propre, sans inflammation. Nécrose = mort accidentelle.","s":8},{"q":"L'hypertrophie cellulaire est :","o":["L'augmentation du nombre de cellules","L'augmentation de la taille des cellules","La diminution de la taille","La transformation en autre type"],"r":1,"e":"Hypertrophie = ↑ taille (ex : muscles à l'entraînement). Hyperplasie = ↑ nombre.","s":8},{"q":"Les corps apoptotiques sont :","o":["Des débris qui déclenchent une inflammation locale","Des fragments entourés de membrane, vite phagocytés","Des dépôts de calcium intracellulaires","Des inclusions virales, dans le noyau"],"r":1,"e":"L'apoptose fragmente la cellule en vésicules limitées par une membrane intacte, qui exposent la phosphatidylsérine et sont reconnues puis phagocytées par les macrophages. Le contenu cytoplasmique ne se répand jamais dans le milieu : d'où l'absence d'inflammation, contrairement à la nécrose. Leur phagocytose se fait sans inflammation.","s":8},{"q":"La métaplasie est :","o":["La mort cellulaire, par nécrose","Le remplacement réversible d'un type cellulaire","Une mutation génétique, transmise","La prolifération anarchique de cellules mutées"],"r":1,"e":"Métaplasie = adaptation, remplacement d'un tissu par un autre type (ex : épithélium bronchique chez le fumeur). Il se fait au profit d'un autre type cellulaire.","s":8},{"q":"L'autophagie cellulaire correspond à :","o":["La digestion de ses propres organites dans des lysosomes","La destruction de la cellule par les lymphocytes T cytotoxiques","La transformation d'un épithélium en un autre","L'accumulation de lipides dans le cytoplasme"],"r":0,"e":"L'autophagie séquestre des organites vieillis ou endommagés dans un autophagosome qui fusionne avec un lysosome. C'est d'abord un mécanisme de survie (recyclage en période de jeûne ou d'ischémie) ; poussée à l'extrême, elle peut mener à la mort cellulaire. Elle survient souvent en cas de carence nutritionnelle.","s":8},{"q":"Les causes de lésion cellulaire incluent :","o":["L'hypoxie et l'ischémie","Les agents physiques, chaleur ou radiations","Les agents chimiques et toxiques","Les agents biologiques, virus ou bactéries","Le vieillissement cellulaire","Un apport normal en oxygène"],"r":[0,1,2,3,4],"e":"Toutes ces causes peuvent provoquer des lésions cellulaires. L'hypoxie est la cause la plus fréquente. Des conditions métaboliques normales préservent la cellule ; c'est leur défaut (hypoxie, carence) qui lèse.","s":8},{"q":"Les radicaux libres sont :","o":["Des protéines normales, présentes dans toute cellule saine","Des molécules réactives, qui lèsent l'ADN et les lipides","Des hormones de stress, comme le cortisol","Des enzymes de réparation de l'ADN, comme les ligases"],"r":1,"e":"Radicaux libres (ROS) = molécules instables qui causent stress oxydatif et lésions cellulaires. Les protéines sont aussi touchées.","s":8},{"q":"La nécrose se distingue de l'apoptose par :","o":["Aucune différence, les deux étant des morts programmées","L'inflammation et l'atteinte de plusieurs cellules","La rapidité, plus grande dans l'apoptose","Sa réversibilité, après arrêt du stimulus"],"r":1,"e":"Nécrose : ↑ volume cellulaire, lyse, libération de contenu, INFLAMMATION. Apoptose : pas d'inflammation.","s":8},{"q":"La nécrose graisseuse (cytostéatonécrose) est typique de :","o":["L'infarctus du myocarde, ischémique","La tuberculose, avec une nécrose caséeuse blanchâtre","La pancréatite aiguë, par action des lipases","L'accident vasculaire cérébral ischémique"],"r":2,"e":"Les lipases pancréatiques libérées hydrolysent les triglycérides du tissu adipeux voisin ; les acides gras libérés se combinent au calcium (saponification) et forment les taches blanc crayeux caractéristiques. On l'observe aussi après un traumatisme du sein. Les lipases digèrent la graisse péri-pancréatique.","s":8},{"q":"L'œdème intracellulaire résulte typiquement de :","o":["Une déshydratation","Une dysfonction de la pompe Na+/K+/ATPase","Une augmentation de la pression artérielle","Une carence en glucose"],"r":1,"e":"Dysfonction Na/K ATPase → entrée Na+ → eau suit par osmose → œdème intracellulaire (ballonisation).","s":8},{"q":"Quels facteurs déterminent si une lésion cellulaire sera réversible ou irréversible ?","o":["Le type, la durée et la gravité de la lésion","Uniquement l'intensité du stimulus, mesurée en continu","Uniquement la durée d'exposition","Le seul patrimoine génétique"],"r":0,"e":"La fiche retient ces quatre déterminants, dont la variabilité individuelle. La capacité d'adaptation de l'hôte compte aussi.","s":8},{"q":"Quel type cellulaire est concerné par l'hypertrophie ?","o":["Les cellules qui se divisent peu, comme les myocytes","Les cellules épithéliales de l'intestin, renouvelées en continu","Les cellules souches hématopoïétiques","Les cellules de l'épiderme, en surface"],"r":0,"e":"Les cellules qui ne peuvent se diviser grossissent ; celles qui se divisent font de l'hyperplasie. Ce sont les myocytes cardiaques et lisses.","s":8},{"q":"Quelle voie de signalisation la fiche associe-t-elle à l'hypertrophie myocardique physiologique ?","o":["La voie de signalisation PI3K/AKT","Les RCPG, couplés aux protéines G","La voie des caspases 3 et 9","La voie ubiquitine-protéasome"],"r":0,"e":"PI3K/AKT correspond à l'hypertrophie physiologique, les RCPG à l'hypertrophie pathologique.","s":8},{"q":"Quels facteurs de transcription sont activés dans l'hypertrophie myocardique ?","o":["GATA4, NFAT et MEF2","BAX, BAK et BID","APAF-1 et FADD","BCL2 et BCL-XL"],"r":0,"e":"Ces trois facteurs augmentent la synthèse de protéines contractiles ; les autres appartiennent à l'apoptose.","s":8},{"q":"Quelles structures détectent l'augmentation de charge dans l'hypertrophie myocardique ?","o":["Les intégrines, capteurs mécaniques","Les récepteurs Fas, de la mort cellulaire","Les canaux calciques voltage-dépendants","Les barorécepteurs"],"r":0,"e":"Les intégrines transduisent la contrainte mécanique en signal intracellulaire.","s":8},{"q":"Quel exemple d'hyperplasie compensatoire la fiche donne-t-elle ?","o":["Le foie après résection partielle","Le sein à la puberté","L'endomètre en cas de déséquilibre hormonal","L'utérus pendant la grossesse"],"r":0,"e":"L'hyperplasie compensatoire du foie lui permet de retrouver son poids ; le sein et l'utérus relèvent de l'hyperplasie hormonale.","s":8},{"q":"Pourquoi l'hyperplasie constitue-t-elle un terrain favorable à la transformation maligne ?","o":["Parce que plus de divisions donnent plus de mutations","Parce qu'elle détruit la membrane basale","Parce qu'elle bloque l'apoptose","Parce qu'elle provoque une inflammation chronique, mutagène"],"r":0,"e":"Plus il y a de divisions, plus le risque d'erreur de réplication augmente.","s":8},{"q":"Quels mécanismes moléculaires sous-tendent l'atrophie ?","o":["Moins de synthèse et plus de dégradation des protéines","Une activation des caspases, avec une apoptose étendue du tissu","Une perméabilisation mitochondriale","Une peroxydation lipidique des membranes"],"r":0,"e":"L'atrophie est un remodelage métabolique, sans mort cellulaire. La dégradation passe par la voie ubiquitine-protéasome et l'autophagie.","s":8},{"q":"Quel exemple d'atrophie physiologique liée au vieillissement la fiche cite-t-elle ?","o":["L'atrophie cérébrale sénile","L'atrophie musculaire sous plâtre","L'atrophie par dénervation","La cachexie néoplasique"],"r":0,"e":"Le vieillissement et la baisse hormonale donnent des atrophies physiologiques ; immobilisation, dénervation et cachexie sont pathologiques.","s":8},{"q":"Par quel mécanisme la métaplasie se produit-elle ?","o":["Par reprogrammation des cellules souches tissulaires","Par transformation directe d'une cellule différenciée en une autre","Par prolifération des cellules matures","Par fusion cellulaire, entre deux types"],"r":0,"e":"La fiche insiste : ce n'est pas une transdifférenciation directe mais une reprogrammation des cellules souches.","s":8},{"q":"Quel cancer risque de compliquer une métaplasie malpighienne bronchique ?","o":["Le carcinome épidermoïde","L'adénocarcinome glandulaire","Le mélanome cutané","Le sarcome des tissus de soutien"],"r":0,"e":"L'œsophage de Barrett expose à l'adénocarcinome, la métaplasie bronchique au carcinome épidermoïde.","s":8},{"q":"Quel type de métaplasie caractérise l'œsophage de Barrett ?","o":["Un malpighien remplacé par un cylindrique intestinal","Un cylindrique remplacé par un épithélium pavimenteux","Une formation osseuse ectopique dans la paroi","Une dysplasie de haut grade, déjà précancéreuse et invasive"],"r":0,"e":"C'est la métaplasie inverse de celle des voies respiratoires.","s":8},{"q":"Où la dysplasie est-elle le mieux étudiée ?","o":["Au col de l'utérus","Dans le foie","Dans le myocarde","Dans le rein"],"r":0,"e":"Le col utérin sert de modèle, ses degrés mineurs étant liés à l'irritation ou l'inflammation chronique.","s":8},{"q":"Quelle est la conséquence métabolique immédiate de l'hypoxie cellulaire ?","o":["Un passage à l'anaérobie, avec acide lactique et baisse du pH","Une activation des caspases, avec apoptose rapide de la cellule","Une peroxydation lipidique isolée","Une hypercalcémie sanguine, réactionnelle"],"r":0,"e":"La chute d'ATP entraîne aussi la défaillance de la pompe Na⁺/K⁺ et le gonflement cellulaire.","s":8},{"q":"L'INFECTION correspond à :","o":["La présence de micro-organismes, sans multiplication ni dommage","La multiplication d'un pathogène, avec dommages","La présence de parasites externes sur la peau","Une réaction allergique, sans agent"],"r":1,"e":"Infection = pénétration + multiplication d'un agent pathogène dans l'hôte avec lésions tissulaires/réaction immunitaire. Différent de la colonisation (sans dommage) ou de l'infestation (parasites externes). L'agent a d'abord pénétré dans l'organisme.","s":9},{"q":"La COLONISATION se distingue de l'infection par :","o":["Une multiplication plus rapide des germes","L'absence de dommage et de réaction de l'hôte","La présence systématique de symptômes","Une transmission obligatoire à l'entourage"],"r":1,"e":"Colonisation = présence de micro-organismes sur/dans l'hôte SANS dommage ni réaction de l'hôte. Beaucoup d'individus sont colonisés sans être infectés (ex : Staphylococcus aureus nasal).","s":9},{"q":"L'INFESTATION concerne :","o":["Les bactéries intracellulaires, comme les chlamydias","Les parasites externes, ou ectoparasites","Les virus, à ADN ou à ARN","Les champignons systémiques"],"r":1,"e":"Infestation = présence/multiplication d'ECTOPARASITES sur la surface du corps (poux, gale, tiques). Différent de l'infection (agent pénétrant).","s":9},{"q":"Concernant les modes de TRANSMISSION DIRECTE, quels exemples sont corrects ?","o":["Le contact sexuel","Les gouttelettes, à courte distance","Le contact peau à peau","Les aliments contaminés","L'eau contaminée"],"r":[0,1,2],"e":"Transmission directe : contact entre personnes (sexuel, peau à peau, gouttelettes courtes). Aliments/eau contaminés = transmission INDIRECTE (par véhicule).","s":9},{"q":"Concernant les modes de TRANSMISSION INDIRECTE, quels exemples sont corrects ?","o":["Les aliments ou l'eau contaminés","Un vecteur, comme le moustique","Les aérosols à longue distance","Les objets contaminés, ou fomites","L'embrassade, par contact direct"],"r":[0,1,2,3],"e":"Transmission indirecte : via véhicule (eau, aliments, objets/fomites), vecteur (moustique, tique), aérosols longue distance. L'embrassade = directe.","s":9},{"q":"La chaîne épidémiologique commence par :","o":["L'hôte sensible","La porte d'entrée","L'agent infectieux","La porte de sortie"],"r":2,"e":"Chaîne épidémiologique : agent → réservoir → porte de sortie → mode de transmission → porte d'entrée → hôte sensible. Elle commence par l'agent infectieux.","s":9},{"q":"Parmi les principaux AGENTS INFECTIEUX, on compte :","o":["Les bactéries","Les virus","Les champignons","Les parasites","Les prions","Les pollens"],"r":[0,1,2,3,4],"e":"Les 5 grands types d'agents infectieux : bactéries, virus, champignons (mycètes), parasites (protozoaires, helminthes), prions (protéines infectieuses, ex : Creutzfeldt-Jakob). Un pollen déclenche une réaction immunitaire d'hypersensibilité, mais ne se multiplie pas dans l'hôte : ce n'est pas un agent infectieux.","s":9},{"q":"Une infection NOSOCOMIALE est :","o":["Acquise dans la communauté, hors de l'hôpital","Acquise dans une structure de soins, à l'hôpital","Toujours d'origine virale","Toujours bénigne, sans traitement"],"r":1,"e":"Infection nosocomiale = acquise lors d'un séjour en structure de soins (hôpital, EHPAD), apparue ≥ 48h après l'admission. Souvent à germes résistants (MRSA, etc.).","s":9},{"q":"Le COMMENSALISME correspond à :","o":["Le micro-organisme bénéficie sans nuire à l'hôte","Le micro-organisme et l'hôte bénéficient mutuellement","Le micro-organisme nuit à l'hôte","Une absence d'interaction"],"r":0,"e":"Commensalisme : un partenaire (microbe) en tire bénéfice, l'autre (hôte) n'en subit ni bien ni mal. Mutualisme = bénéfice réciproque (ex : flore intestinale). Parasitisme = pathogène nuit à l'hôte.","s":9},{"q":"Le MUTUALISME correspond à :","o":["Une situation où l'agent infectieux nuit à l'hôte","Un bénéfice réciproque entre l'hôte et le microbe","Une absence de toute relation entre les deux organismes","Une élimination immédiate du microbe"],"r":1,"e":"Mutualisme = bénéfice réciproque (ex : microbiote intestinal qui aide la digestion et reçoit nutriments). Le parasitisme est unilatéralement nuisible pour l'hôte.","s":9},{"q":"Quels facteurs AUGMENTENT la susceptibilité de l'hôte à l'infection ?","o":["Un âge extrême, très jeune ou très âgé","Une immunodéficience","Une malnutrition","Une maladie chronique, comme le diabète","Une vaccination à jour"],"r":[0,1,2,3],"e":"Facteurs ↑ susceptibilité : âges extrêmes, immunodéficience (VIH, traitements immunosuppresseurs), malnutrition, maladies chroniques (diabète), grossesse. La vaccination DIMINUE la susceptibilité.","s":9},{"q":"Quelles sont des PORTES D'ENTRÉE classiques d'agents infectieux ?","o":["Pénétration cutanée (effraction, piqûre)","Contact (peau intacte, muqueuses)","Ingestion (voie digestive)","Inhalation (voie respiratoire)","Voie transplacentaire","La sécrétion de lysozyme par les larmes"],"r":[0,1,2,3,4],"e":"Portes d'entrée : pénétration (effraction cutanée, piqûre), contact (peau, muqueuses), ingestion (digestif), inhalation (respiratoire), transplacentaire (mère-enfant). Le lysozyme est une défense de l'hôte, donc l'inverse d'une porte d'entrée.","s":9},{"q":"La phase PRODROMIQUE d'une maladie infectieuse correspond à :","o":["L'absence de tout symptôme","Des symptômes non spécifiques, avant la phase d'état","La phase de convalescence","La rechute, après une guérison apparente de la maladie"],"r":1,"e":"Phase prodromique : symptômes vagues et non spécifiques (malaise, fébricule) précédant la phase d'état (symptômes caractéristiques de la maladie).","s":9},{"q":"Une maladie AIGUË se caractérise par :","o":["Une longue durée, de mois ou d'années","Une apparition brutale et une durée courte","Des poussées et des rémissions","Un début insidieux, progressif et sans date précise"],"r":1,"e":"Maladie aiguë = début brutal, courte durée, évolution rapide. Subaiguë = intermédiaire. Chronique = longue durée, parfois insidieuse, peut comporter exacerbations/rémissions.","s":9},{"q":"Concernant l'histoire naturelle de la maladie infectieuse :","o":["Elle commence par l'incubation","Suivie d'une phase prodromique","Puis la phase d'état (clinique)","Et enfin la convalescence ou résolution","Elle ne comporte que 2 phases"],"r":[0,1,2,3],"e":"Histoire naturelle : incubation (silencieuse) → prodromes (symptômes vagues) → phase d'état (signes spécifiques) → convalescence/résolution (ou complications/séquelles).","s":9},{"q":"Les niveaux de prévention sont :","o":["Primaire, secondaire et tertiaire","Primaire seulement, avant toute maladie","Aiguë et chronique","Active et passive"],"r":0,"e":"3 niveaux : Primaire (avant la maladie : vaccination, hygiène) ; Secondaire (dépistage précoce + traitement rapide) ; Tertiaire (rééducation, limitation des séquelles).","s":9},{"q":"Une maladie TRANSMISSIBLE est :","o":["Toujours d'origine virale, respiratoire","Capable de se propager d'un hôte à un autre","Toujours d'origine génétique, héréditaire","Forcément chronique, sur des années"],"r":1,"e":"Maladie transmissible = peut se propager d'un hôte (ou réservoir) à un autre. Non transmissible = pas de transmission interhumaine ou animale (cancer, diabète, maladies cardiovasculaires).","s":9},{"q":"Parmi ces maladies, lesquelles sont TRANSMISSIBLES ?","o":["Tuberculose","Grippe","Diabète de type 1","Hypertension","COVID-19"],"r":[0,1,4],"e":"Transmissibles : tuberculose, grippe, COVID-19, IST, etc. Non transmissibles : diabète, HTA, cancer, maladies cardiovasculaires (origine multifactorielle, pas d'agent infectieux).","s":9},{"q":"Une infection ENDOGÈNE provient :","o":["De l'environnement, comme l'eau","De la flore microbienne propre du patient","D'un soignant, par les mains non désinfectées","D'un autre patient hospitalisé"],"r":1,"e":"Infection endogène = à partir de la flore commensale du patient (ex : translocation digestive). Exogène = source externe. Nosocomiale = liée aux soins.","s":9},{"q":"Quels éléments constituent le SYSTÈME DE DÉFENSE de l'hôte ?","o":["Les barrières mécaniques, peau et muqueuses","Les sécrétions, comme le lysozyme et le mucus","Le microbiote commensal","L'immunité innée, non spécifique","L'immunité adaptative, par les lymphocytes","L'effraction cutanée par piqûre"],"r":[0,1,2,3,4],"e":"Défenses : barrières (peau, muqueuses), sécrétions (lysozyme, HCl, mucus), microbiote (compétition), immunité innée (PNN, macrophages, complément), immunité adaptative (LT, LB, anticorps). Une effraction est une porte d'entrée : elle rompt la défense au lieu de la constituer.","s":9},{"q":"Le RÉSERVOIR de l'agent infectieux peut être :","o":["Uniquement humain, porteur sain","Humain, animal ou environnemental","Uniquement le sol ou l'eau","Uniquement un vecteur"],"r":1,"e":"Réservoirs : humain (porteur sain ou malade), animal (zoonoses : rage, brucellose), environnemental (eau pour Legionella, sol pour tétanos).","s":9},{"q":"Une zoonose est :","o":["Une infection transmise d'humain à humain","Une infection transmise de l'animal à l'humain","Une infection environnementale","Une infection auto-immune"],"r":1,"e":"Zoonose = infection transmise de l'animal à l'humain (rage, brucellose, leptospirose, grippe aviaire, COVID-19). Le réservoir est animal.","s":9},{"q":"Quelles affirmations sur les bactéries sont vraies ?","o":["Procaryotes (sans noyau)","Peuvent être Gram+ ou Gram-","Sensibles aux antibiotiques (en général)","Possèdent un noyau membranaire","Possèdent une paroi"],"r":[0,1,2,4],"e":"Bactéries : procaryotes (PAS de noyau), Gram+/Gram-, sensibles aux antibiotiques (sauf résistances), possèdent une paroi. Le noyau membranaire est une caractéristique eucaryote.","s":9},{"q":"Un VIRUS est :","o":["Un être vivant complet, autonome","Un agent obligatoirement intracellulaire","Un agent sensible aux antibiotiques, comme les bactéries","Une variante de bactérie, plus petite"],"r":1,"e":"Virus = parasite intracellulaire OBLIGATOIRE (a besoin du métabolisme cellulaire pour se répliquer). Insensible aux antibiotiques (qui ciblent les bactéries). Traitement antiviral spécifique.","s":9},{"q":"Un PRION est :","o":["Une bactérie atypique, sans paroi","Un virus à ARN, de très petite taille","Une protéine infectieuse mal repliée","Un parasite eucaryote"],"r":2,"e":"Prion = protéine mal repliée (PrPsc) qui induit le mauvais repliement des protéines normales (PrPc). Cause la maladie de Creutzfeldt-Jakob, ESB. Pas d'acide nucléique → résistant aux traitements classiques.","s":9},{"q":"Le concept de prévention TERTIAIRE inclut :","o":["La vaccination des enfants","Le dépistage précoce du cancer","La réhabilitation des séquelles","La limitation des incapacités","L'hygiène de vie générale"],"r":[2,3],"e":"Tertiaire = limitation des séquelles, rééducation, qualité de vie chez un sujet déjà atteint. Vaccination = primaire ; dépistage = secondaire.","s":9},{"q":"Concernant la fréquence des maladies dans une population :","o":["Sporadique, survenant de façon occasionnelle","Endémique, toujours présente à fréquence stable","Épidémique, touchant beaucoup de monde en peu de temps","Pandémique, sur une vaste zone, parfois mondiale","Endémique, pour une maladie qui a totalement disparu"],"r":[0,1,2,3],"e":"Sporadique (occasionnel) ; endémique (toujours présente à fréquence stable, ex paludisme dans certaines régions) ; épidémique (poussée localisée) ; pandémique (mondiale, ex COVID-19).","s":9},{"q":"Les agents infectieux incluent :","o":["Les virus","Les bactéries","Les champignons","Les parasites","Les prions","Les toxiques"],"r":[0,1,2,3,4],"e":"5 grands groupes d'agents : virus, bactéries, champignons, parasites, prions. Un toxique lèse directement les tissus mais ne se réplique pas : il relève des agents chimiques, pas infectieux.","s":9},{"q":"La virulence d'un microorganisme est :","o":["Sa capacité de reproduction rapide","Sa capacité à causer une maladie sévère","Sa résistance aux antibiotiques usuels","Sa taille, au microscope"],"r":1,"e":"Virulence = degré de pathogénicité, capacité à causer une maladie grave.","s":9},{"q":"La période d'incubation est :","o":["Le délai entre l'exposition et les symptômes","Le temps pendant lequel durent les symptômes","La période contagieuse uniquement","La convalescence, après la guérison"],"r":0,"e":"Incubation = délai entre l'exposition à l'agent et l'apparition des premiers symptômes.","s":9},{"q":"La fièvre est :","o":["Une élévation pathologique de la température","Une diminution de la température","Un signe toujours grave, à traiter","Un signe sans rapport avec les infections, d'origine nerveuse"],"r":0,"e":"Fièvre = ↑ T° corporelle au-dessus de la normale, médiée par les pyrogènes (IL-1, TNF). Elle est souvent due à une infection.","s":9},{"q":"Les modes de transmission incluent :","o":["La voie aérienne","Le contact direct ou indirect","Un vecteur, moustique ou tique","La voie alimentaire ou hydrique","La voie sexuelle","La voie sanguine","La prédisposition génétique"],"r":[0,1,2,3,4,5],"e":"Tous ces modes existent : aérien, contact, vecteur, oro-fécal, sexuel, sanguin (parentéral). Une prédisposition génétique modifie la susceptibilité de l'hôte ; elle ne transmet aucun agent.","s":9},{"q":"Une endotoxine bactérienne est :","o":["Une toxine sécrétée activement par la bactérie","Un composant de la paroi, libéré lors de la lyse","Un anticorps dirigé contre la bactérie","Un antibiotique, produit par un champignon"],"r":1,"e":"Endotoxine = LPS de la paroi des Gram- ; exotoxine = sécrétée activement (Gram+ et -). C'est le LPS des bactéries à Gram négatif.","s":9},{"q":"L'immunité acquise active s'obtient par :","o":["Le passage placentaire, de la mère à l'enfant","La vaccination ou une infection naturelle","Une injection d'anticorps tout prêts","Aucun mécanisme connu"],"r":1,"e":"Active = production propre d'anticorps après vaccination/infection. Passive = anticorps reçus (ex : sérum, allaitement).","s":9},{"q":"La résistance aux antibiotiques est favorisée par :","o":["Une utilisation rare et ciblée","Une utilisation appropriée et brève","Une utilisation excessive et inappropriée","La diversité naturelle des espèces bactériennes"],"r":2,"e":"L'utilisation excessive/inappropriée d'antibiotiques sélectionne les souches résistantes.","s":9},{"q":"Un porteur sain (porteur asymptomatique) est :","o":["Un sujet guéri, qui ne peut plus transmettre l'agent infectieux","Un sujet qui transmet l'agent sans avoir de symptômes","Un sujet vacciné, protégé de la maladie","Un sujet en période d'incubation uniquement"],"r":1,"e":"Le porteur sain est un maillon majeur de la chaîne épidémiologique, précisément parce que rien ne le signale : il alimente la transmission sans être repéré ni isolé. C'est le cas pour le méningocoque, le staphylocoque doré nasal ou les porteurs chroniques du VHB.","s":9},{"q":"La sepsie est :","o":["Une infection localisée, sans signe général","Une réponse systémique, avec dysfonction d'organe","Une maladie auto-immune systémique, chronique","Une allergie, de type anaphylactique"],"r":1,"e":"Sepsie = SIRS + infection avec dysfonction d'organe. Choc septique = sepsie + hypotension réfractaire. Elle fait suite à une infection.","s":9},{"q":"Quelle différence la fiche fait-elle entre maladie infectieuse et maladie contagieuse ?","o":["Toute maladie contagieuse est infectieuse, pas l'inverse","Toute maladie infectieuse est aussi contagieuse","Les deux termes sont synonymes, en pratique","Une maladie contagieuse se passe d'agent infectieux"],"r":0,"e":"La rougeole est contagieuse, le paludisme est infectieux mais non contagieux car il exige un vecteur.","s":9},{"q":"Qu'est-ce qu'un hôte selon la fiche ?","o":["Un organisme qui subvient aux besoins nutritifs d'un autre","Un micro-organisme pathogène, qui envahit","Le milieu où vit et se multiplie l'agent, comme l'eau ou le sol","Le vecteur qui transporte l'agent"],"r":0,"e":"L'hôte nourrit l'agent ; le réservoir est son environnement de vie et de multiplication.","s":9},{"q":"Qu'est-ce qu'un saprophyte ?","o":["Un micro-organisme peu nuisible, nourri de matière morte","Un agent toujours pathogène, même chez le sujet sain et robuste","Un vecteur de transmission, comme un insecte","Une protéine infectieuse, mal repliée"],"r":0,"e":"La majorité des micro-organismes sont saprophytes, mais peuvent devenir opportunistes.","s":9},{"q":"Quelle particularité structurelle définit un prion ?","o":["Il est fait de protéines seules, sans acide nucléique","Il possède un ADN et une capside protéique, comme un virus","Il possède un ARN et une enveloppe","C'est un eucaryote unicellulaire"],"r":0,"e":"L'absence d'acide nucléique explique qu'aucun traitement ne soit efficace (Creutzfeldt-Jakob, Kuru, ESB).","s":9},{"q":"Pourquoi les virus sont-ils dits intracellulaires obligatoires ?","o":["Parce qu'ils ne peuvent pas se reproduire hors des cellules","Parce qu'ils sont trop petits pour survivre à l'air","Parce qu'ils n'ont pas de capside","Parce qu'ils se nourrissent de matières mortes, dans le sol humide"],"r":0,"e":"Le virus détourne la machinerie cellulaire ; les antiviraux ne font que ralentir sa réplication.","s":9},{"q":"Quelle est la structure des bactéries ?","o":["Des procaryotes sans noyau, à reproduction autonome","Des eucaryotes unicellulaires, avec un noyau","Des organismes multicellulaires, aux tissus différenciés","Des protéines sans acide nucléique"],"r":0,"e":"Leur autonomie de reproduction et leur nature procaryote les rendent sensibles aux antibiotiques.","s":9},{"q":"À quelle catégorie appartiennent les levures et les moisissures ?","o":["Aux champignons","Aux protozoaires","Aux helminthes","Aux bactéries"],"r":0,"e":"Les champignons sont unicellulaires (levures) ou multicellulaires (moisissures) et se traitent par antifongiques.","s":9},{"q":"Quelles maladies la fiche associe-t-elle aux protozoaires ?","o":["Le paludisme et la dysenterie amibienne","La trichinose et les infections à vers plats","La candidose et le pied d'athlète","La tuberculose et la gonorrhée"],"r":0,"e":"Les protozoaires sont des eucaryotes unicellulaires, fréquents dans l'eau des pays en développement. La maladie du sommeil en fait aussi partie.","s":9},{"q":"Qu'est-ce qu'une infection endogène ?","o":["Une infection issue de la flore propre de l'hôte","Une infection contractée à l'hôpital","Une infection transmise par un animal domestique ou sauvage","Une infection d'origine alimentaire"],"r":0,"e":"Les infections opportunistes de la flore commensale sont endogènes ; l'origine hospitalière définit le caractère nosocomial.","s":9},{"q":"Quel exemple de mutualisme la fiche donne-t-elle ?","o":["Les bactéries intestinales produisant la vitamine K","Les streptocoques de la bouche, sur les dents et la langue","Les staphylocoques de la peau","Les poux du cuir chevelu, chez l'enfant"],"r":0,"e":"Le mutualisme profite aux deux partenaires ; les streptocoques buccaux illustrent le commensalisme.","s":9},{"q":"Quelle porte de sortie la fiche associe-t-elle à la rage ?","o":["La salive","Le sang","Les selles","Les sécrétions respiratoires"],"r":0,"e":"Le Rhabdovirus de la rage se transmet par la salive lors de la morsure.","s":9},{"q":"Quelle porte de sortie la fiche associe-t-elle à l'amibiase ?","o":["Les selles","Le sperme","Le sang","La salive"],"r":0,"e":"L'amibiase est une maladie à transmission féco-orale.","s":9},{"q":"Quelles défenses protègent la voie d'entrée respiratoire ?","o":["Le mucus, les cils vibratiles et la toux","Le pH acide et les enzymes digestives","La kératine et les acides gras cutanés","La miction répétée, qui chasse les germes de l'urètre"],"r":0,"e":"Chaque porte d'entrée a ses défenses propres ; celles citées en second concernent le tube digestif. Les anticorps et les phagocytes y contribuent aussi.","s":9},{"q":"Quels sont les SIGNES CARDINAUX de l'inflammation aiguë (4 signes de Celse + 1 de Galien) ?","o":["Rougeur (rubor)","Chaleur (calor)","Tuméfaction / œdème (tumor)","Douleur (dolor)","Perte de fonction (functio laesa)","Pâleur (pallor)"],"r":[0,1,2,3,4],"e":"5 signes cardinaux : rubor (rougeur), calor (chaleur), tumor (œdème), dolor (douleur), functio laesa (perte de fonction). Les 4 premiers décrits par Celse, le 5e ajouté par Galien/Virchow. La pâleur traduit une vasoconstriction ou une anémie ; l'inflammation aiguë donne au contraire une rougeur par vasodilatation.","s":10},{"q":"L'inflammation AIGUË :","o":["Dure plusieurs mois, voire des années","Est de courte durée, d'heures à jours","Est dominée par les lymphocytes","Implique toujours une fibrose, avec une cicatrice"],"r":1,"e":"Inflammation aiguë : durée courte (minutes-jours), prédominance de PNN (polynucléaires neutrophiles), réversible. Chronique : durée prolongée, lymphocytes/macrophages, fibrose.","s":10},{"q":"L'inflammation CHRONIQUE est caractérisée par :","o":["Prédominance de macrophages et lymphocytes","Persistance dans le temps","Souvent accompagnée de fibrose","Prédominance de polynucléaires neutrophiles","Réponse adaptative"],"r":[0,1,2,4],"e":"Chronique : durée prolongée, macrophages + lymphocytes (réponse adaptative), fibrose, néoangiogenèse. Les PNN sont des cellules de l'aiguë.","s":10},{"q":"Lors de la phase VASCULAIRE de l'inflammation aiguë, quelle est la première modification ?","o":["Vasoconstriction puis vasodilatation","Vasodilatation immédiate puis vasoconstriction","Vasoconstriction prolongée","Aucune modification vasculaire"],"r":0,"e":"Phase vasculaire : courte vasoconstriction réflexe → vasodilatation marquée → ↑ flux sanguin (rougeur, chaleur) → ↑ perméabilité (œdème).","s":10},{"q":"Un EXSUDAT inflammatoire se distingue d'un transsudat par :","o":["Une teneur en protéines basse, sous 30 g/L, et peu de cellules","Une teneur élevée en protéines et en cellules","Une couleur claire et limpide","Une absence totale de fibrine"],"r":1,"e":"Exsudat : ↑ protéines (>30 g/L), riche en cellules, fibrine — signe d'INFLAMMATION (perméabilité ↑). Transsudat : pauvre en protéines, sans cellules — origine MÉCANIQUE (insuffisance cardiaque, hypoalbuminémie).","s":10},{"q":"Quels types d'EXSUDATS existent ?","o":["Séreux","Fibrineux","Purulent","Hémorragique","Lymphatique"],"r":[0,1,2,3],"e":"Exsudats : séreux (clair, brûlure), fibrineux (péricardite), purulent (pus, pyogènes), hémorragique (très inflammatoire). Pas d'exsudat lymphatique en tant que catégorie.","s":10},{"q":"Concernant le RECRUTEMENT LEUCOCYTAIRE (étapes), elles incluent :","o":["Margination","Roulement","Adhésion","Transmigration / diapédèse","Chimiotactisme","Opsonisation"],"r":[0,1,2,3,4],"e":"Étapes du recrutement leucocytaire (MRATCH) : Margination → Roulement → Adhésion → Transmigration → Chimiotactisme → Phagocytose. Sélectines pour le roulement, intégrines pour l'adhésion. L'opsonisation appartient à la phagocytose, qui suit l'arrivée du leucocyte dans le tissu ; elle ne fait pas partie du recrutement.","s":10},{"q":"Le PHÉNOMÈNE de PHAGOCYTOSE comprend :","o":["1 étape, l'ingestion","2 étapes, l'ingestion puis la digestion","3 étapes, de la reconnaissance à la dégradation","5 étapes, de l'adhésion à l'exocytose finale"],"r":2,"e":"Phagocytose en 3 étapes : 1) reconnaissance (opsonines : IgG, C3b) ; 2) ingestion (pseudopodes, phagosome) ; 3) dégradation (fusion lysosome → phagolysosome → enzymes + ROS).","s":10},{"q":"Quel est le LEUCOCYTE prédominant dans les premières heures de l'inflammation aiguë ?","o":["Le lymphocyte T","Le macrophage tissulaire","Le polynucléaire neutrophile","L'éosinophile, ou PNE"],"r":2,"e":"PNN = première cellule à arriver (premières 24h). Puis macrophages prennent le relais (24-48h). Lymphocytes en cas d'inflammation chronique ou virale.","s":10},{"q":"Parmi les médiateurs chimiques de l'inflammation, on trouve :","o":["L'histamine des mastocytes","Les prostaglandines","Les leucotriènes","Les cytokines, comme le TNF","L'insuline du pancréas"],"r":[0,1,2,3],"e":"Médiateurs : histamine (vasodilatation, perméabilité), prostaglandines/leucotriènes (douleur, fièvre), cytokines (TNF, IL-1, IL-6), complément, NO. L'insuline est une hormone métabolique, pas un médiateur inflammatoire.","s":10},{"q":"Les AINS (anti-inflammatoires non stéroïdiens) inhibent principalement :","o":["L'histamine → ↓ vasodilatation","Les cyclo-oxygénases → ↓ prostaglandines","Le complément → ↓ lyse cellulaire et opsonisation","Les caspases → ↓ apoptose"],"r":1,"e":"AINS = inhibiteurs des COX → ↓ synthèse de prostaglandines → effet anti-inflammatoire, antalgique, antipyrétique. Effet indésirable digestif (COX-1). Ce sont les COX-1 et COX-2.","s":10},{"q":"Concernant les EFFETS SYSTÉMIQUES de l'inflammation (réponse de phase aiguë) :","o":["Une fièvre, par les cytokines","Une leucocytose sanguine","Une hausse de la CRP et du fibrinogène","Une augmentation de la VS","Une hypothermie habituelle"],"r":[0,1,2,3],"e":"Réponse phase aiguë : fièvre (IL-1, IL-6, TNF), leucocytose, ↑ CRP/fibrinogène, ↑ VS, fatigue. L'hypothermie peut survenir en cas de SEPSIS sévère mais ce n'est pas typique.","s":10},{"q":"Un GRANULOME est :","o":["Un type de cellule cancéreuse","Un amas focal de macrophages activés","Une bactérie, comme le bacille de Koch","Une cytokine, comme l'IL-1"],"r":1,"e":"Granulome = lésion d'inflammation chronique : macrophages activés (cellules épithélioïdes), parfois cellules géantes, lymphocytes. Typique : tuberculose, sarcoïdose, mycoses, corps étrangers. Ces macrophages deviennent des cellules épithélioïdes.","s":10},{"q":"Quelles maladies sont caractérisées par une inflammation GRANULOMATEUSE ?","o":["Tuberculose","Sarcoïdose","Maladie de Crohn","Grippe","Lèpre"],"r":[0,1,2,4],"e":"Inflammation granulomateuse : tuberculose (granulome caséeux), sarcoïdose (non caséeux), Crohn, lèpre, mycoses. La grippe = inflammation aiguë virale, pas granulomateuse.","s":10},{"q":"Concernant la classification des tissus selon leur capacité de prolifération :","o":["Les tissus labiles se renouvellent en permanence","Les tissus stables prolifèrent sur un stimulus","Les tissus permanents ne se divisent pas","Tous les tissus se régénèrent à l'identique","Les neurones se régénèrent comme la peau"],"r":[0,1,2],"e":"3 catégories : labiles (renouvellement constant), stables (quiescents mais capables de proliférer), permanents (post-mitotiques : neurones, myocytes cardiaques → pas de régénération vraie). Épithéliums et moelle sont labiles, foie et rein stables, neurones et cardiomyocytes permanents.","s":10},{"q":"La cicatrisation par PREMIÈRE INTENTION concerne :","o":["Les plaies à bords nets, sans grande perte","Les plaies larges avec perte de substance","Les plaies infectées uniquement","Les brûlures profondes, du troisième degré étendu"],"r":0,"e":"1ère intention : plaies bords nets, rapprochés, peu de perte (ex : sutures chirurgicales) → cicatrice fine. 2e intention : perte de substance importante → bourgeon charnu, cicatrice large.","s":10},{"q":"Quels facteurs ALTÈRENT la réparation tissulaire ?","o":["Diabète (hyperglycémie)","Tabagisme","Malnutrition","Infection","Jeune âge"],"r":[0,1,2,3],"e":"Altèrent : diabète, tabac (vasoconstriction), malnutrition (protéines, vitamine C), infections, corticothérapie, ischémie, corps étrangers. Le jeune âge FAVORISE la réparation.","s":10},{"q":"Une cicatrice CHÉLOÏDE est :","o":["Une cicatrice fine et discrète","Une cicatrice hypertrophique, débordant la plaie","Une absence totale de cicatrice, par régénération parfaite","Une cicatrice rouge, qui s'estompe vite"],"r":1,"e":"Chéloïde : cicatrice hypertrophique qui DÉBORDE les limites initiales de la plaie (excès de collagène). Plus fréquente chez les peaux foncées. Différente de l'hypertrophie simple (limitée à la plaie).","s":10},{"q":"Concernant la réparation tissulaire, quelles affirmations sont vraies ?","o":["Régénération = remplacement par le même tissu","Cicatrisation = remplacement par tissu fibreux","La régénération est possible pour les tissus labiles et stables","Les neurones du SNC se régénèrent facilement","La fibrose excessive peut altérer la fonction"],"r":[0,1,2,4],"e":"Régénération (à l'identique) possible pour tissus labiles/stables. Cicatrisation = fibrose (collagène) si la régénération ne suffit pas. Le SNC ne se régénère pas (cicatrice gliale).","s":10},{"q":"Concernant la réaction des 5 R en inflammation :","o":["Reconnaissance de l'agent","Recrutement des leucocytes","Reconnaissance de l'antigène","Régulation de la réponse","Résolution"],"r":[0,1,3,4],"e":"5 R : Reconnaissance de l'agent → Recrutement leucocytaire → Removal/élimination → Régulation → Résolution. Pas de 'reconnaissance d'antigène' en tant qu'étape (c'est plutôt l'immunité adaptative).","s":10},{"q":"Le médiateur clé de la VASODILATATION précoce est :","o":["L'IL-1","L'histamine","Le TNF-α","La fibrine"],"r":1,"e":"Histamine (mastocytes, basophiles) = médiateur précoce de la vasodilatation et de l'augmentation de perméabilité vasculaire (œdème). Action rapide, courte durée.","s":10},{"q":"La FIÈVRE est principalement provoquée par :","o":["L'histamine, par les récepteurs H1","La sérotonine, libérée par les plaquettes activées","Les cytokines pyrogènes, comme l'IL-1","Le calcium, libéré par l'os"],"r":2,"e":"Fièvre : cytokines pyrogènes endogènes (IL-1, IL-6, TNF) → ↑ PGE2 → centre thermorégulateur hypothalamique → augmentation du point de consigne thermique. Elles agissent par la prostaglandine E2.","s":10},{"q":"Le BOURGEON CHARNU est constitué de :","o":["Des cellules cancéreuses, en amas","Un tissu de granulation, riche en néovaisseaux","Du pus seul, sans cellules vivantes","Du tissu nécrotique seul, noirâtre et sec, sans vaisseaux"],"r":1,"e":"Bourgeon charnu = tissu de granulation : néoangiogenèse + fibroblastes + collagène + cellules inflammatoires. Étape clé de la cicatrisation par 2e intention. Aspect rouge framboise. Il contient aussi des fibroblastes, du collagène et des leucocytes.","s":10},{"q":"Quels sont des effets du TNF-α ?","o":["Activation de l'endothélium","Stimulation de la production de cytokines","Cachexie (en chronique)","Apoptose dans certaines cellules","Diminution de la fièvre"],"r":[0,1,2,3],"e":"TNF-α : active endothélium (adhésion leucocytes), stimule production de cytokines, cause cachexie (terme = 'cachectine'), peut induire apoptose. Il PARTICIPE à la fièvre, ne la diminue pas.","s":10},{"q":"Une perte de fonction (functio laesa) est typiquement liée à :","o":["Un état général excellent, sans gêne fonctionnelle","La douleur, l'œdème et l'altération tissulaire","L'absence d'inflammation","Une cicatrice mature et souple"],"r":1,"e":"Functio laesa : perte de fonction de la zone enflammée, liée à la douleur (limitation volontaire du mouvement), l'œdème (ankylose), et l'altération tissulaire. C'est le 5e signe cardinal.","s":10},{"q":"Les 5 signes cardinaux de l'inflammation aiguë (Celse + Galien) sont :","o":["La rougeur, ou rubor","La chaleur, ou calor","La tuméfaction, ou tumor","La douleur, ou dolor","La perte de fonction","La cyanose, ou cyanosis"],"r":[0,1,2,3,4],"e":"5 signes : rubor, calor, tumor, dolor, functio laesa. La cyanose signe une désaturation en oxygène et ne figure pas parmi les signes de Celse et Galien. La perte de fonction se dit functio laesa.","s":10},{"q":"La vasodilatation locale dans l'inflammation est médiée par :","o":["L'adrénaline, par les récepteurs alpha","L'histamine, les prostaglandines et le NO","L'insuline, par le récepteur tyrosine kinase et le GLUT4","Le cortisol, de la surrénale"],"r":1,"e":"Médiateurs de la vasodilatation : histamine (mastocytes), prostaglandines, NO.","s":10},{"q":"L'exsudat inflammatoire est :","o":["Pauvre en protéines, comme un transsudat","Riche en protéines et en leucocytes","Identique au transsudat","Toxique pour les tissus"],"r":1,"e":"Exsudat = riche en protéines et cellules (inflammation). Transsudat = pauvre (↑ pression hydrostatique).","s":10},{"q":"Les cellules dominantes de l'inflammation aiguë sont :","o":["Les lymphocytes T et B","Les neutrophiles","Les macrophages","Les éosinophiles"],"r":1,"e":"PNN = première ligne, dominent les premières 24-48h. Macrophages prennent ensuite le relais. Ce sont les PNN.","s":10},{"q":"L'inflammation chronique se caractérise par :","o":["Des PNN dominants, en nappe","Lymphocytes, macrophages et plasmocytes","Un œdème massif et rapide","Une disparition immédiate des tissus"],"r":1,"e":"Inflammation chronique = infiltrat de cellules mononucléées (lymphocytes, macrophages, plasmocytes), persistance + tentative de réparation.","s":10},{"q":"Un granulome est typique de :","o":["L'inflammation aiguë, dominée par les neutrophiles","L'inflammation chronique granulomateuse","Une infection virale, aiguë","Un cancer, invasif et métastatique"],"r":1,"e":"Granulome = agglomérat de macrophages activés (cellules épithélioïdes), typique TB, sarcoïdose, certains corps étrangers. La tuberculose et la sarcoïdose en sont des exemples.","s":10},{"q":"Les phases de la cicatrisation sont :","o":["L'hémostase","L'inflammation","La prolifération","Le remodelage","La lyse tissulaire"],"r":[0,1,2,3],"e":"4 phases : hémostase → inflammation → prolifération (granulation, angiogenèse) → remodelage. La prolifération correspond à la granulation.","s":10},{"q":"La cicatrisation par SECONDE intention se caractérise par :","o":["Des berges nettes rapprochées, une cicatrice fine","Une perte de substance comblée par du tissu de granulation","Une absence totale de tissu de granulation","Une réparation plus rapide que la première intention"],"r":1,"e":"Quand les berges ne peuvent être rapprochées (plaie large, ulcère, brûlure), la perte de substance se comble par un bourgeon charnu, puis les myofibroblastes contractent la plaie. Il en résulte une cicatrisation plus longue, plus inflammatoire et une cicatrice plus étendue, source de rétractions. Elle s'accompagne d'une contraction et laisse une cicatrice large.","s":10},{"q":"Une chéloïde est :","o":["Une cicatrisation normale","Une cicatrice excessive, qui dépasse la plaie","Un kyste sous-cutané, bénin","Un amas de pus, dans une cavité fermée sous la peau"],"r":1,"e":"Chéloïde = cicatrice hypertrophique débordant les limites de la plaie initiale (excès collagène).","s":10},{"q":"Les facteurs retardant la cicatrisation incluent :","o":["Le jeune âge, avec une peau souple","Une bonne nutrition, riche en protéines","Le diabète, l'ischémie et l'infection","Le repos, avec une mise en décharge de la zone"],"r":2,"e":"Diabète, ischémie, infection, corticoïdes, dénutrition, âge avancé retardent la cicatrisation. Les corticoïdes, la dénutrition et l'âge avancé la retardent aussi.","s":10},{"q":"Sur quels tissus l'inflammation peut-elle se produire ?","o":["Uniquement les tissus vascularisés","Tous les tissus, vascularisés ou non","Uniquement les épithéliums","Uniquement le tissu conjonctif"],"r":0,"e":"La définition insiste sur les tissus vascularisés, puisque la réponse achemine leucocytes et molécules depuis la circulation.","s":10},{"q":"Quels sont les trois rôles protecteurs de l'inflammation ?","o":["Éliminer la cause et ses conséquences, puis réparer","Produire de la fibrose, recruter des fibroblastes, cicatriser","Créer de la douleur, de la chaleur et du gonflement, pour alerter","Activer le complément, la coagulation et les kinines"],"r":0,"e":"Ces trois rôles rendent l'inflammation essentielle à la survie, malgré ses effets délétères possibles.","s":10},{"q":"Quelles cytokines en excès provoquent un choc septique ?","o":["Le TNF et l'IL-1","L'IL-4 et l'IL-13","Le TGF-β et l'IL-10","L'IL-17 seule"],"r":0,"e":"De très hauts taux de TNF et d'IL-1 causent hypotension, CIVD et résistance à l'insuline ; IL-4/IL-13 et TGF-β/IL-10 orientent vers la réparation.","s":10},{"q":"Quelle modification vasculaire précède la vasodilatation dans l'inflammation aiguë ?","o":["Une brève vasoconstriction de quelques secondes","Une stase immédiate du flux","Une augmentation de perméabilité","Une margination leucocytaire, contre la paroi des veinules"],"r":0,"e":"La séquence est : vasoconstriction brève, vasodilatation, hyperperméabilité puis stase.","s":10},{"q":"Quel est le mécanisme le plus fréquent d'augmentation de la perméabilité vasculaire ?","o":["La contraction endothéliale, rapide et brève","La lésion endothéliale directe, par une toxine ou une brûlure","La transcytose, à travers les cellules","La formation du complexe d'attaque membranaire"],"r":0,"e":"La contraction endothéliale induite par histamine, bradykinine et leucotriènes est le mécanisme dominant. Elle dure 15 à 30 minutes.","s":10},{"q":"Quelle conséquence a la stase dans l'inflammation aiguë ?","o":["Le ralentissement du flux et la margination des leucocytes","Une vasoconstriction réflexe, qui ferme les artérioles du foyer","Une baisse de la perméabilité","Une résolution immédiate de l'inflammation"],"r":0,"e":"La stase place les leucocytes en périphérie du courant, première étape de leur recrutement. Les globules rouges se concentrent.","s":10},{"q":"Quel signe clinique distingue un transsudat d'un exsudat ?","o":["Le signe du godet, présent dans le transsudat","Le signe du godet, présent dans l'exsudat","La chaleur locale, au toucher","La perte de fonction, du membre"],"r":0,"e":"Le transsudat pauvre en protéines prend le godet ; l'exsudat riche en fibrine donne un œdème « en casier », non pitting.","s":10},{"q":"Quel type d'exsudat caractérise une péricardite ?","o":["L'exsudat fibrineux","L'exsudat séreux","L'exsudat purulent","L'exsudat hémorragique"],"r":0,"e":"Riche en fibrinogène, épais et collant, l'exsudat fibrineux est typique des séreuses.","s":10},{"q":"Quel type d'exsudat correspond à une vésicule cutanée ?","o":["L'exsudat séreux","L'exsudat fibrineux","L'exsudat purulent","L'exsudat nécrotique"],"r":0,"e":"La phlyctène contient un fluide aqueux pauvre en protéines.","s":10},{"q":"Quelles molécules assurent le roulement des leucocytes ?","o":["Les sélectines","Les intégrines","PECAM-1","Les chimiokines"],"r":0,"e":"Sélectines pour le roulement, intégrines pour l'adhésion ferme, PECAM-1 pour la transmigration.","s":10},{"q":"Quelle molécule permet la transmigration des leucocytes ?","o":["PECAM-1, ou CD31","La L-sélectine, ou CD62L","LFA-1, ou CD11a","ICAM-1, ou CD54"],"r":0,"e":"PECAM-1 assure le passage entre les cellules endothéliales.","s":10},{"q":"Quels sont les ligands endothéliaux des intégrines ?","o":["ICAM-1 et VCAM-1","La P-sélectine et la E-sélectine","IL-8 et MCP-1","C5a et C3b"],"r":0,"e":"ICAM-1 et VCAM-1 fixent les intégrines LFA-1 et MAC-1 pour l'adhésion ferme.","s":10},{"q":"Quelle chimiokine attire spécifiquement les monocytes ?","o":["MCP-1","IL-8 (CXCL8)","L'éotaxine","LTB4"],"r":0,"e":"IL-8 attire les neutrophiles, l'éotaxine les éosinophiles et MCP-1 les monocytes.","s":10},{"q":"Par quel mécanisme cytosquelettique les leucocytes se déplacent-ils lors de la chimiotaxie ?","o":["Par polymérisation d'actine à l'avant de la cellule","Par contraction des myofibrilles, comme le muscle","Par un flux de calcium passif","Par battement ciliaire, comme en bronches"],"r":0,"e":"La polymérisation d'actine au front de migration propulse la cellule vers le gradient.","s":10},{"q":"Pourquoi les neutrophiles dominent-ils les premières 24 heures ?","o":["Ils sont plus nombreux et répondent plus vite aux chimiokines","Ils survivent plus longtemps que les macrophages","Ils prolifèrent dans les tissus","Ils sont recrutés par l'IL-4, sécrétée par les lymphocytes Th2 activés"],"r":0,"e":"La survie longue et la prolifération tissulaire caractérisent au contraire les macrophages, qui prennent le relais à 24-48 h. Ils adhèrent aussi fortement aux sélectines P et E.","s":10},{"q":"Parmi les fonctions du système squelettique, on retrouve :","o":["Soutien du corps","Protection des organes","Mouvement (insertion musculaire)","Stockage minéral (Ca, P)","Hématopoïèse","Production d'insuline"],"r":[0,1,2,3,4],"e":"Fonctions de l'os : soutien, protection (crâne, thorax), mouvement (levier des muscles), homéostasie minérale (Ca, P), production sanguine (moelle rouge), stockage de lipides (moelle jaune). L'insuline est sécrétée par le pancréas endocrine ; l'os stocke le calcium et le phosphore, il ne produit pas d'insuline.","s":11},{"q":"Quelle proportion du calcium corporel est stockée dans l'os ?","o":["~30%","~50%","~70%","~99%"],"r":3,"e":"~99% du calcium corporel est stocké dans le tissu osseux (sous forme d'hydroxyapatite). C'est la principale réserve calcique de l'organisme.","s":11},{"q":"Concernant le tissu osseux COMPACT (cortical), quelles affirmations sont vraies ?","o":["Il représente environ 80 % du squelette","Il est organisé en ostéones, ou systèmes de Havers","Il résiste très bien aux contraintes mécaniques","Il domine dans la diaphyse des os longs","Il est très poreux et léger, en travées"],"r":[0,1,2,3],"e":"Os compact : ~80% du squelette, ostéones (canaux de Havers + lamelles concentriques), résistant, diaphyse des os longs. L'os SPONGIEUX est poreux et léger (épiphyses).","s":11},{"q":"Le tissu osseux SPONGIEUX (trabéculaire) :","o":["Est très dense et compact, sans cavité","Est fait de travées, qui abritent la moelle rouge","Ne contient pas de moelle, ni rouge ni jaune, chez l'adulte","Est inerte, et ne se remodèle pas"],"r":1,"e":"Os spongieux : organisation en travées (trabécules), réseau alvéolaire abritant la moelle rouge hématopoïétique. Présent dans les épiphyses des os longs et les os plats. Très actif métaboliquement.","s":11},{"q":"Quels sont les principaux types CELLULAIRES du tissu osseux ?","o":["Ostéoblastes (formation osseuse)","Ostéocytes (cellules matures)","Ostéoclastes (résorption)","Cellules de Schwann","Cellules bordantes"],"r":[0,1,2,4],"e":"4 cellules : ostéoblastes (synthèse de matrice), ostéocytes (matures, dans les ostéoplastes), ostéoclastes (résorption multinucléés), cellules bordantes (quiescentes). Les cellules de Schwann appartiennent au SNP.","s":11},{"q":"Les OSTÉOBLASTES sont responsables de :","o":["La résorption osseuse, par les lacunes","La formation osseuse, par synthèse de matrice","La phagocytose des débris","L'immunité, par la production d'anticorps dans la moelle"],"r":1,"e":"Ostéoblastes = formation osseuse : synthétisent la matrice organique (ostéoïde, surtout collagène I) qui se minéralise (hydroxyapatite). Quand emmurés, ils deviennent ostéocytes.","s":11},{"q":"Les OSTÉOCLASTES sont responsables de :","o":["La formation de l'os","La résorption osseuse","La synthèse du collagène","La sécrétion de calcitonine"],"r":1,"e":"Ostéoclastes = cellules multinucléées (issues de la lignée monocytaire) qui résorbent l'os : acidification + enzymes (cathepsine K) → libération de Ca, P et fragments de collagène.","s":11},{"q":"L'OSSIFICATION INTRAMEMBRANEUSE concerne :","o":["Les os plats du crâne (voûte)","La clavicule","Les os longs (diaphyse)","La mandibule","Les vertèbres"],"r":[0,1,3],"e":"Ossification intramembraneuse : à partir de membranes mésenchymateuses, sans modèle cartilagineux. Concerne les os plats du crâne, la clavicule, la mandibule. Les os longs et vertèbres = ossification ENDOCHONDRALE.","s":11},{"q":"L'OSSIFICATION ENDOCHONDRALE :","o":["Forme l'os à partir de membranes mésenchymateuses","Forme l'os à partir d'un modèle cartilagineux","Concerne uniquement le crâne","Ne se produit pas chez l'enfant, ni chez le fœtus en croissance"],"r":1,"e":"Ossification endochondrale : remplace progressivement un MODÈLE CARTILAGINEUX par de l'os. Concerne la majorité des os (longs, courts, vertèbres, base du crâne). Permet la croissance en longueur (cartilage de conjugaison).","s":11},{"q":"La croissance EN LONGUEUR des os longs se fait au niveau :","o":["De la diaphyse, au centre","Du périoste, en surface","Du cartilage de conjugaison","Du canal médullaire"],"r":2,"e":"Croissance en longueur = cartilage de conjugaison (plaque épiphysaire), entre épiphyse et diaphyse. Croissance en épaisseur = périoste (apposition). Les plaques se ferment à la fin de la puberté. C'est la plaque épiphysaire.","s":11},{"q":"Le REMODELAGE OSSEUX correspond à :","o":["Une croissance osseuse continue","Un cycle de résorption puis de formation osseuse","Une simple usure progressive de l'os","Un phénomène pathologique, chez le sujet âgé"],"r":1,"e":"Remodelage = cycle continu (BMU - Bone Multicellular Unit) : ostéoclastes résorbent → ostéoblastes reconstruisent. Permet adaptation aux contraintes, réparation des micro-lésions, maintien de la calcémie. Cycle de ~3 mois. Les ostéoclastes résorbent et les ostéoblastes reforment.","s":11},{"q":"Quelles hormones régulent la calcémie ?","o":["La parathormone","La calcitonine","Le calcitriol","L'insuline","Le cortisol"],"r":[0,1,2],"e":"Régulation calcique : PTH (↑ Ca, sécrétée par les parathyroïdes en cas d'hypocalcémie) ; calcitonine (↓ Ca, thyroïde) ; vitamine D (↑ absorption intestinale Ca). Insuline = glycémie ; cortisol = stress. Le calcitriol est la forme active de la vitamine D.","s":11},{"q":"La PTH (parathormone) :","o":["Diminue la calcémie, en fixant le calcium sur les os","Augmente la calcémie en stimulant la résorption osseuse","Augmente la calcémie, en inhibant les ostéoclastes","N'a aucun effet sur le calcium"],"r":1,"e":"PTH = sécrétée en cas d'HYPOcalcémie. Augmente la calcémie par : 1) stimulation indirecte des ostéoclastes (résorption), 2) ↑ réabsorption rénale, 3) ↑ activation de la vitamine D → ↑ absorption intestinale.","s":11},{"q":"La CALCITONINE :","o":["Augmente la calcémie, par l'intestin","Diminue la calcémie en inhibant les ostéoclastes","Stimule la résorption osseuse","Est sécrétée par les parathyroïdes, sur hypocalcémie"],"r":1,"e":"Calcitonine = produite par les cellules C de la thyroïde, sécrétée en cas d'HYPERcalcémie. Diminue la calcémie en inhibant les ostéoclastes. Effet relativement faible chez l'humain.","s":11},{"q":"La VITAMINE D active (calcitriol) augmente la calcémie principalement par :","o":["L'inhibition des ostéoclastes","La hausse de l'absorption intestinale du calcium","La diminution de la réabsorption rénale du calcium","Sa sécrétion par la thyroïde"],"r":1,"e":"Calcitriol (1,25(OH)₂D₃) = forme active de la vitamine D. Augmente l'absorption intestinale du calcium et du phosphate. Sa carence cause le rachitisme (enfant) et l'ostéomalacie (adulte).","s":11},{"q":"Quels sont les rôles VITAUX du calcium ?","o":["La contraction musculaire","La coagulation sanguine","La transmission nerveuse","L'activité enzymatique","La vision des couleurs"],"r":[0,1,2,3],"e":"Rôles du Ca²⁺ : contraction musculaire (couplage excitation-contraction), coagulation (facteur IV), transmission synaptique, activation enzymatique, signalisation cellulaire, structure osseuse. La vision implique surtout la vitamine A.","s":11},{"q":"L'OSTÉOPOROSE est définie par :","o":["Une infection osseuse → ostéite","Une perte de masse osseuse → fractures","Une tumeur osseuse maligne → métastases pulmonaires","Une inflammation osseuse → douleurs"],"r":1,"e":"Ostéoporose = ↓ DMO (densité minérale osseuse) + altération microarchitecturale → fragilité, ↑ risque fracturaire. Diagnostic par DEXA : T-score ≤ -2,5 (OMS). Touche surtout femmes ménopausées. La microarchitecture est aussi altérée.","s":11},{"q":"Parmi les facteurs de risque d'OSTÉOPOROSE, on retrouve :","o":["La ménopause, par carence en œstrogènes","L'âge avancé, après 65 ans","Une carence en calcium ou en vitamine D","La sédentarité prolongée","Une activité physique régulière, en charge"],"r":[0,1,2,3],"e":"Facteurs de risque : ménopause (carence œstrogène), âge, ATCD familiaux, carence Ca/vit D, sédentarité, alcool/tabac, corticoïdes au long cours. L'activité physique en charge est PROTECTRICE.","s":11},{"q":"L'OSTÉOMALACIE chez l'adulte correspond à :","o":["Une infection osseuse, chronique","Une minéralisation insuffisante de la matrice","Une tumeur osseuse, bénigne ou maligne, du sujet âgé","Une fracture de fatigue"],"r":1,"e":"Ostéomalacie = trouble de la MINÉRALISATION (matrice ostéoïde présente mais peu minéralisée), souvent par carence en vitamine D. Équivalent du rachitisme chez l'adulte. Os mou, douloureux, déformations. Elle est due à une carence en vitamine D.","s":11},{"q":"Le RACHITISME concerne :","o":["L'adulte uniquement, après 50 ans","L'enfant en croissance, carencé en vitamine D","Toutes les fractures pathologiques, à tout âge de la vie","Les sujets âgés, en institution"],"r":1,"e":"Rachitisme = équivalent enfantin de l'ostéomalacie. Carence en vitamine D pendant la croissance → trouble de la minéralisation osseuse → déformations (genu varum, chapelet costal, retard de croissance).","s":11},{"q":"Concernant la maladie de PAGET osseuse, quelles affirmations sont vraies ?","o":["Un trouble du remodelage osseux","Une hyperactivité ostéoclastique puis ostéoblastique","Un os épais mais désorganisé et fragile","Une maladie touchant surtout l'enfant","Une localisation fréquente au bassin et au crâne"],"r":[0,1,2,4],"e":"Paget : remodelage ANARCHIQUE (résorption excessive puis formation désorganisée), os épais, déformé et fragile. Touche le sujet âgé (>50 ans), souvent ATCD familiaux. Localisations : bassin, vertèbres, crâne, fémur.","s":11},{"q":"L'OSTÉOMYÉLITE est :","o":["Une tumeur de l'os","Une infection osseuse","Une carence en calcium","Une fracture de fatigue"],"r":1,"e":"Ostéomyélite = infection osseuse (bactérienne le plus souvent : Staphylococcus aureus +++). Aiguë (enfant : voie hématogène) ou chronique. Risque de séquestre osseux.","s":11},{"q":"Quel TYPE DE FRACTURE survient sur un os pathologique ?","o":["Une fracture transversale","Une fracture comminutive","Une fracture pathologique","Une fracture en bois vert"],"r":2,"e":"Fracture pathologique : survient sur un os déjà fragilisé (ostéoporose, métastase, kyste osseux, Paget) après un traumatisme minime ou même spontanément. Elle survient sur un os fragilisé.","s":11},{"q":"Concernant la cicatrisation d'une fracture, dans l'ordre chronologique :","o":["D'abord, l'hématome fracturaire","Ensuite, le cal mou cartilagineux","Puis le cal dur, osseux","Enfin, le remodelage","Des ostéoclastes, seulement à la fin"],"r":[0,1,2,3],"e":"Cicatrisation osseuse : 1) hématome fracturaire (inflammation) → 2) cal mou (fibrocartilagineux, ~3 sem) → 3) cal dur (os immature, ~6-12 sem) → 4) remodelage (os lamellaire, des mois). Les ostéoclastes interviennent dès le début pour résorber l'os mort.","s":11},{"q":"L'effet PIÉZOÉLECTRIQUE de l'os signifie que :","o":["L'os ne réagit jamais aux contraintes","L'os produit des signaux électriques sous contrainte","L'os est totalement isolant, sans charge électrique","L'os ne se remodèle qu'après une fracture, jamais en dehors"],"r":1,"e":"Effet piézoélectrique : sous contrainte mécanique, l'os génère des micro-courants électriques qui stimulent le remodelage selon la loi de Wolff (l'os s'adapte aux contraintes mécaniques). Ces signaux stimulent le remodelage.","s":11},{"q":"La loi de WOLFF dit que :","o":["L'os est uniquement déterminé par la génétique","L'os s'adapte aux contraintes mécaniques","L'os ne change plus après l'enfance, une fois la croissance finie","L'os n'est pas un tissu vivant"],"r":1,"e":"Loi de Wolff : l'os s'adapte (en architecture et densité) aux contraintes mécaniques qu'il subit. Sport en charge → ↑ densité. Immobilisation → ostéoporose de non-usage. Base de la rééducation osseuse. La forme suit la fonction.","s":11},{"q":"Les fonctions de l'os incluent :","o":["Le soutien du corps","La protection des organes","Le mouvement, par les muscles","Le stockage des minéraux","L'hématopoïèse, dans la moelle rouge","La digestion des graisses"],"r":[0,1,2,3,4],"e":"Fonctions os : soutien, protection, mouvement, réservoir minéral, hématopoïèse. Pas de digestion.","s":11},{"q":"L'os compact se trouve :","o":["Au centre des os longs, en travées","Dans la diaphyse, en couche externe","Dans les épiphyses uniquement","Aux articulations"],"r":1,"e":"Os compact = couche externe dense (diaphyse). Os spongieux/trabéculaire = épiphyses.","s":11},{"q":"Les ostéoblastes :","o":["Détruisent la matrice osseuse","Synthétisent la matrice osseuse","Sont des cellules musculaires","Produisent l'hémoglobine des globules rouges"],"r":1,"e":"Ostéoblastes = formation osseuse (synthèse matrice). Ostéoclastes = résorption.","s":11},{"q":"Les ostéoclastes :","o":["Synthétisent la matrice osseuse, par l'ostéoïde","Résorbent la matrice osseuse","Stockent le calcium","Produisent l'érythropoïétine"],"r":1,"e":"Ostéoclastes = cellules multinucléées qui résorbent l'os (équilibre formation-résorption).","s":11},{"q":"Les ostéocytes sont :","o":["Des ostéoblastes inactifs piégés dans la matrice","Des cellules sanguines de la moelle","Des cellules musculaires lisses, dans les canaux de Havers","Des ostéoclastes mûrs, multinucléés"],"r":0,"e":"Ostéocytes = ostéoblastes mûrs emprisonnés dans la matrice qu'ils ont sécrétée, dans les lacunes (canalicules).","s":11},{"q":"Le remodelage osseux est régulé par :","o":["La vitamine D, la PTH et la calcitonine","L'insuline uniquement, après les repas","L'ADH, par la réabsorption d'eau dans le tubule","L'adrénaline, à l'effort"],"r":0,"e":"Régulateurs : vit D, PTH (↑ résorption), calcitonine (↓ résorption), œstrogènes/testostérone (anti-résorption). Les hormones sexuelles y participent aussi.","s":11},{"q":"La parathormone (PTH) :","o":["Diminue la calcémie, en fixant le calcium","Augmente la calcémie en activant les ostéoclastes","N'a pas d'effet sur l'os ni le rein","Stocke le calcium dans l'os, sous forme d'hydroxyapatite"],"r":1,"e":"PTH ↑ calcémie : active ostéoclastes, ↑ réabsorption rénale Ca, ↑ activation vit D → ↑ absorption intestinale Ca.","s":11},{"q":"Le cartilage articulaire est :","o":["Très vascularisé, par les artères épiphysaires","Avascularisé, nourri par le liquide synovial","Richement innervé, donc sensible","Capable de cicatriser parfaitement"],"r":1,"e":"Cartilage articulaire = avascularisé, sans nerf, nourri par diffusion via liquide synovial. Faible capacité de réparation.","s":11},{"q":"L'épiphyse fertile (cartilage de croissance) :","o":["Persiste toute la vie","Se ferme à la fin de la croissance","Est inutile","Ne contient pas de cartilage"],"r":1,"e":"Cartilage de croissance (plaque épiphysaire) actif pendant la croissance, se ferme à l'âge adulte (ossification).","s":11},{"q":"Le tissu osseux contient :","o":["De l'eau seulement, en grande quantité","Une phase organique et une phase minérale","Uniquement des minéraux, sans aucune fibre de collagène","Uniquement des cellules"],"r":1,"e":"Os = matrice organique (90% collagène I, ostéoïde) + phase minérale (cristaux d'hydroxyapatite Ca/P). La phase organique est le collagène I, la phase minérale l'hydroxyapatite.","s":11},{"q":"Quelle proportion du poids corporel le tissu osseux représente-t-il ?","o":["Environ 18 %","Environ 5 %","Environ 30 %","Environ 50 %"],"r":0,"e":"La fiche indique environ 18 % du poids corporel.","s":11},{"q":"Pourquoi chaque os est-il considéré comme un organe ?","o":["Parce qu'il associe plusieurs tissus différents","Parce qu'il contient de la moelle, rouge ou jaune","Parce qu'il est vascularisé","Parce qu'il stocke du calcium"],"r":0,"e":"La présence de plusieurs types de tissus définit un organe. Ce sont les tissus osseux, cartilagineux, conjonctif dense, épithélial, adipeux et nerveux.","s":11},{"q":"Où se trouve la moelle osseuse rouge chez l'adulte ?","o":["Dans les côtes, le sternum et les vertèbres","Dans toute la cavité médullaire des os longs","Uniquement dans le crâne, chez l'adulte","Uniquement dans les diaphyses"],"r":0,"e":"La moelle jaune, adipeuse, occupe la cavité médullaire diaphysaire chez l'adulte. Les hanches, le crâne et les extrémités de l'humérus et du fémur en contiennent aussi.","s":11},{"q":"Qu'est-ce que la métaphyse ?","o":["La zone entre diaphyse et épiphyse","Le corps central de l'os","L'extrémité articulaire","La membrane recouvrant l'os entier"],"r":0,"e":"La plaque épiphysaire y devient ligne épiphysaire chez l'adulte. Elle contient la plaque épiphysaire chez l'enfant.","s":11},{"q":"Comment le périoste est-il fixé à l'os ?","o":["Par les fibres de Sharpey","Par les canalicules","Par les fibres de collagène de type IV","Par l'endoste"],"r":0,"e":"Les fibres de Sharpey ancrent le périoste dans la matrice osseuse.","s":11},{"q":"Quelles sont les deux couches du périoste ?","o":["Une couche fibreuse et une couche ostéogénique","Une couche compacte et une couche spongieuse","Une couche minéralisée et une couche cartilagineuse","Une couche vasculaire et une couche nerveuse, superposées"],"r":0,"e":"La couche ostéogénique interne contient les cellules capables de former de l'os. La fibreuse est externe, l'ostéogénique interne.","s":11},{"q":"Pourquoi le cartilage articulaire se répare-t-il mal ?","o":["Parce qu'il est avasculaire","Parce qu'il est trop dense","Parce qu'il ne contient pas de collagène","Parce qu'il est constamment comprimé"],"r":0,"e":"L'absence de vascularisation limite fortement la capacité de réparation du cartilage hyalin.","s":11},{"q":"Quelle est la composition de la matrice osseuse ?","o":["55 % de minéraux, 30 % de collagène et 15 % d'eau","30 % de minéraux, 55 % de collagène et 15 % de lipides","70 % de minéraux et 30 % de collagène","50 % d'eau et 50 % de minéraux"],"r":0,"e":"Les sels minéraux donnent la dureté, le collagène la souplesse et l'eau le milieu de diffusion.","s":11},{"q":"Quelle est la formule de l'hydroxyapatite ?","o":["Ca₁₀(PO₄)₆(OH)₂","Ca₅(CO₃)₃(OH)₂","Ca₁₀(SO₄)₆(OH)₂","Ca₃(PO₄)₂·H₂O"],"r":0,"e":"L'hydroxyapatite est le cristal minéral principal de l'os, accompagné de carbonate de calcium et d'ions Mg, F, K et SO₄.","s":11},{"q":"Quelles sont les seules cellules osseuses capables de se diviser ?","o":["Les cellules ostéogéniques","Les ostéoblastes matures","Les ostéocytes emmurés","Les ostéoclastes actifs"],"r":0,"e":"Issues du mésenchyme, les cellules ostéogéniques donnent les ostéoblastes ; les autres ne se divisent pas.","s":11},{"q":"De quoi les ostéoclastes proviennent-ils ?","o":["De la fusion d'environ 50 monocytes","De la division de 2 cellules mésenchymateuses","D'ostéoblastes piégés dans la matrice osseuse calcifiée","De chondroblastes du cartilage"],"r":0,"e":"Leur origine monocytaire explique leur capacité de résorption ; les ostéocytes proviennent des ostéoblastes.","s":11},{"q":"Comment les ostéocytes communiquent-ils entre eux ?","o":["Par les canalicules et des jonctions communicantes","Par les canaux de Volkmann uniquement, transversaux","Par la circulation sanguine","Ils ne communiquent pas entre eux"],"r":0,"e":"Les prolongements cytoplasmiques cheminent dans les canalicules qui relient les lacunes.","s":11},{"q":"Qu'est-ce qu'un ostéon ?","o":["Des lamelles concentriques autour d'un canal de Havers","Une trabécule d'os spongieux, en réseau","Une lacune contenant un ostéocyte","Un canal transversal reliant le périoste à l'endoste"],"r":0,"e":"L'ostéon, ou système de Havers, est l'unité de l'os compact ; le canal transversal est celui de Volkmann.","s":11},{"q":"Quelle proportion du squelette l'os compact représente-t-il ?","o":["80 %","20 %","50 %","95 %"],"r":0,"e":"80 % d'os compact pour 20 % d'os spongieux.","s":11},{"q":"La POLYARTHRITE RHUMATOÏDE (PR) est :","o":["Une maladie dégénérative du cartilage","Une maladie auto-immune, chronique et inflammatoire","Une maladie infectieuse, bactérienne ou virale, aiguë","Une fracture pathologique, sur os fragile"],"r":1,"e":"PR = polyarthrite chronique inflammatoire AUTO-IMMUNE. Atteinte symétrique, prédominant aux petites articulations (mains, pieds), avec destruction articulaire progressive et manifestations extra-articulaires.","s":12},{"q":"Quels sont les signes typiques de la PR ?","o":["Une atteinte symétrique","Une atteinte des petites articulations","Une raideur matinale de plus de 30 minutes","Des érosions osseuses à la radiographie","Des déformations en col de cygne","Des ostéophytes marginaux à la radiographie"],"r":[0,1,2,3,4],"e":"PR typique : symétrique, petites articulations (MCP, IPP, poignets, MTP), raideur matinale prolongée (>30-60 min, vs arthrose <15 min), déformations caractéristiques (col de cygne, boutonnière), signes biologiques (FR, anti-CCP). Les ostéophytes sont le signe radiographique de l'arthrose ; la polyarthrite rhumatoïde donne des érosions.","s":12},{"q":"L'ARTHROSE est :","o":["Une maladie auto-immune","Une maladie dégénérative du cartilage","Une fracture articulaire","Une infection articulaire, bactérienne et aiguë"],"r":1,"e":"Arthrose (osteoarthritis) = maladie DÉGÉNÉRATIVE du cartilage articulaire, avec remaniement de l'os sous-chondral, ostéophytes, et inflammation modérée. Pas auto-immune. Très fréquente avec l'âge.","s":12},{"q":"Quels sont les signes radiologiques typiques de l'ARTHROSE ?","o":["Pincement articulaire","Ostéophytes (becs)","Sclérose sous-chondrale","Géodes (kystes sous-chondraux)","Érosions marginales"],"r":[0,1,2,3],"e":"Arthrose RX : 'POSG' = Pincement articulaire, Ostéophytes, Sclérose sous-chondrale, Géodes. Les ÉROSIONS marginales sont signes de POLYARTHRITE inflammatoire (PR).","s":12},{"q":"La douleur d'ARTHROSE est typiquement :","o":["Inflammatoire, matinale et prolongée","Mécanique, calmée par le repos","Permanente, sans facteur déclenchant","Aiguë, avec de la fièvre et des frissons"],"r":1,"e":"Douleur arthrosique = MÉCANIQUE : ↑ à l'effort/marche, calmée par le repos, raideur matinale courte (<15 min, dérouillage). PR = douleur INFLAMMATOIRE : nuit, raideur matinale prolongée. Elle augmente à l'effort.","s":12},{"q":"La GOUTTE est due à :","o":["Une infection bactérienne de l'articulation","Un dépôt de cristaux d'urate dans l'articulation","Une auto-immunité contre la synoviale","Une carence en calcium, chronique"],"r":1,"e":"Goutte = arthropathie microcristalline due au dépôt de cristaux d'urate monosodique liés à une hyperuricémie. Crise aiguë : monoarthrite très inflammatoire (souvent gros orteil = podagre).","s":12},{"q":"Concernant la crise de GOUTTE, quelles affirmations sont vraies ?","o":["Un siège fréquent au gros orteil, ou podagre","Une monoarthrite très inflammatoire","Une hyperuricémie sanguine","La colchicine ou les AINS en aigu","Une atteinte toujours bilatérale"],"r":[0,1,2,3],"e":"Goutte aiguë : podagre (50% des cas), monoarthrite intense, hyperuricémie (mais pas toujours en crise !). Tx aigu = colchicine ou AINS. Tx fond = allopurinol (inhibiteur xanthine oxydase). Souvent UNILATÉRALE.","s":12},{"q":"Le LUPUS érythémateux disséminé est :","o":["Une maladie infectieuse virale","Une maladie auto-immune systémique","Une maladie dégénérative","Une fracture pathologique"],"r":1,"e":"LED = maladie auto-immune SYSTÉMIQUE (multi-organique : peau, articulations, rein, SNC, cœur, sang). Plus fréquent chez les femmes jeunes. Anticorps caractéristiques : anti-ADN natif, anti-Sm.","s":12},{"q":"Manifestations classiques du LUPUS :","o":["Un érythème du visage en ailes de papillon","Une photosensibilité cutanée","Une atteinte rénale, glomérulaire","Une polyarthrite non érosive","Des tassements vertébraux ostéoporotiques"],"r":[0,1,2,3],"e":"LED : rash malaire en ailes de papillon, photosensibilité, atteinte rénale (souvent grave), polyarthrite non érosive (vs PR), atteinte hématologique, sérites, neurologiques. Tassements ostéoporotiques = autre pathologie.","s":12},{"q":"La SCLÉRODERMIE (sclérose systémique) est caractérisée par :","o":["Une démyélinisation du SNC, en plaques","Une fibrose excessive de la peau et des organes","Une infection chronique, par des mycobactéries","Une carence vitaminique, en vitamine C"],"r":1,"e":"Sclérodermie = maladie auto-immune avec FIBROSE excessive de la peau (scléroderme) et des organes (poumons, rein, œsophage, cœur). Peut être limitée (CREST) ou diffuse. Phénomène de Raynaud quasi constant.","s":12},{"q":"Concernant les SPONDYLARTHROPATHIES, quelles affirmations sont vraies ?","o":["Atteinte préférentielle du squelette axial (rachis, sacro-iliaques)","Inflammation des enthèses (enthésites)","Souvent associées au HLA-B27","La spondylarthrite ankylosante en fait partie","Atteignent surtout les femmes âgées"],"r":[0,1,2,3],"e":"Spondylarthropathies : atteinte axiale (rachis, SI), enthésites, dactylites, association HLA-B27, exemples = spondylarthrite ankylosante, rhumatisme psoriasique, arthrite réactionnelle, MICI. Touchent l'adulte jeune (homme +).","s":12},{"q":"Une OSTÉOMYÉLITE est :","o":["Une infection osseuse","Une tumeur","Une carence vitaminique","Une malformation congénitale"],"r":0,"e":"Ostéomyélite = infection bactérienne de l'os (Staphylococcus aureus +++). Voie hématogène (enfant, métaphyse) ou contiguïté/inoculation (adulte). Peut chroniciser → séquestre osseux.","s":12},{"q":"L'OSTÉONÉCROSE aseptique correspond à :","o":["Une infection osseuse sans germe retrouvé à la culture","Une mort osseuse par défaut de vascularisation","Une fracture pathologique","Une décalcification diffuse"],"r":1,"e":"Ostéonécrose aseptique = mort osseuse par interruption de la vascularisation. Site classique : tête fémorale. FdR : corticoïdes, alcool, traumatisme (fracture col), drépanocytose, lupus.","s":12},{"q":"Quels sont des facteurs de risque d'OSTÉONÉCROSE de la tête fémorale ?","o":["Une corticothérapie au long cours","Un alcoolisme chronique","Une drépanocytose","Une fracture du col du fémur","Une hypertension artérielle"],"r":[0,1,2,3],"e":"FdR ostéonécrose tête fémorale : corticoïdes, alcool, drépanocytose, fracture du col, lupus, plongée (maladie des caissons), idiopathique. L'HTA n'est pas un FdR direct.","s":12},{"q":"Les TUMEURS osseuses les plus fréquentes chez l'adulte sont :","o":["Les tumeurs primaires","Les métastases osseuses","Les ostéosarcomes","Les chondromes"],"r":1,"e":"Chez l'adulte, les tumeurs osseuses sont surtout des MÉTASTASES (sein, poumon, prostate, rein, thyroïde — moyen mnémo : 'PSPRT' ou 'RPS'). Les tumeurs primaires sont plus rares.","s":12},{"q":"L'OSTÉOSARCOME est :","o":["Une tumeur bénigne, sans potentiel métastatique","Une tumeur osseuse maligne primitive","Une métastase d'un cancer","Un kyste osseux simple"],"r":1,"e":"Ostéosarcome = tumeur osseuse PRIMITIVE MALIGNE la plus fréquente, pic à l'adolescence (10-20 ans), localisation classique : métaphyse des os longs (fémur distal, tibia proximal). Pronostic amélioré (chimio + chirurgie). Elle touche l'adolescent et l'adulte jeune.","s":12},{"q":"Quels critères différencient PR et ARTHROSE ?","o":["PR inflammatoire, arthrose mécanique","PR symétrique, arthrose souvent asymétrique","PR à raideur matinale longue, arthrose courte","PR à érosions, arthrose à ostéophytes","PR et arthrose, avec les mêmes traitements"],"r":[0,1,2,3],"e":"PR : auto-immune, symétrique, raideur matinale >60 min, érosions, FR/anti-CCP. Arthrose : dégénérative, asymétrique, douleur mécanique, ostéophytes. Traitements TRÈS différents (DMARDs vs antalgiques + kiné).","s":12},{"q":"L'ankylose articulaire correspond à :","o":["Une raideur passagère, au réveil le matin","Une perte définitive de la mobilité, par fusion","Une inflammation aiguë de la synoviale du genou","Une luxation, avec perte de contact"],"r":1,"e":"Ankylose = perte définitive de la mobilité articulaire par fusion fibreuse ou osseuse des surfaces articulaires. Peut compliquer une PR sévère, une spondylarthrite ankylosante, une arthrose terminale.","s":12},{"q":"Le syndrome du CANAL CARPIEN est dû à :","o":["Une compression du nerf médian au poignet","Une compression du nerf ulnaire au coude","Une compression du nerf radial au bras","Une rupture du tendon fléchisseur"],"r":0,"e":"Canal carpien = compression du nerf MÉDIAN dans le canal carpien au poignet. Paresthésies des 3 premiers doigts + bord radial du 4e, recrudescence nocturne, faiblesse de l'opposition du pouce.","s":12},{"q":"L'arthrose des doigts (nodale) se caractérise par :","o":["Une atteinte des MCP en priorité, avec déviation cubitale","Des nodules d'Heberden et de Bouchard","Un pannus synovial érosif","Une atteinte symétrique, avec raideur prolongée"],"r":1,"e":"Arthrose digitale nodale : nodules d'Heberden (IPD), Bouchard (IPP). PAS d'atteinte des MCP (sinon évoquer PR). Touche surtout les femmes ménopausées, souvent familial. Heberden siège aux IPD et Bouchard aux IPP.","s":12},{"q":"Quels examens biologiques sont utiles dans la PR ?","o":["Le facteur rhumatoïde, ou FR","Les anticorps anti-CCP","La CRP et la vitesse de sédimentation","Les ASLO, contre le streptocoque","Le HLA-B27, de la spondylarthrite"],"r":[0,1,2],"e":"PR : FR (peu spécifique), anti-CCP (très spécifique +++), CRP/VS (inflammation). HLA-B27 = spondylarthrite. ASLO = streptocoque (RAA). Anti-ADN natif = lupus.","s":12},{"q":"Le pannus synovial est typique de :","o":["L'arthrose digitale","La polyarthrite rhumatoïde","La goutte tophacée","L'ostéoporose post-ménopausique"],"r":1,"e":"Pannus = tissu synovial inflammatoire prolifératif et invasif qui érode l'os et le cartilage dans la PR. Responsable de la destruction articulaire (érosions, géodes, déformations).","s":12},{"q":"Concernant les MALADIES MÉTABOLIQUES osseuses, on retrouve :","o":["Ostéoporose","Ostéomalacie / rachitisme","Maladie de Paget","Hyperparathyroïdie","Polyarthrite rhumatoïde"],"r":[0,1,2,3],"e":"Maladies métaboliques osseuses : ostéoporose (↓ masse), ostéomalacie/rachitisme (↓ minéralisation), Paget (remodelage anarchique), hyperparathyroïdie (résorption excessive), ostéogenèse imparfaite. La PR est rhumatismale, pas métabolique.","s":12},{"q":"Le RHUMATISME ARTICULAIRE AIGU (RAA) est une complication :","o":["D'une infection à staphylocoque doré, cutanée","D'une angine à streptocoque du groupe A","D'une infection virale, comme la grippe","D'une carence vitaminique"],"r":1,"e":"RAA : complication post-infectieuse d'une angine à streptocoque β-hémolytique A. Survient 2-3 semaines après. Atteinte articulaire (polyarthrite), cardiaque (cardite ++ valvulaire) et neurologique (chorée). Critères de Jones. Le streptocoque est β-hémolytique.","s":12},{"q":"La maladie de PAGET est :","o":["Une infection osseuse chronique","Un remodelage osseux anarchique et localisé","Une carence en calcium, alimentaire","Une maladie auto-immune, avec des anticorps anti-os circulants"],"r":1,"e":"Paget : trouble localisé du remodelage avec phase ostéoclastique excessive puis phase ostéoblastique désorganisée → os hypertrophique mais fragile. Sites : bassin, vertèbres, crâne, fémur. Souvent asymptomatique. L'hyperactivité ostéoclastique y précède une formation désordonnée.","s":12},{"q":"La chondrocalcinose (« pseudo-goutte ») est due au dépôt intra-articulaire de :","o":["Des cristaux d'urate monosodique, en aiguilles","Des cristaux de pyrophosphate de calcium","Des cristaux de cholestérol","Des cristaux d'oxalate de calcium"],"r":1,"e":"La goutte est liée aux cristaux d'urate monosodique (en aiguilles, biréfringence négative) ; la chondrocalcinose aux cristaux de pyrophosphate de calcium (rhomboédriques, biréfringence positive), visibles en radiographie sous forme de liserés calciques du cartilage, notamment aux ménisques et au ligament triangulaire du carpe.","s":12},{"q":"Les ostéophytes sont :","o":["Des trous osseux, ou géodes, sous le cartilage","Des excroissances osseuses, typiques de l'arthrose","Des fractures de fatigue, sur os sain","Des cellules cancéreuses, en amas"],"r":1,"e":"Ostéophytes = excroissances osseuses péri-articulaires, signes radiologiques typiques de l'arthrose. On les appelle aussi becs de perroquet.","s":12},{"q":"Une luxation est :","o":["Une fissure osseuse, sans déplacement","Une perte de contact articulaire permanente","Une contusion, par choc direct","Une déchirure musculaire, à l'effort"],"r":1,"e":"Luxation = perte permanente du contact normal entre les surfaces articulaires.","s":12},{"q":"Une entorse correspond à :","o":["Une fracture de l'épiphyse, sans déplacement","Une lésion ligamentaire, par étirement ou rupture","Une luxation, avec perte de contact articulaire","Une déchirure musculaire, à l'effort"],"r":1,"e":"Entorse = lésion ligamentaire (grade 1: étirement, 2: déchirure partielle, 3: rupture complète).","s":12},{"q":"Le syndrome du canal carpien est :","o":["Une fracture du scaphoïde","Une compression du nerf médian au poignet","Une rupture musculaire des fléchisseurs du poignet","Une infection osseuse du carpe"],"r":1,"e":"Canal carpien = compression du nerf médian dans le canal carpien (paresthésies pouce, index, majeur).","s":12},{"q":"Une tendinite est :","o":["Une rupture totale du tendon","Une inflammation d'un tendon, par surcharge","Une infection du tendon, par un germe pyogène venu de la peau","Une fracture par arrachement"],"r":1,"e":"Tendinite/tendinopathie = atteinte inflammatoire ou dégénérative d'un tendon, souvent par surcharge.","s":12},{"q":"La bursite est :","o":["Une inflammation d'une bourse synoviale","Une fracture de fatigue, près d'une articulation","Une tumeur bénigne des tissus mous","Une infection cutanée, superficielle"],"r":0,"e":"Bursite = inflammation d'une bourse synoviale (épaule, coude, hanche, genou).","s":12},{"q":"L'épicondylite latérale (« tennis elbow ») touche :","o":["L'insertion des fléchisseurs, au coude médial","L'insertion des extenseurs sur l'épicondyle latéral","Le canal carpien, au poignet","La coiffe des rotateurs, à l'épaule du joueur de tennis"],"r":1,"e":"Tennis elbow = tendinopathie d'insertion des extenseurs sur l'épicondyle latéral du coude. Ce sont les extenseurs du poignet.","s":12},{"q":"La rupture du tendon d'Achille est typique :","o":["De l'enfant, lors d'une chute","Du sportif d'âge moyen, en flexion plantaire","De la femme enceinte, au 3e trimestre","Du nourrisson, lors des premiers pas en appui sur la pointe"],"r":1,"e":"Rupture tendon d'Achille : hommes 30-50 ans, sport (squash, badminton), claquement audible.","s":12},{"q":"Une fracture en bois vert touche :","o":["L'adulte âgé, à l'os fragile","L'enfant, dont l'os est flexible","La personne ostéoporotique","Le sportif, lors d'un choc violent sur le tibia"],"r":1,"e":"Fracture en bois vert = enfant, os flexible, une corticale rompue, l'autre intacte (incomplète). La fracture est incomplète.","s":12},{"q":"Quelle est la première cause de mortalité chez l'adulte de moins de 44 ans selon la fiche ?","o":["Les accidents de la route à grande vitesse","Les chutes accidentelles, à domicile","Les blessures sportives, en compétition","Les fractures ostéoporotiques"],"r":0,"e":"Les chutes sont la première cause de blessures non mortelles chez les 0-19 ans.","s":12},{"q":"Quelle proportion des personnes de 65 ans et plus chute au moins une fois par an ?","o":["Une sur trois","Une sur dix","Une sur deux","Une sur vingt"],"r":0,"e":"Ces chutes expliquent la majorité des fractures vertébrales, du radius distal et de la hanche.","s":12},{"q":"Quelle part des blessures sportives de l'enfant relève d'une utilisation excessive ?","o":["50 %","10 %","80 %","25 %"],"r":0,"e":"La fiche oppose les lésions aiguës aux lésions de surmenage, à parts égales chez l'enfant.","s":12},{"q":"Quel traitement la fiche propose-t-elle pour une contusion ?","o":["Élévation et froid, 20 min toutes les 4 h","Suture après nettoyage, sous 6 heures","Aspiration systématique de l'hématome","Immobilisation plâtrée de 3 semaines"],"r":0,"e":"La suture concerne la lacération et l'aspiration éventuellement l'hématome.","s":12},{"q":"Quel risque infectieux particulier présente une plaie perforante par objet rouillé ?","o":["Le tétanos et la gangrène gazeuse, dus à des anaérobies","Une ostéomyélite hématogène, par voie sanguine","Une tuberculose osseuse, par contact avec le sol contaminé","Une nécrose avasculaire de l'os"],"r":0,"e":"Les germes anaérobies profitent de l'anoxie de la plaie profonde.","s":12},{"q":"Quels sites sont les plus fréquents pour un claquage musculaire ?","o":["Le bas du dos, les cervicales et l'épaule","La cheville, en inversion","Le genou, avec le ligament croisé et les ménisques","La hanche, chez le sujet âgé"],"r":0,"e":"La cheville est le site n°1 d'entorse, pas de claquage. Le coude et le pied en font aussi partie.","s":12},{"q":"Qu'est-ce qui distingue cliniquement l'entorse du claquage ?","o":["L'entorse gonfle vite, avec chaleur et décoloration","Le claquage gonfle plus vite que l'entorse","L'entorse est toujours indolore","Le claquage touche les ligaments, et l'entorse les muscles"],"r":0,"e":"Le claquage atteint l'unité musculo-tendineuse sans signe extérieur marqué. L'entorse s'atténue aussi plus lentement.","s":12},{"q":"Combien de temps la résistance à la traction reste-t-elle insuffisante après une lésion tendineuse ?","o":["Environ 2 mois","Environ 2 semaines","Environ 1 semaine","Environ 6 mois"],"r":0,"e":"Les faisceaux de collagène se forment dès les deux premières semaines, mais la solidité tarde.","s":12},{"q":"Qu'est-ce qu'une subluxation ?","o":["Une luxation partielle, avec un contact maintenu","Une luxation complète, sans contact","Une fracture articulaire, avec un fragment déplacé","Une entorse de grade 3"],"r":0,"e":"La luxation vraie sépare complètement les extrémités osseuses.","s":12},{"q":"Quels sont les trois types de luxations selon leur cause ?","o":["Congénitales, traumatiques et pathologiques","Antérieures, postérieures et centrales","Complètes, partielles et récidivantes","Aiguës, subaiguës et chroniques"],"r":0,"e":"Les formes pathologiques compliquent une infection, une PR ou une paralysie.","s":12},{"q":"Quel muscle de la coiffe des rotateurs est le plus souvent atteint ?","o":["Le supraspinatus","Le teres minor","L'infraspinatus","Le subscapularis"],"r":0,"e":"Le sus-épineux est le plus exposé, la récupération postopératoire prenant 6 à 12 mois.","s":12},{"q":"Qu'est-ce que la chondromalacie ?","o":["Un ramollissement du cartilage de la rotule","Une déchirure méniscale, interne","Une rupture du ligament croisé antérieur","Une luxation de la rotule, vers le dehors du genou"],"r":0,"e":"La subluxation rotulienne représente environ 10 % des blessures sportives, avec prédominance féminine. Elle touche surtout le jeune adulte.","s":12},{"q":"Pourquoi la luxation postérieure de hanche est-elle une urgence ?","o":["À cause du risque de nécrose de la tête fémorale","À cause du risque d'infection de l'articulation","À cause du risque de syndrome des loges","À cause du risque d'embolie graisseuse"],"r":0,"e":"La réduction précoce vise à restaurer la vascularisation. La nécrose est avasculaire.","s":12},{"q":"Quels facteurs de risque de fracture de hanche la fiche cite-t-elle ?","o":["Un faible IMC, une grande taille et l'ostéoporose","Un IMC élevé et le tabagisme","Le diabète et l'hypertension, mal équilibrés","Le sport intensif, avec des chutes répétées sur la hanche"],"r":0,"e":"Les localisations sont le col fémoral, la région intertrochantérienne et la région sous-trochantérienne. Les benzodiazépines et les troubles de la vision en font aussi partie.","s":12},{"q":"Quelle complication menace une fracture déplacée du col fémoral ?","o":["Une nécrose avasculaire et une non-consolidation","Un syndrome des loges, de la cuisse","Une embolie graisseuse constante","Une ostéomyélite hématogène, par voie sanguine depuis la peau"],"r":0,"e":"Le caractère intracapsulaire compromet la vascularisation de la tête. Elles résultent de la perturbation vasculaire.","s":12},{"q":"L'OSTÉOPÉNIE correspond, à la DEXA, à un T-score :","o":["≥ -1","Entre -1 et -2,5","≤ -2,5","≤ -2,5 + fracture"],"r":1,"e":"OMS : Normal T-score > -1 ; Ostéopénie : -1 à -2,5 ; Ostéoporose : ≤ -2,5 ; Ostéoporose sévère : ≤ -2,5 + fracture de fragilité.","s":13},{"q":"L'ostéoporose est définie (DEXA) par un T-score :","o":["> -1","Entre -1 et -2,5","≤ -2,5","≤ -3,5"],"r":2,"e":"Ostéoporose densitométrique : T-score ≤ -2,5 (≥ 2,5 écarts-types sous la moyenne d'un adulte jeune de référence).","s":13},{"q":"L'examen de référence pour le diagnostic densitométrique d'ostéoporose est :","o":["Une IRM osseuse, en T1","Une scintigraphie osseuse au technétium","La DEXA, ou absorptiométrie","Une radiographie standard"],"r":2,"e":"DEXA = examen de référence : mesure la DMO (densité minérale osseuse) au rachis lombaire et au col fémoral. Donne le T-score (vs adulte jeune) et le Z-score (vs même âge). Elle est biphotonique.","s":13},{"q":"Parmi les facteurs de risque MAJEURS d'ostéoporose, on retrouve :","o":["Le sexe féminin, après 50 ans","Une ménopause précoce","Un antécédent de fracture de fragilité","Une corticothérapie prolongée","Une activité physique en charge"],"r":[0,1,2,3],"e":"Facteurs majeurs : sexe féminin, ménopause précoce, ATCD personnel/familial de fracture de fragilité, corticoïdes au long cours, IMC bas, alcoolisme, tabagisme. L'activité en charge est PROTECTRICE.","s":13},{"q":"L'ostéoporose POST-MÉNOPAUSIQUE est principalement due à :","o":["Une carence en calcium","Une carence en œstrogènes","Un excès de PTH","Une carence en vitamine K"],"r":1,"e":"Post-ménopause : carence œstrogénique → ↑ activité ostéoclastique → ↑ résorption osseuse > formation → perte osseuse rapide les premières années (jusqu'à 3-5%/an au début).","s":13},{"q":"Quels sites anatomiques sont les plus exposés aux fractures ostéoporotiques ?","o":["Le col du fémur","Les vertèbres, par tassement","Le poignet, ou Pouteau-Colles","Le crâne, en fracture du vertex","L'humérus proximal"],"r":[0,1,2,4],"e":"Sites typiques : col fémoral (gravissime, mortalité 20-25% à 1 an), vertèbres (tassements souvent silencieux), poignet (Pouteau-Colles), humérus proximal. Le crâne n'est pas un site classique.","s":13},{"q":"La fracture de POUTEAU-COLLES est :","o":["Une fracture du col du fémur, après chute","Une fracture distale du radius, en extension","Une fracture vertébrale, par tassement","Une fracture de l'humérus proximal"],"r":1,"e":"Pouteau-Colles : fracture de l'extrémité inférieure du radius, à déplacement postérieur, sur chute en hyperextension du poignet. Très fréquente chez la femme ménopausée.","s":13},{"q":"Concernant les fractures VERTÉBRALES ostéoporotiques :","o":["Elles sont souvent silencieuses","Elles provoquent un tassement vertébral","Elles peuvent réduire la taille","Elles surviennent souvent sans traumatisme net","Elles sont toujours symptomatiques"],"r":[0,1,2,3],"e":"Tassements vertébraux : souvent silencieux (50% asymptomatiques), perte de taille progressive, cyphose dorsale, parfois douleur aiguë. Découverte fréquemment fortuite.","s":13},{"q":"Quels traitements sont utilisés dans l'ostéoporose ?","o":["Bisphosphonates (alendronate)","Dénosumab","Calcium + vitamine D","Tériparatide (PTH 1-34)","Antibiotiques"],"r":[0,1,2,3],"e":"Traitements : antirésorbeurs (bisphosphonates, dénosumab, raloxifène), anaboliques (tériparatide, romosozumab), supplémentation Ca + vit D systématique. Antibiotiques = ostéomyélite, pas ostéoporose.","s":13},{"q":"Les BISPHOSPHONATES agissent en :","o":["Stimulant les ostéoblastes","Inhibant les ostéoclastes","Apportant directement du calcium","Stimulant la PTH"],"r":1,"e":"Bisphosphonates (alendronate, risédronate, acide zolédronique) : se fixent à l'os et inhibent l'activité ostéoclastique → ↓ résorption → stabilisation/gain de DMO.","s":13},{"q":"Un trait de fracture TRANSVERSAL résulte typiquement de :","o":["Une force de torsion, en rotation","Une force directe, perpendiculaire à l'os","Une compression axiale, par chute sur les pieds","Une fracture pathologique, sur os fragile"],"r":1,"e":"Trait transversal : force directe (choc perpendiculaire). Spiroïde = torsion. Comminutif = haute énergie. En bois vert = enfant.","s":13},{"q":"Une fracture EN BOIS VERT survient :","o":["Chez l'adulte âgé, ostéoporotique","Chez l'enfant, à l'os flexible","Sur un os nécrosé, par défaut de vascularisation","Sur une métastase osseuse"],"r":1,"e":"Fracture en bois vert : typique de l'enfant (os flexible) → la corticale se rompt d'un seul côté, l'autre se plie sans rompre. Ressemble à une branche verte qu'on plie.","s":13},{"q":"Concernant la consolidation osseuse, dans l'ordre :","o":["D'abord, l'hématome inflammatoire","Ensuite, le cal mou fibrocartilagineux","Puis le cal dur, osseux","Enfin, le remodelage","Une consolidation, en 2 étapes seulement"],"r":[0,1,2,3],"e":"Consolidation en 4 étapes : hématome (jours), cal mou (3-6 sem), cal dur (6-12 sem), remodelage (mois-années pour retrouver l'architecture).","s":13},{"q":"Quels facteurs RETARDENT la consolidation osseuse ?","o":["Le tabagisme actif","Le diabète déséquilibré","Les AINS au long cours","Une mauvaise vascularisation locale","Le jeune âge du patient"],"r":[0,1,2,3],"e":"Retardateurs : tabac (vasoconstriction), diabète, AINS chroniques (↓ COX-2 et inflammation utile), mauvaise vascularisation, infection, mobilité excessive du foyer, âge avancé. Le jeune âge favorise.","s":13},{"q":"L'OSTÉONÉCROSE de la tête fémorale survient :","o":["Toujours après une infection","Après une perte de la vascularisation","Uniquement chez l'enfant","Sans aucun facteur de risque, de façon spontanée"],"r":1,"e":"Ostéonécrose aseptique : interruption de la vascularisation → mort osseuse. FdR : corticoïdes, alcoolisme, fracture du col, drépanocytose, lupus, traumatisme. Site classique : tête fémorale. La fracture du col, l'alcool ou les corticoïdes en sont des causes.","s":13},{"q":"Une OSTÉOMYÉLITE est :","o":["Une tumeur osseuse, maligne et primitive, de l'enfant","Une infection osseuse, souvent staphylococcique","Une décalcification diffuse","Une carence en vitamine D"],"r":1,"e":"Ostéomyélite : infection osseuse, le plus souvent bactérienne (S. aureus +++). Voie hématogène (enfant) ou par contiguïté/inoculation directe (adulte, post-chirurgie/fracture ouverte).","s":13},{"q":"Parmi les COMPLICATIONS d'une fracture, on retrouve :","o":["Pseudarthrose (non-consolidation)","Cal vicieux","Embolie graisseuse","Syndrome de loge","Aucune complication possible"],"r":[0,1,2,3],"e":"Complications : pseudarthrose (>6 mois sans consolidation), cal vicieux (mauvaise position), embolie graisseuse (fracture os longs), syndrome de loge (urgence !), nécrose avasculaire, infection.","s":13},{"q":"Le syndrome de LOGE est :","o":["Une infection osseuse → abcès","Une hausse de pression dans une loge → ischémie","Une fracture multiple → instabilité","Une rupture ligamentaire → instabilité articulaire chronique"],"r":1,"e":"Syndrome de loge : ↑ pression intra-compartimentale (œdème, hématome) → compression vasculo-nerveuse → ischémie musculaire/nerveuse. URGENCE chirurgicale (fasciotomie). Signe : douleur disproportionnée. La loge musculaire est fermée.","s":13},{"q":"Concernant l'ENTORSE :","o":["Une atteinte d'un ligament","Des grades de 1 à 3","Un mouvement forcé en cause","Une localisation fréquente à la cheville","Une fracture de l'os"],"r":[0,1,2,3],"e":"Entorse = atteinte ligamentaire (étirement à rupture). Grades I (bénigne), II (rupture partielle), III (rupture totale ± instabilité). Cheville (LLE) = la plus fréquente. Pas une fracture (concerne l'os). Le grade 1 est un étirement et le grade 3 une rupture complète.","s":13},{"q":"Une LUXATION est :","o":["Une fracture osseuse, près de l'articulation","Une perte de contact totale et permanente","Un simple étirement ligamentaire","Une déchirure musculaire"],"r":1,"e":"Luxation = perte complète et permanente du contact articulaire (subluxation = perte partielle). Articulations souvent touchées : épaule (la +), interphalangienne, hanche prothétique. Elle touche deux surfaces articulaires.","s":13},{"q":"Une CLAQUAGE musculaire correspond à :","o":["Une rupture des fibres musculaires","Une fracture de fatigue","Une luxation articulaire","Un étirement musculaire simple"],"r":0,"e":"Claquage = déchirure (rupture) de fibres musculaires (grade 2). Crampe = contraction involontaire ; courbatures = micro-lésions. Élongation (grade 1) < claquage (grade 2) < rupture (grade 3).","s":13},{"q":"Quels sont les bénéfices de l'activité physique en CHARGE pour l'os ?","o":["Une stimulation du remodelage osseux","Une amélioration de la densité minérale","La prévention de l'ostéoporose","Un meilleur équilibre, avec moins de chutes","Aucun effet mesurable sur les os"],"r":[0,1,2,3],"e":"Activité en charge : stimule le remodelage osseux (loi de Wolff), ↑ DMO, prévient l'ostéoporose, améliore l'équilibre/musculature → ↓ risque de chute et de fracture. C'est la loi de Wolff.","s":13},{"q":"Le score FRAX permet :","o":["Le diagnostic d'une ostéomyélite aiguë de l'enfant","D'estimer le risque de fracture à 10 ans","La mesure de la calcémie sur 24 heures","L'évaluation du risque cardiovasculaire"],"r":1,"e":"FRAX = outil OMS qui calcule le risque de fracture majeure ostéoporotique et de col fémoral à 10 ans, en intégrant ATCD, FdR et DMO (col).","s":13},{"q":"Concernant le rôle du KINÉSITHÉRAPEUTE dans la prise en charge de l'ostéoporose :","o":["Un renforcement musculaire, en charge","Un travail d'équilibre, contre les chutes","Une éducation posturale","Des mobilisations actives","Un massage exclusivement"],"r":[0,1,2,3],"e":"Le kiné a un rôle clé : renforcement (en charge), proprioception/équilibre (chutes), éducation posturale, mobilisations, contre-indications (mouvements en flexion + rotation rachidienne, sauts à risque).","s":13},{"q":"L'ostéomalacie chez l'adulte se distingue de l'ostéoporose par :","o":["Une atteinte de la seule masse osseuse","Un trouble de la minéralisation osseuse","Une infection osseuse, à bacille tuberculeux","Une cause uniquement génétique"],"r":1,"e":"Ostéomalacie = trouble de la MINÉRALISATION (matrice ostéoïde non minéralisée), souvent par carence en vit D. Ostéoporose = ↓ masse osseuse avec minéralisation normale. Symptômes différents : douleurs diffuses pour ostéomalacie. Il est dû à une carence en vitamine D.","s":13},{"q":"L'ostéopénie correspond à :","o":["Une densité osseuse normale","Une baisse modérée de la densité minérale osseuse","Une fracture de fragilité, au poignet","Une infection osseuse, de type ostéite chronique du sujet âgé"],"r":1,"e":"Ostéopénie : T-score entre -1 et -2,5 (perte modérée). Ostéoporose : T-score ≤ -2,5. Le T-score est entre -1 et -2,5.","s":13},{"q":"L'ostéoporose se définit par un T-score :","o":["≥ -1","Entre -1 et -2,5","≤ -2,5","≥ 0"],"r":2,"e":"OMS : Ostéoporose = T-score ≤ -2,5. Ostéoporose sévère : T-score ≤ -2,5 + fracture.","s":13},{"q":"Les facteurs de risque de l'ostéoporose incluent :","o":["La post-ménopause","Un âge avancé","La sédentarité","Une carence en calcium","Une corticothérapie prolongée","Le tabac et l'alcool","Un IMC élevé"],"r":[0,1,2,3,4,5],"e":"Tous : ménopause (chute œstrogènes), âge, sédentarité, malnutrition, corticoïdes, tabac, alcool. Une charge mécanique élevée stimule l'ostéoformation : la maigreur est un facteur de risque, pas le surpoids.","s":13},{"q":"Le DEXA mesure :","o":["La pression artérielle, au bras","La densité minérale de l'os","La masse musculaire seule","Les minéraux du sang"],"r":1,"e":"DEXA (DXA) = absorptiométrie biphotonique à rayons X : examen de référence pour la DMO.","s":13},{"q":"Une fracture pathologique survient :","o":["Sur os sain après traumatisme important","Sur os fragilisé après traumatisme minime","Toujours après chute","Uniquement chez l'enfant"],"r":1,"e":"Fracture pathologique = sur os déjà fragilisé (ostéoporose, métastases) avec traumatisme minime.","s":13},{"q":"La fracture du col du fémur est typique de :","o":["L'enfant, lors des jeux","La personne âgée ostéoporotique","Le sportif jeune, en contact","Le nouveau-né, lors de l'accouchement par le siège"],"r":1,"e":"Fracture col du fémur : très fréquente chez la personne âgée ostéoporotique après chute.","s":13},{"q":"Le traitement de l'ostéoporose inclut souvent :","o":["Des antibiotiques, comme l'amoxicilline orale","Des bisphosphonates, comme l'alendronate","Des bêta-bloquants, comme le propranolol","Des anticoagulants oraux"],"r":1,"e":"Bisphosphonates = inhibent les ostéoclastes → freinent la résorption osseuse.","s":13},{"q":"La consolidation d'une fracture passe par :","o":["Hématome","Cal mou (fibro-cartilagineux)","Cal dur (osseux)","Remodelage","Désintégration"],"r":[0,1,2,3],"e":"4 phases : hématome → cal mou (cartilage/fibres) → cal dur (os primitif) → remodelage (os mature).","s":13},{"q":"L'ostéomalacie chez l'adulte est due à :","o":["Carence en vitamine D","Excès de calcium","Cancer","Infection virale"],"r":0,"e":"Ostéomalacie = défaut de minéralisation par carence en vit D (équivalent du rachitisme chez l'enfant).","s":13},{"q":"Pour prévenir l'ostéoporose, on recommande :","o":["La sédentarité, pour ménager les articulations portantes","L'activité en charge, le calcium et l'arrêt du tabac","Un régime hypercalorique","Aucune mesure particulière"],"r":1,"e":"Prévention : exercice en charge (marche, musculation) + Ca 1000-1200mg/j + vit D + arrêt tabac/alcool. La vitamine D en fait aussi partie.","s":13},{"q":"Quelle est la prévalence mondiale de l'ostéopénie selon la fiche ?","o":["40,4 %","19,7 %","5,6 %","14,4 %"],"r":0,"e":"19,7 % pour l'ostéoporose et 40,4 % pour l'ostéopénie.","s":13},{"q":"Quelle proportion de femmes est touchée après 50 ans ?","o":["3 sur 5","1 sur 5","1 sur 2","4 sur 5"],"r":0,"e":"La fiche indique 3 femmes sur 5 après 50 ans.","s":13},{"q":"Quelle part des cas portugais d'ostéoporose concerne les femmes ?","o":["80,4 %","50 %","19,6 %","95 %"],"r":0,"e":"80,4 % de femmes contre 19,6 % d'hommes, sur 681 000 individus en 2019.","s":13},{"q":"Quelle est la projection du nombre de fractures ostéoporotiques au Portugal en 2034 ?","o":["91 200, soit +28,9 %","70 700, stable","120 000, soit +70 %","50 000, en baisse"],"r":0,"e":"De 70 700 fractures en 2019 à 91 200 projetées en 2034.","s":13},{"q":"Quel est le risque de fracture de hanche chez une femme de plus de 50 ans ?","o":["14,4 %","5,6 %","19,7 %","40,4 %"],"r":0,"e":"La fiche donne 14,4 % de risque vie entière de fracture de hanche.","s":13},{"q":"Par quel mécanisme le tabac altère-t-il l'os ?","o":["Il réduit l'apport sanguin et augmente les radicaux libres","Il inhibe les ostéoblastes par un effet toxique direct","Il gêne l'absorption du calcium, comme le café","Il augmente la PTH, avec une résorption osseuse fortement accrue"],"r":0,"e":"L'alcool inhibe les ostéoblastes et réduit l'absorption du calcium ; le café interfère avec le métabolisme calcique. Il altère aussi l'ostéogenèse.","s":13},{"q":"Pourquoi la chirurgie gastrique constitue-t-elle un facteur de risque ?","o":["Elle diminue le calcium et la vitamine D et augmente la PTH","Elle augmente directement l'activité des ostéoclastes","Elle réduit l'exposition aux contraintes mécaniques, par le repos","Elle abaisse les œstrogènes et la LH"],"r":0,"e":"La malabsorption calcique et vitaminique entraîne une hyperparathyroïdie secondaire.","s":13},{"q":"Quelles causes endocriniennes secondaires d'ostéoporose la fiche cite-t-elle ?","o":["Le diabète de type 1, l'hyperparathyroïdie et les dysthyroïdies","L'insuffisance hépatique et la malabsorption","Les corticostéroïdes et les anticonvulsivants, pris au très long cours","L'immobilisation et l'ostéogenèse imparfaite de type 1"],"r":0,"e":"Les autres réponses appartiennent aux catégories gastro-intestinale/autres et médicamenteuse. La maladie d'Addison, les tumeurs hypophysaires et le myélome multiple en font aussi partie.","s":13},{"q":"Quel médicament la fiche signale-t-elle comme cause secondaire majeure d'ostéoporose ?","o":["Les corticostéroïdes","Le paracétamol","Les bêtabloquants","Les statines"],"r":0,"e":"Les glucocorticoïdes inhibent les ostéoblastes, réduisent la vitamine D et les hormones sexuelles, et activent les ostéoclastes.","s":13},{"q":"Quel antinéoplasique est cité comme facteur de risque en pré-ménopause ?","o":["Le tamoxifène","Le raloxifène","Le dénosumab","Le zolédronate"],"r":0,"e":"Le tamoxifène a un effet osseux défavorable avant la ménopause, contrairement au raloxifène qui est un traitement.","s":13},{"q":"Quelles cytokines augmentent dans l'ostéoporose post-ménopausique ?","o":["IL-1, IL-6 et TNF","IL-4 et IL-13","TGF-β, IL-10 et IL-4","IL-17 seule"],"r":0,"e":"La chute des œstrogènes lève le frein sur ces cytokines, qui stimulent RANK/RANKL et les ostéoclastes.","s":13},{"q":"Quel système de signalisation est surexprimé dans l'ostéoporose post-ménopausique ?","o":["Le système RANK/RANKL","Le système PI3K/AKT","Le système COX-1/COX-2","Le système MMP/TIMP"],"r":0,"e":"L'axe RANK/RANKL commande la différenciation et l'activité des ostéoclastes.","s":13},{"q":"Qu'est-ce qui caractérise l'ostéoporose sénile ?","o":["Un déficit de formation, par des ostéoblastes moins actifs","Une hausse des ostéoclastes, par chute des œstrogènes","Une carence isolée en vitamine D","Une hyperparathyroïdie primaire, d'origine tumorale"],"r":0,"e":"La forme sénile est un déficit de formation, la forme post-ménopausique un excès de résorption. Les cellules ostéoprogénitrices se répliquent aussi moins.","s":13},{"q":"Quel risque supplémentaire les glucocorticoïdes font-ils courir à l'os, outre l'ostéoporose ?","o":["La nécrose avasculaire","L'ostéomalacie","La maladie de Paget","L'ostéomyélite"],"r":0,"e":"La fiche signale ce risque spécifique de l'ostéoporose cortico-induite.","s":13},{"q":"Quel rôle les vitamines K et B12 jouent-elles dans l'os ?","o":["Elles participent à la synthèse des protéines osseuses","Elles augmentent l'absorption intestinale du calcium","Elles durcissent la matrice extracellulaire","Elles inhibent les ostéoclastes"],"r":0,"e":"Leur déficit abaisse la densité osseuse ; l'absorption calcique dépend de la vitamine D.","s":13},{"q":"La POSTURE est définie comme :","o":["Une position figée, prise par le corps au repos","La position relative des segments entre eux et face à la gravité","Un réflexe inné permanent, présent dès la naissance chez tout le monde","Un trouble musculo-squelettique"],"r":1,"e":"Posture = position relative des segments corporels les uns par rapport aux autres ET à la gravité. Elle implique un équilibre tonique entre muscles agonistes et antagonistes.","s":14},{"q":"Concernant les COURBURES RACHIDIENNES, quelles affirmations sont vraies ?","o":["Cyphose dorsale = courbure primaire","Lordose lombaire = courbure secondaire","Lordose cervicale = courbure secondaire","Cyphose sacrée = courbure primaire","Toutes les courbures sont primaires"],"r":[0,1,2,3],"e":"Courbures primaires (présentes à la naissance, à concavité antérieure) : dorsale + sacrée. Secondaires (apparaissent avec la mise en charge, à concavité postérieure) : cervicale (port de tête) + lombaire (marche).","s":14},{"q":"À quel âge apparaît la lordose CERVICALE ?","o":["À la naissance","Quand l'enfant tient sa tête (~3 mois)","Quand l'enfant marche (~12 mois)","À l'adolescence"],"r":1,"e":"La lordose cervicale apparaît vers 3 mois quand le nourrisson commence à tenir sa tête. La lordose lombaire apparaît plus tard, lors de la station debout/marche.","s":14},{"q":"À quel âge apparaît la lordose LOMBAIRE ?","o":["À la naissance","Quand l'enfant tient sa tête (~3 mois)","Quand l'enfant s'assoit (~6-8 mois)","À l'adolescence"],"r":2,"e":"Selon le cours : lordose lombaire apparaît à 6-8 mois (lorsque l'enfant s'assoit). Elle se complète avec la marche (~12-18 mois). La lordose cervicale apparaît à ~3 mois (tenue de tête).","s":14},{"q":"La SCOLIOSE est :","o":["Une courbure normale du rachis","Une déviation du rachis dans les trois plans","Une simple inclinaison latérale, réversible en position couchée","Une fracture vertébrale, par tassement"],"r":1,"e":"Scoliose = déformation 3D du rachis : déviation latérale (frontale) + modification de courbure sagittale + ROTATION vertébrale (gibbosité). Différent de l'attitude scoliotique (réversible, sans rotation). Elle associe une déviation frontale, sagittale et une rotation vertébrale.","s":14},{"q":"Quels signes différencient la SCOLIOSE STRUCTURELLE de l'attitude scoliotique ?","o":["Une rotation vertébrale, avec gibbosité","Une réversibilité en position couchée","Une persistance en flexion antérieure","Une évolutivité possible","Une absence constante de douleur"],"r":[0,2,3],"e":"Scoliose vraie : NON réversible, gibbosité au test d'Adams (flexion ant.), évolutive (surtout durant croissance). Attitude scoliotique : réversible, pas de rotation, sans gibbosité.","s":14},{"q":"Le test d'ADAMS consiste à :","o":["Toucher ses pieds en inclinaison latérale, jambes tendues","Fléchir le patient en avant pour chercher une gibbosité","Mesurer la lordose lombaire","Vérifier l'équilibre debout"],"r":1,"e":"Test d'Adams : patient debout, flexion antérieure du tronc bras pendants. On observe par derrière → recherche d'une GIBBOSITÉ (saillie costale ou paravertébrale signant la rotation vertébrale).","s":14},{"q":"L'angle de COBB permet de :","o":["Mesurer la longueur des membres inférieurs","Mesurer l'angle de la courbure scoliotique","Évaluer la force musculaire du tronc, au dynamomètre","Quantifier la lordose lombaire seule"],"r":1,"e":"Angle de Cobb : mesure radiologique de la courbure scoliotique (frontale). Définit la sévérité : <10° pas de scoliose, 10-25° légère, 25-40° modérée, >40° sévère (chirurgie envisagée). La mesure se fait sur radiographie.","s":14},{"q":"Concernant la SCOLIOSE IDIOPATHIQUE de l'adolescent (SIA) :","o":["Une cause inconnue, idiopathique","Une prédominance féminine","Un risque maximal pendant la puberté","Une douleur toujours présente","Une disparition à l'âge adulte"],"r":[0,1,2],"e":"SIA : étiologie inconnue (idiopathique), prédominance féminine (4-7:1 pour formes évolutives), pic évolutif lors du pic de croissance pubertaire. Souvent INDOLORE chez l'ado. Persiste à l'âge adulte.","s":14},{"q":"Une CYPHOSE pathologique correspond à :","o":["Une courbure cervicale exagérée","Une convexité dorsale accentuée, en dos rond","Une lordose lombaire excessive, avec un bassin en antéversion","Une scoliose sévère, à angle élevé"],"r":1,"e":"Hypercyphose dorsale = accentuation pathologique de la courbure dorsale → 'dos rond'. Causes : posturale, congénitale (Scheuermann), ostéoporose (tassements), ankylosante.","s":14},{"q":"Une HYPERLORDOSE LOMBAIRE est :","o":["Une perte de la courbure lombaire","Une accentuation de la lordose lombaire","Une cyphose cervicale","Une scoliose"],"r":1,"e":"Hyperlordose lombaire = augmentation de la concavité postérieure lombaire (creux du dos accentué). Causes : faiblesse abdominale, antéversion bassin, grossesse, obésité abdominale.","s":14},{"q":"Concernant la maladie de SCHEUERMANN :","o":["Affecte les adolescents","Hypercyphose dorsale rigide","Aspect cunéiforme des vertèbres","Souvent indolore","Toujours d'origine traumatique"],"r":[0,1,2,3],"e":"Scheuermann (cyphose juvénile) : ostéochondrose vertébrale de l'adolescent, hypercyphose dorsale rigide, vertèbres cunéiformes (≥5° d'angulation sur 3 vertèbres consécutives), nodules de Schmorl. Souvent indolore.","s":14},{"q":"Le GENU VARUM correspond à :","o":["Genoux qui se touchent en X","Genoux écartés en O","Genoux normalement alignés","Une luxation patellaire"],"r":1,"e":"Genu varum = jambes en O (genoux écartés). Genu valgum = jambes en X (genoux rapprochés). Physiologique chez nourrisson (varum) puis valgum vers 3-4 ans, normal vers 7 ans.","s":14},{"q":"Le GENU VALGUM correspond à :","o":["Des genoux en O, écartés","Des genoux en X, rapprochés","Une hyperextension du genou","Une hyperflexion du genou"],"r":1,"e":"Genu valgum = genoux qui se touchent (en X), pieds écartés. Physiologique entre 2 et 4 ans, mais pathologique si persistant ou asymétrique chez l'enfant plus grand.","s":14},{"q":"Parmi les facteurs influençant la POSTURE, on retrouve :","o":["Des facteurs anatomiques, comme la structure osseuse","Des facteurs physiologiques, comme le tonus","Des facteurs psychologiques, comme la confiance","Des facteurs pathologiques, comme la douleur","Les habitudes professionnelles","Le groupe sanguin, comme le système ABO et le rhésus"],"r":[0,1,2,3,4],"e":"La posture est influencée par : facteurs anatomiques, physiologiques, psychologiques, pathologiques, habitudes (poste de travail, sports), âge, état émotionnel. Approche multifactorielle. Le groupe sanguin n'a aucune influence connue sur l'organisation posturale.","s":14},{"q":"La LIGNE DE GRAVITÉ idéale (vue latérale) passe par :","o":["L'oreille, l'épaule, le grand trochanter et le genou","Le nez, le sternum et le pubis","La colonne vertébrale uniquement","L'arrière du crâne, le sacrum et les talons, en arrière du corps"],"r":0,"e":"Ligne de gravité idéale (latérale) : conduit auditif externe → acromion → grand trochanter → légèrement en avant du genou → légèrement en avant de la malléole externe. Elle passe aussi juste en avant de la malléole externe.","s":14},{"q":"Une HALLUX VALGUS correspond à :","o":["Une déviation latérale du gros orteil","Une griffe des orteils, en flexion des interphalangiennes","Une fasciite plantaire, au talon","Un pied creux, à voûte haute"],"r":0,"e":"Hallux valgus ('oignon') : déviation latérale (vers le 2e orteil) de la phalange du gros orteil avec saillie médiale de la 1ère articulation métatarso-phalangienne. Plus fréquent chez la femme.","s":14},{"q":"Quelles sont des OSTÉOCHONDROSES juvéniles ?","o":["La maladie d'Osgood-Schlatter","La maladie de Sever","La maladie de Scheuermann","La maladie de Legg-Calvé-Perthes","La polyarthrite rhumatoïde"],"r":[0,1,2,3],"e":"Ostéochondroses juvéniles : Osgood-Schlatter (tubérosité tibiale, ado sportif), Sever (calcanéum), Scheuermann (rachis), Legg-Calvé-Perthes (tête fémorale, garçon 4-8 ans), Köhler (os naviculaire). PR = adulte, auto-immune. Elles touchent la tubérosité tibiale, le calcanéum, le rachis et la tête fémorale.","s":14},{"q":"La maladie d'OSGOOD-SCHLATTER touche :","o":["L'épaule du nageur, par conflit sous-acromial","La tubérosité tibiale, chez l'adolescent sportif","Le rachis lombaire, chez le jeune gymnaste","La tête humérale, chez le lanceur de javelot"],"r":1,"e":"Osgood-Schlatter : ostéochondrose de l'apophyse tibiale antérieure (insertion du tendon rotulien), chez l'adolescent sportif (10-15 ans). Douleur antérieure du genou, aggravée à l'effort. Évolution favorable à la fin de la croissance.","s":14},{"q":"Concernant le PIED PLAT :","o":["Un affaissement de la voûte interne","Un aspect physiologique chez le jeune enfant","Un valgus calcanéen souvent associé","Un caractère toujours pathologique","Une forme souple ou rigide"],"r":[0,1,2,4],"e":"Pied plat = affaissement de l'arche médiale, valgus calcanéen. Physiologique chez le jeune enfant (la voûte se forme vers 5-6 ans). Pathologique si persistant, douloureux ou rigide.","s":14},{"q":"Une POLYDACTYLIE est :","o":["Une absence congénitale d'un ou plusieurs doigts","Un nombre de doigts ou d'orteils supérieur à cinq","Une fusion de deux doigts voisins","Une raideur des doigts"],"r":1,"e":"Polydactylie = présence de doigts/orteils SURNUMÉRAIRES. Syndactylie = fusion entre 2 doigts/orteils. Souvent congénitales, parfois isolées ou syndromiques.","s":14},{"q":"Le port d'un CORSET dans la scoliose vise à :","o":["Corriger définitivement la courbure","Empêcher l'aggravation pendant la croissance","Renforcer les muscles du tronc, par contraction contre la coque","Soulager la douleur uniquement"],"r":1,"e":"Corset (Cheneau, Boston…) : indication pour scoliose 25-40° en croissance. Vise à PRÉVENIR l'aggravation (pas à corriger la courbure existante). Port quotidien long (16-23h/j) jusqu'à fin de croissance.","s":14},{"q":"Concernant le rôle du KINÉSITHÉRAPEUTE dans la scoliose :","o":["Renforcement musculaire global du tronc","Auto-allongements axiaux","Travail postural et proprioceptif","Méthodes spécifiques (Schroth, Méziere)","Réduction de la courbure structurelle à long terme"],"r":[0,1,2,3],"e":"Rôle kiné : renforcement, auto-grandissement, postural, méthodes spécifiques (Schroth, RPG), respiration. Le kiné NE RÉDUIT PAS une scoliose structurelle ; il accompagne, prévient et complète corset/chirurgie.","s":14},{"q":"Une scoliose ≥ 40-45° d'angle de Cobb à la fin de la croissance évoque :","o":["Une surveillance simple","L'indication d'un corset, porté jour et nuit","Une indication chirurgicale, par arthrodèse","Aucune prise en charge"],"r":2,"e":"Scoliose >40-45° : indication chirurgicale (arthrodèse rachidienne avec instrumentation). En dessous : surveillance ou corset selon angle et stade de croissance.","s":14},{"q":"Une scoliose se définit dès une déviation latérale frontale de :","o":["5° ou plus","10° ou plus","25° ou plus","40° ou plus"],"r":1,"e":"Définition de la scoliose : angle de Cobb ≥ 10°. En dessous : attitude scoliotique simple. La sévérité est ensuite graduée par paliers (10-25 légère, 25-40 modérée, >40 sévère). C'est l'angle de Cobb.","s":14},{"q":"La cyphose pathologique correspond à :","o":["Une courbure latérale du rachis","Une exagération de la courbure dorsale","Une exagération de la lordose lombaire, en avant","Une inversion de courbure, au cou"],"r":1,"e":"Cyphose = courbure dorsale (thoracique) postérieure exagérée. Hyperlordose = lombaire. Scoliose = latérale.","s":14},{"q":"Le genu recurvatum correspond à :","o":["Une déviation du genou en dedans dans le plan frontal","Une déviation du genou en dehors dans le plan frontal","Une hyperextension du genou dans le plan sagittal","Une rotation permanente du tibia"],"r":2,"e":"Le recurvatum se lit dans le plan sagittal : le genou dépasse la position neutre en extension. Le varum (jambes arquées) et le valgum (genoux en X) sont, eux, des déviations frontales. Le recurvatum accompagne souvent une hyperlaxité ou un déficit du quadriceps.","s":14},{"q":"L'hyperlordose lombaire est associée à :","o":["Une déformation cervicale, par antéprojection de la tête","Une accentuation de la courbure lombaire","Une cyphose dorsale, en dos rond","Un effondrement vertébral"],"r":1,"e":"Hyperlordose = courbure lombaire concave postérieure exagérée.","s":14},{"q":"La cyphose de la personne âgée est typiquement liée à :","o":["Une croissance excessive","Une scoliose congénitale","Des tassements vertébraux ostéoporotiques","Une posture sportive, maintenue de longues années"],"r":2,"e":"Cyphose dorsale du sujet âgé : tassements vertébraux ostéoporotiques (cunéiformisation).","s":14},{"q":"La maladie de Scheuermann correspond à :","o":["Une scoliose de l'adulte","Une cyphose juvénile, par dystrophie de croissance","Une lordose congénitale, présente dès la naissance","Une infection vertébrale"],"r":1,"e":"Scheuermann = cyphose juvénile (10-16 ans), cunéiformisation antérieure de ≥3 vertèbres adjacentes.","s":14},{"q":"La scoliose idiopathique de l'adolescent :","o":["Est rare, et touche surtout les garçons à la puberté","Est la plus fréquente, surtout chez la fille","Survient dès la naissance","Est toujours douloureuse"],"r":1,"e":"Scoliose idiopathique = forme la plus fréquente, prédominance féminine (4-7:1), pic 10-15 ans.","s":14},{"q":"L'angle de Cobb mesure :","o":["L'amplitude articulaire du rachis","La sévérité de la déformation scoliotique","La force musculaire du tronc","La vitesse de marche, sur dix mètres chronométrés"],"r":1,"e":"Angle de Cobb = mesure de l'angle entre les vertèbres terminales sur radio, sévérité scoliose.","s":14},{"q":"Une scoliose sévère peut entraîner :","o":["Une amélioration spontanée, à l'âge adulte","Une insuffisance respiratoire restrictive","Une augmentation de la taille","Une accélération motrice"],"r":1,"e":"Scoliose sévère (>90°) → restriction thoracique → insuffisance respiratoire restrictive.","s":14},{"q":"Le traitement par corset est indiqué :","o":["Pour toutes les scolioses, quel que soit l'angle de 10 à 90°","Pour les scolioses évolutives de 25 à 40°","Uniquement chez l'adulte, après 20 ans","Jamais, faute d'efficacité"],"r":1,"e":"Corset : indiqué pour scolioses 25-40° pendant la croissance pour ralentir l'évolution. Il s'adresse aux patients en croissance.","s":14},{"q":"La chirurgie est envisagée pour scoliose :","o":["Au-delà de 10°, dès le diagnostic","Au-delà de 20°, en croissance","Au-delà de 45 à 50°, si elle évolue","Jamais, la chirurgie étant inutile"],"r":2,"e":"Chirurgie (arthrodèse) : scoliose ≥ 45-50° évolutive ou très douloureuse.","s":14},{"q":"Combien d'os le squelette perd-il entre la naissance et l'âge adulte ?","o":["94, par fusion osseuse","50, par résorption de l'os","206, soit tous les os","300, par disparition"],"r":0,"e":"Environ 300 os à la naissance contre 206 chez l'adulte, soit 94 de moins par fusion.","s":14},{"q":"Quelles structures relient un os à un autre ?","o":["Les ligaments","Les tendons","Les fascias","Les aponévroses"],"r":0,"e":"Les ligaments relient os à os, les tendons muscle à os.","s":14},{"q":"Pourquoi les malformations de l'appareil locomoteur du jeune enfant sont-elles fréquentes ?","o":["Parce que des ligaments souples subissent des torsions","Parce que les os sont déjà rigides et cassants à la naissance","Parce que les muscles sont trop puissants","Parce que le cartilage de croissance est absent"],"r":0,"e":"La laxité ligamentaire du jeune, combinée aux forces de rotation intra-utérines ou familiales, explique ces anomalies.","s":14},{"q":"Qu'est-ce que la macrodactylie ?","o":["L'hypertrophie d'un ou plusieurs doigts ou orteils","La présence de doigts surnuméraires","La fusion de deux doigts adjacents","L'absence d'un doigt, dès la naissance, par agénésie"],"r":0,"e":"La polydactylie ajoute des doigts, la syndactylie les fusionne.","s":14},{"q":"Qu'est-ce que la syndactylie ?","o":["La fusion de deux doigts ou orteils adjacents","Un doigt surnuméraire, au bord externe de la main","Un doigt hypertrophié","Une déviation latérale du gros orteil"],"r":0,"e":"La syndactylie est une fusion ; la polydactylie et la macrodactylie sont d'autres anomalies digitales. Elle peut être partielle ou complète.","s":14},{"q":"Quel est l'autre nom de l'ostéogenèse imparfaite ?","o":["La maladie des os de verre","La maladie de Legg-Calvé-Perthes","La maladie d'Osgood-Schlatter","La maladie de Scheuermann"],"r":0,"e":"C'est une maladie héréditaire du collagène responsable d'une fragilité osseuse majeure. On l'appelle aussi maladie d'Ekman-Lobstein.","s":14},{"q":"Quel est le mécanisme de la maladie de Legg-Calvé-Perthes ?","o":["Une nécrose de la tête fémorale","Une surcharge du tendon rotulien","Une dystrophie vertébrale de croissance","Une luxation congénitale"],"r":0,"e":"Perthes touche la hanche par nécrose, Osgood-Schlatter le genou par surcharge du tendon rotulien.","s":14},{"q":"Comment la fiche définit-elle une posture correcte ?","o":["Une position économe pour articulations et muscles","Une position bien droite, esthétique de profil","Une position parfaitement symétrique, de face","Une position figée, sans aucun mouvement"],"r":0,"e":"La posture correcte est une posture économe, pas une posture esthétique. Elle exerce le moins de pression possible avec un minimum d'activité musculaire.","s":14},{"q":"Quelles situations articulaires rendent la posture pathogène ?","o":["Des articulations raides ou instables, des muscles faibles","Des articulations parfaitement mobiles, sans aucune restriction","Des muscles équilibrés et souples","Une bonne proprioception, entraînée"],"r":0,"e":"Maintenir la posture coûte alors davantage, générant un stress répété source de pathologie. Les muscles peuvent aussi être étirés ou raccourcis.","s":14},{"q":"Quelles sont les courbures primaires du rachis ?","o":["La cyphose thoracique et la concavité sacro-coccygienne","La lordose cervicale et la lordose lombaire","La lordose cervicale et la cyphose thoracique, dès la naissance","Les courbures frontales, latérales"],"r":0,"e":"Les courbures primaires, concaves en avant, sont présentes dès la naissance ; les secondaires sont des lordoses.","s":14},{"q":"Dans quel sens apparaissent les courbures secondaires ?","o":["Dans le sens céphalo-caudal, cervicale puis lombaire","Dans le sens caudo-céphalique, lombaire puis cervicale","Simultanément, vers un an","De façon aléatoire, selon l'enfant"],"r":0,"e":"Lordose cervicale vers 3 mois, lombaire vers 6-8 mois, en suivant le développement moteur.","s":14},{"q":"À quel acquis moteur correspond l'apparition de la lordose cervicale ?","o":["La tenue de tête en position ventrale","La station assise, sans appui","La marche, vers l'âge d'un an","Le retournement, du dos sur le ventre et inversement"],"r":0,"e":"Le nourrisson soutient sa tête vers 3 mois, ce qui crée la lordose cervicale.","s":14},{"q":"Par quel repère crânien la ligne de gravité idéale passe-t-elle de profil ?","o":["Le conduit auditif externe","Le vertex","L'angle de la mâchoire","La protubérance occipitale externe"],"r":0,"e":"La ligne passe en arrière de la suture coronale, par le conduit auditif externe puis l'odontoïde de C2.","s":14},{"q":"Où passe la ligne de gravité par rapport au genou ?","o":["Légèrement en avant de l'axe du genou","Nettement en arrière du genou","Exactement sur l'axe articulaire","Au niveau du creux poplité"],"r":0,"e":"Elle passe légèrement en avant de l'axe (base de rotule, tête du péroné), puis en avant de la malléole latérale.","s":14},{"q":"Quelle règle s'applique au rachis dans le plan frontal ?","o":["Aucune courbure n'y est normale","Une légère courbure droite y est normale","Une courbure compensatrice est normale","Elles apparaissent vers 3 mois"],"r":0,"e":"C'est ce qui fait de la scoliose une déviation pathologique par définition. Toute déviation latérale est pathologique.","s":14},{"q":"L'arthrose (osteoarthritis) est :","o":["Une maladie auto-immune systémique","Une maladie dégénérative du cartilage hyalin","Une infection articulaire","Un cancer osseux, de l'os sous-chondral, chez le sujet âgé"],"r":1,"e":"Arthrose = maladie articulaire dégénérative caractérisée par la dégradation progressive du cartilage hyalin, avec atteinte de l'os sous-chondral, de la synoviale et des structures péri-articulaires. Composante inflammatoire modérée. Elle comporte aussi une composante inflammatoire.","s":15},{"q":"Le cartilage HYALIN articulaire est constitué essentiellement de :","o":["Des chondrocytes et une matrice de collagène","Des ostéoblastes et de l'os minéralisé","Des fibres élastiques, en réseau très dense","Des cellules sanguines et du plasma"],"r":0,"e":"Cartilage hyalin : chondrocytes (peu nombreux) + matrice extracellulaire riche en collagène de type II et protéoglycanes (agrécane = aggregat avec acide hyaluronique). NON vascularisé, NON innervé. La matrice contient du collagène II et des protéoglycanes.","s":15},{"q":"Le cartilage articulaire est :","o":["Vascularisé, par des capillaires","Dépourvu de vaisseaux","Innervé, donc sensible","Dépourvu de nerfs","Nourri par diffusion du liquide synovial"],"r":[1,3,4],"e":"Le cartilage hyalin est NON vascularisé et NON innervé. Sa nutrition se fait par diffusion à partir du liquide synovial (mouvement = pompe à diffusion). C'est pourquoi sa cicatrisation est très limitée.","s":15},{"q":"Quels sont les principaux FACTEURS DE RISQUE de l'arthrose ?","o":["Un âge avancé","Un surpoids ou une obésité","Des antécédents traumatiques articulaires","Une prédisposition génétique","Une activité physique modérée"],"r":[0,1,2,3],"e":"FdR : âge, sexe féminin, obésité (genou ++), traumatismes (entorse, fracture articulaire), génétique, anomalies axiales (varus, valgus), surcharge professionnelle/sportive intensive. L'activité MODÉRÉE est protectrice.","s":15},{"q":"Le critère DOULEUR dans l'arthrose est typiquement :","o":["Inflammatoire, nocturne avec raideur matinale","Mécanique, déclenchée par l'activité","Permanente, sans relation avec l'activité","Spontanée et fébrile, avec des frissons et des sueurs"],"r":1,"e":"Douleur arthrosique = MÉCANIQUE : ↑ à la mise en charge/activité, ↓ au repos, raideur matinale courte (<15-30 min, dérouillage). PR = douleur inflammatoire (nuit, raideur matinale prolongée). Elle est calmée par le repos.","s":15},{"q":"Quels sont les signes RADIOLOGIQUES de l'arthrose (4 signes classiques) ?","o":["Un pincement de l'interligne","Des ostéophytes marginaux","Une sclérose sous-chondrale","Des géodes sous-chondrales","Des érosions marginales"],"r":[0,1,2,3],"e":"4 signes radiologiques de l'arthrose ('POSG') : Pincement, Ostéophytes, Sclérose sous-chondrale, Géodes (kystes). Les ÉROSIONS sont caractéristiques des polyarthrites inflammatoires (PR).","s":15},{"q":"L'arthrose la plus fréquente du membre inférieur est :","o":["Coxarthrose (hanche)","Gonarthrose (genou)","Arthrose tibio-tarsienne","Arthrose métatarso-phalangienne"],"r":1,"e":"La GONARTHROSE (genou) est la localisation la plus fréquente d'arthrose, devant la coxarthrose (hanche). Souvent fémoro-tibiale interne (varus) ou fémoro-patellaire.","s":15},{"q":"L'arthrose digitale NODALE comprend les nodules de :","o":["Heberden aux IPP et Bouchard aux MCP","Bouchard aux IPD et Heberden aux MCP","Heberden aux IPD et Bouchard aux IPP","Heberden et Bouchard aux MCP"],"r":2,"e":"Nodules d'Heberden = arthrose des IPD (inter-phalangiennes distales). Nodules de Bouchard = IPP (inter-phalangiennes proximales). Pas d'atteinte des MCP en arthrose nodale (sinon évoquer PR).","s":15},{"q":"Concernant le tableau CLINIQUE de l'arthrose :","o":["Une douleur mécanique, à l'effort","Une raideur matinale courte","Une limitation progressive des mouvements","Des crépitements articulaires possibles","Une tuméfaction intense, rouge et chaude"],"r":[0,1,2,3],"e":"Clinique arthrosique : douleur mécanique, raideur matinale brève, ↓ amplitude, crépitements/craquements, parfois épanchement articulaire. Inflammation locale modérée. Rougeur/chaleur intenses = arthrite (à distinguer).","s":15},{"q":"La PRINCIPALE prise en charge de l'arthrose est :","o":["La chirurgie immédiate, par prothèse","L'exercice adapté, la perte de poids et les antalgiques","Les antibiotiques au long cours","Les corticoïdes par voie veineuse, au très long cours"],"r":1,"e":"Prise en charge de 1ère intention : non médicamenteuse (exercice adapté +++, perte de poids, kiné, éducation), puis antalgiques (paracétamol, AINS, infiltrations), enfin chirurgie (PTH/PTG) en dernier recours.","s":15},{"q":"Concernant le RÔLE DU KINÉSITHÉRAPEUTE dans l'arthrose, quelles propositions sont correctes ?","o":["Un renforcement musculaire stabilisateur","Des mobilisations articulaires douces","Des étirements, pour gagner en amplitude","Une éducation à l'économie articulaire","Le remplacement du cartilage perdu"],"r":[0,1,2,3],"e":"Le kiné : renforce (stabilité), mobilise, étire, conseille (économie articulaire, charge, équilibre poids), travaille la proprioception, l'équilibre. Il NE PEUT PAS remplacer le cartilage (régénération limitée).","s":15},{"q":"Le cartilage articulaire a une capacité de RÉGÉNÉRATION :","o":["Très bonne, avec une régénération totale","Bonne, en quelques semaines","Très limitée, faute de vaisseaux","Inexistante, de façon absolue"],"r":2,"e":"Le cartilage régénère TRÈS PEU : pauvre en cellules (chondrocytes), pas de vascularisation. C'est pourquoi les lésions cartilagineuses cicatrisent mal et l'arthrose est chronique et progressive. Il contient aussi peu de cellules.","s":15},{"q":"Les TRAITEMENTS médicamenteux de l'arthrose comprennent :","o":["Le paracétamol","Les AINS, oraux ou topiques","Les infiltrations de corticoïdes","L'acide hyaluronique intra-articulaire","Les antibiotiques au long cours"],"r":[0,1,2,3],"e":"Médicaments : paracétamol (1ère intention), AINS, infiltrations (corticoïdes ou acide hyaluronique = visco-supplémentation). Les antibiotiques n'ont pas leur place (sauf arthrite septique surajoutée).","s":15},{"q":"L'épanchement articulaire dans le genou arthrosique est :","o":["Toujours absent, quel que soit le stade","Possible, souvent modéré, de type mécanique","Massif et purulent, à germes","Toujours hémorragique, rouge"],"r":1,"e":"Épanchement arthrosique = possible, modéré, liquide mécanique (peu cellulaire, jaune citrin). Si très inflammatoire ou purulent → suspecter arthrite septique. Hémarthrose → traumatisme ou trouble de coagulation.","s":15},{"q":"Concernant les MYTHES sur l'arthrose, quels sont des FAUSSES idées ?","o":["L'arthrose touche uniquement les personnes âgées","Le repos absolu est le meilleur traitement","Faire de l'exercice aggrave l'arthrose","La perte de poids améliore les symptômes du genou","La douleur est toujours proportionnelle aux lésions radiologiques"],"r":[0,1,2,4],"e":"FAUX : L'arthrose peut survenir avant 65 ans (post-traumatique). Le repos AGGRAVE (atrophie). L'exercice ADAPTÉ est BÉNÉFIQUE. Perte de poids = vrai bénéfice. La douleur n'est PAS proportionnelle aux images (dissociation radio-clinique fréquente).","s":15},{"q":"Le traitement chirurgical de référence dans l'arthrose AVANCÉE de la hanche/genou est :","o":["L'arthroscopie de lavage","La prothèse totale articulaire","La greffe de cartilage, par mosaïcplastie","La désarticulation du membre"],"r":1,"e":"Arthrose terminale invalidante (échec du traitement médical) → PTH (prothèse totale de hanche) ou PTG (prothèse totale de genou). Arthroscopie = peu d'intérêt prouvé. Greffe cartilagineuse réservée à des indications très spécifiques. C'est la PTH à la hanche et la PTG au genou.","s":15},{"q":"L'OBÉSITÉ est un facteur de risque PARTICULIÈREMENT important pour :","o":["L'arthrose des doigts, nodale","La gonarthrose, au genou","L'arthrose temporo-mandibulaire","L'arthrose lombaire isolée"],"r":1,"e":"L'obésité augmente massivement le risque de gonarthrose (charge mécanique sur le genou). Effet majeur aussi par les adipokines (rôle inflammatoire). La perte de poids améliore significativement la douleur.","s":15},{"q":"L'ARTHROSE PRIMITIVE est :","o":["Toujours secondaire à un traumatisme, comme une fracture","Sans cause identifiable, liée à l'âge","Toujours d'origine génétique pure","D'origine infectieuse, bactérienne"],"r":1,"e":"Arthrose primitive (idiopathique) = pas de cause identifiable, multifactorielle (âge, génétique, hormonale). Arthrose secondaire = liée à une cause précise (traumatisme, malformation, surcharge pondérale, anomalie axiale). Des facteurs intrinsèques y contribuent.","s":15},{"q":"Quels sont des EFFETS du vieillissement sur le cartilage ?","o":["Une baisse de la teneur en eau","Une baisse des protéoglycanes","Une hausse de la rigidité","Une modification du collagène","Plus de chondrocytes en division"],"r":[0,1,2,3],"e":"Vieillissement cartilage : ↓ eau, ↓ protéoglycanes, fibres collagène modifiées, ↑ rigidité, ↓ capacité à supporter les charges. Les chondrocytes deviennent moins actifs (sénescence), ne prolifèrent pas davantage.","s":15},{"q":"Un OSTÉOPHYTE est :","o":["Un kyste osseux sous-chondral, rempli de liquide synovial","Un bec osseux marginal, par prolifération","Une zone de nécrose osseuse","Une calcification ligamentaire"],"r":1,"e":"Ostéophyte (bec, exostose) = production osseuse en périphérie de l'articulation arthrosique. Tentative d'adaptation à la perte de cartilage. Visible à la radiographie, peut limiter les amplitudes.","s":15},{"q":"L'ARTHROSE FÉMORO-PATELLAIRE provoque typiquement :","o":["Une douleur lors de la marche en terrain plat","Une douleur dans les escaliers et assis longtemps","Une douleur uniquement nocturne, au repos","Aucune douleur, seulement une gêne"],"r":1,"e":"Arthrose fémoro-patellaire : douleur antérieure du genou, ↑ aux escaliers (descente +++), accroupissement, station assise prolongée (signe du cinéma/Soulier). Crépitements rotuliens fréquents. C'est le signe du cinéma.","s":15},{"q":"Concernant les CRITÈRES DIAGNOSTIQUES de l'arthrose du genou (ACR), on retrouve :","o":["Douleur du genou","Âge > 50 ans","Raideur matinale < 30 min","Crépitements","Œdème malléolaire"],"r":[0,1,2,3],"e":"Critères ACR gonarthrose : douleur + ≥3 critères parmi (âge >50 ans, raideur matinale <30 min, crépitements, sensibilité osseuse, hypertrophie osseuse, pas de chaleur palpable). Œdème malléolaire = autre cause.","s":15},{"q":"Une INFILTRATION de corticoïdes intra-articulaire dans l'arthrose :","o":["Doit être faite tous les mois, sans limite","Peut soulager une poussée inflammatoire","Régénère le cartilage, en quelques mois de traitement","Est toxique pour l'organisme à dose locale"],"r":1,"e":"Infiltration de corticoïde : effet anti-inflammatoire local lors d'une poussée. Effet temporaire (semaines à mois), à ne pas répéter trop souvent (max 3-4/an). Pas d'effet sur le cartilage. Effet systémique faible à dose locale. Son effet dure quelques semaines.","s":15},{"q":"L'acide HYALURONIQUE intra-articulaire vise à :","o":["Supprimer définitivement l'arthrose","Améliorer la lubrification et l'amortissement","Régénérer l'os sous-chondral, détruit par l'arthrose évoluée","Détruire les ostéophytes marginaux"],"r":1,"e":"Visco-supplémentation par acide hyaluronique : améliore la viscoélasticité du liquide synovial, lubrifie, amortit. Effet symptomatique (semaines à mois). Pas de régénération du cartilage. C'est la visco-supplémentation.","s":15},{"q":"Concernant la PHYSIOPATHOLOGIE de l'arthrose, quelles affirmations sont vraies ?","o":["Un déséquilibre entre dégradation et synthèse","Une activation des chondrocytes et des protéases","Une atteinte secondaire de l'os sous-chondral","Une atteinte primitive de l'os sous-chondral","Une inflammation purement systémique, générale"],"r":[0,1,2],"e":"Arthrose : déséquilibre dégradation (MMP, ADAMTS) > synthèse cartilagineuse, chondrocytes activés (IL-1, TNF), atteinte secondaire de l'os sous-chondral (sclérose, géodes) et de la synoviale (synovite modérée). Atteinte cartilagineuse primaire.","s":15},{"q":"La polyarthrite rhumatoïde (PR) est :","o":["Une maladie dégénérative du cartilage, liée à l'âge","Une maladie auto-immune, chronique et articulaire","Une infection articulaire","Un cancer de la synoviale"],"r":1,"e":"PR = maladie auto-immune chronique, synovite proliférative, destruction articulaire progressive.","s":15},{"q":"Les caractéristiques cliniques de la PR incluent :","o":["Une atteinte symétrique","Une atteinte des mains et des pieds","Une raideur matinale de plus de 30 minutes","Une atteinte des seules grosses articulations","Des déformations en col de cygne"],"r":[0,1,2,4],"e":"PR : symétrique, mains/pieds, raideur matinale prolongée, déformations caractéristiques. L'asymétrie grosses articulations = arthrose ou spondyloarthrites.","s":15},{"q":"Les anticorps caractéristiques de la PR sont :","o":["Le facteur rhumatoïde","Les anticorps anti-CCP","Les anti-ADN natifs","Les ANCA des vascularites","Les anticorps anti-RNP"],"r":[0,1],"e":"PR : FR (peu spécifique) et anti-CCP (très spécifique). Anti-DNA = lupus.","s":15},{"q":"Le lupus érythémateux systémique (LED) :","o":["Une atteinte d'un seul organe, la peau du visage","Une maladie auto-immune touchant plusieurs organes","Une infection bactérienne, à streptocoque","Un cancer, des cellules sanguines"],"r":1,"e":"LED = maladie auto-immune multisystémique : peau, articulations, rein, SNC, séreuses, cellules sanguines.","s":15},{"q":"Le rash en aile de papillon (vespertilio) est typique de :","o":["La PR","Le lupus","L'arthrose","La spondylarthrite"],"r":1,"e":"Érythème en aile de papillon (visage, joues, nez) = signe cutané typique du lupus.","s":15},{"q":"La spondylarthrite ankylosante :","o":["Atteint surtout les femmes âgées, aux mains","Touche surtout l'homme jeune, au rachis","Touche les petites articulations, de façon symétrique","N'a aucun marqueur génétique connu"],"r":1,"e":"SPA : homme jeune, atteinte axiale (sacro-iliite + rachis), HLA-B27 +, raideur inflammatoire. Elle atteint aussi les sacro-iliaques.","s":15},{"q":"L'antigène HLA-B27 est associé à :","o":["La PR, avec les anti-CCP","Les spondyloarthrites, axiales","L'arthrose, liée à l'âge","La goutte, par l'acide urique"],"r":1,"e":"HLA-B27 : association forte avec spondyloarthrites (SPA, Reiter, psoriasis arthropathique, MICI).","s":15},{"q":"La goutte est causée par :","o":["Des dépôts de cristaux d'urate de sodium","Des dépôts de cristaux de calcium","Des auto-anticorps, contre la synoviale","Une infection bactérienne aiguë"],"r":0,"e":"Goutte = dépôt de cristaux d'urate monosodique (UMS) dans les articulations, hyperuricémie.","s":15},{"q":"L'articulation typiquement touchée dans la crise aiguë de goutte est :","o":["Le coude, à la bourse de l'olécrane","La métatarso-phalangienne du gros orteil","La hanche, en coxo-fémorale profonde","Le poignet, au niveau du carpe"],"r":1,"e":"Crise de goutte : podagre = arthrite aiguë de la 1ère MTP du gros orteil, ultra-douloureuse, rouge. C'est la première MTP, ou podagre.","s":15},{"q":"Le traitement de fond de la PR repose sur :","o":["Des antibiotiques, au long cours","Le méthotrexate, avec ou sans biothérapie","Une chirurgie d'emblée, par synovectomie","Aucun traitement de fond"],"r":1,"e":"PR : DMARDs synthétiques (MTX en 1ère ligne) ± biothérapies (anti-TNF, anti-IL-6, etc.). Ce sont les DMARDs ; les biothérapies comprennent les anti-TNF.","s":15},{"q":"Combien de maladies différentes le terme « rhumatisme » recouvre-t-il ?","o":["Plus de 200","Environ 20","Environ 50","Environ 1 000"],"r":0,"e":"La fiche indique plus de 200 maladies, l'arthrose étant la plus fréquente.","s":15},{"q":"Quelles sont les six maladies rhumatismales les plus courantes citées ?","o":["Arthrose, polyarthrite rhumatoïde, lupus, fibromyalgie, goutte et spondylarthrite","Arthrose, ostéoporose, ostéomalacie, Paget, ostéomyélite et arthrite septique","Arthrose, tendinite, bursite, capsulite, entorse et luxation","Arthrose, scoliose, cyphose, lordose, genu varum et genu valgum"],"r":0,"e":"La fiche liste ces six entités comme les plus courantes du groupe rhumatismal.","s":15},{"q":"Combien de personnes l'arthrose touche-t-elle dans le monde ?","o":["Environ 520 millions","Environ 100 millions","Environ 1 milliard","Environ 50 millions"],"r":0,"e":"La fiche donne 520 millions de personnes, avec 60 % de gonarthroses.","s":15},{"q":"Quelle proportion des cas d'arthrose concerne le genou ?","o":["60 %","30 %","90 %","11 %"],"r":0,"e":"La gonarthrose représente 60 % des cas d'arthrose.","s":15},{"q":"De combien le nombre de cas d'arthrose a-t-il augmenté entre 1990 et 2019 ?","o":["+48 %","+10 %","+100 %","Il a diminué"],"r":0,"e":"La fiche indique une progression de 48 % sur cette période.","s":15},{"q":"À quelle place l'arthrose se situe-t-elle parmi les causes mondiales d'incapacité ?","o":["11e","1re","25e","50e"],"r":0,"e":"Sur une étude portant sur 291 conditions, l'arthrose occupe le 11e rang.","s":15},{"q":"Combien d'années vécues avec un handicap l'arthrose a-t-elle représenté en 2017 ?","o":["9,6 millions","520 millions","1 million","100 000"],"r":0,"e":"La fiche cite 9,6 millions d'années vécues avec handicap.","s":15},{"q":"Quels sont les trois grands facteurs de risque d'arthrose retenus par la fiche ?","o":["Le surpoids, les antécédents articulaires et la génétique","Le tabac, l'alcool et le café","La carence en vitamine D, la sédentarité et l'âge","L'infection, l'inflammation chronique et l'auto-immunité systémique"],"r":0,"e":"La cause exacte reste inconnue, mais ces trois facteurs sont identifiés. Les antécédents comprennent les lésions et les chirurgies articulaires.","s":15},{"q":"Quel type de collagène domine dans le cartilage hyalin ?","o":["Le type II, à 95 %","Le type I, à 60 %","Le type III, à 80 %","Le type IV, à 5 %"],"r":0,"e":"Le collagène de type II représente 95 % des fibres du cartilage articulaire.","s":15},{"q":"Quels composants forment la matrice du cartilage hyalin, outre le collagène ?","o":["Des glycosaminoglycanes, des protéines et de l'eau","Des sels d'hydroxyapatite, comme dans l'os","Des fibres élastiques, de la réticuline et de la kératine","Des lipides et du glycogène"],"r":0,"e":"L'eau est un composant principal ; l'hydroxyapatite appartient à l'os. L'eau y est abondante.","s":15},{"q":"Quelle est la première étape du mécanisme lésionnel de l'arthrose ?","o":["Une surcharge mécanique, avec microfractures sous-chondrales","La dérégulation enzymatique, avec des protéases","L'intervention des médiateurs inflammatoires, comme l'IL-1 et le TNF","La mort des chondrocytes, par apoptose"],"r":0,"e":"La fiche décrit une séquence en quatre temps commençant par la surcharge mécanique. L'os sous-chondral se remodèle aussi.","s":15},{"q":"Quelle est l'étape finale du mécanisme lésionnel de l'arthrose ?","o":["Une dérégulation enzymatique qui détruit le collagène","La surcharge mécanique initiale, sur un cartilage sain","Les microfractures de l'os sous-chondral","La mort des chondrocytes, par apoptose"],"r":0,"e":"La destruction enzymatique du collagène clôture la cascade. La matrice est aussi altérée.","s":15},{"q":"Quel âge figure parmi les critères de diagnostic clinique de l'arthrose ?","o":["45 ans ou plus","50 ans ou plus","65 ans ou plus","30 ans ou plus"],"r":0,"e":"45 ans, avec douleur liée à l'activité et raideur matinale absente ou inférieure à 30 minutes ; un diagnostic reste possible plus jeune après traumatisme.","s":15},{"q":"Quelle durée maximale de raideur matinale est compatible avec le diagnostic d'arthrose ?","o":["Moins de 30 minutes","Moins de 2 heures","Moins de 5 minutes","La raideur matinale exclut l'arthrose"],"r":0,"e":"Une raideur matinale prolongée oriente plutôt vers un rhumatisme inflammatoire.","s":15},{"q":"Que traduit une sclérose sous-chondrale sur une radiographie ?","o":["Une condensation de l'os sous-chondral","Une prolifération osseuse marginale","Une réduction de l'espace articulaire","Une géode osseuse"],"r":0,"e":"Les quatre signes radiologiques sont le pincement, les ostéophytes, la sclérose et les kystes sous-chondraux.","s":15},{"q":"La RÉGÉNÉRATION tissulaire correspond à :","o":["Le remplacement par un tissu fibreux cicatriciel","Le remplacement à l'identique du tissu lésé","Une mort cellulaire programmée, par apoptose étendue","Une fibrose excessive, avec rétraction"],"r":1,"e":"Régénération = remplacement à l'identique du tissu lésé (restitution ad integrum). Possible pour les tissus à fort potentiel prolifératif (labiles, stables). La cicatrisation = remplacement par tissu fibreux.","s":16},{"q":"La CICATRISATION tissulaire correspond à :","o":["Le remplacement à l'identique du tissu lésé","Le remplacement par un tissu conjonctif fibreux","Une infection chronique de la plaie","Un cancer, développé sur la plaie"],"r":1,"e":"Cicatrisation = remplacement par tissu conjonctif fibreux (collagène) lorsque la régénération est insuffisante ou impossible. Survient quand l'agression est sévère ou que le tissu est à faible potentiel régénératif.","s":16},{"q":"Concernant les CELLULES LABILES :","o":["Se renouvellent en permanence","Exemples : épithéliums, moelle hématopoïétique","Capacité régénérative très bonne","Exemples : neurones, cardiomyocytes","Cellules en G0 quiescentes"],"r":[0,1,2],"e":"Cellules labiles : renouvellement permanent (cycle continu) → épiderme, épithélium digestif, moelle, gamètes. Excellente régénération. Les neurones/cardiomyocytes = cellules permanentes (post-mitotiques).","s":16},{"q":"Concernant les CELLULES STABLES :","o":["Elles sont quiescentes, en G0","Elles se divisent sur stimulation","Ce sont les cellules du foie et du rein","Ce sont les cardiomyocytes","Elles permettent une régénération"],"r":[0,1,2,4],"e":"Cellules stables : quiescentes (G0), prolifèrent si stimulus (lésion). Foie, rein, glandes endocrines, endothélium, fibroblastes. Le foie a une remarquable capacité de régénération. Cardiomyocytes = permanents.","s":16},{"q":"Les CELLULES PERMANENTES :","o":["Se renouvellent en permanence","Ne se divisent plus chez l'adulte","Sont identiques aux cellules labiles","Régénèrent facilement après une lésion, en quelques jours"],"r":1,"e":"Cellules permanentes : post-mitotiques, ne se divisent plus chez l'adulte. Neurones, cardiomyocytes, myocytes squelettiques. Lésion → cicatrisation par tissu fibreux (gliose pour SNC, cicatrice fibreuse pour le cœur). Ce sont par exemple les neurones et les cardiomyocytes.","s":16},{"q":"Quelles sont les ÉTAPES classiques de la cicatrisation cutanée ?","o":["D'abord, l'hémostase et le caillot","Ensuite, l'inflammation","Puis la prolifération, avec le bourgeon charnu","Enfin, le remodelage du collagène","Une métaplasie, toujours obligatoire"],"r":[0,1,2,3],"e":"4 étapes de la cicatrisation : 1) hémostase (clou plaquettaire, coagulation) → 2) inflammation (PNN, macrophages) → 3) prolifération (fibroblastes, angiogenèse, tissu de granulation) → 4) remodelage (maturation collagène). La métaplasie n'est PAS une étape normale.","s":16},{"q":"Concernant le tissu de GRANULATION (bourgeon charnu) :","o":["Il apparaît en phase proliférative","Il associe néovaisseaux et fibroblastes","Il a un aspect rouge framboise","Il marque la cicatrisation de 2e intention","Il n'est fait que de collagène mature"],"r":[0,1,2,3],"e":"Bourgeon charnu : apparaît en phase proliférative, mélange de néovaisseaux, fibroblastes (myofibroblastes), matrice (collagène jeune type III), cellules inflammatoires. Aspect rouge granulaire. Sera remodelé en cicatrice mature.","s":16},{"q":"La cicatrisation par PREMIÈRE INTENTION concerne :","o":["Les plaies à bords nets, sans grande perte","Les plaies infectées, avec une perte importante","Les brûlures profondes","Les plaies chroniques, comme l'ulcère"],"r":0,"e":"1ère intention : plaies bords nets, rapprochés (sutures chirurgicales), peu de perte de substance → cicatrice fine et rapide. 2e intention : plaies béantes, perte de substance → bourgeon charnu, cicatrice large.","s":16},{"q":"La cicatrisation par DEUXIÈME INTENTION :","o":["Concerne les plaies suturées, bord à bord","Implique un bourgeon charnu volumineux","Donne une cicatrice toujours invisible, même sur une grande plaie","Est plus rapide que la première intention"],"r":1,"e":"2e intention : plaie béante avec perte de substance importante → bourgeon charnu volumineux, comblement progressif, contraction des berges, cicatrice plus large et plus longue. Plus risquée (infection, fibrose excessive).","s":16},{"q":"Quels FACTEURS EXTRINSÈQUES retardent la cicatrisation ?","o":["Infection","Corps étranger","Déshydratation de la plaie","Mobilisation excessive","Tabac","Le diabète"],"r":[0,1,2,3,4],"e":"Facteurs extrinsèques : infection, corps étranger, déshydratation, mobilité excessive de la plaie, tabac (vasoconstriction), traumatisme répété, mauvaise hygiène. Tous retardent la cicatrisation. Le diabète est un facteur intrinsèque, lié au terrain du patient et non à l'environnement de la plaie.","s":16},{"q":"Quels FACTEURS INTRINSÈQUES retardent la cicatrisation ?","o":["Le diabète, par hyperglycémie chronique","Les carences en protéines et en vitamines","Un âge avancé du patient","Une anémie ou une hypoxie","Une corticothérapie au long cours","Un corps étranger dans la plaie"],"r":[0,1,2,3,4],"e":"Facteurs intrinsèques : diabète, malnutrition (protéines, Vit C/A, zinc), âge, anémie, hypoxie, corticothérapie (↓ inflammation utile, ↓ collagène), immunosuppresseurs, maladies chroniques. Un corps étranger est un facteur extrinsèque : il vient du milieu, pas du terrain du patient. Le zinc et la vitamine A comptent aussi.","s":16},{"q":"Une CHÉLOÏDE est :","o":["Une cicatrice fine et discrète","Une cicatrice hypertrophique qui déborde la plaie","Une absence de cicatrice, par régénération complète du derme","Une infection de la cicatrice"],"r":1,"e":"Chéloïde : cicatrice exubérante qui DÉBORDE les limites de la plaie d'origine, par excès de production de collagène. Plus fréquente sur peaux foncées, en zones spécifiques (sternum, épaule, lobes d'oreille).","s":16},{"q":"Une cicatrice HYPERTROPHIQUE se distingue d'une chéloïde par :","o":["Elle dépasse les limites de la plaie, en s'étendant","Elle reste limitée à la plaie, bien qu'épaisse","Elle disparaît d'elle-même en quelques jours","Elle ne saigne jamais au contact"],"r":1,"e":"Hypertrophique : épaisse, rouge, mais limitée aux contours de la plaie. Chéloïde : déborde les limites. Hypertrophique tend à régresser dans le temps ; chéloïde persiste, voire s'étend. Elle est aussi rouge.","s":16},{"q":"Concernant le COLLAGÈNE de cicatrisation :","o":["Le type III, immature, domine au début","Le type I, mature, domine en fin de remodelage","La cicatrice n'atteint jamais 100 % de résistance","Le remodelage peut durer jusqu'à un an","Il ne change pas au cours du temps"],"r":[0,1,2,3],"e":"Cicatrisation : phase proliférative = collagène III (jeune, désorganisé) → remodelage = collagène I (mature, organisé). La cicatrice atteint ~80% de la résistance du tissu sain au mieux. Remodelage ~6-12 mois. Elle plafonne vers 70 à 80 % de la résistance d'origine.","s":16},{"q":"Le rôle du MYOFIBROBLASTE est :","o":["Synthétiser du collagène uniquement, sans jamais se contracter","Produire du collagène et contracter la plaie","Phagocyter les débris de la plaie","Produire des anticorps locaux"],"r":1,"e":"Myofibroblaste = fibroblaste différencié exprimant l'α-actine musculaire lisse. Synthétise le collagène ET contracte → rapprochement des berges (contraction de la plaie) durant la phase proliférative. Il combine les fonctions de fibroblaste et de cellule musculaire lisse.","s":16},{"q":"Quels sont des MODES DE COMMUNICATION cellulaire impliqués dans la réparation ?","o":["Autocrine, sur la cellule elle-même","Paracrine, sur les cellules voisines","Endocrine, à distance par le sang","Synaptique, entre cellules nerveuses","Aucune, les cellules restant isolées"],"r":[0,1,2,3],"e":"Modes : autocrine (la cellule sur elle-même), paracrine (voisinage, ex : facteurs de croissance), endocrine (à distance, hormones), juxtacrine (contact direct), synaptique (neurones). Tous interviennent dans la réparation.","s":16},{"q":"Parmi les FACTEURS DE CROISSANCE impliqués dans la réparation, on trouve :","o":["Le PDGF, d'origine plaquettaire","Le FGF, des fibroblastes","Le TGF-β, transformant","Le VEGF, vasculaire","L'ATP, mitochondrial"],"r":[0,1,2,3],"e":"Facteurs de croissance : PDGF (plaquettes, recrute fibroblastes), FGF (prolifération), TGF-β (production de collagène, fibrose), VEGF (angiogenèse), EGF, IGF. ATP n'est pas un facteur de croissance mais une source d'énergie.","s":16},{"q":"L'ANGIOGENÈSE durant la cicatrisation est :","o":["Inutile, le tissu se nourrissant par simple diffusion","Indispensable pour apporter oxygène et nutriments","Pathologique, et donc à freiner par un traitement","Délétère, par excès de vaisseaux"],"r":1,"e":"L'angiogenèse (formation de nouveaux vaisseaux à partir de vaisseaux existants) est CRUCIALE : apporte O₂ et nutriments, permet la migration cellulaire, stimule la prolifération. Médiée par VEGF, FGF.","s":16},{"q":"Concernant le BOURGEON CHARNU pathologique (excessif) :","o":["Un aspect framboisé exubérant","Un saignement facile","Un retard d'épithélialisation","Un traitement par nitrate d'argent","Un caractère toujours inoffensif"],"r":[0,1,2,3],"e":"Bourgeonnement excessif : framboisé, fragile, saignant, déborde de la plaie, retarde l'épithélialisation (les kératinocytes ne peuvent pas migrer). Tx : nitrate d'argent, corticoïdes locaux, ablation chirurgicale.","s":16},{"q":"L'ÉPITHÉLIALISATION d'une plaie cutanée se fait :","o":["Par migration de kératinocytes des berges","Par division des cellules fibroblastiques","Par migration des macrophages","Par formation de tissu osseux"],"r":0,"e":"Épithélialisation : kératinocytes des berges (et des annexes pilo-sébacées) prolifèrent et migrent pour recouvrir la plaie. Nécessite un lit de plaie propre, humide, sans infection.","s":16},{"q":"La CONTRACTION de la plaie est due principalement à :","o":["Aux fibroblastes seuls","Aux myofibroblastes, contractiles","Aux polynucléaires neutrophiles","Aux mastocytes, du derme"],"r":1,"e":"La contraction de la plaie (réduction de la surface) est due à l'action contractile des myofibroblastes (fibroblastes exprimant l'α-actine de muscle lisse). Très importante pour les plaies de 2e intention.","s":16},{"q":"Concernant les CICATRICES PATHOLOGIQUES (anomalies) :","o":["Cicatrice hypertrophique","Cicatrice chéloïde","Cicatrice atrophique (déprimée)","Cicatrice rétractile (limitant le mouvement)","Cicatrice toujours esthétique"],"r":[0,1,2,3],"e":"Anomalies cicatricielles : hypertrophique (limitée), chéloïde (déborde), atrophique (déprimée, ex : varicelle, acné), rétractile (limite la mobilité, ex : brûlures). Toutes peuvent altérer la fonction et l'esthétique.","s":16},{"q":"L'ÉCHEC complet de cicatrisation aboutit à :","o":["Une cicatrice normale, plane et souple","Une plaie chronique, comme un ulcère","Une régénération parfaite","Une chéloïde, dans tous les cas"],"r":1,"e":"Échec de cicatrisation = plaie chronique (>4-6 semaines sans cicatrisation). Exemples : ulcères veineux/artériels/diabétiques, escarres. Causes multiples : infection, ischémie, diabète, malnutrition.","s":16},{"q":"La cicatrisation OPTIMALE nécessite un environnement :","o":["Sec","Humide et chaud","Stérile glacial","Acide"],"r":1,"e":"Cicatrisation idéale : milieu HUMIDE et chaud (favorise la migration cellulaire, l'angiogenèse, et limite la formation de croûtes qui ralentissent). Principe des pansements modernes (hydrocolloïdes, hydrogels).","s":16},{"q":"La FIBROSE EXCESSIVE post-cicatricielle peut entraîner :","o":["Une amélioration fonctionnelle","Une perte de fonction, par rétraction","Une régénération améliorée","Aucune conséquence, la fibrose étant toujours bénéfique"],"r":1,"e":"Fibrose excessive : remplace le tissu fonctionnel → perte de fonction. Ex : cirrhose hépatique (hépatocytes → fibrose), fibrose pulmonaire (alvéoles → fibrose), rétractions cutanées post-brûlures. Ankylose et organe non fonctionnel en sont d'autres formes.","s":16},{"q":"La cicatrisation de TROISIÈME intention correspond à :","o":["Une plaie suturée bord à bord, en première intention","Une plaie laissée ouverte, avec bourgeon charnu","Une correction chirurgicale après la granulation","Une cicatrisation chéloïdienne automatique, sans aucune intervention"],"r":2,"e":"3 types de cicatrisation : 1ère intention (plaie nette suturée) ; 2ème intention (perte de substance, bourgeon charnu, contraction) ; 3ème intention (suture différée après formation du tissu de granulation, ex : plaies infectées initialement laissées ouvertes puis suturées secondairement). Elle vise de meilleurs résultats fonctionnels et esthétiques.","s":16},{"q":"Les phases de la cicatrisation d'une plaie sont :","o":["L'hémostase","L'inflammation","La prolifération","Le remodelage","La calcification"],"r":[0,1,2,3],"e":"4 phases : hémostase (caillot) → inflammation → prolifération → remodelage. La prolifération comprend la granulation et la ré-épithélialisation.","s":16},{"q":"L'angiogenèse est :","o":["La formation de vaisseaux à partir des existants","La destruction des vaisseaux lésés et bouchés","Une fonction de détoxification hépatique","Une mort cellulaire, par ischémie"],"r":0,"e":"Angiogenèse = formation de nouveaux vaisseaux (essentielle pour la cicatrisation, induite par VEGF).","s":16},{"q":"Le tissu de granulation est :","o":["Du pus, fait de neutrophiles","Un tissu conjonctif très vascularisé, comblant la plaie","Une cicatrice mature, blanche et riche en collagène de type I","Un os néoformé, dans la plaie"],"r":1,"e":"Granulation = tissu jeune, rouge, vascularisé (capillaires + fibroblastes + matrice), précurseur de la cicatrice.","s":16},{"q":"Les fibroblastes synthétisent :","o":["Des anticorps, contre les germes de la plaie","Du collagène et de la matrice extracellulaire","De l'insuline, pour la cicatrisation","Des hormones stéroïdes, locales"],"r":1,"e":"Fibroblastes = synthèse collagène, élastine, glycosaminoglycanes ; clés du remodelage.","s":16},{"q":"Le collagène prédominant dans la peau cicatricielle initiale est :","o":["Le type I, mature","Le type III, ensuite remplacé par le I","Le type IV, des membranes basales","Le type V, mineur"],"r":1,"e":"Collagène III déposé d'abord, puis remplacé progressivement par le collagène I (résistance) lors du remodelage.","s":16},{"q":"La cicatrisation par seconde intention concerne :","o":["Les plaies suturées propres","Les plaies béantes, comblées par granulation","Les brûlures superficielles uniquement","Les petites coupures, refermées en quelques heures sans soin"],"r":1,"e":"Seconde intention : plaie ouverte, comblement par granulation, ré-épithélialisation depuis les bords. Cicatrice plus large. Il y a une perte de substance.","s":16},{"q":"Les facteurs locaux retardant la cicatrisation incluent :","o":["Infection","Ischémie locale","Présence de corps étrangers","Mauvaise apposition des berges","Bonne irrigation"],"r":[0,1,2,3],"e":"Locaux : infection, ischémie, corps étrangers, bords mal rapprochés, hématome, exposition aux UV.","s":16},{"q":"Les facteurs systémiques retardant la cicatrisation incluent :","o":["Diabète","Corticothérapie","Carence nutritionnelle","Tabagisme","Âge avancé","Sport"],"r":[0,1,2,3,4],"e":"Systémiques : diabète, corticoïdes, dénutrition, tabac, âge, immunodépression. Le sport modéré aide.","s":16},{"q":"Une chéloïde se distingue d'une cicatrice hypertrophique par :","o":["Aucune différence nette","Elle dépasse les limites initiales de la plaie","Elle est moins épaisse et moins rouge","Elle disparaît seule, en quelques mois de massage"],"r":1,"e":"Chéloïde déborde la plaie (formation excessive collagène). Cicatrice hypertrophique reste dans les limites.","s":16},{"q":"L'escarre (ulcère de pression) est due à :","o":["Une infection → nécrose infectieuse","Une compression prolongée → ischémie","Un traumatisme → hématome profond","Une brûlure → phlyctène, par contact avec une surface chaude"],"r":1,"e":"Escarre = lésion ischémique par compression prolongée (alité, fauteuil) sur saillies osseuses (sacrum, talons). Elle touche les tissus mous sur les saillies osseuses.","s":16},{"q":"De quoi dépend le choix entre régénération et cicatrisation ?","o":["Du type de tissu, du type cellulaire et de l'étendue","Uniquement de l'âge du patient","Uniquement de la localisation anatomique, profonde ou superficielle","Uniquement de la présence d'une infection"],"r":0,"e":"Les deux mécanismes peuvent d'ailleurs coexister dans un même tissu. L'étendue de la lésion est déterminante.","s":16},{"q":"Quels épithéliums font partie des cellules labiles ?","o":["La peau, la bouche et le tube digestif","Les hépatocytes et les cellules rénales","Les neurones et les cardiomyocytes","Les muscles lisses, les fibroblastes"],"r":0,"e":"Les cellules labiles se divisent en permanence ; les hépatocytes et fibroblastes sont stables. Le vagin, le col utérin et l'épithélium urinaire de transition en font aussi partie.","s":16},{"q":"Dans quelle phase du cycle cellulaire les cellules stables se trouvent-elles normalement ?","o":["En phase G0, quiescentes","En phase G2, avant la mitose","En phase S, en réplication","Hors du cycle, définitivement"],"r":0,"e":"Les cellules stables sortent du cycle mais peuvent y rentrer si un stimulus approprié survient.","s":16},{"q":"Quelles cellules la fiche classe-t-elle parmi les cellules stables ?","o":["Les hépatocytes, les cellules rénales et les fibroblastes","Les cellules de la moelle osseuse, en division continue et rapide","Les neurones et les cardiomyocytes","L'épithélium de transition urinaire"],"r":0,"e":"Moelle osseuse et épithélium urinaire sont labiles ; neurones et cardiomyocytes sont permanents. Les muscles lisses et l'endothélium vasculaire en font aussi partie.","s":16},{"q":"Qu'est-ce que l'inhibition par contact ?","o":["Un arrêt de la prolifération quand les cellules se touchent","Une stimulation de la prolifération par le contact","Un blocage de la migration des fibroblastes","Une inhibition de l'angiogenèse, par contact des vaisseaux entre eux"],"r":0,"e":"Ce stimulus négatif évite la formation de néoplasmes ; sa défaillance est en cause dans la chéloïde.","s":16},{"q":"Quelles conditions sont nécessaires à la régénération ?","o":["Une matrice intacte et des signaux de facteurs de croissance","Une matrice extracellulaire détruite","Une inflammation persistante","La présence de myofibroblastes, en grand nombre et bien actifs"],"r":0,"e":"Sans matrice intacte, la réparation ne peut se faire que par cicatrisation. La maturation cellulaire et le contrôle du cycle sont aussi nécessaires.","s":16},{"q":"Qu'est-ce qu'une libération autocrine de facteur de croissance ?","o":["La cellule produit son propre facteur de croissance","Des cellules voisines libèrent le facteur","Le facteur est transporté par le sang","Le facteur est libéré dans la matrice extracellulaire uniquement"],"r":0,"e":"La voie paracrine part des cellules voisines, la voie endocrine de la circulation.","s":16},{"q":"Quel est le stimulateur le plus important de l'angiogenèse ?","o":["Le VEGF","Le PDGF","L'EGF","Le TGF-β"],"r":0,"e":"Le VEGF agit sur les cellules endothéliales ; le FGF et l'EGF y contribuent aussi mais moins spécifiquement.","s":16},{"q":"Quelles actions le PDGF exerce-t-il ?","o":["Attirer les macrophages et faire proliférer les fibroblastes","Inhiber les cellules épithéliales, à la manière du TGF-β","Assurer seul l'angiogenèse, à la place du VEGF","Produire des interleukines"],"r":0,"e":"Le TGF-β, lui, inhibe les cellules épithéliales tout en stimulant les fibroblastes. Il fait aussi proliférer les cellules épithéliales et musculaires lisses.","s":16},{"q":"Quel rôle les interleukines jouent-elles dans la réparation ?","o":["Elles font proliférer et attirent les fibroblastes","Elles inhibent l'angiogenèse","Elles dégradent le collagène","Elles assurent l'inhibition de contact entre les cellules voisines"],"r":0,"e":"Libérées par les cellules inflammatoires, elles recrutent et activent les fibroblastes.","s":16},{"q":"Quelles cellules dominent la première vague de la phase inflammatoire ?","o":["Les neutrophiles","Les macrophages","Les fibroblastes","Les myofibroblastes"],"r":0,"e":"Les neutrophiles nettoient, puis les macrophages produisent les facteurs de croissance essentiels.","s":16},{"q":"Quelles molécules dominent la matrice entre J0 et J4 ?","o":["La fibronectine et le collagène III","Le collagène I, mature et très résistant","Le collagène IV, des membranes","Les protéoglycanes seuls"],"r":0,"e":"Le collagène I monte de J6 à J12 et devient dominant au-delà de J12.","s":16},{"q":"Quelle est la dernière étape de la phase proliférative ?","o":["La prolifération épithéliale en surface","La migration des fibroblastes","L'angiogenèse, dans la plaie","La formation du caillot de fibrine, avec les plaquettes"],"r":0,"e":"La réépithélialisation clôt la phase proliférative, après la granulation.","s":16},{"q":"Quelle est la durée approximative de la phase de remodelage ?","o":["De la 3e semaine à 6 mois et au-delà","De J0 à J4, au cours de la phase inflammatoire","De J4 à la 3e semaine","Moins d'une semaine"],"r":0,"e":"Inflammatoire J0-J4, proliférative J4-3 semaines, remodelage à partir de 3 semaines.","s":16},{"q":"La SEPSIE (sepsis) est définie comme :","o":["Une infection localisée, sans gravité","Une infection avec dysfonction d'organes menaçant la vie","Une bactériémie isolée, sans aucun symptôme","Une simple fièvre, au-delà de 38 °C, sans autre signe associé"],"r":1,"e":"Sepsis (Sepsis-3) = dysfonction d'organes potentiellement létale due à une réponse DYSRÉGULÉE de l'hôte à une infection. Plus grave que l'infection simple, moins que le choc septique. Elle résulte d'une réponse dysrégulée de l'hôte.","s":17},{"q":"Le CHOC SEPTIQUE est :","o":["Une infection sans aucun retentissement","Un sepsis avec hypotension persistante sous vasopresseurs","Une simple fièvre, au-delà de 38 °C","Une infection urinaire bactérienne, à colibacille, chez la femme"],"r":1,"e":"Choc septique = sepsis avec hypotension persistante nécessitant amines vasopressives pour maintenir PAM ≥65 mmHg + lactates >2 mmol/L malgré remplissage adéquat. Mortalité élevée (>40%). Les lactates dépassent 2 mmol/L malgré le remplissage.","s":17},{"q":"Concernant le CONTINUUM INFECTION → CHOC SEPTIQUE :","o":["Une infection localisée, puis une bactériémie","Un sepsis, avec dysfonction d'organes","Un choc septique, hypotension réfractaire","Une défaillance multi-organique possible","Une régression spontanée, toujours garantie"],"r":[0,1,2,3],"e":"Continuum : infection → bactériémie → sepsis → choc septique → MODS (défaillance multi-organique) → décès. Aggravation progressive si non traité, mortalité croissante.","s":17},{"q":"Le CHOC se définit par :","o":["Une augmentation brutale de la pression artérielle","Une insuffisance circulatoire aiguë, avec hypoxie","Une fièvre élevée isolée","Une douleur intense, aiguë"],"r":1,"e":"Choc = défaillance circulatoire aiguë → ↓ perfusion tissulaire → hypoxie cellulaire → métabolisme anaérobie → acidose lactique → dysfonction d'organes. Urgence vitale absolue. La perfusion tissulaire est insuffisante.","s":17},{"q":"Quels sont les TYPES DE CHOC ?","o":["Le choc hypovolémique","Le choc cardiogénique","Le choc obstructif","Le choc distributif","Le choc artérithérapique"],"r":[0,1,2,3],"e":"4 types principaux : hypovolémique (perte volémique : hémorragie, brûlure), cardiogénique (défaillance pompe : IDM), obstructif (obstacle au remplissage : EP, tamponnade, pneumothorax), distributif (vasodilatation : sepsis, anaphylaxie, neurogénique). Le choc distributif peut être septique, anaphylactique ou neurogénique.","s":17},{"q":"Le choc HYPOVOLÉMIQUE est typiquement causé par :","o":["Une infection grave, avec vasodilatation diffuse","Une perte de volume circulant, par hémorragie","Une défaillance de la pompe cardiaque","Une réaction allergique massive"],"r":1,"e":"Choc hypovolémique = ↓ volume sanguin circulant : hémorragie (intra/extra-corporelle), brûlures étendues, déshydratation sévère, 3e secteur (péritonite). Tx = REMPLISSAGE rapide. Brûlures et déshydratation en sont d'autres causes.","s":17},{"q":"Le choc ANAPHYLACTIQUE est :","o":["Un choc cardiogénique, par défaillance du ventricule gauche","Un choc distributif, avec vasodilatation massive","Un choc hypovolémique, par hémorragie","Un choc obstructif, par embolie"],"r":1,"e":"Choc anaphylactique = choc distributif d'origine immunoallergique. Histamine massive → vasodilatation, ↑ perméabilité, bronchoconstriction. Tx urgence = ADRÉNALINE IM (cuisse) + remplissage + corticoïdes/antihistaminiques. Il est allergique et s'accompagne d'une bronchoconstriction.","s":17},{"q":"Concernant le CHOC CARDIOGÉNIQUE :","o":["Une défaillance de la pompe cardiaque","Un infarctus du myocarde, cause typique","Un débit bas malgré un remplissage normal","Une hypoxie tissulaire","Une évolution bénigne, sans séquelle"],"r":[0,1,2,3],"e":"Choc cardiogénique : défaillance ventriculaire (IDM, myocardite, arythmies, valvulopathies). Mortalité élevée. Tx = inotropes, support mécanique (BCPIA, ECMO), revascularisation.","s":17},{"q":"Une CIVD (Coagulation Intra-Vasculaire Disséminée) :","o":["Des microthrombi diffus → épuisement des facteurs","Une absence totale de saignement","Une forme bénigne → guérison sans traitement en quelques jours","Une coagulation améliorée → protection"],"r":0,"e":"CIVD : activation diffuse de la coagulation → microthrombi → consommation des facteurs et plaquettes → SAIGNEMENTS paradoxaux. Complication majeure du sepsis. Diagnostic : ↓ plaquettes, ↑ D-dimères, ↓ fibrinogène, ↑ TP/TCA. L'épuisement des facteurs entraîne des saignements.","s":17},{"q":"Le SDRA / ARDS / 'poumon de choc' correspond à :","o":["Un poumon hyperventilé, physiologique","Une atteinte alvéolo-capillaire → œdème → hypoxémie","Une infection bronchique simple","Une tumeur pulmonaire → obstruction → atélectasie lobaire"],"r":1,"e":"SDRA (Syndrome de détresse respiratoire aiguë) : lésion alvéolo-capillaire diffuse → œdème lésionnel non cardiogénique → hypoxémie réfractaire (PaO2/FiO2 ≤300). Complication majeure du sepsis. Tx = ventilation protectrice. L'œdème est non cardiogénique et l'hypoxémie sévère.","s":17},{"q":"Concernant l'INSUFFISANCE RÉNALE AIGUË (IRA) lors du choc :","o":["Une nécrose tubulaire aiguë, souvent","Une baisse de la diurèse","Une hausse de la créatinine","Une réversibilité si le traitement est précoce","Une absence de toute gravité"],"r":[0,1,2,3],"e":"IRA septique : NTA par hypoperfusion + toxicité. Oligurie (<400 mL/24h) ou anurie, ↑ créatinine. Réversible si pris à temps mais peut nécessiter dialyse temporaire. Mortalité élevée si MODS.","s":17},{"q":"Le MODS (Multi-Organ Dysfunction Syndrome) :","o":["L'atteinte d'un seul organe, souvent le rein","La défaillance progressive de plusieurs organes","Une défaillance toujours réversible","Une simple fièvre, sans autre signe"],"r":1,"e":"MODS = défaillance simultanée ou successive de plusieurs systèmes (≥2 organes). Mortalité augmente avec le nombre d'organes touchés. Complication terminale fréquente du sepsis non contrôlé. Rein, foie, cœur, poumon et cerveau peuvent être touchés.","s":17},{"q":"Concernant la PHYSIOPATHOLOGIE du choc septique :","o":["Réaction inflammatoire systémique excessive","Vasodilatation périphérique massive","Augmentation de la perméabilité capillaire (œdèmes, hypovolémie relative)","Dépression myocardique secondaire","Augmentation des résistances vasculaires"],"r":[0,1,2,3],"e":"Choc septique : libération massive de cytokines (TNF, IL-1, IL-6) → vasodilatation (NO), ↑ perméabilité, dépression myocardique, microthrombi (CIVD), ↓ extraction d'oxygène. Résistances vasculaires DIMINUENT (vasodilatation).","s":17},{"q":"Le score qSOFA permet :","o":["Le diagnostic de l'infection","Le dépistage rapide d'un sepsis, au lit","La mesure de la glycémie capillaire","L'évaluation cardiologique, par l'ECG et l'échographie cardiaque"],"r":1,"e":"qSOFA (quick SOFA) : 3 critères au lit du patient (Glasgow <15, PA syst ≤100, FR ≥22). ≥2 critères positifs → suspicion de sepsis avec mortalité élevée → urgence. Il associe une FR d'au moins 22, une conscience altérée et une PAS d'au plus 100.","s":17},{"q":"Concernant la PRISE EN CHARGE du choc septique, dans la 1ère heure ('bundle 1h') :","o":["Un dosage des lactates","Des hémocultures avant les antibiotiques","Des antibiotiques à large spectre","Un remplissage par cristalloïdes","Des vasopresseurs si la PAM reste basse","Une kinésithérapie respiratoire intensive"],"r":[0,1,2,3,4],"e":"Bundle 1 heure (Surviving Sepsis Campaign) : 1) lactates, 2) hémocultures, 3) antibiothérapie large spectre rapide, 4) remplissage cristalloïde 30 mL/kg, 5) vasopresseurs si hypotension persistante (NORADRÉNALINE en 1ère ligne). À la première heure, la priorité est hémodynamique et anti-infectieuse ; la kinésithérapie vient une fois le patient stabilisé.","s":17},{"q":"Le vasopresseur de PREMIÈRE LIGNE dans le choc septique est :","o":["L'adrénaline","La noradrénaline","La dobutamine","La dopamine"],"r":1,"e":"Noradrénaline = vasopresseur de 1ère ligne dans le choc septique (vasoconstriction α-adrénergique). Adrénaline en 2e ligne. Dobutamine si dysfonction cardiaque associée.","s":17},{"q":"Quels sont des AGENTS BACTÉRIENS classiques de sepsie ?","o":["Escherichia coli","Staphylococcus aureus","Streptococcus pneumoniae","Klebsiella pneumoniae","Aucune bactérie"],"r":[0,1,2,3],"e":"Sepsis communautaire : E. coli, S. pneumoniae, S. aureus, Streptococcus, méningocoque. Sepsis nosocomial : Pseudomonas, Klebsiella, Enterobacter, S. aureus résistant (MRSA). Champignons aussi (Candida).","s":17},{"q":"Le SIRS (Systemic Inflammatory Response Syndrome) inclut :","o":["Un seul critère, quel qu'il soit","Au moins 2 critères, dont la FC et la FR","La fièvre seule, au-delà de 38,5 °C","Une FC seule, au-delà de 90"],"r":1,"e":"SIRS = ≥2 critères parmi : T°<36 ou >38°C, FC>90/min, FR>20/min ou PaCO2<32, leucocytes <4 ou >12×10⁹/L (ou >10% de formes immatures). Réponse inflammatoire pas nécessairement infectieuse. Les critères portent sur la température, la FC, la FR et les globules blancs.","s":17},{"q":"L'hyperlactatémie (>2 mmol/L) en contexte de choc traduit :","o":["Une bonne perfusion des tissus, avec un débit élevé","Une hypoxie tissulaire, en anaérobie","Une hypoglycémie sévère","L'absence d'hypoxie cellulaire"],"r":1,"e":"Hyperlactatémie = marqueur d'hypoxie tissulaire (passage en glycolyse anaérobie). >2 mmol/L = signe de gravité (sepsis). >4 mmol/L = très sévère. Suivi du lactate = indicateur de réponse au traitement.","s":17},{"q":"Concernant le RÔLE DU KINÉSITHÉRAPEUTE en réanimation auprès du patient septique :","o":["Une mobilisation précoce, contre la fonte musculaire","Une kinésithérapie respiratoire de drainage","La prévention des escarres, par le positionnement","Une verticalisation progressive","L'initiation de l'antibiothérapie probabiliste"],"r":[0,1,2,3],"e":"Le kiné en réa : mobilisation précoce (ICU-AW = ICU acquired weakness), kiné respiratoire, prévention escarres/TVP, verticalisation. NE prescrit PAS d'antibiotiques (rôle médical).","s":17},{"q":"L'ICU-AW (faiblesse acquise en réanimation) :","o":["Est rare et bénigne, chez le jeune","Est fréquente, liée à l'alitement et au sepsis","Régresse spontanément en 24 h, sans séquelle","Est exclusivement neurologique, centrale"],"r":1,"e":"ICU-AW : faiblesse musculaire généralisée acquise en réanimation (polyneuromyopathie de réa). Causes : sepsis, immobilité, corticoïdes, curares, hyperglycémie. Récupération longue (mois). Prévention : mobilisation précoce. Corticoïdes et curares y contribuent ; c'est une polyneuromyopathie.","s":17},{"q":"Le choc OBSTRUCTIF est typiquement causé par :","o":["Une infection grave, avec une vasodilatation diffuse","Un obstacle au remplissage ou à l'éjection du cœur","Une perte de sang abondante","Une défaillance intrinsèque du ventricule"],"r":1,"e":"Choc obstructif : obstacle au remplissage ou à l'éjection cardiaque. Causes : EP massive, tamponnade, pneumothorax compressif, dissection aortique. Tx = lever l'obstacle (drainage, fibrinolyse...). Embolie pulmonaire massive, tamponnade et pneumothorax compressif en sont des causes.","s":17},{"q":"Concernant les COMPLICATIONS du choc septique :","o":["Un SDRA, ou poumon de choc","Une insuffisance rénale aiguë","Une CIVD, avec saignements","Une défaillance multi-organique","Une rémission immédiate"],"r":[0,1,2,3],"e":"Complications : SDRA, IRA (NTA), CIVD, MODS, ictère cholestatique, choc cardiogénique secondaire, syndrome post-réanimation (cognitif, ICU-AW, troubles psy). Mortalité élevée (>40%).","s":17},{"q":"La PORTE D'ENTRÉE la plus fréquente d'un sepsis chez l'adulte est :","o":["Cutanée, par une plaie infectée","Pulmonaire, par pneumonie","Méningée, par méningite","Articulaire, par arthrite"],"r":1,"e":"Portes d'entrée : pulmonaire (~50%, pneumonie), urinaire, abdominale (péritonite), cutanée (DHBN), cathéters (nosocomial). Toujours rechercher et traiter le foyer primaire (drainage si pertinent).","s":17},{"q":"Les SIGNES CLINIQUES classiques du choc à un stade avancé incluent :","o":["Une hypotension artérielle","Une tachycardie","Des marbrures cutanées","Une oligurie, voire une anurie","Une altération de la conscience","Une polyurie abondante"],"r":[0,1,2,3,4],"e":"Signes de choc : hypotension, tachycardie, peau froide pâle marbrée (sauf phase chaude initiale du choc septique : peau chaude rouge), oligurie, polypnée, troubles de conscience (somnolence à coma), acidose lactique. Le choc entraîne une oligurie par hypoperfusion rénale, exactement l'inverse.","s":17},{"q":"Le SIRS (Syndrome de Réponse Inflammatoire Systémique) requiert :","o":["Un seul critère, parmi les 4 retenus","Au moins 2 critères, dont la FC et les leucocytes","Aucun critère, au jugement du SAMU","Une hospitalisation seule, en service de réanimation polyvalente"],"r":1,"e":"SIRS : ≥ 2 critères : T°<36 ou >38°C, FC>90, FR>20 ou PaCO2<32, leucocytes<4000 ou >12000 ou >10% bandes. Les critères portent sur la température, la FC, la FR ou la PaCO₂ et les leucocytes.","s":17},{"q":"La sepsie est définie comme :","o":["Une infection localisée, sans gravité","Une dysfonction d'organe menaçant la vie, liée à l'infection","Un choc cardiogénique, par infarctus","Une intoxication, par une toxine bactérienne libérée dans le sang"],"r":1,"e":"Sepsie (Sepsis-3, 2016) = dysfonction d'organe menaçant la vie causée par une dérégulation de la réponse à l'infection. La réponse de l'hôte à l'infection est dérégulée.","s":17},{"q":"Le score qSOFA inclut :","o":["FC, température et glycémie","Glasgow ≤ 14, TAS ≤ 100, FR ≥ 22","Hémoglobine, plaquettes et créatinine","Le lactate seul, au-delà de 2 mmol/L"],"r":1,"e":"qSOFA = Glasgow≤14 + TAS≤100 mmHg + FR≥22/min ; ≥2 → suspicion sepsie.","s":17},{"q":"Le choc septique se définit par :","o":["Une sepsie, avec hypotension sous vasopresseurs","Une sepsie sans aucune hypotension","Une infection bénigne, localisée","Une déshydratation sévère, avec une perte de poids de plus de 10 %"],"r":0,"e":"Choc septique = sepsie avec hypotension persistante nécessitant vasopresseurs pour PAM≥65 + lactate >2 mmol/L. Les lactates dépassent 2 mmol/L.","s":17},{"q":"Le lactate sanguin élevé dans le sepsis traduit :","o":["Une bonne perfusion des tissus actifs","Une hypoperfusion tissulaire, en anaérobie","Une déshydratation simple, par la fièvre","Une infection bénigne, localisée"],"r":1,"e":"Lactate ↑ = anaérobiose tissulaire par hypoperfusion → marqueur de gravité du sepsis.","s":17},{"q":"La prise en charge initiale du sepsis inclut :","o":["Des hémocultures avant les antibiotiques","Des antibiotiques dans la première heure","Un remplissage par 30 mL/kg de cristalloïdes","Un contrôle du lactate","Des vasopresseurs si l'hypotension persiste","Une corticothérapie systématique d'emblée"],"r":[0,1,2,3,4],"e":"Bundle 1h sepsis : hémocs, ATB large spectre, lactate, remplissage 30 mL/kg, vasopresseurs (noradrénaline) si nécessaire. Les corticoïdes ne sont envisagés qu'en cas de choc réfractaire aux vasopresseurs, jamais en systématique initiale.","s":17},{"q":"Le remplissage vasculaire initial recommandé devant un sepsis avec hypoperfusion est de :","o":["5 mL/kg de cristalloïdes, répartis sur les 6 premières heures","30 mL/kg de cristalloïdes en 3 heures","100 mL/kg de colloïdes en 1 heure","Aucun remplissage avant le vasopresseur"],"r":1,"e":"Les recommandations de la Surviving Sepsis Campaign fixent 30 mL/kg de cristalloïdes dans les trois premières heures, avant ou en même temps que la noradrénaline si la pression reste basse. Le remplissage précède le vasopresseur, sauf hypotension profonde d'emblée.","s":17},{"q":"Le foyer infectieux primaire le plus fréquent du sepsis est :","o":["Cutané","Pulmonaire","ORL","Articulaire"],"r":1,"e":"Sources fréquentes : pulmonaire (1ère), abdominale, urinaire, cathéter, peau.","s":17},{"q":"La mortalité du choc septique est :","o":["< 5%","10-15%","30-50% voire plus","Toujours > 90%"],"r":2,"e":"Mortalité du choc septique reste élevée : 30-50% selon les séries, dépend du terrain et précocité de la PEC.","s":17},{"q":"La défaillance multiviscérale (MOF) :","o":["Est rare au cours du sepsis","Est l'évolution grave d'un sepsis non contrôlé","Est sans gravité particulière","Touche un seul organe, le plus souvent le rein, chez l'enfant"],"r":1,"e":"MOF/MODS = défaillance simultanée de ≥2 organes, conséquence du choc septique non contrôlé.","s":17},{"q":"Quel est le taux de mortalité du choc septique aux États-Unis selon la fiche ?","o":["Environ 50 %","Environ 10 %","Environ 25 %","Environ 80 %"],"r":0,"e":"La fiche indique 50 % aux États-Unis et 40 % de mortalité hospitalière au Portugal.","s":17},{"q":"Combien de cas de sepsie sont recensés chaque année aux États-Unis ?","o":["Plus de 750 000","Environ 50 000","Environ 10 millions","Environ 100 000"],"r":0,"e":"La fiche cite plus de 750 000 cas annuels.","s":17},{"q":"Quelle mortalité la fiche associe-t-elle à un score SOFA supérieur ou égal à 2 ?","o":["Environ 10 %","Environ 40 %","Environ 1 %","Environ 70 %"],"r":0,"e":"Une élévation de 2 points du SOFA définit le dysfonctionnement organique, avec environ 10 % de mortalité.","s":17},{"q":"De quand date la définition Sepsis-3 ?","o":["2016, publiée dans le JAMA","2001, lors d'une conférence","2010, par l'OMS","2020, pendant la pandémie de COVID-19"],"r":0,"e":"Sepsis-3 (Singer et al., JAMA 2016) a redéfini sepsie et choc septique.","s":17},{"q":"Pourquoi le terme « septicémie grave » a-t-il été abandonné ?","o":["Parce que la sepsie implique déjà une dysfonction d'organe","Parce qu'il est trop imprécis sur l'agent infectieux en cause","Parce qu'il désigne désormais le choc septique","Parce qu'il ne s'applique qu'à l'enfant"],"r":0,"e":"Depuis Sepsis-3, l'expression est redondante.","s":17},{"q":"Pourquoi le SIRS n'est-il plus utilisé seul pour diagnostiquer la sepsie ?","o":["Sa sensibilité est faible","Il est trop spécifique","Il exige un dosage du lactate","Il n'existe plus de critères"],"r":0,"e":"Le SIRS reste utile pour repérer une infection, mais ne suffit plus au diagnostic.","s":17},{"q":"Quel critère de fréquence respiratoire figure dans le SIRS ?","o":["Plus de 20/min ou une PaCO₂ inférieure à 32 mmHg","Au moins 22/min, comme le qSOFA","Plus de 30/min, avec un tirage et une cyanose des lèvres","Moins de 12/min, en bradypnée"],"r":0,"e":"22/min est le seuil du qSOFA ; le SIRS retient 20/min ou une hypocapnie.","s":17},{"q":"Quels seuils de globules blancs définissent le critère hématologique du SIRS ?","o":["Plus de 12 000 ou moins de 4 000/mm³","Plus de 20 000/mm³ uniquement, sans seuil bas","Moins de 1 000/mm³ seulement","Plus de 15 000/mm³ uniquement"],"r":0,"e":"Leucocytose ou leucopénie sont l'un des quatre critères du SIRS.","s":17},{"q":"Quelle anomalie métabolique figure parmi les signes précoces de sepsie ?","o":["Une hyperglycémie sans diabète","Une hypoglycémie profonde","Une hypercalcémie","Une hyponatrémie"],"r":0,"e":"TNF, IL-1 et catécholamines induisent une résistance à l'insuline.","s":17},{"q":"Quel seuil de diurèse définit l'oligurie dans le choc septique ?","o":["Moins de 0,5 mL/kg/h","Moins de 2 mL/kg/h","Moins de 1 L/24 h","Moins de 100 mL/h"],"r":0,"e":"L'oligurie figure parmi les signes tardifs, avec l'hypotension réfractaire et l'acidose lactique.","s":17},{"q":"Que sont les PAMPs ?","o":["Des motifs des pathogènes, reconnus par les récepteurs Toll","Des cytokines anti-inflammatoires","Des facteurs de coagulation, plasmatiques","Des anticorps antibactériens, produits par les plasmocytes activés"],"r":0,"e":"Leur reconnaissance par les TLR active NF-κB et la cascade cytokinique.","s":17},{"q":"Quel facteur de transcription relaie l'activation des TLR ?","o":["NF-κB","GATA4","APAF-1","BCL2"],"r":0,"e":"NF-κB déclenche la production de TNF, IL-1, IL-6, IL-8 et HMGB1.","s":17},{"q":"Quel mécanisme explique la vasodilatation du choc septique ?","o":["La production de monoxyde d'azote","La libération d'adrénaline","La contraction endothéliale isolée","La thrombose microvasculaire"],"r":0,"e":"Le NO provoque la vasodilatation et l'hypotension systémique, tandis que le relâchement des jonctions serrées crée l'œdème.","s":17},{"q":"Quelle molécule procoagulante augmente dans la CIVD du sepsis ?","o":["Le facteur tissulaire, ou TF","La protéine C activée","La thrombomoduline endothéliale","Le TFPI, inhibiteur"],"r":0,"e":"Le TF et le PAI-1 augmentent tandis que protéine C, TFPI et thrombomoduline diminuent.","s":17},{"q":"Quelle molécule antifibrinolytique s'élève dans le sepsis ?","o":["Le PAI-1","Le TFPI-1","La protéine C","La thrombomoduline"],"r":0,"e":"L'élévation du PAI-1 bloque la fibrinolyse et aggrave la thrombose microvasculaire.","s":17},{"q":"Les VOIES RESPIRATOIRES SUPÉRIEURES comprennent :","o":["Nez et fosses nasales","Pharynx","Larynx","Sinus paranasaux","Bronches"],"r":[0,1,2,3],"e":"VRS : nez/fosses nasales, sinus paranasaux, pharynx, larynx (jusqu'aux cordes vocales). Les bronches font partie des VRI (voies respiratoires inférieures).","s":18},{"q":"Le RHUME (rhinite aiguë) est principalement d'origine :","o":["Bactérienne, surtout à streptocoque du groupe A","Virale, surtout à rhinovirus","Allergique, aux pollens","Mycosique, à Candida"],"r":1,"e":"Le rhume est principalement viral : rhinovirus (>50%), coronavirus, adénovirus, VRS, parainfluenza. Pas d'antibiothérapie indiquée. Auto-résolutif en 7-10 jours. Coronavirus et adénovirus sont aussi en cause.","s":18},{"q":"Symptômes typiques du RHUME :","o":["Une rhinorrhée, claire puis muqueuse","Une obstruction nasale","Des éternuements","Des maux de gorge","Une fièvre toujours élevée"],"r":[0,1,2,3],"e":"Rhume : rhinorrhée, obstruction nasale, éternuements, irritation pharyngée, parfois fébricule (faible). Une fièvre élevée doit faire suspecter une grippe ou une surinfection bactérienne.","s":18},{"q":"La SINUSITE BACTÉRIENNE aiguë est suspectée si :","o":["Des symptômes de rhume depuis moins de 3 jours","Des symptômes au-delà de 10 jours, avec fièvre et pus","Un simple rhume, sans complication","L'absence de tout signe clinique, à l'examen et à l'interrogatoire"],"r":1,"e":"Sinusite bactérienne : symptômes >10 jours sans amélioration, ou aggravation après amélioration initiale, douleur faciale, fièvre >39°C, rhinorrhée purulente. Sinusite virale = la majorité, auto-résolutive. Une douleur faciale est aussi évocatrice.","s":18},{"q":"Quels SINUS sont concernés par la sinusite ?","o":["Les sinus maxillaires","Les sinus frontaux","Les sinus ethmoïdaux","Les sinus sphénoïdaux","Les sinus mastoïdiens"],"r":[0,1,2,3],"e":"4 paires de sinus paranasaux : maxillaires (+ fréquents en sinusite), frontaux, ethmoïdaux, sphénoïdaux. Les sinus mastoïdiens font partie de l'oreille moyenne (mastoïdite).","s":18},{"q":"La PHARYNGITE STREPTOCOCCIQUE (à streptocoque β-hémolytique du groupe A) doit être traitée par :","o":["Des antiviraux, pendant 5 jours","De l'amoxicilline, pendant 6 jours","Aucun traitement, la guérison étant spontanée en 7 jours","Des antifongiques, pendant 10 jours"],"r":1,"e":"Pharyngite à SBHA : antibiothérapie obligatoire pour prévenir les complications post-streptococciques (RAA, glomérulonéphrite). Amoxicilline 6 jours en France. Diagnostic : TROD streptococcique ou culture.","s":18},{"q":"Concernant les complications post-streptococciques de la pharyngite à SBHA :","o":["Un rhumatisme articulaire aigu","Une glomérulonéphrite aiguë","Un phlegmon péri-amygdalien","Une otite moyenne aiguë","Un diabète de type 1"],"r":[0,1,2,3],"e":"Complications : précoces (phlegmon, OMA, sinusite, abcès rétropharyngé), tardives non suppuratives = RAA (cardite, polyarthrite, chorée) et GN aiguë. Le diabète n'a pas de lien direct.","s":18},{"q":"La LARYNGITE aiguë chez l'adulte est principalement :","o":["Virale","Bactérienne","Toujours mycosique","Auto-immune"],"r":0,"e":"Laryngite aiguë = principalement virale (suite d'une infection des VRS). Symptômes : dysphonie/aphonie, toux sèche. Auto-résolutive en quelques jours. Tx : repos vocal, hydratation.","s":18},{"q":"La LARYNGITE SOUS-GLOTTIQUE de l'enfant (croup) :","o":["Une dyspnée expiratoire, avec une toux grasse","Une infection bactérienne, à streptocoque","Une maladie de l'adolescent, entre 12 et 16 ans","Un stridor inspiratoire et une toux aboyante"],"r":3,"e":"Croup : laryngite sous-glottique virale (parainfluenza) chez 6 mois-3 ans. Triade : toux aboyante (rauque), stridor inspiratoire, dyspnée. Tx = corticoïdes (dexaméthasone) ± adrénaline en aérosol si grave. Elle est principalement virale (parainfluenza), touche l'enfant de 6 mois à 3 ans et peut être une urgence respiratoire.","s":18},{"q":"La GRIPPE (influenza) est causée par :","o":["Un virus à ADN, de la famille des herpès","Le virus Influenza, à ARN segmenté","Une bactérie, Haemophilus influenzae","Un champignon, inhalé avec les poussières humides"],"r":1,"e":"Grippe = virus Influenza, ARN segmenté (Orthomyxoviridae). 3 types : A (le + grave, pandémies, épidémies, animal+humain), B (épidémies humaines), C (formes bénignes). Il en existe trois types, A, B et C.","s":18},{"q":"Symptômes typiques de la GRIPPE :","o":["Un début brutal","Une fièvre élevée, au-delà de 39 °C","Des myalgies et une asthénie marquée","Des céphalées intenses","Une rhinorrhée isolée, sans autre signe"],"r":[0,1,2,3],"e":"Grippe : début BRUTAL, fièvre élevée, frissons, myalgies/arthralgies, céphalées, asthénie majeure ('sentiment d'être passé sous un camion'), toux sèche. Distinct du rhume (progressif, peu fébrile).","s":18},{"q":"Concernant les COMPLICATIONS de la grippe :","o":["Une pneumonie virale","Une surinfection bactérienne pulmonaire","La décompensation d'une maladie chronique","Un syndrome de Reye sous aspirine","Aucune complication possible"],"r":[0,1,2,3],"e":"Complications : pneumonie virale primaire, surinfection bactérienne (pneumocoque, staph), décompensation cardio-respiratoire, encéphalite, péricardite, syndrome de Reye (enfant + aspirine = CONTRE-INDIQUÉ).","s":18},{"q":"Le VACCIN antigrippal est :","o":["À ARN messager, comme le COVID","Inactivé, et recomposé chaque année","Vivant atténué uniquement, par voie nasale chez l'adulte","Inutile, faute d'efficacité"],"r":1,"e":"Vaccin antigrippal saisonnier : inactivé (injection IM), recomposé chaque année selon les souches OMS prédites (3 ou 4 souches : A/H1N1, A/H3N2, B). Recommandé : >65 ans, malades chroniques, soignants, enceintes.","s":18},{"q":"Le COVID-19 est causé par :","o":["Le virus Influenza A, ou H1N1","Le SARS-CoV-2, un coronavirus à ARN","Une bactérie atypique","Un parasite intracellulaire"],"r":1,"e":"COVID-19 = SARS-CoV-2 : coronavirus à ARN simple brin positif. Famille Coronaviridae. Découvert fin 2019, pandémie déclarée mars 2020.","s":18},{"q":"Symptômes possibles du COVID-19 :","o":["Une fièvre modérée","Une toux sèche","Une anosmie ou une agueusie","Une dyspnée d'effort","Des diarrhées","Un ictère cutanéo-muqueux"],"r":[0,1,2,3,4],"e":"COVID-19 : très polymorphe. Fièvre, toux, anosmie/agueusie (très évocateurs), dyspnée, asthénie, myalgies, céphalées, troubles digestifs, formes asymptomatiques fréquentes. Formes graves = SDRA. L'ictère traduit une atteinte hépatique ou hémolytique et ne fait pas partie du tableau du COVID-19.","s":18},{"q":"La voie d'entrée principale du SARS-CoV-2 dans les cellules est le récepteur :","o":["ACE2","Hémagglutinine","CD4","TLR4"],"r":0,"e":"Le SARS-CoV-2 utilise la protéine spike (S) pour se lier au récepteur ACE2 (Angiotensin Converting Enzyme 2) sur les cellules épithéliales (poumon, intestin, vaisseaux). Activation par TMPRSS2.","s":18},{"q":"Concernant la PRÉVENTION des infections respiratoires saisonnières :","o":["Lavage des mains","Port du masque en cas de symptômes","Hygiène respiratoire (tousser dans le coude)","Vaccination (grippe, COVID, pneumocoque)","Antibiothérapie systématique"],"r":[0,1,2,3],"e":"Prévention : hygiène (mains, masque, hygiène respiratoire), vaccination, distanciation. L'antibiothérapie systématique est INUTILE et néfaste (résistances, déséquilibre microbiote) pour les infections virales.","s":18},{"q":"Une OTITE MOYENNE AIGUË (OMA) est :","o":["Une infection de l'oreille externe","Une infection de l'oreille moyenne","Une atteinte de la cochlée","Une atteinte du vestibule"],"r":1,"e":"OMA = inflammation de l'oreille moyenne, fréquemment chez l'enfant. Souvent bactérienne (pneumocoque, Haemophilus, Moraxella) compliquant un rhume. Symptômes : otalgie, fièvre, parfois écoulement (perforation). Elle siège dans la caisse du tympan.","s":18},{"q":"La principale étiologie BACTÉRIENNE des sinusites aiguës est :","o":["Streptococcus pneumoniae","Mycobacterium tuberculosis","Pseudomonas","E. coli"],"r":0,"e":"Sinusites bactériennes (rares vs virales) : Streptococcus pneumoniae +++, Haemophilus influenzae, Moraxella catarrhalis. Tx = amoxicilline (souvent + acide clavulanique).","s":18},{"q":"Concernant le DRAINAGE BRONCHIQUE / kinésithérapie respiratoire :","o":["Elle aide à mobiliser les sécrétions","Elle est indiquée dans la bronchiolite","Elle utilise l'AFE et le drainage autogène","Elle est toujours indiquée dans le rhume","Elle est indiquée après une chirurgie pulmonaire"],"r":[0,1,2,4],"e":"Kiné respi : mobilise les sécrétions (techniques expiratoires lentes ou rapides). Indications : encombrement (bronchiolite, BPCO, mucoviscidose, post-op). Le rhume ne nécessite pas de kiné respi. La mucoviscidose et la BPCO décompensée en sont aussi des indications.","s":18},{"q":"Le mécanisme de transmission majeur des virus respiratoires est :","o":["La voie sanguine, par transfusion ou piqûre","La voie sexuelle, par les muqueuses","Les gouttelettes, les surfaces et les aérosols","La voie digestive uniquement"],"r":2,"e":"Virus respiratoires : transmission par gouttelettes (>5µm, courte distance), aérosols (<5µm, longue distance, surtout en milieu fermé), contact direct ou indirect (mains, surfaces, fomites).","s":18},{"q":"Les ANTIVIRAUX antigrippaux (oseltamivir = Tamiflu) :","o":["Tuent directement le virus → guérison immédiate","Bloquent la neuraminidase → moins de virions","Sont efficaces sur tous les virus","Doivent être donnés au stade tardif"],"r":1,"e":"Oseltamivir/zanamivir : inhibiteurs de la neuraminidase. Efficacité optimale si donnés dans les 48h après le début des symptômes. Réduisent la durée et la sévérité des symptômes. Indiqués chez les patients à risque.","s":18},{"q":"L'incubation du COVID-19 est en moyenne de :","o":["1 jour, avec une contagion immédiate","3 à 5 jours, et jusqu'à 14 jours","3 semaines environ","2 mois en moyenne"],"r":1,"e":"COVID-19 : incubation médiane 5 jours, possible 1-14 jours. Période de contagion : commence ~2 jours avant les symptômes, max le jour des symptômes, dure ~7-10 jours en cas léger.","s":18},{"q":"Concernant l'évolution naturelle du rhume :","o":["Toujours grave, avec hospitalisation","Auto-résolutive en 7 à 10 jours","Avec des antibiotiques systématiques pendant 5 jours","Sans aucune résolution spontanée"],"r":1,"e":"Rhume : évolution bénigne, auto-résolutive en 7-10 jours. Tx symptomatique uniquement (antalgiques, antipyrétiques, désinfection nasale). Pas d'antibiotiques (virus). Surveillance d'éventuelles complications (sinusite, OMA).","s":18},{"q":"Les facteurs FAVORISANT les infections des VRS chez l'adulte :","o":["Une alimentation équilibrée, riche en fruits","Le tabagisme actif, qui paralyse les cils","Une immunité optimale","Un sport modéré et régulier"],"r":1,"e":"Facteurs de risque : tabac (paralyse les cils muco-ciliaires, altère la muqueuse), pollution, immunodépression, allergies, RGO, déviation septale, terrain ORL (amygdales hypertrophiées). Le sport modéré PROTÈGE. Il altère aussi la muqueuse.","s":18},{"q":"La rhinite allergique est due à :","o":["Une infection bactérienne, à pneumocoque","Une hypersensibilité à IgE, envers un allergène","Une déshydratation des muqueuses, par un air sec","Une carence en IgA sécrétoires"],"r":1,"e":"Rhinite allergique = hypersensibilité type I (IgE) → libération d'histamine par les mastocytes → rhinorrhée, prurit, éternuements.","s":18},{"q":"La sinusite aiguë se caractérise par :","o":["Une douleur faciale et un écoulement purulent","Une toux chronique seule, nocturne","Une fièvre isolée, sans aucun autre signe local ni général","Des vertiges rotatoires, au lever"],"r":0,"e":"Sinusite : douleur sinusale (frontale/maxillaire), obstruction, rhinorrhée purulente, ± fièvre. L'obstruction nasale complète le tableau.","s":18},{"q":"L'angine streptococcique se traite par :","o":["Des antiviraux, comme l'aciclovir","Des antibiotiques, comme l'amoxicilline","Aucun traitement spécifique","Des corticoïdes seuls, pour réduire l'inflammation"],"r":1,"e":"Angine à streptocoque A : antibiothérapie (pénicilline) pour prévenir RAA, glomérulonéphrite, abcès. La pénicilline est aussi utilisée.","s":18},{"q":"L'épiglottite aiguë de l'enfant est :","o":["Une affection bénigne, sans gravité","Une urgence médicale, par risque d'asphyxie","Une maladie chronique, évoluant sur plusieurs années","Une allergie saisonnière"],"r":1,"e":"Épiglottite (Haemophilus influenzae b) : urgence vitale, risque d'obstruction aiguë des voies respiratoires supérieures.","s":18},{"q":"L'apnée obstructive du sommeil (SAOS) est :","o":["Un trouble psychiatrique du sommeil","Des collapsus répétés du pharynx pendant le sommeil","Une infection des voies aériennes","Une maladie hépatique, avec une encéphalopathie nocturne"],"r":1,"e":"SAOS : pauses respiratoires répétées par collapsus pharyngé → désaturations, micro-éveils, somnolence diurne.","s":18},{"q":"Les facteurs de risque du SAOS incluent :","o":["Obésité","Sexe masculin","Cou court / large","Prise d'alcool ou sédatifs","Anomalies maxillo-mandibulaires","Activité sportive"],"r":[0,1,2,3,4],"e":"SAOS : obésité, homme, cou large (>43 cm H), alcool/sédatifs, micrognatie. Le sport est protecteur.","s":18},{"q":"La laryngite aiguë de l'adulte se manifeste par :","o":["Une diarrhée, d'origine virale","Une dysphonie ou une aphonie","Une constipation","Des vertiges"],"r":1,"e":"Laryngite : dysphonie/aphonie + toux sèche, souvent virale et auto-résolutive.","s":18},{"q":"L'examen clé du SAOS est :","o":["Un EEG seul, en journée","La polysomnographie, la nuit","Une radiographie du thorax","Une échocardiographie"],"r":1,"e":"Polysomnographie : compte les apnées/hypopnées par heure → IAH (Index Apnée Hypopnée). >5 = SAOS.","s":18},{"q":"Le traitement principal du SAOS modéré-sévère est :","o":["Des antibiotiques au long cours","Une pression positive continue la nuit","Une trachéotomie d'emblée, en première intention","Un antitussif, le soir"],"r":1,"e":"CPAP = traitement de référence du SAOS modéré-sévère ; maintient les voies aériennes ouvertes. C'est la CPAP, ou PPC.","s":18},{"q":"Une rhinorrhée claire prolongée + obstruction nasale chronique évoque :","o":["Une rhinite allergique chronique","Un cancer ORL débutant","Une fracture nasale ancienne","Une amygdalite récidivante"],"r":0,"e":"Rhinite allergique chronique = rhinorrhée claire, obstruction, éternuements, prurit, parfois conjonctivite.","s":18},{"q":"Combien de personnes les infections respiratoires supérieures ont-elles touché en 2021, hors COVID ?","o":["Environ 13 milliards de cas","Environ 1 milliard, sur l'année","Environ 100 millions","Environ 500 millions"],"r":0,"e":"La fiche cite 13 milliards d'épisodes en 2021, hors COVID.","s":18},{"q":"Combien d'épisodes de rhume un enfant de 5 à 9 ans fait-il par an ?","o":["6 à 8","2 à 5","1 à 2","10 à 15"],"r":0,"e":"6 à 8 épisodes chez l'enfant de 5-9 ans contre 2 à 5 chez l'adulte.","s":18},{"q":"Quelle est la mortalité liée au rhume selon la fiche ?","o":["1 pour 20 000","1 pour 100","1 pour 1 000","Nulle"],"r":0,"e":"La fiche mentionne une mortalité de 1/20 000.","s":18},{"q":"De quoi dépendent les symptômes d'une infection respiratoire supérieure ?","o":["De la structure touchée, de la gravité et du terrain","Uniquement de l'agent infectieux, viral ou autre","Uniquement de la saison, hiver ou été","Uniquement du terrain allergique"],"r":0,"e":"C'est le principe clé énoncé par la fiche. Le terrain correspond à l'état de santé et à l'âge.","s":18},{"q":"Combien de sous-types de rhinovirus existe-t-il ?","o":["Environ 160","Environ 3","Environ 20","Environ 1 000"],"r":0,"e":"Cette diversité explique l'absence d'immunité durable et la répétition des rhumes.","s":18},{"q":"À quelle saison le pic de rhinovirus survient-il ?","o":["À l'automne et au printemps","En hiver uniquement","En été","Toute l'année de façon stable"],"r":0,"e":"Grippe et VRS piquent en hiver, les rhinovirus à l'automne et au printemps.","s":18},{"q":"Quelle est la durée d'incubation du rhume ?","o":["1 à 4 jours","1 à 5 jours","3 à 7 jours","2 semaines"],"r":0,"e":"1 à 4 jours pour le rhume, 1 à 5 pour la grippe, 3 à 7 pour le COVID-19.","s":18},{"q":"Quel est le réservoir du rhume ?","o":["Le nasopharynx","Le larynx","Les alvéoles","Le tube digestif"],"r":0,"e":"La transmission se fait par aérosols, surfaces et auto-inoculation nasale ou conjonctivale.","s":18},{"q":"Quel médiateur la fiche associe-t-elle au mal de gorge et à l'écoulement nasal du rhume ?","o":["La bradykinine","L'histamine","Le TNF-α","L'acétylcholine"],"r":0,"e":"Le rhinovirus augmente les médiateurs inflammatoires, la bradykinine produisant ces symptômes.","s":18},{"q":"Quel est le premier symptôme du rhume ?","o":["Le mal de gorge, dès le premier jour","L'écoulement nasal, clair","La toux, sèche puis grasse, dès le réveil","La congestion nasale"],"r":0,"e":"Mal de gorge à J1, écoulement et éternuements à J2-J3, puis congestion, pharyngite et toux.","s":18},{"q":"Pourquoi le terme « rhinosinusite » est-il préféré à « sinusite » ?","o":["Parce que la muqueuse nasale est généralement aussi touchée","Parce que l'atteinte est toujours nasale et jamais sinusienne","Parce que la sinusite n'existe pas chez l'adulte","Parce que le terme sinusite désigne une forme chronique"],"r":0,"e":"L'atteinte est en pratique naso-sinusienne.","s":18},{"q":"Quelle proportion des sinusites est bactérienne ?","o":["0,5 à 2 %","20 à 30 %","50 %","80 %"],"r":0,"e":"L'immense majorité est virale, ce qui limite l'indication des antibiotiques.","s":18},{"q":"Quelles causes non infectieuses de sinusite la fiche cite-t-elle ?","o":["L'allergie, une déviation de la cloison ou une tumeur","Le tabagisme uniquement, actif","Le reflux gastro-œsophagien, par des remontées acides la nuit","Un traumatisme vocal, chez le chanteur"],"r":0,"e":"Ces causes créent une obstruction ou une inflammation sans infection initiale. Le barotraumatisme et les corps étrangers en font aussi partie.","s":18},{"q":"À partir de quelle durée parle-t-on de rhinosinusite chronique ?","o":["Plus de 12 semaines","Plus de 4 semaines","Plus de 2 semaines","Plus de 6 mois"],"r":0,"e":"Aiguë sous 4 semaines, subaiguë de 4 à 12, chronique au-delà de 12 ; récurrente si au moins 4 épisodes par an.","s":18},{"q":"Quels critères permettent de poser le diagnostic clinique de rhinosinusite ?","o":["Deux critères majeurs, ou un majeur et un mineur","Trois critères majeurs","Un seul critère majeur, ou trois critères mineurs","Deux critères mineurs"],"r":0,"e":"La combinaison majeure/mineure est la règle diagnostique retenue.","s":18},{"q":"Une PNEUMONIE est :","o":["Une infection limitée aux bronches, sans atteinte alvéolaire","Une infection du parenchyme pulmonaire","Une atteinte pleurale isolée","Une simple bronchite virale"],"r":1,"e":"Pneumonie = infection du parenchyme pulmonaire (alvéoles, espace interstitiel). À distinguer de la bronchite (atteinte des bronches) et de la pleurésie (atteinte de la plèvre). Elle touche les alvéoles et le tissu interstitiel.","s":19},{"q":"L'agent BACTÉRIEN le plus fréquent de la pneumonie communautaire est :","o":["Mycobacterium tuberculosis","Streptococcus pneumoniae, ou pneumocoque","Pseudomonas aeruginosa, ou bacille pyocyanique","Staphylococcus aureus"],"r":1,"e":"Streptococcus pneumoniae (pneumocoque) = 1ère cause de pneumonie communautaire. Tableau classique : début brutal, fièvre élevée, frissons, point de côté, toux + crachats rouillés, foyer de condensation.","s":19},{"q":"Symptômes typiques d'une pneumonie LOBAIRE (alvéolaire, bactérienne) :","o":["Un début brutal, en heures","Une fièvre élevée et des frissons","Une toux avec expectoration purulente","Un point de côté","Une évolution insidieuse"],"r":[0,1,2,3],"e":"Pneumonie lobaire bactérienne (pneumocoque ++) : début BRUTAL, fièvre/frissons, toux purulente parfois rouillée, douleur thoracique (point de côté), polypnée, foyer de condensation à l'auscultation.","s":19},{"q":"Concernant la PNEUMONIE ATYPIQUE :","o":["Un début progressif","Une fièvre modérée","Une toux sèche et tenace","Des céphalées et des myalgies","Mycoplasma, Chlamydia ou Legionella","Des crachats rouillés abondants"],"r":[0,1,2,3,4],"e":"Pneumonie atypique : début progressif, signes généraux + extra-pulmonaires (céphalées, myalgies, troubles digestifs), toux sèche, dissociation radio-clinique. Agents : Mycoplasma pneumoniae, Chlamydophila, Legionella (sévère). Ces crachats évoquent la pneumonie franche lobaire aiguë à pneumocoque, forme typique et non atypique.","s":19},{"q":"À l'examen physique, le syndrome de CONDENSATION pulmonaire associe :","o":["Une matité, des vibrations vocales accrues et des crépitants","Une hypersonorité et une abolition complète du murmure vésiculaire","Un tympanisme et un silence auscultatoire","Des sibilants diffus, uniquement"],"r":0,"e":"Sd de condensation (alvéolaire) : MATITÉ percussion, ↑ vibrations vocales, râles crépitants ± souffle tubaire (alvéoles remplies). Pneumothorax = hypersonorité + abolition. Asthme = sibilants. Un souffle tubaire est possible.","s":19},{"q":"Quels examens diagnostiques sont utiles dans la PNEUMONIE ?","o":["Une radiographie du thorax","Une CRP et une numération sanguine","Une procalcitonine, pour orienter","Des hémocultures si fièvre","Une échographie cardiaque systématique"],"r":[0,1,2,3],"e":"Diagnostic : RX thorax (foyer alvéolaire systématisé), CRP/NFS, procalcitonine (↑ si bactérien), hémocultures, ECBC, antigénurie pneumocoque/Legionella. Échographie cardiaque pas systématique.","s":19},{"q":"Le score CRB-65 permet :","o":["Le diagnostic de la tuberculose pulmonaire","D'évaluer la gravité d'une pneumonie en ville","La mesure de la calcémie","Le suivi cardiaque, par ECG"],"r":1,"e":"CRB-65 = score de gravité pour pneumonie communautaire en ambulatoire. 4 critères : Confusion, FR ≥30, PA basse (PAS <90 ou PAD ≤60), Âge ≥65. ≥1 critère → hospitalisation à envisager. Il cote la confusion, une FR d'au moins 30, une PA basse et un âge d'au moins 65 ans.","s":19},{"q":"L'antibiothérapie de PREMIÈRE INTENTION dans la pneumonie communautaire à pneumocoque chez l'adulte sans comorbidité est :","o":["Vancomycine","Amoxicilline","Cotrimoxazole","Métronidazole"],"r":1,"e":"Pneumocoque (suspecté/confirmé) : amoxicilline 1g x3/j en 1ère intention (PO ou IV selon gravité). Si allergie : pristinamycine ou macrolides. Adapter selon antibiogramme.","s":19},{"q":"La TUBERCULOSE est causée par :","o":["Streptococcus pneumoniae","Mycobacterium tuberculosis, un BAAR","Un virus respiratoire, à ARN","Un champignon, de type Aspergillus"],"r":1,"e":"Tuberculose = Mycobacterium tuberculosis (bacille de Koch), BAAR (Bacille Acido-Alcoolo-Résistant) à coloration de Ziehl-Neelsen. Croissance lente. Transmission aérienne interhumaine.","s":19},{"q":"Quels sont les SYMPTÔMES classiques de la TB pulmonaire ?","o":["Toux chronique > 2-3 semaines","Hémoptysie","Fièvre vespérale + sueurs nocturnes","Amaigrissement / asthénie","Évolution toujours aiguë sur 1 jour"],"r":[0,1,2,3],"e":"TB pulmonaire : signes constitutionnels (fièvre vespérale, sueurs nocturnes, amaigrissement, asthénie) + toux chronique (>3 sem), hémoptysie possible. Évolution INSIDIEUSE et CHRONIQUE (semaines/mois).","s":19},{"q":"L'examen de référence pour le diagnostic bactériologique de la TB est :","o":["La radiographie du thorax, avec des cavernes apicales","La bacilloscopie et surtout la culture","La sérologie tuberculeuse","L'antibiogramme uniquement"],"r":1,"e":"Diagnostic TB : crachats x3 → bacilloscopie directe (Ziehl) + CULTURE sur milieu de Löwenstein-Jensen (référence, lente : 4-6 semaines) ou MGIT (plus rapide). Tests moléculaires (GeneXpert) : rapides + résistance. La bacilloscopie se fait au Ziehl ; la culture est la référence.","s":19},{"q":"L'IDR à la TUBERCULINE (test de Mantoux) :","o":["Diagnostique une TB maladie","Révèle un contact avec le BK ou un BCG","Permet de prescrire des antibiotiques","Est obsolète, remplacée partout par la radiographie"],"r":1,"e":"IDR : injection ID de tuberculine, lecture à 72h (induration). Témoigne d'une exposition au BK ou d'un BCG. NE distingue PAS infection latente vs maladie active. Tests IGRA (Quantiferon, T-SPOT) plus spécifiques (non interférés par BCG). Elle se lit par l'induration cutanée.","s":19},{"q":"Le TRAITEMENT antituberculeux standard comprend :","o":["Une quadrithérapie pendant 2 mois","Une bithérapie pendant 4 mois","Une durée totale de 6 mois","Une prise observée, ou DOT","Une antibiothérapie de 5 jours"],"r":[0,1,2,3],"e":"Tx TB standard (forme sensible) : 2 mois RIPE (isoniazide H, rifampicine R, pyrazinamide Z, éthambutol E) puis 4 mois HR. Total 6 mois. Observance cruciale (DOT). Surveiller hépatotoxicité et neuropathie (B6). La quadrithérapie associe isoniazide, rifampicine, pyrazinamide et éthambutol.","s":19},{"q":"Le vaccin BCG :","o":["Empêche complètement la tuberculose","Réduit les formes graves chez l'enfant","Est inefficace, et donc abandonné dans tous les pays du monde","Doit être refait chaque année"],"r":1,"e":"BCG : protection partielle, surtout contre les formes graves chez l'enfant (méningite tuberculeuse, miliaire). Inefficace contre les formes pulmonaires de l'adulte. Recommandé chez enfants à risque (pays de forte endémie, contact avec patient bacillifère). Ces formes graves sont la méningite et la miliaire.","s":19},{"q":"Quels sont des FACTEURS DE RISQUE de tuberculose ?","o":["VIH / immunodépression","Précarité, promiscuité","Diabète","Origine de pays endémique","Tabagisme","Une vaccination BCG récente"],"r":[0,1,2,3,4],"e":"FdR : VIH (RR x100), immunodépression (corticoïdes, biothérapies), précarité, milieu carcéral, sans-abri, contact étroit avec patient bacillifère, origine de pays endémique, diabète, tabac, dénutrition, alcoolisme. Le BCG protège des formes graves de l'enfant : c'est un facteur protecteur, non un facteur de risque.","s":19},{"q":"La maladie de POTT correspond à :","o":["Une tuberculose pulmonaire, avec des cavernes","Une tuberculose vertébrale, ou spondylite","Une tuberculose méningée","Une tuberculose rénale"],"r":1,"e":"Maladie de Pott = tuberculose VERTÉBRALE (spondylite tuberculeuse). Atteinte des vertèbres dorsales surtout, abcès paravertébral, cyphose typique ('gibbosité'). Risque neurologique (compression médullaire).","s":19},{"q":"Une TUBERCULOSE MILIAIRE est :","o":["Une forme bénigne, localisée à un lobe","Une dissémination par le sang, multi-organique","Une simple toux, persistante et sèche","Une pneumonie atypique, d'origine virale aiguë"],"r":1,"e":"TB miliaire = dissémination hématogène du BK → multiples micro-granulomes dans tous les organes (aspect de 'grains de mil' à la RX). Forme grave, urgence thérapeutique, risque méningite. Poumons, méninges et foie peuvent être touchés.","s":19},{"q":"Concernant la PHYSIOPATHOLOGIE de la TB :","o":["Le BK est phagocyté par les macrophages","Un granulome se forme, avec nécrose caséeuse","Une immunité cellulaire efficace le contrôle","Une réactivation est possible si immunodépression","L'infection est toujours symptomatique"],"r":[0,1,2,3],"e":"TB : inhalation BK → phagocytose macrophages → granulome caséeux (Langhans, lymphocytes) → contrôle immunitaire (90% restent ASYMPTOMATIQUES en TB latente) ou évolution maladie (10%). Réactivation si immunodépression.","s":19},{"q":"L'EMBOLIE PULMONAIRE est :","o":["Une infection pulmonaire, bactérienne","L'obstruction aiguë d'une artère pulmonaire","Une pneumonie lobaire franche","Un asthme aigu grave, avec bronchospasme et silence auscultatoire"],"r":1,"e":"EP = obstruction d'une branche de l'artère pulmonaire, le plus souvent par un thrombus migré depuis une TVP des membres inférieurs. Symptômes : douleur thoracique, dyspnée brutale, tachycardie, parfois hémoptysie. Le caillot vient souvent d'une TVP.","s":19},{"q":"L'ASPECT MILLET / 'grains de mil' à la radio thoracique évoque :","o":["Une pneumonie lobaire","Une tuberculose miliaire","Un épanchement pleural","Une bronchiolite"],"r":1,"e":"Image en 'grains de mil' (millet) = micronodules disséminés dans les 2 champs pulmonaires = TB miliaire (dissémination hématogène). Urgence thérapeutique.","s":19},{"q":"Concernant la PRISE EN CHARGE KINÉSITHÉRAPIQUE en pathologie respiratoire :","o":["Le désencombrement bronchique","Le réentraînement à l'effort","L'éducation respiratoire","La verticalisation post-aiguë","L'antibiothérapie directe"],"r":[0,1,2,3],"e":"Kiné respi : drainage des sécrétions, réentrainement à l'effort, éducation, ventilation dirigée, désinsufflation. Pas de prescription d'antibiotiques (rôle médical).","s":19},{"q":"Une COMPLICATION grave d'une pneumonie est :","o":["Pleurésie / empyème","Une simple congestion","Une rhinorrhée","Une éruption cutanée bénigne"],"r":0,"e":"Complications de pneumonie : pleurésie purulente (empyème), abcès pulmonaire, sepsis, SDRA, IRA, choc septique. Risque ↑ chez personnes âgées et fragiles.","s":19},{"q":"Concernant la BPCO (bronchopneumopathie chronique obstructive) :","o":["Une maladie respiratoire chronique","Le tabagisme, cause principale","Un VEMS/CV inférieur à 70 %","Une réversibilité totale, sous traitement","Un trouble obstructif non totalement réversible"],"r":[0,1,2,4],"e":"BPCO : maladie inflammatoire chronique des bronches, liée au tabac essentiellement. Trouble ventilatoire OBSTRUCTIF (VEMS/CV <70%) NON réversible (vs asthme). Évolution progressive avec exacerbations.","s":19},{"q":"Un PNEUMOTHORAX est :","o":["De l'air dans les bronches → emphysème","De l'air dans la cavité pleurale → collapsus","De l'eau dans les poumons → œdème","Une infection bronchique → toux"],"r":1,"e":"Pneumothorax = présence d'air dans la cavité pleurale → décollement pulmonaire → ↓ ventilation. Causes : spontané (jeune homme grand maigre), traumatique, iatrogène. Peut être compressif (urgence).","s":19},{"q":"Les PRÉCAUTIONS pour TUBERCULOSE pulmonaire bacillifère sont :","o":["Aucune précaution particulière","Un isolement aérien, masque filtrant pour les soignants","Un isolement gouttelettes, avec masque chirurgical","Un isolement de contact uniquement"],"r":1,"e":"TB bacillifère = précautions AÉRIENNES : chambre individuelle (pression négative idéalement), masque FFP2 pour soignants, masque chirurgical pour le patient. Isolement maintenu jusqu'à négativation des crachats (2-3 semaines de tx efficace). Les soignants portent un masque FFP2 ; le patient porte un masque chirurgical, en chambre seule.","s":19},{"q":"La bronchite aiguë est le plus souvent :","o":["Bactérienne, à pneumocoque","Virale, et auto-résolutive","Cancéreuse, chez le fumeur","Allergique, aux acariens de la literie"],"r":1,"e":"Bronchite aiguë : 90% virale, toux ± expectorations, auto-résolutive en 1-3 semaines.","s":19},{"q":"La pneumonie communautaire la plus fréquente est due à :","o":["Mycobacterium tuberculosis","Streptococcus pneumoniae, ou pneumocoque","Aspergillus fumigatus, champignon des sols humides","Le VIH, par immunodépression"],"r":1,"e":"Pneumocoque (Streptococcus pneumoniae) = 1ère cause de pneumonie communautaire.","s":19},{"q":"Les signes d'une pneumonie incluent :","o":["Fièvre","Toux productive","Douleur thoracique","Dyspnée","Râles crépitants à l'auscultation","Apyrexie totale"],"r":[0,1,2,3,4],"e":"Pneumonie : fièvre + toux + expectorations + douleur thoracique + crépitants ± dyspnée. Foyer radiographique.","s":19},{"q":"La tuberculose pulmonaire est causée par :","o":["Streptococcus pneumoniae, ou pneumocoque","Mycobacterium tuberculosis, ou BK","Un virus respiratoire, le VRS","Un champignon inhalé"],"r":1,"e":"BK = Mycobacterium tuberculosis, bacille acido-alcoolo-résistant (BAAR).","s":19},{"q":"La transmission de la tuberculose est :","o":["Sexuelle, par contact avec les muqueuses","Aérienne, par de fines gouttelettes","Sanguine uniquement, par transfusion","Alimentaire, par le lait"],"r":1,"e":"TB : transmission par voie aérienne (toux, parole), gouttelettes/aérosols, contagiosité forme bacillifère. Ces gouttelettes mesurent moins de 5 µm.","s":19},{"q":"L'IDR (intradermo-réaction) à la tuberculine teste :","o":["L'infection actuelle uniquement","Un contact passé ou présent avec le BK","Les anticorps circulants, dosés dans le sang","Le génome viral, par PCR"],"r":1,"e":"IDR : réaction d'hypersensibilité retardée → positive si contact (BCG, infection latente ou active). Elle est aussi positive après le BCG.","s":19},{"q":"Le traitement standard de la TB pulmonaire est :","o":["Un seul antibiotique pendant 1 mois","Une quadrithérapie de 2 mois, puis une bithérapie","Des antiviraux, pendant 10 jours","Aucun traitement, la guérison étant spontanée chez l'adulte"],"r":1,"e":"TB : quadrithérapie INH+RMP+EMB+PZA 2 mois → bithérapie INH+RMP 4 mois. La bithérapie dure 4 mois ; la quadrithérapie est dite RIPE.","s":19},{"q":"L'embolie pulmonaire (EP) est :","o":["Une infection du poumon, bactérienne","Une obstruction de l'artère pulmonaire","Une tumeur primaire du poumon, d'origine bronchique","Une bronchite aiguë, virale"],"r":1,"e":"EP : obstruction d'une branche de l'artère pulmonaire par un thrombus migré (souvent depuis MI - TVP). C'est souvent un caillot.","s":19},{"q":"Les signes évocateurs d'EP sont :","o":["Dyspnée brutale","Douleur thoracique","Tachycardie","Hémoptysie","Syncope","Bradycardie"],"r":[0,1,2,3,4],"e":"EP : dyspnée +++, douleur, tachycardie, hémoptysie, syncope (massive), désaturation. Tachy >> brady.","s":19},{"q":"L'examen de référence pour confirmer une EP est :","o":["La radiographie du thorax","L'angioscanner thoracique","L'échographie cardiaque, par voie transthoracique","L'électrocardiogramme"],"r":1,"e":"Angio-scanner thoracique = examen de référence pour le diagnostic de l'EP.","s":19},{"q":"Combien de causes respiratoires figurent dans le top 10 mondial des décès en 2021 ?","o":["4 sur 10","2 sur 10","6 sur 10","1 sur 10"],"r":0,"e":"BPCO, infections respiratoires inférieures, cancers broncho-pulmonaires et tuberculose.","s":19},{"q":"À quel rang mondial la tuberculose se situe-t-elle parmi les causes de décès en 2021 ?","o":["10e","4e","1re","20e"],"r":0,"e":"La BPCO est 4e, les infections respiratoires inférieures 5e et la tuberculose 10e.","s":19},{"q":"De quoi la pneumonie est-elle la première cause dans le monde ?","o":["De la mortalité infantile","De la mortalité chez les plus de 65 ans","Des cancers pulmonaires","Des hospitalisations en réanimation"],"r":0,"e":"La fiche souligne ce rôle dans la mortalité de l'enfant.","s":19},{"q":"Quels sont les trois mécanismes de défense physiologiques des voies respiratoires ?","o":["Le flux expiratoire, le tapis mucociliaire et la barrière","La toux, la fièvre et l'inflammation locale","Les macrophages, les neutrophiles et les lymphocytes","Le surfactant, le mucus et la vasoconstriction"],"r":0,"e":"La pneumonie survient quand ces défenses sont altérées ou l'immunité faible.","s":19},{"q":"Quelles situations suppriment le réflexe de toux selon la fiche ?","o":["La douleur thoracique, la chirurgie et l'anesthésie","Le tabagisme et l'inhalation de fumées","L'alcool et le tabac, consommés de façon chronique et massive","La mucoviscidose et l'obstruction bronchique"],"r":0,"e":"Le tabac altère plutôt la fonction mucociliaire et l'alcool les macrophages. Médicaments, AVC, sonde nasogastrique et troubles neuromusculaires en font aussi partie.","s":19},{"q":"Qu'est-ce qui réduit la capacité des macrophages alvéolaires ?","o":["L'alcool et le tabagisme","La fibrose kystique","Une sonde nasogastrique","Une anesthésie générale"],"r":0,"e":"La fiche associe alcool et tabac à cette baisse de capacité phagocytaire.","s":19},{"q":"Quelle est la deuxième étape histologique de la pneumonie ?","o":["L'hépatisation rouge, avec congestion et neutrophiles","L'hépatisation grise, avec des macrophages et de la fibrine","La résolution, avec restitution","L'œdème alvéolaire initial"],"r":0,"e":"Inhalation-œdème, hépatisation rouge, hépatisation grise puis résolution. Les globules rouges remplissent les alvéoles.","s":19},{"q":"Qu'est-ce qui caractérise l'hépatisation grise ?","o":["Des macrophages remplaçant les leucocytes, avec fibrine","Une congestion capillaire, avec globules rouges","L'exsudat œdémateux initial, riche en bactéries et en protéines","La restitution de l'architecture normale"],"r":0,"e":"Les macrophages assurent le nettoyage tardif, les neutrophiles la phase aiguë. Le poumon est consolidé.","s":19},{"q":"Quelle cellule alvéolaire produit le surfactant ?","o":["Le pneumocyte de type II","Le pneumocyte de type I","Le macrophage alvéolaire","Le neutrophile, ou PNN"],"r":0,"e":"Le pneumocyte I forme la paroi alvéolaire, le pneumocyte II sécrète le surfactant.","s":19},{"q":"Quelle proportion des pneumonies est communautaire ?","o":["60 à 80 %","20 %","95 %","40 %"],"r":0,"e":"La pneumonie communautaire est diagnostiquée dans les 48 h suivant l'admission.","s":19},{"q":"Quelle est la mortalité de la pneumonie nosocomiale ?","o":["20 à 50 %","Moins de 5 %","60 à 80 %","Environ 10 %"],"r":0,"e":"Elle est diagnostiquée au moins 48 h après l'admission, souvent à germes résistants.","s":19},{"q":"Quels germes dominent la pneumonie nosocomiale ?","o":["S. aureus, Pseudomonas et les entérobactéries","S. pneumoniae et H. influenzae","Mycoplasma et Chlamydia, atypiques","La flore anaérobie buccale, par aspiration lors des repas"],"r":0,"e":"La flore anaérobie buccale est responsable des pneumonies d'aspiration. Le MRSA, Klebsiella et Serratia en font partie.","s":19},{"q":"Quel lobe est préférentiellement atteint dans la pneumonie d'aspiration ?","o":["Le lobe inférieur droit","Le lobe supérieur gauche","Le lobe moyen","Les apex"],"r":0,"e":"L'anatomie bronchique droite, plus verticale, explique cette localisation.","s":19},{"q":"Quel aspect radiologique caractérise la bronchopneumonie ?","o":["Un aspect hétérogène, segmentaire ou multifocal","Une condensation lobaire, homogène et systématisée","Des opacités interstitielles réticulaires","Une image cavitaire apicale"],"r":0,"e":"Elle est souvent associée à la BPCO et aux bronchectasies.","s":19},{"q":"Quels germes sont responsables des pneumonies atypiques ?","o":["Mycoplasma, Chlamydia, Legionella et des virus","S. pneumoniae et S. aureus, en surinfection grippale","Klebsiella et Serratia","Bacteroides et Prevotella"],"r":0,"e":"Le début est insidieux, sans consolidation alvéolaire. Coxiella burnetii en fait aussi partie.","s":19},{"q":"Un trouble ventilatoire OBSTRUCTIF se définit en spirométrie par :","o":["Un VEMS/CV supérieur à 80 %","Un VEMS/CV inférieur à 70 %","Une CV diminuée seule, avec VEMS/CV normal","Une diffusion diminuée seule"],"r":1,"e":"Trouble ventilatoire obstructif (TVO) : VEMS/CV (rapport de Tiffeneau) <70% (post-bronchodilatateur). Caractérise BPCO, asthme, bronchectasies, mucoviscidose.","s":20},{"q":"La BPCO est caractérisée par :","o":["Une obstruction bronchique totalement réversible sous traitement","Une obstruction non entièrement réversible, liée au tabac","Une infection chronique des bronches","Une maladie auto-immune, systémique"],"r":1,"e":"BPCO = trouble ventilatoire obstructif PERSISTANT, NON entièrement réversible (vs asthme), inflammatoire chronique des bronches/poumons, principalement liée au tabac. Évolution progressive avec exacerbations. Elle s'accompagne d'une inflammation chronique.","s":20},{"q":"Quels sont les facteurs DE RISQUE de la BPCO ?","o":["Tabagisme actif","Tabagisme passif","Pollution atmosphérique / professionnelle","Déficit en α1-antitrypsine (génétique)","Activité physique régulière"],"r":[0,1,2,3],"e":"FdR BPCO : tabac (~90% des cas), tabac passif, pollution (extérieure et intérieure : biomasse), expositions professionnelles (silice, poussières), déficit en α1-antitrypsine. L'activité physique est protectrice.","s":20},{"q":"La classification GOLD de la BPCO repose principalement sur :","o":["L'âge du patient et l'ancienneté du tabagisme","Le VEMS, les symptômes et les exacerbations","La radiographie du thorax, ou RX","La SpO2 seule, au repos"],"r":1,"e":"Classification GOLD : sévérité spirométrique (GOLD 1 ≥80%, 2 50-79%, 3 30-49%, 4 <30% du VEMS prédit) + groupes symptômes/exacerbations (A, B, E). Le VEMS est mesuré après bronchodilatateur, en % de la valeur prédite.","s":20},{"q":"Symptômes typiques de la BPCO :","o":["Une dyspnée d'effort, puis de repos","Une toux chronique productive","Une expectoration chronique","Des sibilants à l'auscultation","Un début aigu, sans tabagisme"],"r":[0,1,2,3],"e":"Symptômes BPCO : dyspnée chronique progressive, toux + expectoration (>3 mois/an, 2 ans = bronchite chronique), sibilants, distension thoracique. Évolution INSIDIEUSE chez fumeur (≥10 paquets-année).","s":20},{"q":"Quels TRAITEMENTS sont utilisés dans la BPCO stable ?","o":["Le sevrage tabagique","Les bronchodilatateurs","Les corticoïdes inhalés, selon le profil","La réhabilitation respiratoire","Des antibiotiques au long cours"],"r":[0,1,2,3],"e":"Tx BPCO : sevrage tabagique (le PLUS efficace), bronchodilatateurs LABA/LAMA, ICS si éosinophilie/exacerbations, vaccination grippe + pneumocoque, oxygénothérapie longue durée si IRC, kiné/réhabilitation respiratoire. Antibiotiques uniquement en exacerbation. Les bronchodilatateurs sont des β2-mimétiques ou des anticholinergiques.","s":20},{"q":"L'ASTHME se distingue de la BPCO par :","o":["Une obstruction réversible sous bronchodilatateurs","Une obstruction non réversible","Une absence d'inflammation des bronches, éosinophile ou non","Une cause exclusivement tabagique"],"r":0,"e":"Asthme = obstruction RÉVERSIBLE (totalement ou partiellement) sous bronchodilatateurs ou spontanément. BPCO = obstruction non/peu réversible. Asthme : inflammation à éosinophiles, allergique souvent.","s":20},{"q":"Quels sont les SYMPTÔMES typiques de l'ASTHME ?","o":["Dyspnée variable / paroxystique","Sibilants","Toux (souvent nocturne)","Oppression thoracique","Stable et constante"],"r":[0,1,2,3],"e":"Asthme : symptômes VARIABLES dans le temps, ↑ la nuit / au petit matin, déclenchés par allergènes, effort, infection, froid, irritants. Typiquement : dyspnée + sibilants + toux + oppression thoracique.","s":20},{"q":"Concernant la PHYSIOPATHOLOGIE de l'asthme :","o":["Inflammation chronique des bronches","Hyperréactivité bronchique","Bronchospasme (contraction muscle lisse)","Hypersécrétion de mucus","Lésion alvéolaire avec emphysème"],"r":[0,1,2,3],"e":"Asthme = triade : inflammation chronique (éosinophiles, IgE), hyperréactivité bronchique, obstruction (bronchospasme + œdème + mucus). L'emphysème est une caractéristique de la BPCO, pas de l'asthme.","s":20},{"q":"Quels FACTEURS DÉCLENCHANTS d'une crise d'asthme ?","o":["Allergènes (acariens, pollens, animaux)","Effort physique (asthme d'effort)","Infections virales","Air froid, fumée","Aspirine et AINS chez certains patients","Les bêta-2 mimétiques inhalés"],"r":[0,1,2,3,4],"e":"Déclencheurs : allergènes, effort, infections virales (rhume), air froid, fumée, irritants chimiques, aspirine/AINS (asthme à AINS), reflux gastro-œsophagien, stress émotionnel. Les bêta-2 mimétiques sont le traitement de la crise : ils bronchodilatent au lieu de la déclencher.","s":20},{"q":"Le traitement de SECOURS de la crise d'asthme est :","o":["Les corticoïdes inhalés, 2 fois par jour","Un β2-mimétique de courte durée, le salbutamol","Des antibiotiques à large spectre","Des antihistaminiques, en sirop, pour calmer la toux nocturne"],"r":1,"e":"Tx de crise : β2-mimétiques courte durée (salbutamol/Ventoline) en aérosols-doseurs ou nébulisation. Si crise sévère : corticoïdes systémiques (oraux ou IV). Bronchodilatateur d'urgence.","s":20},{"q":"Le traitement de FOND de l'asthme persistant repose sur :","o":["Le salbutamol seul, à la demande, lors des crises","Les corticoïdes inhalés, avec un β2 longue durée","Des antibiotiques, en cures de 5 jours","Des antihistaminiques uniquement, oraux"],"r":1,"e":"Tx de fond asthme : CSI = pierre angulaire (anti-inflammatoire), associés à un LABA (β2 longue durée) si nécessaire. Selon sévérité : palier de Salford/GINA. Éducation thérapeutique cruciale. Le β2 de longue durée est ajouté si l'asthme est modéré à sévère.","s":20},{"q":"Une BRONCHIECTASIE / DDB (dilatation des bronches) est :","o":["Une dilatation transitoire et bénigne","Une dilatation irréversible des bronches","Une inflammation alvéolaire","Un cancer bronchique"],"r":1,"e":"DDB = dilatation IRRÉVERSIBLE et permanente des bronches avec destruction de la paroi (élastique, musculaire), entraînant accumulation de sécrétions et infections récurrentes. Causes : post-infectieuses, mucoviscidose, déficit immunitaire. Les parois bronchiques sont détruites.","s":20},{"q":"Symptômes des BRONCHIECTASIES :","o":["Toux chronique productive","Bronchorrhée importante (expectoration abondante)","Hémoptysies récurrentes","Infections respiratoires à répétition","Apparition brutale en 1 jour"],"r":[0,1,2,3],"e":"DDB : toux + bronchorrhée chronique (parfois plusieurs verres/jour, expectoration jaune-verte), hémoptysies fréquentes, infections récidivantes (Pseudomonas, H. influenzae). Évolution chronique progressive.","s":20},{"q":"L'examen de référence pour le diagnostic de BRONCHIECTASIES est :","o":["La radiographie du thorax, de face et de profil","Le scanner thoracique haute résolution","L'électrocardiogramme de repos","L'IRM cardiaque, injectée"],"r":1,"e":"TDM HR thoracique = examen de référence pour DDB : visualise la dilatation bronchique (bronches > artère adjacente, image 'en bague à chaton'), épaississement pariétal, mucus, atteintes sacculaires/cylindriques.","s":20},{"q":"L'EMPHYSÈME pulmonaire est :","o":["Une inflammation aiguë des bronches, réversible","Une destruction des parois alvéolaires, irréversible","Une infection bactérienne chronique, des alvéoles","Une tumeur bénigne du poumon"],"r":1,"e":"Emphysème : destruction irréversible des parois alvéolaires → hyperdistension distale, ↓ surface d'échange. Souvent associé à la BPCO. Centrolobulaire (tabac) ou panlobulaire (déficit α1-antitrypsine). Elle s'accompagne d'une hyperdistension.","s":20},{"q":"Une EXACERBATION de BPCO est définie par :","o":["Une amélioration transitoire des symptômes","Une aggravation aiguë des symptômes, à traiter","Le diagnostic initial de la maladie, posé par la spirométrie","La fin de l'évolution de la maladie"],"r":1,"e":"Exacerbation BPCO = aggravation aiguë des symptômes (dyspnée, toux, expectoration ± purulence) au-delà des variations quotidiennes, nécessitant une modification du traitement. Souvent infectieuse (virale ou bactérienne). Elle impose un changement de traitement et est souvent infectieuse.","s":20},{"q":"Concernant la KINÉSITHÉRAPIE RESPIRATOIRE dans la BPCO :","o":["Le désencombrement bronchique","Le réentraînement à l'effort","L'éducation thérapeutique","La réhabilitation respiratoire","Aucun bénéfice prouvé"],"r":[0,1,2,3],"e":"Kiné BPCO : désencombrement (AFE, ELTGOL), réentraînement à l'effort (vélo, marche), éducation, ventilation diaphragmatique, lèvres pincées, technique de toux. Réhabilitation respiratoire = bénéfice MAJEUR prouvé sur dyspnée et qualité de vie.","s":20},{"q":"Le SEVRAGE TABAGIQUE est :","o":["Inutile, les lésions étant irréversibles","La mesure la plus efficace contre l'évolution","Réservé aux jeunes fumeurs","Recommandé uniquement après 70 ans, chez le grand fumeur"],"r":1,"e":"Le sevrage tabagique est LA SEULE intervention qui ralentit le déclin du VEMS et améliore la survie en BPCO. À tout âge ! Outils : substitution nicotinique, varénicline, bupropion, accompagnement psychologique. Il réduit aussi la mortalité.","s":20},{"q":"L'OXYGÉNOTHÉRAPIE de longue durée (OLD) en BPCO est indiquée si :","o":["Une SpO2 normale, au repos et à l'effort","Une PaO2 d'au plus 55 mmHg, à l'état stable","Une dyspnée légère, sans hypoxémie","Toujours, dans toute BPCO, quel que soit le stade de la maladie"],"r":1,"e":"OLD : indiquée si PaO2 ≤55 mmHg en AA à l'état stable (ou 56-59 + HTAP, polyglobulie, ICD), ≥15h/jour (idéalement 18h+). Améliore la survie chez insuffisant respiratoire chronique hypoxémique. Le seuil passe à 56-59 mmHg en cas d'HTAP ou d'œdème ; l'O₂ est prise au moins 15 h par jour.","s":20},{"q":"Le tableau du « PINK PUFFER » (BPCO emphysémateuse) typique :","o":["Cyanosé, en surcharge, avec une polypnée minime","Maigre, dyspnéique, peu cyanosé, thorax distendu","Obèse, somnolent et cyanosé","Asymptomatique au repos, sans signe"],"r":1,"e":"Pink puffer (souffleur rose) : type EMPHYSÉMATEUX → maigre, distension thoracique majeure, dyspnée +++, peu cyanosé (PaO2 préservée par hyperventilation). Vs blue bloater (bronchitique chronique : obèse, cyanose, ICD).","s":20},{"q":"Un signe de DÉTRESSE RESPIRATOIRE majeur lors d'une crise d'asthme grave est :","o":["Des sibilants intenses et diffus","Une cyanose, un tirage et un silence auscultatoire","Une toux légère, sans gêne","Une FC normale, à 70 par minute, sans tachycardie associée"],"r":1,"e":"Crise d'asthme grave : tachycardie, polypnée, tirage, cyanose, difficulté à parler, agitation. SILENCE AUSCULTATOIRE = très grave (obstruction quasi-totale, plus de sibilants !). Urgence vitale → réa. La FR dépasse 30 par minute.","s":20},{"q":"Concernant la MUCOVISCIDOSE :","o":["Une maladie génétique, autosomique récessive","Un mucus épais et un encombrement bronchique","Une atteinte de plusieurs organes","Un diagnostic par le test de la sueur","Une maladie acquise, liée au tabagisme passif"],"r":[0,1,2,3],"e":"Mucoviscidose : maladie génétique (CFTR), mucus visqueux → encombrement bronchique chronique, infections récurrentes (Pseudomonas, S. aureus), insuffisance pancréatique. Diagnostic : test sueur, génétique. Pas tabac. Le gène en cause est CFTR ; pancréas, intestin et foie sont touchés.","s":20},{"q":"L'ASTHME D'EFFORT (AIE) :","o":["Survient au repos, la nuit, vers 4 h du matin","Apparaît 5 à 15 minutes après un effort intense","Ne peut pas être prévenu, même échauffé","N'est pas un asthme vrai, mais une gêne"],"r":1,"e":"Asthme d'effort : bronchospasme post-effort (5-15 min après), surtout après effort intense en air froid/sec. Prévention : β2-CDA 15 min avant l'effort, échauffement progressif, contrôle de l'asthme de fond.","s":20},{"q":"Le rôle des CORTICOSTÉROÏDES INHALÉS (CSI) dans l'asthme est :","o":["Un rôle bronchodilatateur immédiat","Un rôle anti-inflammatoire, sur les bronches","Un rôle antibiotique, préventif","Un rôle antitussif, en calmant la toux sèche de la nuit"],"r":1,"e":"CSI (béclométhasone, fluticasone, budésonide) : effet ANTI-INFLAMMATOIRE local. Pierre angulaire du Tx de fond. PAS de bronchodilatation immédiate (vs β2). À prendre quotidiennement même asymptomatique. Rincer la bouche après.","s":20},{"q":"Une maladie obstructive est caractérisée par :","o":["Une diminution de la capacité pulmonaire totale","Une limitation des débits expiratoires","Une atteinte interstitielle pure","Une atteinte musculaire"],"r":1,"e":"Obstructif : ↓ VEMS/CVF (Tiffeneau < 0,7) → asthme, BPCO, bronchectasies, mucoviscidose. Le VEMS/CVF est inférieur à 0,7.","s":20},{"q":"L'asthme est :","o":["Une obstruction fixe, définitive","Une obstruction bronchique réversible","Une fibrose pulmonaire, avec rayon de miel à la base","Une infection chronique"],"r":1,"e":"Asthme = obstruction réversible (spontanément ou sous bronchodilatateurs), inflammation chronique des bronches.","s":20},{"q":"Les médiateurs de la crise d'asthme incluent :","o":["Histamine","Leucotriènes","Prostaglandines","IgE","Insuline"],"r":[0,1,2,3],"e":"Asthme allergique : IgE → mastocytes → histamine, leucotriènes, prostaglandines → bronchoconstriction + inflammation.","s":20},{"q":"Le bronchodilatateur d'urgence dans la crise d'asthme est :","o":["Le salbutamol, β2-mimétique","Un antibiotique oral","Un antihistaminique, en sirop","Un diurétique, 1 fois par jour"],"r":0,"e":"Salbutamol (Ventolin) = β2-agoniste de courte durée, traitement de la crise. Il agit en courte durée.","s":20},{"q":"La BPCO se définit par :","o":["Un asthme aigu, totalement réversible sous BD","Une obstruction non entièrement réversible","Une fibrose pulmonaire, restrictive","Une tumeur bronchique"],"r":1,"e":"BPCO : obstruction non entièrement réversible (VEMS/CVF<0,7 après bronchodilatateur), souvent liée au tabac. Le VEMS/CVF reste inférieur à 0,7 après bronchodilatateur.","s":20},{"q":"La cause principale de BPCO dans les pays développés est :","o":["Asthme","Tabagisme actif ou passif","Infections récurrentes","Pollution seule"],"r":1,"e":"BPCO : 80-90% liée au tabagisme (actif ou passif). Autres : pollution, professions exposées, déficit α1-antitrypsine.","s":20},{"q":"La BPCO englobe :","o":["La bronchite chronique","L'emphysème pulmonaire","L'asthme allergique pur","La mucoviscidose"],"r":[0,1],"e":"BPCO = bronchite chronique (clinique) + emphysème (anatomopathologique : destruction alvéolaire). La bronchite chronique associe toux et expectoration au moins 3 mois par an, 2 ans de suite.","s":20},{"q":"L'emphysème pan-lobulaire est associé à :","o":["Le tabagisme, à 20 paquets-années","Le déficit en α1-antitrypsine","L'asthme ancien","L'allergie aux acariens"],"r":1,"e":"Emphysème pan-lobulaire = destruction homogène, associé à déficit α1-antitrypsine. Centro-lobulaire = tabac.","s":20},{"q":"La saturation en O₂ (SpO₂) normale est :","o":["≥ 95%","85%","70%","100% obligatoire"],"r":0,"e":"SpO₂ normale ≥ 95% à l'air ambiant. < 90% = insuffisance respiratoire (hypoxémie).","s":20},{"q":"L'oxygénothérapie longue durée (OLD) dans la BPCO est indiquée :","o":["Si la SpO₂ est inférieure à 95 %","Si la PaO₂ est sous 55 mmHg, voire 60 mmHg","Pour tous les patients atteints","Jamais, l'oxygène aggravant toujours la BPCO"],"r":1,"e":"OLD : PaO₂ < 55 mmHg, ou < 60 mmHg + polyglobulie/HTAP/cœur pulmonaire chronique. ≥ 15h/jour. Le seuil de 60 mmHg vaut en cas de polyglobulie ou d'HTAP.","s":20},{"q":"Quelle est la prévalence mondiale actuelle de la BPCO selon la fiche ?","o":["10,3 %","23 %","6 %","56 %"],"r":0,"e":"La prévision est de 23 % d'ici 2050.","s":20},{"q":"Quelle part des dépenses de santé de l'Union européenne les maladies respiratoires représentent-elles ?","o":["6 %, dont 56 % liés à la BPCO","23 %, dont la moitié pour l'asthme","10,3 %, dont 30 % liés au cancer du poumon","1 %, faute de BPCO"],"r":0,"e":"La BPCO pèse pour plus de la moitié de ce poste de dépenses.","s":20},{"q":"Quelle mutation génétique est associée au déficit en alpha-1-antitrypsine ?","o":["SERPINA1","SOD1","APOE-ε4","CFTR"],"r":0,"e":"Ce déficit est le principal facteur génétique de BPCO.","s":20},{"q":"Quel déséquilibre enzymatique aboutit à la destruction de la paroi alvéolaire ?","o":["Le déséquilibre protéase / antiprotéase","Le déséquilibre MMP / TIMP osseux","Le déséquilibre RANK / RANKL","Le déséquilibre COX-1 / COX-2"],"r":0,"e":"Le stress oxydatif et l'inflammation aboutissent à cet excès de protéases.","s":20},{"q":"Quelles conséquences mécaniques l'obstruction bronchique entraîne-t-elle dans la BPCO ?","o":["Un piégeage d'air et une hyperinflation","Une réduction de la capacité pulmonaire totale","Une augmentation de la compliance alvéolaire uniquement","Une baisse du volume résiduel"],"r":0,"e":"Le piégeage et l'hyperinflation s'accompagnent d'anomalies des échanges gazeux.","s":20},{"q":"Quelles causes la fiche donne-t-elle aux modifications musculaires de la BPCO ?","o":["L'hypoxémie, l'inflammation et l'inactivité physique","Uniquement le tabagisme actif","Uniquement la dénutrition sévère","Uniquement les corticoïdes, pris au long cours par voie orale"],"r":0,"e":"L'inactivité physique est un facteur aggravant sur lequel la rééducation peut agir. L'âge et le stress oxydatif y contribuent aussi.","s":20},{"q":"Quel VEMS définit le stade GOLD 3 ?","o":["Entre 30 et 50 % de la valeur prédite","Au moins 80 % de la valeur prédite","Entre 50 et 80 % de la valeur prédite","Moins de 30 % de la valeur prédite"],"r":0,"e":"GOLD 1 ≥ 80 %, GOLD 2 50-80 %, GOLD 3 30-50 %, GOLD 4 < 30 %.","s":20},{"q":"Sur quel VEMS la classification GOLD est-elle fondée ?","o":["Le VEMS post-bronchodilatateur","Le VEMS pré-bronchodilatateur","La capacité vitale forcée","La capacité pulmonaire totale"],"r":0,"e":"Tous les grades supposent en outre un rapport VEMS/CVF inférieur à 0,7.","s":20},{"q":"Qu'est-ce que la pré-BPCO ?","o":["Un VEMS bas ou une hyperinflation, avec un rapport préservé","Un stade GOLD 1 débutant, très léger","Une BPCO sans aucun symptôme, découverte au hasard","Un asthme ancien, devenu fixé avec le temps chez le fumeur"],"r":0,"e":"Le ratio préservé exclut le critère diagnostique classique. Le rapport VEMS/CVF reste préservé ; le piégeage gazeux est possible.","s":20},{"q":"Quel traitement initial la GOLD 2024 propose-t-elle pour le groupe A ?","o":["Un bronchodilatateur","LABA + LAMA","LABA + LAMA + ICS","Une corticothérapie orale"],"r":0,"e":"Les groupes B et E reçoivent d'emblée LABA + LAMA.","s":20},{"q":"Quel critère définit le groupe E de la classification ABE ?","o":["Au moins 2 exacerbations, ou 1 hospitalisation","Un score mMRC d'au moins 2","Un VEMS inférieur à 30 % de la valeur théorique prédite","Aucune exacerbation, sur l'année"],"r":0,"e":"Le groupe E peut recevoir un ICS si les éosinophiles sont ≥ 300/µL. Les exacerbations sont modérées.","s":20},{"q":"Quel seuil d'éosinophiles justifie l'ajout d'un corticoïde inhalé dans le groupe E ?","o":["300/µL ou plus","100/µL","1 000/µL","50/µL"],"r":0,"e":"Ce seuil oriente vers une inflammation de type 2, sensible aux corticoïdes inhalés.","s":20},{"q":"Que recouvre la méthode 5A d'aide au sevrage tabagique ?","o":["Ask, Advise, Assess, Assist, Arrange","Assess, Analyse, Adapt, Act, Assure","Ask, Act, Apply, Adjust, Assess","Advise, Avoid, Assist, Adapt, Arrange"],"r":0,"e":"Identifier, conseiller, évaluer la motivation, soutenir et organiser le suivi.","s":20},{"q":"Quelles vaccinations la fiche recommande-t-elle dans la BPCO ?","o":["La grippe, le pneumocoque, le COVID et le zona","La grippe uniquement, chaque automne, à 65 ans","Le BCG, contre la tuberculose","L'hépatite B, chez les soignants"],"r":0,"e":"Ces vaccinations réduisent les exacerbations infectieuses. La coqueluche et le VRS en font aussi partie.","s":20},{"q":"Quelle association a démontré une réduction de mortalité dans les essais IMPACT et ETHOS ?","o":["LABA + LAMA + ICS","LAMA seul","LABA seul","Les corticoïdes oraux"],"r":0,"e":"Cette trithérapie concerne les patients symptomatiques à exacerbations fréquentes ou sévères.","s":20},{"q":"Un trouble ventilatoire RESTRICTIF se définit en spirométrie par :","o":["Un VEMS/CV diminué, sous 70 %","Une CPT inférieure à 80 % de la prédite","Une CV augmentée, au-delà de 120 % de la valeur prédite","Une obstruction des bronches"],"r":1,"e":"Trouble ventilatoire restrictif (TVR) = ↓ CPT (<80% prédit), avec CV ↓ et VEMS/CV NORMAL ou augmenté. Distinction importante avec le trouble obstructif (VEMS/CV <70%). La CPT est la capacité pulmonaire totale.","s":21},{"q":"Concernant les TROUBLES RESTRICTIFS EXTRINSÈQUES (cage thoracique) :","o":["Cyphoscoliose sévère","Obésité majeure","Maladies neuromusculaires (myasthénie, SLA)","Pleurésies massives","Fibrose pulmonaire idiopathique"],"r":[0,1,2,3],"e":"Restrictifs extrinsèques : déformations rachidiennes (cyphoscoliose), obésité, troubles neuromusculaires (paralysie diaphragmatique, SLA, Guillain-Barré, myopathies), pathologie pleurale, ascite massive. La fibrose = INTRINSÈQUE (parenchyme).","s":21},{"q":"Concernant les TROUBLES RESTRICTIFS INTRINSÈQUES (parenchyme) :","o":["La fibrose pulmonaire idiopathique","La sarcoïdose","Les pneumoconioses, comme la silicose","Les connectivites atteignant le poumon","L'asthme bronchique, allergique ou non"],"r":[0,1,2,3],"e":"Restrictifs intrinsèques (parenchyme) : MIP (maladies interstitielles), FPI, sarcoïdose, pneumoconioses (silice, amiante), connectivites (PR, sclérodermie), pneumonies organisées. L'asthme = OBSTRUCTIF.","s":21},{"q":"La FIBROSE PULMONAIRE IDIOPATHIQUE (FPI) est :","o":["Réversible sous corticoïdes","Une maladie chronique progressive, de cause inconnue","Une infection pulmonaire chronique","Une tumeur du poumon, d'évolution lente et souvent bénigne"],"r":1,"e":"FPI : maladie chronique progressive de cause inconnue, fibrose interstitielle prédominante aux bases. Pronostic réservé (médiane de survie 3-5 ans). Tx : antifibrotiques (pirfénidone, nintédanib), transplantation. Elle comporte une fibrose interstitielle.","s":21},{"q":"Manifestations cliniques classiques des MALADIES INTERSTITIELLES PULMONAIRES (MIP) :","o":["Dyspnée d'effort progressive","Toux sèche persistante","Râles crépitants 'velcro' aux bases","Hippocratisme digital","Sibilants et ronchi prédominants"],"r":[0,1,2,3],"e":"MIP : dyspnée d'effort progressive, toux sèche, crépitants 'secs' type velcro aux bases (fin d'inspiration), hippocratisme digital (fibrose chronique), désaturation à l'effort. Sibilants/ronchi = obstructif.","s":21},{"q":"La SARCOÏDOSE est :","o":["Une infection bactérienne, à mycobactérie atypique","Une maladie systémique à granulomes non caséeux","Une tumeur maligne du médiastin","Une maladie infectieuse virale"],"r":1,"e":"Sarcoïdose : maladie inflammatoire systémique avec granulomes EPITHELIOÏDES sans nécrose CASÉEUSE (vs TB). Atteinte préférentielle pulmonaire (adénopathies hilaires, MIP), peau, yeux, foie, etc. Étiologie inconnue. Elle est inflammatoire et sans cause identifiée.","s":21},{"q":"Une PNEUMOCONIOSE est :","o":["Une infection respiratoire, contractée au travail","Une fibrose due à des poussières inhalées","Une tumeur bénigne de la plèvre","Une affection allergique, saisonnière"],"r":1,"e":"Pneumoconioses = maladies professionnelles dues à l'inhalation chronique de poussières minérales : silicose (silice), asbestose (amiante), anthracose (charbon), bérylliose, etc. Évolution vers fibrose. Ce sont la silice, l'amiante ou le charbon.","s":21},{"q":"L'ASBESTOSE :","o":["Est due à l'amiante","Est due au tabagisme","Est une infection","Est une tumeur"],"r":0,"e":"Asbestose : fibrose pulmonaire due à l'exposition chronique à l'AMIANTE (asbeste). Risque accru de mésothéliome pleural et de cancer bronchique (synergique avec tabac). Maladie professionnelle reconnue.","s":21},{"q":"L'ÉPANCHEMENT PLEURAL est :","o":["De l'air dans la cavité pleurale","Du liquide en excès dans la cavité pleurale","Une fibrose pleurale, après inflammation","Une tumeur pleurale, primitive ou secondaire à un cancer"],"r":1,"e":"Épanchement pleural = accumulation de liquide dans l'espace pleural. Pneumothorax = AIR. Hémothorax = SANG. Pyothorax/empyème = pus. Chylothorax = lymphe.","s":21},{"q":"Concernant les TRANSSUDATS pleuraux :","o":["Un liquide pauvre en protéines","L'insuffisance cardiaque ou la cirrhose","Un épanchement souvent bilatéral","Une absence de cellules inflammatoires","Un liquide riche en protéines, inflammatoire"],"r":[0,1,2,3],"e":"Transsudat : ↓ protéines, peu cellulaire, mécanisme MÉCANIQUE (↑ pression hydrostatique = ICC ou ↓ pression oncotique = cirrhose, hypoalbuminémie). Souvent bilatéral. Pas inflammatoire. Les protéines sont sous 30 g/L ; le syndrome néphrotique en est une autre cause.","s":21},{"q":"Concernant les EXSUDATS pleuraux :","o":["Un liquide riche en protéines","Une pneumonie, un cancer ou une embolie","Une origine inflammatoire","Un épanchement souvent unilatéral","Une origine toujours cardiaque"],"r":[0,1,2,3],"e":"Exsudat : ↑ protéines, cellulaire, origine INFLAMMATOIRE (perméabilité capillaire ↑ ou drainage lymphatique altéré). Causes : pneumonie, cancer, EP, TB, connectivites. Critères de Light pour différencier. Les protéines dépassent 30 g/L ; la tuberculose en est une autre cause.","s":21},{"q":"L'EMPYÈME est :","o":["Un transsudat, par insuffisance cardiaque gauche","Un exsudat purulent, dans la cavité pleurale","De l'air dans la plèvre","Du sang dans la plèvre"],"r":1,"e":"Empyème = présence de pus dans la cavité pleurale (pleurésie purulente), souvent compliquant une pneumonie bactérienne. Diagnostic : ponction → liquide trouble/purulent, pH bas, glucose bas. Tx = drainage + antibiothérapie.","s":21},{"q":"L'examen physique d'un épanchement pleural montre typiquement :","o":["Un tympanisme et des sibilants","Une matité et une abolition des vibrations vocales","Des râles crépitants diffus, aux deux bases, en fin d'inspiration","Un wheezing expiratoire, diffus"],"r":1,"e":"Sd d'épanchement pleural liquidien : MATITÉ percussion + ABOLITION des vibrations vocales + ABOLITION du murmure vésiculaire (parfois souffle pleural en haut de l'épanchement). Le murmure vésiculaire est aussi aboli.","s":21},{"q":"Le PNEUMOTHORAX est :","o":["Du liquide pleural → matité","De l'air dans la cavité pleurale → collapsus","Du sang dans le poumon → hémoptysie","Une infection de la plèvre → pleurésie purulente fébrile"],"r":1,"e":"Pneumothorax = présence d'air dans la cavité pleurale. Spontané (rupture de bulle, jeune homme grand maigre), traumatique, iatrogène (post-ponction, ventilation). Peut être COMPRESSIF (urgence).","s":21},{"q":"Symptômes typiques du PNEUMOTHORAX :","o":["Une douleur thoracique brutale","Une dyspnée aiguë","Une toux sèche","Une hypersonorité, murmure aboli","Des râles crépitants"],"r":[0,1,2,3],"e":"Pneumothorax : douleur thoracique brutale latéralisée, dyspnée, toux sèche. Examen : HYPERSONORITÉ percussion + abolition du murmure vésiculaire + abolition des vibrations vocales. RX confirme.","s":21},{"q":"Un pneumothorax COMPRESSIF (suffocant) est :","o":["Bénin → simple surveillance, à domicile","Une urgence vitale → exsufflation immédiate","Sans symptôme → découverte fortuite","Spontanément résolutif → repos"],"r":1,"e":"Pneumothorax compressif/suffocant : air sous tension comprime médiastin, vaisseaux, poumon controlatéral → choc obstructif → décès rapide. URGENCE : exsufflation à l'aiguille en 2e EIC ligne médio-claviculaire puis drainage thoracique. Il comprime le médiastin.","s":21},{"q":"Un HÉMOTHORAX correspond à :","o":["De l'air dans la plèvre","Du sang dans la cavité pleurale","De l'eau dans la plèvre","Du pus dans la plèvre, par une infection grave"],"r":1,"e":"Hémothorax = sang dans la cavité pleurale. Causes : traumatique (le plus souvent), iatrogène, néoplasique, anévrismale. Tx = drainage thoracique, surveillance saignement, parfois chirurgie. Il est souvent traumatique.","s":21},{"q":"Le MÉSOTHÉLIOME PLEURAL est :","o":["Une tumeur bénigne fréquente, sans lien avec le travail","Une tumeur maligne rare, liée à l'amiante","Une infection de la plèvre","Une atrophie de la plèvre"],"r":1,"e":"Mésothéliome pleural malin : tumeur agressive primitive de la plèvre, fortement liée à l'exposition à l'amiante (avec long délai 20-40 ans). Pronostic très sombre. Maladie professionnelle indemnisable. Elle touche la plèvre.","s":21},{"q":"Concernant la PRISE EN CHARGE KINÉSITHÉRAPIQUE des troubles restrictifs :","o":["Le réentraînement à l'effort","Le travail de la ventilation thoraco-abdominale","Le maintien des amplitudes thoraciques","Le drainage bronchique, si besoin","Aucun bénéfice prouvé, à ce jour"],"r":[0,1,2,3],"e":"Kiné restrictif : réentraînement à l'effort, ventilation dirigée (diaphragmatique), assouplissement thoracique, désencombrement, oxygénothérapie d'effort. Améliore la qualité de vie et la dyspnée.","s":21},{"q":"Les râles crépitants dits 'velcro' sont caractéristiques de :","o":["L'asthme, en crise sévère nocturne","La fibrose pulmonaire, interstitielle","La BPCO, en exacerbation infectieuse","Le pneumothorax, spontané du jeune"],"r":1,"e":"Crépitants 'velcro' : crépitants secs, fins, en fin d'inspiration, prédominant aux bases. Caractéristiques de la fibrose pulmonaire idiopathique et autres MIP. Évoquent une atteinte interstitielle.","s":21},{"q":"L'HIPPOCRATISME DIGITAL (clubbing) :","o":["Est un signe de bronchite chronique simple, sans gravité","Traduit souvent une hypoxie chronique","N'a aucune signification","Est une malformation congénitale"],"r":1,"e":"Hippocratisme digital : déformation des doigts en baguette de tambour avec ongles bombés. Causes : hypoxémie chronique (MIP, mucoviscidose, cardiopathie cyanogène), cancer broncho-pulmonaire, MICI. Mécanisme mal compris. Il se voit dans les MIP, la BPCO sévère et le cancer broncho-pulmonaire.","s":21},{"q":"Le DIAGNOSTIC d'un trouble restrictif repose sur :","o":["La spirométrie seule, avec le rapport VEMS/CV","La pléthysmographie, qui mesure la CPT","La radiographie seule","La seule DLCO, sans mesure des volumes"],"r":1,"e":"TVR confirmé par pléthysmographie (CPT <80% prédit). EFR complémentaires : DLCO (capacité de diffusion CO) souvent ↓ dans les MIP. Spirométrie seule insuffisante (mesure VEMS/CV).","s":21},{"q":"Causes IATROGÈNES de fibrose pulmonaire :","o":["Amiodarone","Méthotrexate","Bléomycine (chimiothérapie)","Radiothérapie thoracique","Antibiotiques courants"],"r":[0,1,2,3],"e":"Médicaments pneumotoxiques : amiodarone (cordarone), méthotrexate (PR), bléomycine (cancer testiculaire), radiothérapie. Toujours évoquer en cas de toux/dyspnée chez patient sous ces traitements.","s":21},{"q":"Une PLEURÉSIE est :","o":["Une inflammation de la plèvre, avec épanchement","Une infection bronchique","Un trouble alvéolaire, diffus","Un cancer pulmonaire, avec des métastases pleurales"],"r":0,"e":"Pleurésie = inflammation de la plèvre, souvent associée à un épanchement liquidien. Causes : infectieuses (pneumonie, TB), tumorales, cardiaques (transsudat ICC), inflammatoires (PR, lupus).","s":21},{"q":"Le rôle du KINÉSITHÉRAPEUTE dans la PLEURÉSIE est :","o":["Drainer chirurgicalement la plèvre","Aider la réexpansion pulmonaire et prévenir les synéchies","Prescrire des antibiotiques, adaptés à l'antibiogramme du liquide","Laisser le patient au repos strict"],"r":1,"e":"Kiné post-pleurésie : ventilation dirigée pour réexpansion pulmonaire, mobilisation thoracique, prévention des séquelles fibrotiques (pachypleurite). Ne réalise pas le drainage chirurgical. Il incite à l'inspiration et prévient la pachypleurite.","s":21},{"q":"Une maladie restrictive est caractérisée par :","o":["Un VEMS/CVF abaissé, sous 0,7","Une CPT basse avec un VEMS/CVF normal","Une obstruction réversible, en crise","Une infection chronique"],"r":1,"e":"Restrictif : ↓ CPT (capacité pulmonaire totale), VEMS/CVF normal ou élevé. Causes : fibrose, atteintes pariétales, neuro-musculaires.","s":21},{"q":"La pneumopathie d'hypersensibilité (alvéolite allergique extrinsèque) est due à :","o":["Une infection bactérienne chronique","L'inhalation répétée d'antigènes organiques","Une inhalation de fibres d'amiante, sur des années de chantier","Une cause strictement génétique"],"r":1,"e":"Ce sont les « poumons de fermier » et « poumons d'éleveur d'oiseaux » : une réaction immunitaire à des antigènes organiques inhalés, réversible à la phase aiguë si l'exposition cesse, mais qui évolue vers la fibrose en cas d'exposition prolongée. L'éviction de l'antigène est le traitement clé. Moisissures du foin et déjections d'oiseaux en sont des exemples.","s":21},{"q":"L'image radiologique typique de la FPI est :","o":["Une pneumonie lobaire franche","Un rayon de miel sous-pleural","Une cavité apicale","Une atélectasie lobaire"],"r":1,"e":"FPI : pattern UIP (Usual Interstitial Pneumonia) = rayon de miel sous-pleural, bronchectasies de traction, prédominance basale.","s":21},{"q":"Les causes de pneumopathies interstitielles connues incluent :","o":["Des médicaments, comme l'amiodarone","Des connectivites, comme la sclérodermie","Des pneumoconioses, comme la silicose","Des pneumonies d'hypersensibilité","Un tabagisme modéré et ancien"],"r":[0,1,2,3],"e":"PI secondaires : médicaments, connectivites, expositions pro (silice, amiante), hypersensibilité (poumon d'éleveur).","s":21},{"q":"L'asbestose est une maladie due à :","o":["Des bactéries, inhalées","L'inhalation chronique de fibres d'amiante","Un virus respiratoire, contracté sur un chantier","Un parasite pulmonaire"],"r":1,"e":"Asbestose = fibrose pulmonaire par inhalation prolongée de fibres d'amiante (mineurs, BTP). Risque de cancer + mésothéliome.","s":21},{"q":"Le syndrome de Löfgren associe :","o":["Fièvre, érythème noueux, adénopathies hilaires et arthralgies","Hémoptysie, amaigrissement et sueurs nocturnes","Dyspnée d'effort, hippocratisme digital et râles velcro aux bases","Douleur thoracique brutale et murmure aboli"],"r":0,"e":"C'est la forme aiguë et de bon pronostic de la sarcoïdose : elle régresse spontanément dans la grande majorité des cas. Sa reconnaissance évite des explorations invasives, la biopsie n'étant alors pas indispensable.","s":21},{"q":"L'épanchement pleural restrictif compresse :","o":["Le poumon, dont la capacité baisse","Le cœur seul, par tamponnade","Le rein, par compression de la loge et de l'uretère","Le foie, sous la coupole droite"],"r":0,"e":"Épanchement pleural massif → restriction par compression du poumon, ↓ CPT et capacité ventilatoire.","s":21},{"q":"Les causes neuromusculaires de syndrome restrictif incluent :","o":["La myasthénie auto-immune","La sclérose latérale amyotrophique","Le syndrome de Guillain-Barré","Une lésion médullaire haute","L'asthme allergique, en crise"],"r":[0,1,2,3],"e":"Neuromusculaires : SLA, GBS, myasthénie, polio, lésions médullaires (au-dessus de C4) → atteinte respiratoire restrictive.","s":21},{"q":"La cyphoscoliose sévère provoque :","o":["Un syndrome obstructif","Un syndrome restrictif, par déformation","Une infection pulmonaire, par encombrement chronique","Un cancer du poumon, à terme"],"r":1,"e":"Cyphoscoliose sévère → restriction par déformation de la cage thoracique, ↓ CPT, peut évoluer vers IRC.","s":21},{"q":"Le traitement de la fibrose pulmonaire idiopathique inclut :","o":["Des antibiotiques au long cours","Des antifibrotiques, comme le nintédanib","Des antihistaminiques, contre la composante allergique","Aucun traitement disponible"],"r":1,"e":"FPI : antifibrotiques (pirfénidone, nintédanib) ralentissent la progression. Transplantation pulmonaire si éligible. La pirfénidone est l'autre antifibrotique.","s":21},{"q":"À quelles altérations tissulaires la réduction d'expansion du parenchyme est-elle liée ?","o":["Aux altérations du tissu conjonctif et du collagène","À une destruction des alvéoles par les protéases","À une bronchoconstriction","À une hypersécrétion de mucus"],"r":0,"e":"Le trouble restrictif est un trouble de compliance, non d'obstruction.","s":21},{"q":"Quelle évolution la compliance pulmonaire suit-elle dans un trouble restrictif ?","o":["Elle diminue","Elle augmente","Elle reste normale","Elle augmente puis diminue"],"r":0,"e":"Elle augmente au contraire dans les troubles obstructifs, comme la capacité pulmonaire totale.","s":21},{"q":"Comment se comporte la CVF dans un trouble obstructif pur ?","o":["Elle est normale ou légèrement diminuée","Elle est nettement diminuée, de plus de moitié","Elle est augmentée, par piégeage","Elle est quasi nulle"],"r":0,"e":"Dans le trouble restrictif, VEMS et CVF baissent proportionnellement, d'où un rapport conservé.","s":21},{"q":"Quel est le critère distinctif du syndrome restrictif en spirométrie ?","o":["Un VEMS et une CPT bas, avec un rapport conservé","Un rapport VEMS/CVF inférieur à 0,7, abaissé","Une augmentation du volume résiduel, piégé","Une compliance pulmonaire augmentée"],"r":0,"e":"Le rapport conservé, associé à une CPT abaissée, signe la restriction. Le rapport conservé est le VEMS/CVF.","s":21},{"q":"Quel mécanisme explique la restriction dans l'obésité sévère ?","o":["La graisse limite le diaphragme, d'où une hypoventilation","Une fibrose interstitielle diffuse, liée à l'inflammation du tissu","Une inflammation des parois alvéolaires","Une destruction des cils bronchiques"],"r":0,"e":"L'obésité est une cause extrinsèque, de même que les maladies pleurales et neuromusculaires. Il rétrécit aussi les voies aériennes supérieures et altère le rapport V/Q.","s":21},{"q":"Quelles causes de restriction sont dites extrinsèques ?","o":["L'obésité, la cyphoscoliose et les maladies pleurales","La fibrose pulmonaire idiopathique et la sarcoïdose pulmonaire","Les pneumoconioses, comme l'asbestose","Les connectivites, comme le lupus"],"r":0,"e":"Les causes intrinsèques concernent le parenchyme lui-même. Les maladies neuromusculaires en font aussi partie.","s":21},{"q":"Quels mécanismes étiologiques la fiche retient-elle pour les maladies interstitielles ?","o":["L'exposition professionnelle, le tabac, l'âge et l'immunité","Uniquement le tabagisme, actif ou passif, sur plusieurs décennies","Uniquement l'exposition à l'amiante","Uniquement les infections virales"],"r":0,"e":"Ces cinq mécanismes recouvrent l'ensemble des MIP. Les facteurs génétiques en font aussi partie.","s":21},{"q":"Combien de catégories de maladies interstitielles la fiche distingue-t-elle ?","o":["5","3","4","6"],"r":0,"e":"Primaires, environnementales, iatrogènes, connectivites et idiopathiques.","s":21},{"q":"À quelle catégorie de MIP la sarcoïdose appartient-elle ?","o":["Aux maladies primaires","Aux expositions environnementales","Aux formes iatrogènes","Aux idiopathiques"],"r":0,"e":"La FPI est la principale forme idiopathique, les pneumoconioses sont environnementales.","s":21},{"q":"Quelle anomalie est présente à tous les stades des maladies interstitielles ?","o":["Un septum alvéolaire épaissi, avec une barrière accrue","La prolifération des fibroblastes","La formation de cavités, par nécrose étendue du parenchyme","Une hyperinflation, par piégeage"],"r":0,"e":"La prolifération du tissu conjonctif et des fibroblastes n'apparaît qu'aux stades avancés. C'est la barrière alvéolo-capillaire qui s'épaissit.","s":21},{"q":"Quelles cellules interviennent dans la cascade inflammatoire des MIP ?","o":["Des macrophages, des lymphocytes T et des neutrophiles","Uniquement les mastocytes, du derme","Uniquement les éosinophiles, comme dans l'asthme allergique","Uniquement les plasmocytes, producteurs d'anticorps"],"r":0,"e":"Elles libèrent des médiateurs pro-fibrotiques qui aboutissent à la fibrose.","s":21},{"q":"Quel type de crépitants caractérise les maladies interstitielles ?","o":["Des crépitements secs, dits « velcro »","Des sibilants expiratoires, diffus","Des ronchi, à la toux","Un souffle tubaire, en foyer"],"r":0,"e":"Ces crépitants inspiratoires secs sont très évocateurs de fibrose.","s":21},{"q":"Quelle taille ont les nodules radiologiques décrits dans les MIP ?","o":["1 à 5 mm, avec un aspect en nid d'abeille","1 à 5 cm, avec un aspect de lâcher de ballons","Moins de 0,5 mm, invisibles","Plus de 2 cm, en masse"],"r":0,"e":"L'aspect en rayon de miel traduit la fibrose évoluée.","s":21},{"q":"Comment évolue la gazométrie dans les maladies interstitielles ?","o":["D'une hypoxémie seule vers une hypercapnie tardive","D'une hypercapnie initiale vers une hypoxémie","Elle reste normale, à tous les stades","Elle montre une alcalose métabolique, par perte rénale d'acide"],"r":0,"e":"L'hypercapnie traduit l'épuisement ventilatoire tardif.","s":21},{"q":"Quel est le mécanisme d'action du nintédanib ?","o":["C'est un anti-fibrotique inhibiteur de tyrosine kinase","C'est un corticoïde inhalé, anti-inflammatoire","C'est un bronchodilatateur, de longue durée","C'est un antibiotique, de la famille des macrolides"],"r":0,"e":"La pirfénidone est l'autre anti-fibrotique cité, à action anti-inflammatoire.","s":21},{"q":"Une NÉOPLASIE est :","o":["Un retour des tissus à leur état normal","Une prolifération cellulaire anormale et autonome","Une simple inflammation, sans aucune prolifération cellulaire","Une atrophie des tissus, par perte"],"r":1,"e":"Néoplasie = nouvelle formation tissulaire par prolifération cellulaire anormale, autonome (échappe à la régulation du tissu), pouvant être bénigne ou maligne. 'Tumeur' = synonyme. Elle échappe aux contrôles physiologiques.","s":22},{"q":"Quelles sont les CARACTÉRISTIQUES différenciant une tumeur MALIGNE d'une tumeur bénigne ?","o":["Croissance rapide","Anaplasie (perte de différenciation)","Invasion locale (effraction tissulaire)","Métastases possibles","Capsule bien délimitée"],"r":[0,1,2,3],"e":"Tumeur maligne : croissance rapide, anaplasie, invasion locale, métastases, mauvaise délimitation. Bénigne : croissance lente, différenciée, encapsulée, pas d'invasion ni de métastase.","s":22},{"q":"L'ANAPLASIE correspond à :","o":["Une augmentation de la différenciation, vers la maturité","Une perte de différenciation cellulaire","Une diminution du nombre de cellules","Une augmentation de la fonction cellulaire"],"r":1,"e":"Anaplasie = perte de différenciation, cellules indifférenciées atypiques (variation taille/forme = pléomorphisme, gros noyaux hyperchromiques, mitoses anormales). Caractéristique des tumeurs malignes. Les cellules sont immatures et atypiques.","s":22},{"q":"Les VOIES DE DISSÉMINATION métastatique sont :","o":["Voie sanguine (hématogène)","Voie lymphatique","Voie séreuse / cavités péritonéale, pleurale","Implantation directe (chirurgicale, biopsie)","Voie nerveuse exclusivement"],"r":[0,1,2,3],"e":"4 voies de dissémination : hématogène (carcinomes → poumon, foie, os ; sarcomes), lymphatique (ganglions régionaux puis distance), séreuse (cavités), implantation. La voie nerveuse (périneurale) existe aussi mais minoritaire.","s":22},{"q":"Un CARCINOME est :","o":["Une tumeur maligne d'origine MÉSENCHYMATEUSE","Une tumeur maligne d'origine ÉPITHÉLIALE","Une tumeur bénigne épithéliale","Une tumeur du système nerveux"],"r":1,"e":"Carcinome = tumeur MALIGNE d'origine ÉPITHÉLIALE (carcinome bronchique, mammaire, colorectal...). Sarcome = origine mésenchymateuse (os, muscle, conjonctif). Adénocarcinome = épithélium glandulaire.","s":22},{"q":"Un SARCOME est :","o":["Une tumeur maligne épithéliale","Une tumeur maligne d'origine mésenchymateuse","Une tumeur bénigne du tissu conjonctif, bien encapsulée","Une métastase d'un carcinome"],"r":1,"e":"Sarcome = tumeur maligne MÉSENCHYMATEUSE : ostéosarcome (os), chondrosarcome (cartilage), liposarcome (graisse), rhabdomyosarcome (muscle squelettique), léiomyosarcome (muscle lisse). Plus rares que les carcinomes. Elle naît de l'os, du cartilage, du muscle ou du tissu conjonctif.","s":22},{"q":"Concernant la NOMENCLATURE des tumeurs, quelles affirmations sont vraies ?","o":["Le suffixe -ome désigne en général une tumeur bénigne","Le suffixe -carcinome désigne une tumeur épithéliale maligne","Le suffixe -sarcome désigne une tumeur conjonctive maligne","Le lymphome désigne une tumeur bénigne des ganglions","Le mélanome désigne une tumeur bénigne de la peau"],"r":[0,1,2],"e":"-OME : généralement bénin (adénome, lipome, fibrome, ostéome). EXCEPTIONS importantes : lymphome, mélanome, séminome → MALINS malgré la terminaison. Carcinome = épithélial malin, sarcome = mésenchymateux malin.","s":22},{"q":"Le système de stadification TNM repose sur :","o":["La tumeur, les ganglions et les métastases","Le type, la nature et le mécanisme","Trois grades histologiques, de 1 à 3","Trois mutations génétiques, sur les oncogènes et les suppresseurs"],"r":0,"e":"TNM (UICC) : T = taille/extension de la Tumeur primitive (T1-T4), N = atteinte ganglionnaire (N0-N3), M = présence de Métastases (M0/M1). Stadification universelle, pronostique, guide le tx.","s":22},{"q":"Concernant les TRAITEMENTS du cancer :","o":["Chirurgie (résection)","Radiothérapie (rayonnements)","Chimiothérapie (cytotoxiques)","Immunothérapie","Antibiothérapie"],"r":[0,1,2,3],"e":"Tx oncologiques : chirurgie, radiothérapie, chimiothérapie, hormonothérapie, thérapies ciblées (anti-HER2, anti-EGFR), immunothérapie (anti-PD1/PD-L1). Choix selon type, stade, état général. Antibiotiques en cas d'infection associée seulement.","s":22},{"q":"L'ANGIOGENÈSE TUMORALE est :","o":["Inutile à la croissance de la tumeur, à tout stade","Indispensable à la croissance au-delà de quelques mm","Une simple coïncidence, sans rôle","Toujours bénéfique au patient"],"r":1,"e":"Angiogenèse tumorale : la tumeur stimule la formation de nouveaux vaisseaux (VEGF) pour son propre apport en O₂/nutriments. Cible thérapeutique : anti-angiogéniques (bevacizumab). Elle apporte les nutriments.","s":22},{"q":"Concernant les ONCOGÈNES et GÈNES SUPPRESSEURS DE TUMEURS :","o":["Les oncogènes activent la prolifération","Les gènes suppresseurs freinent la prolifération","Une mutation activant un oncogène favorise le cancer","Une mutation inactivant p53 favorise le cancer","Tous ces gènes ont la même fonction, sans opposition"],"r":[0,1,2,3],"e":"Oncogènes : activent la croissance. Activation par mutation/amplification = pro-oncogène. Gènes suppresseurs : freinent la croissance et réparent l'ADN. Inactivation par mutation = perte de frein. Cancer = accumulation de ces altérations. RAS et MYC sont des oncogènes ; p53 et RB des suppresseurs.","s":22},{"q":"La p53 est :","o":["Un oncogène, activateur","Un gène suppresseur de tumeur","Sans rôle dans le cancer","Un médicament anticancéreux, ciblé sur la mitose"],"r":1,"e":"p53 (TP53) = gène suppresseur majeur (gardien du génome) : induit l'arrêt du cycle ou apoptose en cas de lésion ADN. Inactivé dans >50% des cancers humains. Mutations germinales = syndrome de Li-Fraumeni. On l'appelle le gardien du génome.","s":22},{"q":"Quels sont des FACTEURS DE RISQUE généraux du cancer ?","o":["Le tabagisme","La consommation d'alcool","L'obésité abdominale","Certaines infections, comme le HPV","L'activité physique régulière"],"r":[0,1,2,3],"e":"FdR : tabac, alcool, obésité, sédentarité, expositions (UV, amiante, radiations), infections (HPV, HBV/HCV, EBV, H. pylori, HIV), antécédents familiaux/génétiques (BRCA), âge. L'activité physique est PROTECTRICE.","s":22},{"q":"Le CANCER DU SEIN est :","o":["Le plus rare des cancers féminins","Le cancer le plus fréquent chez la femme","Un cancer exclusivement féminin, jamais observé chez l'homme","Une infection mammaire, la mastite"],"r":1,"e":"Cancer du sein = 1er cancer féminin en incidence (1 femme sur 8 risque vie entière). Possible chez l'homme (rare, ~1%). Dépistage organisé par mammographie 50-74 ans en France.","s":22},{"q":"Concernant le DÉPISTAGE des cancers en France :","o":["Le sein, par mammographie de 50 à 74 ans","Le côlon, par test immunologique de 50 à 74 ans","Le col de l'utérus, par frottis puis test HPV","La prostate, sans dépistage organisé","Tous les cancers, de façon organisée"],"r":[0,1,2,3],"e":"Dépistages organisés : sein (mammographie 50-74 ans), côlon (FIT 50-74 ans), col utérin (FCV/HPV 25-65 ans). PROSTATE : pas de dépistage organisé (intérêt débattu, individuel). Tous les cancers n'ont pas de dépistage organisé. Les tests du sein et du côlon se font tous les 2 ans.","s":22},{"q":"Une MÉTASTASE est :","o":["Une tumeur primitive isolée, sans aucun foyer à distance","Une localisation tumorale secondaire, à distance","Une tumeur bénigne encapsulée","Une cicatrice fibreuse, après chirurgie"],"r":1,"e":"Métastase = colonisation tumorale secondaire à distance (souvent par voie hématogène ou lymphatique). Sites fréquents selon origine : poumons, foie, os, cerveau. Indique une maladie disséminée (M1).","s":22},{"q":"Quels sites sont FRÉQUEMMENT le siège de métastases osseuses ?","o":["Cancer du sein","Cancer de la prostate","Cancer du poumon","Cancer du rein","Cancer thyroïdien","Cancer du côlon"],"r":[0,1,2,3,4],"e":"Cancers ostéophiles (mnémo PSPRT) : Prostate, Sein, Poumon, Rein, Thyroïde. Sites métastatiques : rachis (++), bassin, fémur, côtes. Risque de fractures pathologiques, hypercalcémie, douleurs. Le côlon métastase surtout au foie et au poumon par le drainage porte ; l'os est une localisation rare.","s":22},{"q":"Le syndrome PARANÉOPLASIQUE :","o":["Est lié à une métastase locale","Une manifestation à distance, sans métastase","Est toujours bénin, et régresse sans traitement de la tumeur","N'existe pas en pratique clinique"],"r":1,"e":"Syndrome paranéoplasique : manifestations cliniques à distance, indépendantes de l'envahissement local ou métastatique. Mécanismes : sécrétion ectopique d'hormones (ACTH → Cushing, ADH → SIADH), auto-immunité. Peut précéder le diagnostic du cancer. Elle est souvent endocrinienne ou immunologique.","s":22},{"q":"La CACHEXIE cancéreuse est :","o":["Une bonne nouvelle, signe de réponse au traitement","Une fonte musculaire malgré les apports","Un état sans aucune gravité, transitoire","Une réaction allergique au traitement"],"r":1,"e":"Cachexie cancéreuse : syndrome multifactoriel = perte de poids, atrophie musculaire, anorexie, asthénie, anémie. Liée aux cytokines (TNF-α 'cachectine', IL-6). Marqueur de mauvais pronostic. Elle associe une dénutrition et passe par le TNF et l'IL-6.","s":22},{"q":"Concernant la KINÉSITHÉRAPIE EN CANCÉROLOGIE :","o":["Le réentraînement à l'effort, contre la fatigue","Le drainage lymphatique, après curage","Les mobilisations articulaires","Un soutien psychologique","Aucun bénéfice prouvé, à ce jour"],"r":[0,1,2,3],"e":"Kiné en oncologie : reconditionnement, lutte contre la fatigue (cancer-related fatigue), DLM pour lymphœdème (mastectomie), mobilisations, prévention des amyotrophies, accompagnement post-chirurgical/radiothérapie. Bénéfices prouvés sur qualité de vie.","s":22},{"q":"Une RADIOTHÉRAPIE peut entraîner comme effet secondaire :","o":["Aucun effet secondaire notable","Une radiodermite, une fibrose et une fatigue","Toujours une amélioration sans effet indésirable, à court terme","Une infection systématique, bactérienne"],"r":1,"e":"Effets secondaires radiothérapie : précoces (radiodermite, mucite, fatigue, alopécie locale, troubles digestifs si abdo) et tardifs (fibrose, sténoses, second cancer rare). Importance de la kiné post-RT.","s":22},{"q":"Quels sont des effets secondaires CLASSIQUES des CHIMIOTHÉRAPIES ?","o":["Des nausées et des vomissements","Une alopécie, réversible","Une pancytopénie, avec risque infectieux","Une mucite buccale","Une polyarthrose des mains"],"r":[0,1,2,3],"e":"Effets chimio : nausées/vomissements, alopécie, mucite, pancytopénie (risque infection si neutropénie), neuropathie (cisplatine, taxanes), cardiotoxicité (anthracyclines). Ne provoque pas de polyarthrose.","s":22},{"q":"L'IMMUNOTHÉRAPIE moderne du cancer (anti-PD1/PD-L1) :","o":["Tue directement les cellules cancéreuses visées","Lève le frein des lymphocytes T contre la tumeur","Empêche la croissance des bactéries","Stimule la sécrétion d'hormones"],"r":1,"e":"Immunothérapie (checkpoint inhibitors : nivolumab, pembrolizumab, atézolizumab) : bloque les freins (PD-1/PD-L1, CTLA-4) du système immunitaire → réactivation des LT contre la tumeur. Révolutionne le pronostic de certains cancers (mélanome, poumon).","s":22},{"q":"Le facteur de risque PRINCIPAL du cancer du POUMON est :","o":["Le tabagisme","La pollution","L'âge","L'amiante"],"r":0,"e":"Tabac = facteur de risque MAJEUR du cancer du poumon (>85% des cas). Amiante (synergie avec tabac), radon, pollution, antécédents familiaux sont aussi des FdR. Sevrage tabagique = meilleure prévention.","s":22},{"q":"Concernant la BIOPSIE en oncologie :","o":["Elle donne un diagnostic de certitude","Elle précise le type et le grade","Elle oriente le choix du traitement","Elle est indispensable avant un traitement curatif","Elle est toujours dangereuse, et à éviter"],"r":[0,1,2,3],"e":"Biopsie : geste diagnostique INDISPENSABLE pour confirmer le cancer, identifier le type/grade/marqueurs (récepteurs hormonaux, HER2, EGFR, PD-L1...). Risque ENSEMENCEMENT marginal mais nécessaire pour traitement adapté.","s":22},{"q":"L'effet Warburg des cellules tumorales désigne :","o":["Leur capacité à métastaser par voie lymphatique, tôt","Le recours à la glycolyse, même en présence d'oxygène","Leur résistance spontanée à la chimiothérapie","Leur perte de la protéine p53"],"r":1,"e":"Les cellules cancéreuses privilégient la glycolyse aérobie, moins rentable en ATP mais rapide et fournissant des précurseurs de biosynthèse. Cette avidité pour le glucose est ce que met en image le TEP-scanner au 18F-FDG.","s":22},{"q":"Une tumeur maligne se distingue d'une tumeur bénigne par :","o":["Croissance rapide / désorganisée","Capacité d'invasion locale","Capacité de métastaser","Différenciation faible","Capsule limitante nette"],"r":[0,1,2,3],"e":"Maligne : croissance rapide, invasive, métastatique, peu différenciée. Bénigne : encapsulée, bien différenciée, lente, locale.","s":22},{"q":"Le préfixe « -ome » indique généralement :","o":["Tumeur maligne","Tumeur bénigne","Infection","Inflammation"],"r":1,"e":"Suffixe -ome = bénin (lipome, fibrome). Carcinome (épithéliale maligne), sarcome (conjonctive maligne).","s":22},{"q":"Un carcinome est un cancer :","o":["Du tissu conjonctif","De l'épithélium","Du sang","Du système nerveux"],"r":1,"e":"Carcinome = cancer d'origine épithéliale (sein, poumon, côlon, prostate, peau).","s":22},{"q":"Un sarcome est un cancer :","o":["De l'épithélium de revêtement ou glandulaire","Du tissu conjonctif, comme l'os","Du sang, comme la leucémie","Du foie uniquement, primitif"],"r":1,"e":"Sarcome = cancer d'origine mésenchymateuse / conjonctive (os = ostéosarcome, muscle = rhabdomyosarcome). Le cartilage et le muscle sont aussi concernés.","s":22},{"q":"Un lymphome est :","o":["Un cancer du tissu lymphoïde","Un cancer du poumon","Un cancer du foie","Un cancer de la peau, comme le mélanome"],"r":0,"e":"Lymphome : prolifération maligne de cellules lymphoïdes (Hodgkin, non-Hodgkinien).","s":22},{"q":"Le marqueur tumoral PSA est utilisé dans le dépistage et le suivi du cancer :","o":["Du sein","De la prostate","Du côlon","Du poumon"],"r":1,"e":"Le PSA (antigène spécifique de prostate) est spécifique de l'organe, non du cancer : il s'élève aussi dans l'hypertrophie bénigne et la prostatite. Repères d'usage : CA 15-3 pour le sein, ACE et CA 19-9 pour le tube digestif, AFP pour le foie et le testicule.","s":22},{"q":"Les voies de dissémination tumorale sont :","o":["La voie lymphatique","La voie sanguine","L'extension par contiguïté","Les cavités séreuses","La voie aérienne"],"r":[0,1,2,3],"e":"Voies : lymphatique (carcinomes), hématogène (sarcomes), contiguïté, séreuses. Pas aérienne. Les séreuses sont la plèvre et le péritoine.","s":22},{"q":"Les facteurs de risque de cancer incluent :","o":["Tabac","Alcool","Rayonnements (UV, ionisants)","Infections (HPV, HBV, EBV)","Génétique","Sport régulier"],"r":[0,1,2,3,4],"e":"Carcinogènes : tabac, alcool, rayonnements, virus oncogènes, prédispositions héréditaires (BRCA, Lynch). Sport = protecteur.","s":22},{"q":"La classification TNM décrit :","o":["Le traitement uniquement, en trois lignes","La taille, les ganglions et les métastases","La couleur de la tumeur","La biologie moléculaire"],"r":1,"e":"TNM (UICC) : T (Tumor size), N (Nodes ganglions régionaux), M (Metastases) → stadification cancer.","s":22},{"q":"Quelle était la signification initiale du mot « tumeur » ?","o":["Une augmentation de volume causée par l'inflammation","Une masse maligne, invasive","Une métastase à distance, dans le foie ou dans le poumon","Un processus de croissance incontrôlée"],"r":0,"e":"Le terme désigne aujourd'hui toute masse occupant un espace anormal, et s'emploie comme synonyme de néoplasme.","s":22},{"q":"Quelle relation la fiche établit-elle entre cancer et néoplasme ?","o":["Tout cancer est un néoplasme, pas l'inverse","Tout néoplasme est un cancer, même s'il est bénin","Les deux termes sont équivalents","Le cancer est un néoplasme bénin"],"r":0,"e":"Le cancer correspond aux seules néoplasies malignes.","s":22},{"q":"Qu'est-ce que la différenciation cellulaire ?","o":["La spécialisation croissante des cellules","La mort cellulaire programmée","La division cellulaire de remplacement, à l'identique","L'entrée en phase G0, de repos"],"r":0,"e":"Prolifération, différenciation et apoptose sont les trois processus normaux rappelés par la fiche. Elle progresse à chaque division.","s":22},{"q":"Quelles cellules n'entrent jamais en phase G0 ?","o":["Les cellules labiles, comme les cellules sanguines","Les cellules permanentes, comme les neurones du cortex","Les cellules stables, comme les hépatocytes","Les cellules souches adultes"],"r":0,"e":"Les cellules labiles répètent continuellement le cycle cellulaire.","s":22},{"q":"Que se passe-t-il lors de l'initiation de la carcinogenèse ?","o":["Un cancérigène lèse l'ADN et crée une mutation, en G0","Les oncogènes sont activés par un promoteur, en G1","Les mutations confèrent des avantages de survie","La tumeur devient invasive"],"r":0,"e":"Initiation, promotion puis progression constituent les trois étapes.","s":22},{"q":"Que se passe-t-il durant la phase de promotion ?","o":["Un promoteur active les oncogènes, la cellule entrant en G1","L'ADN est endommagé pour la première fois, en G0","Les métastases se forment, par les voies sanguine et lymphatique","La cellule entre en apoptose"],"r":0,"e":"La cellule mutée prolifère alors de manière autonome, sans contrôle de l'apoptose. L'hypoxie fait entrer la cellule en G1.","s":22},{"q":"Qu'est-ce qui caractérise la phase de progression ?","o":["Des mutations qui donnent un avantage de survie","La première mutation de l'ADN","L'activation initiale des oncogènes","La différenciation cellulaire, vers un type mature et fonctionnel"],"r":0,"e":"C'est l'aboutissement vers la tumeur maligne. La prolifération devient indépendante des signaux normaux.","s":22},{"q":"D'où résulte l'anaplasie ?","o":["D'une prolifération sans maturation, le plus souvent","D'une dédifférenciation systématique","D'une hyperplasie prolongée, sur des années d'irritation","D'une métaplasie, adaptative"],"r":0,"e":"L'anaplasie est l'absence de différenciation, caractéristique des cellules malignes. La dédifférenciation est plus rare.","s":22},{"q":"Quelles mitoses observe-t-on dans une tumeur bénigne ?","o":["Des mitoses rares et normales","Des mitoses nombreuses et anormales","Aucune mitose","Des mitoses anormales mais rares"],"r":0,"e":"Les tumeurs malignes ont une croissance erratique avec des mitoses nombreuses ou atypiques.","s":22},{"q":"Qu'est-ce qui rend une tumeur bénigne mobile et discrètement palpable ?","o":["Sa capsule de tissu conjonctif condensé","Son infiltration des tissus voisins","Sa vascularisation abondante","Son caractère indifférencié"],"r":0,"e":"L'encapsulation empêche la pénétration des tissus environnants.","s":22},{"q":"Quel type de tumeur donne des métastases plus fréquentes ?","o":["Les tumeurs primaires larges et peu différenciées","Les tumeurs petites et bien différenciées, de bas grade","Les tumeurs encapsulées, bien limitées","Les tumeurs bénignes volumineuses"],"r":0,"e":"Taille et indifférenciation augmentent le risque métastatique.","s":22},{"q":"Qu'est-ce qui permet à la cellule cancéreuse d'envahir les tissus ?","o":["L'expression de molécules d'adhésion de surface","La perte totale de toute molécule de surface","Son encapsulation, dans une coque fibreuse épaisse","Sa différenciation accrue"],"r":0,"e":"Ces molécules d'adhésion permettent l'invasion puis la dissémination.","s":22},{"q":"Quels organes la dissémination par voie sanguine atteint-elle fréquemment ?","o":["Le foie, les poumons et les os","Les ganglions lymphatiques régionaux","La plèvre et le péritoine","La peau, les muscles et les tendons des membres"],"r":0,"e":"La voie lymphatique gagne les ganglions et la voie cavitaire les séreuses.","s":22},{"q":"Dans quel cas une tumeur bénigne peut-elle être dangereuse ?","o":["Si elle gêne une fonction vitale, comme dans le cerveau","Si elle donne des métastases à distance","Si elle est bien différenciée, avec des cellules matures normales","Si elle est encapsulée, bien limitée"],"r":0,"e":"La localisation, non la nature, fait le danger des tumeurs bénignes.","s":22},{"q":"Sur quelle composante la dénomination d'une tumeur est-elle fondée ?","o":["Sur la composante parenchymateuse","Sur le stroma de soutien","Sur la vascularisation, artérielle et veineuse","Sur la taille, en centimètres"],"r":0,"e":"C'est le tissu d'origine du parenchyme qui donne son nom à la tumeur.","s":22}]};
